window.LEXICON_DATA = (window.LEXICON_DATA || []).concat([{"id":"mitigate","word":"mitigate","ipa":{"uk":"/ˈmɪtɪɡeɪt/","us":"/ˈmɪtɪɡeɪt/"},"pos":"v.","definition":{"en":"To make the harmful effects of something less severe.","zh":"减轻、缓解不利影响或严重程度。"},"libraries":["writing"],"topics":["自然与环境","社会与经济"],"functions":["改善与恶化","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"极正式学术语域；适用于大作文政策干预段、环境治理及风险评估（侧重缓冲或减轻负面后果）","synonyms":[{"id":"alleviate","note":"都可表示减轻；alleviate 更常接痛苦、压力或贫困，mitigate 更强调危害与风险。"},{"id":"ameliorate","note":"都涉及改善不利状况；ameliorate 强调整体变好，mitigate 强调程度变轻。"},{"id":"abate","note":"mitigate 为及物动词“减轻危害”；abate 常作不及物动词表“（风暴/危机本身）减弱”。"},{"id":"assuage","note":"mitigate 侧重缓冲或减轻危害、风险等客观负面后果；assuage 侧重平息焦虑、内疚或不满等主观情绪。"}],"antonyms":[{"id":"exacerbate","note":"直接的程度对照：mitigate 减轻问题，exacerbate 使问题加剧。"},{"id":"aggravate","note":"aggravate 使原有困难或症状更严重。"},{"id":"intensify","note":"反义对照：mitigate 表“使缓和”，而 intensify 表“使增强”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"mitigate the adverse repercussions of","zh":"减轻……的不利连锁影响"},{"en":"mitigate anthropogenic climate change","zh":"减缓人为气候变化"},{"en":"partially mitigate the socioeconomic fallout","zh":"部分缓解社会经济负面冲击"},{"en":"implement measures to mitigate risk","zh":"采取措施以降低风险"}],"examples":[{"type":"IELTS","en":"Investing in subsidized mass transit can substantially mitigate the adverse repercussions of rapid urbanization while improving access to employment.","zh":"投资补贴性大众公交不仅能大幅减轻快速城市化的不利连锁影响，还能改善就业可达性。","highlights":["mitigate the adverse repercussions of"]},{"type":"IELTS","en":"Were governments to mandate stricter carbon disclosure, multinational corporations would be compelled to mitigate their environmental footprint.","zh":"倘若政府强制实行更严格的碳信息披露制度，跨国公司将被迫减轻其环境足迹。","highlights":["mitigate their environmental footprint"]},{"type":"GRE","en":"The researchers introduced longitudinal controls to mitigate the risk that seasonal variation would distort their estimates of demographic growth.","zh":"研究人员引入了纵向控制变量，以降低季节性波动扭曲其人口增长估计值的风险。","highlights":["mitigate the risk"]},{"type":"GRE","en":"Although maritime insurance could not prevent shipwrecks, it served to mitigate the catastrophic financial losses that previously deterred long-distance trade.","zh":"尽管海事保险无法防止海难发生，但它有效缓解了此前令远洋贸易望而却步的灾难性财务损失。","highlights":["mitigate the catastrophic financial losses"]}],"note":"【句型框架】常用于 `mitigate the adverse effects/repercussions of X on Y`（减轻 X 对 Y 的负面影响）或分词结构 `thereby mitigating the risk of...`（从而降低……的风险）。【高阶替换】用于替换基础词 `reduce / lessen / make less bad`；与 `alleviate`（侧重缓解痛苦、贫困或负担）不同，`mitigate` 更强调通过预防或缓冲手段降低危害、风险或冲击的严重程度，且不等于彻底消除（`eradicate`）。【避坑指南】`mitigate` 是纯及物动词，直接接负面名词作宾语（如 `risk, damage, impact`），中国考生常误受 `militate against`（对……不利）干扰而错写为 `mitigate against`。","forms":["mitigates","mitigated","mitigating","mitigation"],"partners":[{"id":"repercussion","rel":"动+名","phrase":"mitigate the adverse repercussions of","note":"常用搭配：mitigate the adverse repercussions of（减轻……的不利连锁影响），与 repercussion（恶果、连锁反应）构成高频「动+名」词伙。"},{"id":"risk","rel":"动+名","phrase":"implement measures to mitigate risk","note":"常用搭配：implement measures to mitigate risk（采取措施以降低风险），与 risk（风险）构成高频「动+名」词伙。"}]},{"id":"ameliorate","word":"ameliorate","ipa":{"uk":"/əˈmiːliəreɪt/","us":"/əˈmiːliəreɪt/"},"pos":"v.","definition":{"en":"To improve an unsatisfactory condition or situation.","zh":"改善不理想的状况。"},"libraries":["writing"],"topics":["社会与经济","健康与生活"],"functions":["改善与恶化","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"极正式书面与政策语域；适用于大作文民生改善、社会福利与弱势群体帮扶论述","synonyms":[{"id":"improve","note":"核心义接近；ameliorate 通常用于有问题的状况，而 improve 适用范围更广。"},{"id":"alleviate","note":"改善困境时接近，但 alleviation 侧重负担减轻。"},{"id":"mitigate","note":"可用于同一不利情境，重点分别是改善状况与减轻程度。"},{"id":"rectify","note":"ameliorate 侧重改善恶劣状况；rectify 侧重彻底修正具体错误或缺陷。"}],"antonyms":[{"id":"exacerbate","note":"使不良状况加剧，与 ameliorate 的改善方向相反。"},{"id":"deteriorate","note":"deteriorate 日益恶化，ameliorate 改善向好。"},{"id":"degenerate","note":"ameliorate 改善提升，与蜕变恶化的 degenerate 相反。"}],"collocations":[{"en":"ameliorate the plight of marginalized groups","zh":"改善边缘群体的困境"},{"en":"ameliorate living conditions in deprived areas","zh":"改善贫困地区的生活条件"},{"en":"help to ameliorate structural inequalities","zh":"有助于改善结构性不平等"},{"en":"ameliorate the harshness of austerity measures","zh":"缓和紧缩措施的严苛程度"}],"examples":[{"type":"IELTS","en":"Well-targeted investment in municipal sanitation can ameliorate living conditions in deprived neighbourhoods without displacing established communities.","zh":"有针对性的市政卫生设施投资可以改善贫困社区的生活条件，而无需迁移原有社区居民。","highlights":["ameliorate living conditions"]},{"type":"IELTS","en":"While progressive taxation alone cannot eradicate wealth gaps, it remains a vital fiscal tool to ameliorate the plight of low-income households.","zh":"尽管累进税制本身无法根除贫富差距，但它仍是改善低收入家庭困境的重要财政工具。","highlights":["ameliorate the plight of"]},{"type":"GRE","en":"The revised econometric model was intended to ameliorate the methodological shortcomings of earlier estimates, though several sources of bias persisted.","zh":"修订后的计量经济学模型旨在改善早期估计在方法论上的缺陷，尽管若干偏差来源依然存在。","highlights":["ameliorate the methodological shortcomings"]}],"note":"【句型框架】核心模板为 `ameliorate the plight/conditions of...`（改善……的困境/处境）或定语后置 `policies designed to ameliorate...`（旨在改善……的政策）。【高阶替换】作为 `improve / make better` 的高阶学术替换词，它专指将原本“糟糕、艰难或令人不满的客观境况”变得更好一些；相比 `upgrade`（软硬件或技能升级）和 `enhance`（锦上添花地提升已有价值），`ameliorate` 带有明显的“雪中送炭、救弊补偏”色彩。【避坑指南】切勿将其当作所有 `improve` 的万能替换，例如不能写 `ameliorate my English skills` 或 `ameliorate efficiency`，其宾语必须是负面或亟待救援的困境（如 `poverty, suffering, living conditions`）。","forms":["ameliorates","ameliorated","ameliorating","amelioration"],"partners":[{"id":"plight","rel":"动+名","phrase":"ameliorate the plight of marginalized groups","note":"常用搭配：ameliorate the plight of marginalized groups（改善边缘群体的困境），与 plight（困境、苦境）构成高频「动+名」词伙。"},{"id":"condition","rel":"动+名","phrase":"ameliorate living conditions in deprived areas","note":"常用搭配：ameliorate living conditions in deprived areas（改善贫困地区的生活条件），与 condition（条件、状况）构成高频「动+名」词伙。"}]},{"id":"exacerbate","word":"exacerbate","ipa":{"uk":"/ɪɡˈzæsəbeɪt/","us":"/ɪɡˈzæsərbeɪt/"},"pos":"v.","definition":{"en":"To make an existing problem, bad situation, or negative feeling worse.","zh":"使已有问题、困境或负面情绪恶化。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["改善与恶化","因果与影响"],"frequency":{"ielts":5,"gre":5},"register":"极正式学术语域；适用于大作文反驳段或负面因果链推导（强调政策失当令既有问题雪上加霜）","synonyms":[{"id":"aggravate","note":"恶化义相近；aggravate 还可在口语中表示惹恼。"},{"id":"escalate","note":"exacerbate 为及物动词“使……恶化”；escalate 常作不及物动词“（事态本身）升级、激化”。"},{"id":"deteriorate","note":"语法大不同：deteriorate 主要作不及物动词（状况自己恶化）；exacerbate 是及物动词（使状况恶化）。"}],"antonyms":[{"id":"mitigate","note":"反义对照：exacerbate 表“恶化”，而 mitigate 表“使缓和”，二者构成鲜明的语义对立。"},{"id":"alleviate","note":"反义对照：exacerbate 表“恶化”，而 alleviate 表“减轻”，二者构成鲜明的语义对立。"},{"id":"ameliorate","note":"反义对照：exacerbate 表“恶化”，而 ameliorate 表“改善”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"exacerbate socioeconomic disparities","zh":"加剧社会经济差距"},{"en":"exacerbate an already precarious situation","zh":"使本已岌岌可危的局势雪上加霜"},{"en":"unintendedly exacerbate social tensions","zh":"无意中加剧社会紧张局势"},{"en":"exacerbate urban housing shortages","zh":"加剧城市住房短缺"}],"examples":[{"type":"IELTS","en":"Raising university tuition fees without expanding means-tested grants may exacerbate socioeconomic disparities by pricing out disadvantaged students.","zh":"提高大学学费而不扩大与收入挂钩的助学金规模，可能会因将弱势学生拒之门外而加剧社会经济差距。","highlights":["exacerbate socioeconomic disparities"]},{"type":"IELTS","en":"Constructing additional inner-city ring roads often fails to relieve congestion; instead, it tends to exacerbate vehicular emissions by inducing further traffic demand.","zh":"修建更多内城环路往往无法缓解拥堵；相反，它会诱发更多交通需求，从而加剧机动车排放问题。","highlights":["exacerbate vehicular emissions"]},{"type":"GRE","en":"The authors argue that fragmented municipal governance can exacerbate an already precarious situation by preventing agencies from coordinating disaster relief.","zh":"作者认为，碎片化的市政治理会阻碍各机构协调救灾行动，从而使本已岌岌可危的局势进一步恶化。","highlights":["exacerbate an already precarious situation"]}],"note":"【句型框架】常用于主动因果句 `X may inadvertently exacerbate Y`（X 可能无意中加剧 Y）或分词补充说明 `, thereby exacerbating existing inequalities`（从而使既有不平等恶化）。【高阶替换】直接升级 `worsen / make worse`；与 `aggravate`（兼具“加重问题”与口语“激怒某人”两义）及不及物动词 `deteriorate`（自行恶化）相比，`exacerbate` 是纯粹的学术及物动词，专指外部因素使原本已存在的危机或矛盾进一步加深。【避坑指南】一是拼写与发音切勿同 `exaggerate`（夸大、言过其实）混淆；二是宾语必须本身具有负面属性（`crisis, shortage, tension`），不可接中性或正面名词。","forms":["exacerbates","exacerbated","exacerbating","exacerbation"],"partners":[{"id":"disparity","rel":"动+名","phrase":"exacerbate socioeconomic disparities","note":"常用搭配：exacerbate socioeconomic disparities（加剧社会经济差距），与 disparity（悬殊差距）构成高频「动+名」词伙。"},{"id":"tension","rel":"动+名","phrase":"unintendedly exacerbate social tensions","note":"常用搭配：unintendedly exacerbate social tensions（无意中加剧社会紧张局势），与 tension（紧张局势）构成高频「动+名」词伙。"}]},{"id":"impede","word":"impede","ipa":{"uk":"/ɪmˈpiːd/","us":"/ɪmˈpiːd/"},"pos":"v.","definition":{"en":"To slow down or obstruct movement, development, or progress.","zh":"阻碍、妨碍进展或行动。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["因果与影响","改善与恶化"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与政策语域；适用于大作文分析官僚主义、资源匮乏或贸易壁垒对发展进程的阻滞","synonyms":[{"id":"hinder","note":"近义，hinder 更常用；均不必表示完全阻止。"},{"id":"inhibit","note":"抑制义相近；inhibit 常见于行为、活动或生物过程。"},{"id":"retard","note":"都可阻碍进展；retard 尤其强调使发展速度变慢。"},{"id":"hamper","note":"二者均表阻碍进程；impede 语气更正式，常指制度或结构性阻力，hamper 常指具体条件受限导致行动不便。"}],"antonyms":[{"id":"facilitate","note":"使过程更容易，与阻碍形成直接对照。"},{"id":"promote","note":"在发展、增长语境中表示促进。"},{"id":"precipitate","note":"impede 阻碍事件发生，而 precipitate 促使其骤然发生。"}],"collocations":[{"en":"impede sustainable economic growth","zh":"阻碍可持续经济增长"},{"en":"impede the free flow of information","zh":"阻碍信息的自由流动"},{"en":"severely impede upward social mobility","zh":"严重阻碍向上社会流动"},{"en":"bureaucratic red tape that impedes innovation","zh":"阻碍创新的官僚繁文缛节"}],"examples":[{"type":"IELTS","en":"Excessive bureaucratic red tape can severely impede sustainable economic growth by diverting resources that small enterprises would otherwise invest in innovation.","zh":"过多的官僚繁文缛节会占用小企业原本可用于创新的资源，从而严重阻碍可持续经济增长。","highlights":["impede sustainable economic growth"]},{"type":"IELTS","en":"Persistent digital divides between urban and rural districts continue to impede upward social mobility for students from remote agricultural communities.","zh":"城乡之间持续存在的数字鸿沟，仍在阻碍偏远农村社区学生的向上社会流动。","highlights":["impede upward social mobility"]},{"type":"GRE","en":"Topographical fragmentation may impede the free flow of genetic material between isolated alpine populations, accelerating allopatric divergence.","zh":"地形破碎化可能会阻碍孤立高山种群之间遗传物质的自由流动，从而加速异域分化。","highlights":["impede the free flow of"]}],"note":"【句型框架】常用于 `impede + 动态发展类名词（growth / progress / recovery / mobility / transition）`；其派生名词 `impediment` 常构成 `pose a major impediment to...`（对……构成重大障碍）。【高阶替换】词根 `ped`（脚）表示“绊脚”，用来升级 `slow down / hold back / block`；与 `preclude`（彻底排除可能性）不同，`impede` 指制造阻力使进程放缓或步履维艰，而非使其完全不可能发生。【避坑指南】`impede` 是及物动词（直接说 `impede progress`），而名词 `impediment` 后必须接介词 `to`（如 `an impediment to economic recovery`）。","forms":["impedes","impeded","impeding","impediment"],"partners":[{"id":"growth","rel":"动+名","phrase":"impede sustainable economic growth","note":"常用搭配：impede sustainable economic growth（阻碍可持续经济增长），与 growth（增长、发展）构成高频「动+名」词伙。"},{"id":"mobility","rel":"动+名","phrase":"severely impede upward social mobility","note":"常用搭配：severely impede upward social mobility（严重阻碍向上社会流动），与 mobility（流动性）构成高频「动+名」词伙。"}]},{"id":"facilitate","word":"facilitate","ipa":{"uk":"/fəˈsɪlɪteɪt/","us":"/fəˈsɪlɪteɪt/"},"pos":"v.","definition":{"en":"To make an action or process easier or more likely to happen.","zh":"使某项行动或过程更容易实现；促进。"},"libraries":["writing"],"topics":["科技与教育","社会与经济"],"functions":["因果与影响","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与公共管理语域；适用于大作文科技利弊、全球化交流、教育改革及基础设施功能论述","synonyms":[{"id":"promote","note":"都可促进某事；facilitate 强调降低障碍，promote 强调积极推动。"},{"id":"foster","note":"在 cooperation / learning 语境中接近；foster 更强调长期培育。"},{"id":"boost","note":"近义辨析：二者在“促进”义项上相通；facilitate 侧重“使便利”，boost 侧重“使增长”。"}],"antonyms":[{"id":"impede","note":"反义对照：facilitate 表“使便利”，而 impede 表“阻碍”，二者构成鲜明的语义对立。"},{"id":"hinder","note":"反义对照：facilitate 表“使便利”，而 hinder 表“阻碍”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"facilitate equitable access to information","zh":"促进信息的公平获取"},{"en":"facilitate cross-border trade and capital flows","zh":"便利跨境贸易与资本流动"},{"en":"facilitate knowledge acquisition and retention","zh":"促进知识的获取与留存"},{"en":"facilitate the transition towards green energy","zh":"促进向绿色能源的转型"}],"examples":[{"type":"IELTS","en":"Municipal libraries play a vital equalizing role by offering digital resources that facilitate equitable access to information for low-income residents.","zh":"市政图书馆通过提供数字资源，为低收入居民公平获取信息提供便利，从而发挥着重要的均衡器作用。","highlights":["facilitate equitable access to information"]},{"type":"IELTS","en":"While teleconferencing platforms effortlessly facilitate cross-border collaboration, they rarely replicate the spontaneous rapport built through face-to-face interaction.","zh":"尽管远程会议平台能轻松便利跨境协作，但它们很少能复制面对面交流所建立的自发默契。","highlights":["facilitate cross-border collaboration"]},{"type":"GRE","en":"Standardized metrological protocols facilitate international scientific cooperation because researchers can compare empirical findings without reconciling incompatible units.","zh":"标准化的计量协议促进了国际科学合作，因为研究人员无需调和互不相容的单位即可比较实证结果。","highlights":["facilitate international scientific cooperation"]}],"note":"【句型框架】标准学术结构为 `X facilitates + 抽象过程名词（communication / integration / learning / transition）`，意为“X 为某过程扫清障碍、提供便利”。【高阶替换】精准替换 `make easier / help / promote`；与 `promote`（侧重宣传推广或提升职位）和 `encourage`（侧重心理激励）不同，`facilitate` 强调客观工具、制度或技术使原本繁琐的过程变得顺畅高效。【避坑指南】切忌使用中国考生高频错句 `facilitate somebody to do something`（`facilitate` 的宾语只能是“事/过程”而不能是“人”，若接人作宾语必须改为 `enable / allow somebody to do something`）。","forms":["facilitates","facilitated","facilitating","facilitation"],"partners":[{"id":"acquisition","rel":"动+名","phrase":"facilitate knowledge acquisition and retention","note":"常用搭配：facilitate knowledge acquisition and retention（促进知识的获取与留存），与 acquisition（获取、习得）构成高频「动+名」词伙。"},{"id":"transition","rel":"动+名","phrase":"facilitate the transition towards green energy","note":"常用搭配：facilitate the transition towards green energy（促进向绿色能源的转型），与 transition（转型、过渡）构成高频「动+名」词伙。"}]},{"id":"foster","word":"foster","ipa":{"uk":"/ˈfɒstə/","us":"/ˈfɔːstər/"},"pos":"v.","definition":{"en":"To encourage the gradual development of a quality, relationship, or activity.","zh":"促进、培育某种品质、关系或活动。"},"libraries":["writing"],"topics":["科技与教育","社会与经济"],"functions":["因果与影响","改善与恶化"],"frequency":{"ielts":5,"gre":4},"register":"正式教育学与社会学语域；适用于大作文素质教育、社区营造、创新生态及国际互信培养论述","synonyms":[{"id":"promote","note":"都表示促进；foster 更常用于信任、创造力和关系的逐渐形成。"},{"id":"facilitate","note":"在学习、合作语境中相关；facilitate 更强调提供便利条件。"},{"id":"bolster","note":"都可使有利因素增强；bolster 更偏向巩固已经存在的支持。"},{"id":"incentivise","note":"foster 侧重长期培育某种风气或关系，incentivise 侧重通过具体的利益机制（如减税、补贴、奖金）刺激行为主体的积极性。"}],"antonyms":[{"id":"inhibit","note":"反义对照：foster 表“培养”，而 inhibit 表“抑制”，二者构成鲜明的语义对立。"},{"id":"undermine","note":"逐步削弱信任、合作等已有基础。"},{"id":"suppress","note":"反义对照：foster 表“培养”，而 suppress 表“压制”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"foster critical thinking and independent inquiry","zh":"培养批判性思维与独立探究能力"},{"en":"foster a strong sense of civic belonging","zh":"培育强烈的公民归属感"},{"en":"foster an environment conducive to innovation","zh":"营造有利于创新的环境"},{"en":"foster mutual understanding across cultures","zh":"增进跨文化相互理解"}],"examples":[{"type":"IELTS","en":"Seminar-based pedagogy can foster critical thinking and independent inquiry when students are encouraged to interrogate competing hypotheses.","zh":"当鼓励学生质询相互竞争的假说时，研讨式教学法能够培养批判性思维与独立探究能力。","highlights":["foster critical thinking and independent inquiry"]},{"type":"IELTS","en":"Designing pedestrian-friendly public plazas and community gardens helps to foster a strong sense of civic belonging among urban dwellers.","zh":"设计步行友好的公共广场和社区花园，有助于在城市居民中培育强烈的公民归属感。","highlights":["foster a strong sense of civic belonging"]},{"type":"GRE","en":"Repeated reciprocal exchanges may foster mutual trust among trading partners, yet cooperation remains fragile when enforcement mechanisms are absent.","zh":"反复的互惠交易或许能在贸易伙伴间培育相互信任，但在缺乏执行机制的情况下，合作关系依然脆弱。","highlights":["foster mutual trust"]}],"note":"【句型框架】常用于 `foster + 抽象积极品质/关系（creativity / empathy / trust / a sense of community）` 或 `foster a climate/culture of...`（培育……的氛围/文化）。【高阶替换】升级教育与社会类高频词 `develop / build / encourage`；与 `cultivate`（侧重刻意磨练个人技能或修养）相比，`foster` 更强调提供适宜的土壤与外部条件，使某种良好的品质、情感或创新生态自然生长。【避坑指南】在家庭类大作文中要注意区分其另一常见义项：`foster care / foster parents`（寄养制度/寄养父母），切勿在同一段落中将“寄养儿童”与“培养能力”混为一谈造成歧义。","forms":["fosters","fostered","fostering"],"partners":[{"id":"inquiry","rel":"动+名","phrase":"foster critical thinking and independent inquiry","note":"常用搭配：foster critical thinking and independent inquiry（培养批判性思维与独立探究能力），与 inquiry（探究、调查）构成高频「动+名」词伙。"},{"id":"innovation","rel":"动+名","phrase":"foster an environment conducive to innovation","note":"常用搭配：foster an environment conducive to innovation（营造有利于创新的环境），与 innovation（创新）构成高频「动+名」词伙。"}]},{"id":"inhibit","word":"inhibit","ipa":{"uk":"/ɪnˈhɪbɪt/","us":"/ɪnˈhɪbɪt/"},"pos":"v.","definition":{"en":"To restrain or slow an activity, process, or expression.","zh":"抑制、阻止或减缓活动、过程或表达。"},"libraries":["writing"],"topics":["科技与教育","健康与生活"],"functions":["因果与影响","改善与恶化"],"frequency":{"ielts":5,"gre":5},"register":"正式心理学、教育学与自然科学语域；适用于大作文探讨高压环境或僵化制度对创造力、表达欲及经济活力的压抑","synonyms":[{"id":"hinder","note":"广义上都可阻碍；inhibit 更强调抑制活动或表达。"},{"id":"impede","note":"进程受阻的近义词；inhibit 还常用于酶、反应或冲动。"},{"id":"suppress","note":"近义辨析：二者在“抑制”义项上相通；inhibit 侧重“抑制”，suppress 侧重“压制”。"},{"id":"curb","note":"inhibit 侧重抑制心理表达、生理反应或投资活动；curb 侧重通过有力措施遏制不良趋势蔓延。"}],"antonyms":[{"id":"foster","note":"反义对照：inhibit 表“抑制”，而 foster 表“培养”，二者构成鲜明的语义对立。"},{"id":"promote","note":"反义对照：inhibit 表“抑制”，而 promote 表“促进”，二者构成鲜明的语义对立。"},{"id":"incentivise","note":"抑制阻止（inhibit）与正向激励（incentivise）构成反义。"}],"collocations":[{"en":"inhibit artistic creativity and experimentation","zh":"抑制艺术创造力与探索精神"},{"en":"inhibit open communication in the workplace","zh":"抑制职场中的坦诚沟通"},{"en":"high interest rates that inhibit business investment","zh":"抑制商业投资的高利率"},{"en":"inhibit students from voicing dissenting views","zh":"使学生不敢表达不同观点"}],"examples":[{"type":"IELTS","en":"Excessively rigid standardized testing may inhibit artistic creativity and experimentation by compelling teachers to narrow the curriculum.","zh":"过于僵化的标准化考试会迫使教师收窄课程范围，从而抑制艺术创造力与探索精神。","highlights":["inhibit artistic creativity and experimentation"]},{"type":"IELTS","en":"Fear of online harassment and reputational damage can inhibit citizens from participating candidly in digital civic debates.","zh":"对网络骚扰和名誉受损的恐惧，可能会使公民不敢坦率地参与数字公共讨论。","highlights":["inhibit citizens from participating"]},{"type":"GRE","en":"The synthesized alkaloid appears to inhibit enzymatic activity under in vitro conditions, though its bioavailability in mammalian tissues remains untested.","zh":"这种合成生物碱在体外条件下似乎能抑制酶活性，但其在哺乳动物组织中的生物利用度尚待检验。","highlights":["inhibit enzymatic activity"]}],"note":"【句型框架】既可直接接名词 `inhibit creativity/growth/investment`，也可用于 `inhibit somebody from doing something`（抑制/束缚某人做某事，使其因顾虑而不敢行动）。【高阶替换】替换 `discourage / hold back / suppress`；相比 `impede`（外部路障阻挡前进），`inhibit` 更侧重内在心理顾虑、生物化学机制或严苛氛围对自然活力与本能表达的“压抑与束缚”。【避坑指南】切勿将 `inhibit`（抑制）与拼写极像的 `inhabit`（栖息于、居住在，如 `inhabit the rainforest`）混淆；形容词 `inhibited` 指人“拘谨的、放不开的”。","forms":["inhibits","inhibited","inhibiting","inhibition","inhibitory"],"partners":[{"id":"investment","rel":"动+名","phrase":"high interest rates that inhibit business investment","note":"常用搭配：high interest rates that inhibit business investment（抑制商业投资的高利率），与 investment（投资）构成高频「动+名」词伙。"},{"id":"communication","rel":"动+名","phrase":"inhibit open communication in the workplace","note":"常用搭配：inhibit open communication in the workplace（抑制职场中的坦诚沟通），与 communication（沟通、交流）构成高频「动+名」词伙。"}]},{"id":"bolster","word":"bolster","ipa":{"uk":"/ˈbəʊlstə/","us":"/ˈboʊlstər/"},"pos":"v.","definition":{"en":"To strengthen or support something that already exists.","zh":"加强、支持或巩固已有事物。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["改善与恶化","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式经济、政治与学术论证语域；适用于大作文阐述政策如何提振信心、巩固韧性或证据如何支撑论点","synonyms":[{"id":"foster","note":"在 confidence 语境中相关；foster 偏培育，bolster 偏增强已有信心。"},{"id":"promote","note":"都可能增强积极发展，但 promote 更强调推动而非巩固。"},{"id":"improve","note":"在 resilience / performance 语境中相关；bolster 特别强调支持。"},{"id":"substantiate","note":"证据均可加强论点；substantiate 更强调建立事实依据。"}],"antonyms":[{"id":"undermine","note":"直接对照：加强基础或信心与逐步削弱。"},{"id":"diminish","note":"在 confidence / support 等语境中相反：增强与减弱；diminish 也可表示纯粹数量减少。"},{"id":"debilitate","note":"在系统或能力上对照：bolster 加强支持，debilitate 削弱功能。"}],"collocations":[{"en":"bolster public confidence in the judiciary","zh":"增强公众对司法系统的信心"},{"en":"bolster macroeconomic resilience against shocks","zh":"增强抵御冲击的宏观经济韧性"},{"en":"empirical evidence that bolsters the hypothesis","zh":"有力支持该假说的实证证据"},{"en":"bolster the domestic manufacturing sector","zh":"扶持提振国内制造业"}],"examples":[{"type":"IELTS","en":"Transparent budgetary auditing can bolster public confidence in municipal governance, particularly when citizens are invited to scrutinize spending priorities.","zh":"透明的预算审计可以增强公众对市政治理的信心，尤其是在邀请公民监督支出重点时。","highlights":["bolster public confidence in"]},{"type":"IELTS","en":"Diversifying energy imports and expanding strategic reserves are essential measures to bolster macroeconomic resilience against geopolitical disruptions.","zh":"实现能源进口多元化并扩大战略储备，是增强宏观经济韧性以抵御地缘政治动荡的必要举措。","highlights":["bolster macroeconomic resilience against"]},{"type":"GRE","en":"The discovery of parallel isotopic signatures in independent ice cores served to bolster the paleoclimatologist's previously contested hypothesis.","zh":"在独立冰芯中发现平行的同位素特征，有力支撑了这位古气候学家此前备受争议的假说。","highlights":["bolster the paleoclimatologist's previously contested hypothesis"]}],"note":"【句型框架】常用于 `bolster confidence/morale/resilience`（提振信心/士气/韧性）或学术论证句 `These findings bolster the contention that...`（这些发现强化了……的论点）。【高阶替换】原本指垫高枕头支撑，引申为替换 `strengthen / support / boost` 的高分及物动词；相比 `underpin`（作为底层根基支撑），`bolster` 强调对已存在但可能略显薄弱的事物进行“加固、增援或提振”。【避坑指南】在学术写作中，`bolster an argument/claim` 意为“增强论点的说服力”，并不等同于绝对证实（`prove / verify`），恰当使用能体现严谨的学术分寸感。","forms":["bolsters","bolstered","bolstering"],"partners":[{"id":"confidence","rel":"动+名","phrase":"bolster public confidence in the judiciary","note":"常用搭配：bolster public confidence in the judiciary（增强公众对司法系统的信心），与 confidence（信心、信任）构成高频「动+名」词伙。"},{"id":"resilience","rel":"动+名","phrase":"bolster macroeconomic resilience against shocks","note":"常用搭配：bolster macroeconomic resilience against shocks（增强抵御冲击的宏观经济韧性），与 resilience（韧性、恢复力）构成高频「动+名」词伙。"}]},{"id":"undermine","word":"undermine","ipa":{"uk":"/ˌʌndəˈmaɪn/","us":"/ˌʌndərˈmaɪn/"},"pos":"v.","definition":{"en":"To gradually weaken the strength, confidence, or effectiveness of something.","zh":"逐步削弱力量、信心或有效性。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["改善与恶化","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与评论语域；适用于大作文反驳段或负面影响分析（指从内部或根基处逐步瓦解权威、信任或有效性）","synonyms":[{"id":"diminish","note":"在 confidence / effectiveness 等语境中都表示削弱；undermine 常强调逐步、间接地破坏基础，diminish 只是程度减小。"},{"id":"debilitate","note":"比喻义中都削弱；undermine 常指逐渐侵蚀基础，debilitate 强调功能衰退。"},{"id":"erode","note":"undermine 强调从根基处暗中破坏；erode 强调表面与存量随时间慢慢磨损流失。"},{"id":"corrode","note":"undermine 侧重挖墙脚动摇根基；corrode 侧重从内部腐蚀溃烂。"}],"antonyms":[{"id":"foster","note":"反义对照：undermine 表“削弱”，而 foster 表“培养”，二者构成鲜明的语义对立。"},{"id":"bolster","note":"反义对照：undermine 表“削弱”，而 bolster 表“支持”，二者构成鲜明的语义对立。"},{"id":"restore","note":"在抽象语境中，restore public trust（恢复公众信任）与 undermine public trust（削弱信任）直接对立。"}],"collocations":[{"en":"undermine the credibility of public institutions","zh":"削弱公共机构的公信力"},{"en":"undermine social cohesion and solidarity","zh":"破坏社会凝聚力与团结"},{"en":"subtly undermine the effectiveness of a policy","zh":"暗中削弱政策的有效性"},{"en":"undermine the foundational premise of an argument","zh":"动摇论点的基本前提"}],"examples":[{"type":"IELTS","en":"Inconsistent enforcement of environmental levies can undermine the credibility of public institutions, especially when multinational polluters receive exemptions.","zh":"环境税执法不一致会削弱公共机构的公信力，尤其是当跨国污染企业获得豁免时。","highlights":["undermine the credibility of public institutions"]},{"type":"IELTS","en":"Over-reliance on extrinsic financial rewards in primary schools may inadvertently undermine children's intrinsic curiosity and love of learning.","zh":"在小学阶段过度依赖外部物质奖励，可能会在无意中削弱儿童内在的好奇心与对学习的热爱。","highlights":["undermine children's intrinsic curiosity"]},{"type":"GRE","en":"A substantial discrepancy between the predicted and observed trajectories would undermine the credibility of the theoretical model without wholly refuting it.","zh":"预测轨迹与观测轨迹之间的显著偏差会削弱该理论模型的可信度，但未必彻底推翻它。","highlights":["undermine the credibility of"]}],"note":"【句型框架】常用 `undermine the credibility/efficacy/authority/foundations of X`（动摇/削弱 X 的可信度/效力/权威/根基）。【高阶替换】与 `underpin`（加固地基）恰好构成词源与语义上的完美反义词（`under-` 在底下 + `mine` 挖地道破坏根基）；相比 `damage / weaken`，`undermine` 更强调隐蔽地、渐进地从内部或根基处掏空事物的稳定性或权威性。【避坑指南】在 GRE 阅读与学术写作中要注意程度差异：`undermine an argument` 指“削弱论据支持力”，程度弱于 `refute / disprove`（彻底驳倒或证伪）。","forms":["undermines","undermined","undermining"],"partners":[{"id":"credibility","rel":"动+名","phrase":"undermine the credibility of public institutions","note":"常用搭配：undermine the credibility of public institutions（削弱公共机构的公信力），与 credibility（公信力、可信性）构成高频「动+名」词伙。"},{"id":"cohesion","rel":"动+名","phrase":"undermine social cohesion and solidarity","note":"常用搭配：undermine social cohesion and solidarity（破坏社会凝聚力与团结），与 cohesion（凝聚力）构成高频「动+名」词伙。"}]},{"id":"detrimental","word":"detrimental","ipa":{"uk":"/ˌdetrɪˈmentəl/","us":"/ˌdetrɪˈmentəl/"},"pos":"adj.","definition":{"en":"Causing harm or disadvantage.","zh":"有害的；不利的。"},"libraries":["writing"],"topics":["健康与生活","社会与经济"],"functions":["利弊权衡","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与议论语域；大作文全话题通用的负面影响核心评价词，常用于因果论证段与主题句","synonyms":[{"id":"deleterious","note":"近义但更正式，常见于健康、环境与功能损害。"},{"id":"pernicious","note":"有害义接近，但 pernicious 更强调严重而隐蔽的危害。"},{"id":"adverse","note":"二者均表不利的；detrimental 强调造成实质性损害（常接 to），adverse 常作定语修饰效果、反应或环境（如 adverse effects）。"},{"id":"harmful","note":"harmful 为通用词，泛指造成伤害的；detrimental 语域更正式，多用于政策评估与学术论述。"}],"antonyms":[{"id":"beneficial","note":"反义对照：detrimental 表“不利的”，而 beneficial 表“有利的”，二者构成鲜明的语义对立。"},{"id":"advantageous","note":"反义对照：detrimental 表“不利的”，而 advantageous 表“有利的”，二者构成鲜明的语义对立。"},{"id":"salutary","note":"反义对照：detrimental 表“不利的”，而 salutary 表“有益的”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"detrimental to public health","zh":"有害于公共健康"},{"en":"have a detrimental effect on","zh":"对……产生不利影响"},{"en":"prove detrimental in the long run","zh":"长远来看被证明是有害的"},{"en":"environmentally detrimental practices","zh":"损害环境的做法"}],"examples":[{"type":"IELTS","en":"Persistent noise pollution can be detrimental to public health, making effective urban planning an essential complement to individual changes in behaviour.","zh":"持续的噪声污染可能有害于公共健康，因此有效的城市规划是个人行为改变的重要补充。","highlights":["detrimental to public health"]},{"type":"IELTS","en":"Obsessive reliance on standardised testing prioritizes rote memorisation to the detriment of creative inquiry and emotional resilience.","zh":"对标准化考试的盲目依赖将死记硬背置于优先地位，却以损害创造性探究和心理韧性为代价。","highlights":["to the detriment of"]},{"type":"GRE","en":"The mutation was detrimental under experimental conditions, but the researchers cautioned against assuming that its effects would remain constant across environments.","zh":"该突变在实验条件下是不利的，但研究人员提醒，不应假定其影响在不同环境中保持不变。","highlights":["was detrimental under"]}],"note":"【句型框架】① X is profoundly detrimental to Y / exerts a detrimental impact on Y（X 对 Y 极具危害/产生不利影响）；② pursue short-term gains to the detriment of long-term sustainability（追求短期利益却以损害长期可持续性为代价，名词短语 to the detriment of 极为高阶）。【高阶替换】全面替换 bad for、harmful to、do harm to；相比 devastating/catastrophic（毁灭性的、灾难性的，程度极重）和 damaging（侧重造成具体损伤），detrimental 客观、冷静地指出“造成不利影响或耗损”，适用面最广。【避坑指南】介词搭配极易出错：作表语时必须接介词 to（be detrimental to health），切勿受 bad for 影响写成 detrimental for；但修饰名词 effect/impact 时，后面的介词取决于该名词，应写 detrimental effects on health。","forms":["detriment","detrimentally"],"partners":[{"id":"health","rel":"形+名","phrase":"detrimental to public health","note":"常用搭配：detrimental to public health（有害于公共健康），与 health（健康）构成高频「形+名」词伙。"},{"id":"effect","rel":"形+名","phrase":"have a detrimental effect on","note":"常用搭配：have a detrimental effect on（对……产生不利影响），与 effect（影响、效果）构成高频「形+名」词伙。"}]},{"id":"deleterious","word":"deleterious","ipa":{"uk":"/ˌdelɪˈtɪəriəs/","us":"/ˌdelɪˈtɪriəs/"},"pos":"adj.","definition":{"en":"Causing damage, especially to health or normal functioning.","zh":"有害的；尤指损害健康或正常功能的。"},"libraries":["writing"],"topics":["健康与生活","自然与环境"],"functions":["改善与恶化","利弊权衡"],"frequency":{"ielts":5,"gre":5},"register":"高度正式学术与科学医学语域；常用于公共卫生、环境毒理学、心理健康及科技伦理议题的深度危害分析","synonyms":[{"id":"detrimental","note":"近义，适用范围更广、语体稍常见。"},{"id":"pernicious","note":"同属负面影响词；pernicious 常强调隐蔽、持续的危害。"},{"id":"adverse","note":"deleterious 语气极正式，强调对健康、认知或生态造成深层毒害；adverse 强调方向相反、产生不利影响。"},{"id":"harmful","note":"二者均表有害的；deleterious 为高阶学术词，多修饰长期或隐蔽的损害，harmful 为日常与学术通用词。"}],"antonyms":[{"id":"beneficial","note":"反义对照：deleterious 表“有害的”，而 beneficial 表“有利的”，二者构成鲜明的语义对立。"},{"id":"advantageous","note":"反义对照：deleterious 表“有害的”，而 advantageous 表“有利的”，二者构成鲜明的语义对立。"},{"id":"salutary","note":"反义对照：deleterious 表“有害的”，而 salutary 表“有益的”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"deleterious effects on cognitive development","zh":"对认知发展的有害影响"},{"en":"deleterious consequences for ecosystems","zh":"对生态系统的有害后果"},{"en":"a deleterious genetic mutation","zh":"有害的基因突变"},{"en":"exert a deleterious influence on","zh":"对……施加有害影响"}],"examples":[{"type":"IELTS","en":"Governments should consider the potentially deleterious effects of chronic sleep deprivation when designing policies on working hours and public transport.","zh":"政府在制定工时和公共交通政策时，应考虑长期睡眠不足可能带来的有害影响。","highlights":["deleterious effects"]},{"type":"IELTS","en":"Prolonged exposure to algorithmically curated echo chambers can exert a deleterious influence on civic discourse and democratic tolerance.","zh":"长期暴露于算法精心编排的信息茧房中，会对公共讨论和民主宽容产生隐蔽而深远的有害影响。","highlights":["exert a deleterious influence on"]},{"type":"GRE","en":"A deleterious mutation may persist in a population when its harmful effects emerge only after individuals have completed most of their reproduction.","zh":"如果有害影响仅在个体完成大部分繁殖之后才出现，有害突变就可能在种群中持续存在。","highlights":["A deleterious mutation"]}],"note":"【句型框架】① exert a deleterious effect/influence on X（对 X 产生有害影响）；② shield vulnerable populations from the deleterious consequences of X（保护脆弱人群免受 X 的有害后果侵害）。【高阶替换】harmful 与 detrimental 的C2级高雅学术升格词；相比 detrimental（泛指一切不利或有损的事物），deleterious 语体更庄重书面，尤指对“生命健康、心理机能、自然生态或社会肌体”造成渐进性、往往不易立刻察觉却深具破坏力的伤害。【避坑指南】一篇文章中若已使用 detrimental，可用 deleterious 实现完美同义替换以避免重复；但要注意它多作定语修饰抽象名词（deleterious effects/consequences/impact/mutations），较少用于日常琐事（不说 Missing the bus was deleterious）。","forms":["deleteriously"],"partners":[{"id":"effect","rel":"形+名","phrase":"deleterious effects on cognitive development","note":"常用搭配：deleterious effects on cognitive development（对认知发展的有害影响），与 effect（影响、作用）构成高频「形+名」词伙。"},{"id":"consequence","rel":"形+名","phrase":"deleterious consequences for ecosystems","note":"常用搭配：deleterious consequences for ecosystems（对生态系统的有害后果），与 consequence（后果、结果）构成高频「形+名」词伙。"}]},{"id":"benign","word":"benign","ipa":{"uk":"/bɪˈnaɪn/","us":"/bɪˈnaɪn/"},"pos":"adj.","definition":{"en":"Not harmful or threatening; sometimes gentle or favourable.","zh":"无害的、温和的；有时指有利的。"},"libraries":["writing"],"topics":["健康与生活","自然与环境"],"functions":["利弊权衡","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与医学评价语域；常用于政策评估、科技伦理（表面无害 vs 潜在风险）及生态环境条件描述","synonyms":[{"id":"innocuous","note":"二者均表无害的；benign 常指性质温和、良性或对环境友好，innocuous 常指言行或物质本身缺乏杀伤力、不会冒犯人。"},{"id":"inoffensive","note":"benign 侧重温和无害甚至产生良性影响；inoffensive 侧重不刺耳、不招人反感。"}],"antonyms":[{"id":"pernicious","note":"反义对照：benign 表温和无害的、良性的，而 pernicious 表危害严重且隐蔽的。"},{"id":"deleterious","note":"反义对照：benign 表无害的，而 deleterious 表毒害身心或生态功能的。"},{"id":"malignant","note":"反义对照：benign 表良性的、温和无害的，而 malignant 表恶性的、恶毒的。"}],"collocations":[{"en":"seemingly benign practices","zh":"看似无害的做法"},{"en":"environmentally benign alternatives","zh":"对环境无害的替代方案"},{"en":"a benign influence on","zh":"对……温和而有利的影响"},{"en":"a benign explanation","zh":"无害的/善意的解释"}],"examples":[{"type":"IELTS","en":"A policy presented as a benign influence on consumer choice may still have unintended consequences for households with limited financial resources.","zh":"被描述为对消费者选择有温和影响的政策，仍可能给经济资源有限的家庭带来意想不到的后果。","highlights":["a benign influence"]},{"type":"IELTS","en":"Even seemingly benign data-collection practices by smartphone applications can, when aggregated across platforms, compromise personal privacy.","zh":"即便智能手机应用程序看似无害的数据收集做法，一旦跨平台汇总，也可能会危及个人隐私。","highlights":["seemingly benign"]},{"type":"GRE","en":"The researchers initially favoured a benign explanation for the anomaly, but subsequent measurements suggested that the underlying process required closer examination.","zh":"研究人员起初倾向于认为该异常有无害的解释，但后续测量提示需要更仔细地考察其机制。","highlights":["a benign explanation"]}],"note":"【句型框架】① Even seemingly benign X can have unintended negative consequences（即便看似无害的 X 也可能产生始料未及的负面后果——用于隐私、消费主义或环境话题的深度剖析）；② transition toward environmentally benign materials（向环境友好型无害材料转型）。【高阶替换】精准替代 harmless、gentle、not dangerous；与反义词 malignant（恶性的、有害的）或 pernicious（阴险有害的）相对应，benign 既可指医学上的“良性”，也可在社会科学中指“温和无害的、有利的”。【避坑指南】注意区分“无害（benign）”与“大有裨益（beneficial）”：同含词根 bene-（好），但 benign 侧重“温和、不造成伤害或威胁”，而 beneficial 强调“积极产生益处和成效”，切勿将 benign policy 直接当成“极有成效的政策”滥用。","forms":["benignly"],"partners":[{"id":"practice","rel":"形+名","phrase":"seemingly benign practices","note":"常用搭配：seemingly benign practices（看似无害的做法），与 practice（做法、实践）构成高频「形+名」词伙。"},{"id":"influence","rel":"形+名","phrase":"a benign influence on","note":"常用搭配：a benign influence on（对……温和而有利的影响），与 influence（影响）构成高频「形+名」词伙。"}]},{"id":"proliferate","word":"proliferate","ipa":{"uk":"/prəˈlɪfəreɪt/","us":"/prəˈlɪfəreɪt/"},"pos":"v.","definition":{"en":"To multiply or increase rapidly in number.","zh":"迅速增殖；数量迅速增加。"},"libraries":["writing"],"topics":["科技与教育","自然与环境"],"functions":["数量与趋势","因果与影响"],"frequency":{"ielts":5,"gre":5},"register":"正式学术语域；常用于科技、媒体、城市化及生态话题中描述事物数量呈爆发式增长或迅速扩散","synonyms":[{"id":"multiply","note":"在数量迅速增加、细胞增殖等语境中近义；proliferate 更正式，multiply 还可作及物动词。"},{"id":"mushroom","note":"proliferate 是最高级的学术同义词（增殖、激增）；mushroom 更具画面感，形容短期内到处冒出来。"},{"id":"burgeon","note":"proliferate 强调数量裂变繁殖；burgeon（词源为嫩芽萌发）强调生机勃勃地崛起与壮大。"}],"antonyms":[{"id":"dwindle","note":"数量变化方向相反：迅速增多与逐渐减少；速度含义并不完全对称。"},{"id":"diminish","note":"在数量语境中表示减少；diminish 的程度、规模或重要性减少义更广。"},{"id":"stagnate","note":"proliferate 迅速扩张增殖，与死水般停滞的 stagnate 相反。"}],"collocations":[{"en":"proliferate rapidly","zh":"迅速增殖/激增"},{"en":"proliferate across digital platforms","zh":"在数字平台上大量涌现"},{"en":"proliferate unchecked","zh":"不受控制地蔓延/激增"},{"en":"the proliferation of misinformation","zh":"虚假信息的扩散"}],"examples":[{"type":"IELTS","en":"When misleading claims proliferate across digital platforms, schools should equip students with the skills needed to evaluate sources and identify unsupported assertions.","zh":"当误导性说法在数字平台上大量涌现时，学校应培养学生评估来源、识别无依据断言所需的技能。","highlights":["proliferate across digital platforms"]},{"type":"IELTS","en":"Allowed to proliferate unchecked on the urban periphery, informal settlements often lack basic sanitation infrastructure and potable water.","zh":"若任由非正式定居点在城市边缘不受控制地激增，这些区域往往缺乏基本的卫生基础设施和饮用水。","highlights":["proliferate unchecked"]},{"type":"GRE","en":"Cells may proliferate rapidly when regulatory signals are disrupted, although the resulting growth depends on the availability of nutrients and space.","zh":"当调控信号受到干扰时，细胞可能迅速增殖，不过实际生长取决于营养和空间是否充足。","highlights":["proliferate rapidly"]}],"note":"【句型框架】① As X continues to proliferate across..., ...（随着 X 在……持续大量涌现）；② curb / stem the proliferation of X（遏制 X 的泛滥/扩散，常用于名词形式）。【高阶替换】大幅升级 increase quickly、grow fast、spread everywhere；相比 mushroom（虽形象但偏新闻口语）和 accumulate（侧重逐步累积），proliferate 源自生物学“细胞增殖”，强调个体数量在短时间内成倍繁衍、遍地开花。【避坑指南】proliferate 是纯粹的不及物动词（vi.），绝对不能带宾语，也没有被动语态（切忌写出 are proliferated 或 proliferate fake news）；主语必须是可数名词复数或群体概念（如 platforms, weapons, rumours），不可用于单一数值（不说 the rate proliferated）。","forms":["proliferates","proliferated","proliferating","proliferation"],"partners":[{"id":"platform","rel":"动+名","phrase":"proliferate across digital platforms","note":"常用搭配：proliferate across digital platforms（在数字平台上大量涌现），与 platform（平台）构成高频「动+名」词伙。"},{"id":"device","rel":"动+名","phrase":"digital devices proliferate rapidly","note":"常用搭配：digital devices proliferate rapidly（数字设备迅速普及激增），与 device（设备、装置）构成高频「动+名」词伙。"}]},{"id":"dwindle","word":"dwindle","ipa":{"uk":"/ˈdwɪndəl/","us":"/ˈdwɪndəl/"},"pos":"v.","definition":{"en":"To become gradually smaller in number, size, or amount.","zh":"数量、规模或程度逐渐减少。"},"libraries":["writing"],"topics":["自然与环境","社会与经济"],"functions":["数量与趋势","改善与恶化"],"frequency":{"ielts":5,"gre":5},"register":"正式学术语域；常用于资源环境、人口结构及文化遗产话题中描述存量日渐枯竭或规模逐步萎缩","synonyms":[{"id":"diminish","note":"数量减少义接近；dwindle 强调逐渐变少，常暗示趋于不足；diminish 的范围更广，也可作及物动词。"},{"id":"decline","note":"数量逐渐下降时近义；dwindle 往往突出变得越来越少。"},{"id":"wane","note":"dwindle 常指具体数量或存量日渐缩减；wane（本义月亏）常指抽象权势、声望或热情消退。"},{"id":"ebb","note":"dwindle 偏重数量变少；ebb 偏重气势、活力或情绪衰退。"}],"antonyms":[{"id":"proliferate","note":"反义对照：dwindle 表“变小”，而 proliferate 表“激增”，二者构成鲜明的语义对立。"},{"id":"multiply","note":"反义对照：dwindle 表“变小”，而 multiply 表“增加”，二者构成鲜明的语义对立。"},{"id":"burgeon","note":"反义对照：dwindle 表数量或规模日渐萎缩减少，而 burgeon 表蓬勃发展、急剧增长。"}],"collocations":[{"en":"dwindling natural resources","zh":"日益枯竭的自然资源"},{"en":"dwindle to a mere fraction","zh":"萎缩至原先的一小部分"},{"en":"dwindling rural populations","zh":"日益减少的农村人口"},{"en":"dwindling public support","zh":"逐渐减弱的公众支持"}],"examples":[{"type":"IELTS","en":"As natural resources dwindle, governments face growing pressure to encourage efficient consumption and develop alternatives to environmentally damaging production methods.","zh":"随着自然资源逐渐减少，政府面临越来越大的压力，需要鼓励高效消费并发展替代破坏环境生产方式的方案。","highlights":["natural resources dwindle"]},{"type":"IELTS","en":"With the number of native speakers dwindling with each passing generation, hundreds of indigenous languages are now on the brink of extinction.","zh":"随着母语使用者人数代代减少，数百种土著语言如今正处于灭绝的边缘。","highlights":["native speakers dwindling"]},{"type":"GRE","en":"Public support began to dwindle as promised benefits failed to materialise, suggesting that initial enthusiasm depended heavily on expectations of rapid improvement.","zh":"随着承诺的好处未能实现，公众支持开始减弱，表明最初的热情很大程度上取决于对迅速改善的期待。","highlights":["began to dwindle"]}],"note":"【句型框架】① As X continues to dwindle, ...（随着存量 X 持续萎缩……）；② With + 名词 + dwindling at an alarming rate, ...（with 独立主格结构，常用于环境或文化保护类文章开头揭示紧迫性）。【高阶替换】精准替代 become less and less、gradually decrease；相比 plummet（瞬间暴跌）和 wane（侧重权势、光芒或热情由盛转衰），dwindle 强调“原本充足的事物一点点消耗、缩水，直至所剩无几”。【避坑指南】dwindle 是严格的不及物动词（vi.），主语只能是正在减少的资源、储量或群体本身（Resources dwindle），切勿把人或政府作主语写成及物用法（不能写 Humans dwindle natural resources，表“消耗殆尽”应使用及物动词 deplete）。","forms":["dwindles","dwindled","dwindling"],"partners":[{"id":"resource","rel":"动+名","phrase":"dwindling natural resources","note":"常用搭配：dwindling natural resources（日益枯竭的自然资源），与 resource（资源）构成高频「动+名」词伙。"},{"id":"population","rel":"动+名","phrase":"dwindling rural populations","note":"常用搭配：dwindling rural populations（日益减少的农村人口），与 population（人口）构成高频「动+名」词伙。"}]},{"id":"plausible","word":"plausible","ipa":{"uk":"/ˈplɔːzəbəl/","us":"/ˈplɔːzəbəl/"},"pos":"adj.","definition":{"en":"Seeming reasonable or likely to be true, without being established as true.","zh":"看似合理的；貌似可信但未获证实的。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["观点评价","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式（审慎推理与假说评估）· 常用于大作文分析段引出合理推论，或在驳论段欲抑先扬（承认表面合理性，再指出证据不足）。","synonyms":[{"id":"credible","note":"都可表示可信；credible 更强调值得相信，plausible 强调表面合理。"},{"id":"persuasive","note":"persuasive 强调能说服他人采纳；plausible 强调表面上合情合理、貌似可信。"},{"id":"tenable","note":"plausible 指表面看似合理的；tenable 指在遭遇质疑和反驳时依然“守得住、站得住脚的”。"},{"id":"conceivable","note":"近义辨析：二者在“可信”义项上相通；plausible 侧重“似有道理的”，conceivable 侧重“可能的”。"}],"antonyms":[{"id":"implausible","note":"直接反义：不太合理或不大可能为真。"},{"id":"dubious","note":"存疑、缺乏可靠性；并非始终表示不可能。"},{"id":"unlikely","note":"反义对照：plausible 表貌似合理可信的，而 unlikely 表不太可能发生的。"}],"collocations":[{"en":"a superficially plausible explanation","zh":"表面上看似合理的解释"},{"en":"formulate a plausible hypothesis","zh":"提出一个合理的假设"},{"en":"sound intuitively plausible","zh":"听起来在直觉上合乎情理"},{"en":"a plausible alternative account","zh":"言之成理的替代性解释"}],"examples":[{"type":"IELTS","en":"A plausible explanation for declining civic participation in metropolitan areas is that gruelling commuting schedules leave residents with scant energy for neighbourhood governance.","zh":"大都市地区公民参与度下降的一个合理解释是，繁重的通勤安排使居民几乎没有精力参与社区治理。","highlights":["A plausible explanation"]},{"type":"IELTS","en":"Although imposing a blanket ban on private vehicles in city centres sounds intuitively plausible as an anti-pollution measure, it would severely disrupt small retail businesses without prior transit upgrades.","zh":"尽管在市中心全面禁行私家车作为反污染措施听起来在直觉上合乎情理，但在公共交通尚未升级前，这会严重冲击小型零售企业。","highlights":["sounds intuitively plausible"]},{"type":"GRE","en":"The palaeontologist's predation hypothesis remains entirely plausible, yet the fragmentary fossil record cannot distinguish it from competing climatic accounts that predict an identical extinction pattern.","zh":"这位古生物学家的捕食假说依然完全貌似合理，但零碎的化石记录无法将其与预测相同灭绝模式的竞争性气候解释区分开来。","highlights":["remains entirely plausible"]}],"note":"【句型框架】常用于评价解释或假说：A plausible explanation for X is that...；或用于让步从句：While the proposal seems superficially plausible, empirical scrutiny reveals...。【高阶替换】替代基础词 reasonable / believable / possible；与近义词 credible（侧重信息来源或证人本身可靠）和 valid（逻辑形式或科学上确凿有效）不同，plausible 强调“表面上或逻辑上讲得通、貌似可信，但尚待最终证实”。【避坑指南】切勿将 plausible 等同于 proven / true（已证实为真），也切勿与绝对贬义词 specious（似是而非、实则荒谬）混为一谈！plausible 本身偏中性至温和肯定，若想表达负面含义需加副词修饰（如 merely / superficially plausible）。","forms":["plausibility","plausibly"],"partners":[{"id":"hypothesis","rel":"形+名","phrase":"formulate a plausible hypothesis","note":"常用搭配：formulate a plausible hypothesis（提出一个合理的假设），与 hypothesis（假说、假设）构成高频「形+名」词伙。"},{"id":"formulate","rel":"动+形","phrase":"formulate a plausible hypothesis","note":"常用搭配：formulate a plausible hypothesis（提出一个合理的假设），与 formulate（构想、提出）构成高频「动+形」词伙。"}]},{"id":"specious","word":"specious","ipa":{"uk":"/ˈspiːʃəs/","us":"/ˈspiːʃəs/"},"pos":"adj.","definition":{"en":"Seeming reasonable or correct on the surface but actually false or misleading.","zh":"似是而非的；表面合理但实则错误或误导的。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式且呈鲜明贬义（强势驳论与逻辑证伪）· 专用于大作文反驳段（Refutation），一针见血地揭露对方论点“外强中干、似是而非”。","synonyms":[{"id":"fallacious","note":"都可形容错误论证；specious 额外强调表面合理、具有迷惑性，fallacious 强调推理错误。"},{"id":"deceptive","note":"specious 的论点貌似正确却站不住脚；它属于 deceptive 的一种具体表现。"},{"id":"spurious","note":"都用于批驳错误论点；specious 强调表面合理但实则荒谬（金玉其外），spurious 强调虚假不真或因果不成立。"}],"antonyms":[{"id":"sound","note":"论证评价中直接对照：sound 有可靠理据，specious 只有表面的合理性而实际有误。"},{"id":"valid","note":"在一般论证评价中，valid 实质上成立，specious 则仅看似成立；须注意 valid 的形式逻辑专门义。"},{"id":"empirical","note":"specious 指似是而非、经不起实证检验的。"}],"collocations":[{"en":"a specious argument","zh":"似是而非的论点"},{"en":"expose specious reasoning","zh":"揭露似是而非的推理"},{"en":"a specious justification for","zh":"为……辩护的华而不实的借口"},{"en":"rest on a specious analogy","zh":"建立在似是而非的类比之上"}],"examples":[{"type":"IELTS","en":"The assertion that stringent environmental regulations inevitably stifle industrial competitiveness is a specious argument that ignores the immense export potential of clean energy technologies.","zh":"声称严格的环境监管必然扼杀工业竞争力的说法是一个似是而非的论点，它忽视了清洁能源技术巨大的出口潜力。","highlights":["a specious argument"]},{"type":"IELTS","en":"Tech conglomerates often invoke user convenience as a specious justification for harvesting vast quantities of biometric and behavioural data without explicit authorisation.","zh":"科技巨头经常拿用户便利作为华而不实的借口，在未经明确授权的情况下收集海量生物特征与行为数据。","highlights":["a specious justification for"]},{"type":"GRE","en":"The essay systematically dismantles the lobby's specious reasoning, demonstrating that the cited correlation between deregulation and wage growth was an artefact of inflationary accounting.","zh":"该文系统地驳斥了游说团体似是而非的推理，证明其所引用的放松监管与工资增长之间的相关性只是通胀会计核算造成的人为假象。","highlights":["specious reasoning"]}],"note":"【句型框架】经典驳论句式：The claim that + 从句 + is a specious argument that overlooks...；或 Critics rightly dismiss X as a specious justification for Y。【高阶替换】用于强力替换 misleading / false / deceptive；与近义词 fallacious（侧重逻辑推导过程存在漏洞或谬误）相比，specious 的核心精髓在于“极具欺骗性的表面合理性（deceptively attractive/plausible on the surface, but fundamentally false）”。【避坑指南】严禁将 specious 当作 plausible（貌似合理的）的同义词使用！一旦用 specious 修饰某个观点，意味着写作者已经对该观点作出了“绝对错误且具有误导性”的否定判决，切忌在赞同某观点时误用。","forms":["speciously","speciousness"],"partners":[{"id":"argument","rel":"形+名","phrase":"a specious argument","note":"常用搭配：a specious argument（似是而非的论点），与 argument（论点、论证）构成高频「形+名」词伙。"},{"id":"reasoning","rel":"形+名","phrase":"expose specious reasoning","note":"常用搭配：expose specious reasoning（揭露似是而非的推理），与 reasoning（推理、论证）构成高频「形+名」词伙。"}]},{"id":"fallacious","word":"fallacious","ipa":{"uk":"/fəˈleɪʃəs/","us":"/fəˈleɪʃəs/"},"pos":"adj.","definition":{"en":"Based on faulty reasoning or a mistaken belief.","zh":"推理错误的；基于谬误的。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（逻辑批判与方法论驳斥）· 适用于大作文驳论段剖析对方观点背后的逻辑谬误（如因果倒置、以偏概全或非黑即白）。","synonyms":[{"id":"specious","note":"都可用于错误论证；fallacious 强调推理有误，specious 强调虽有误但表面很有说服力。"},{"id":"indefensible","note":"fallacious 侧重逻辑推理包含谬误；indefensible 兼含逻辑上站不住脚与道义上不可原谅（morally indefensible）。"},{"id":"spurious","note":"在评价推理时同义；fallacious 强调包含逻辑谬误，spurious 强调证据或联系本身是假的。"}],"antonyms":[{"id":"valid","note":"在推理有效性语境中对照：有效推导与存在推理错误。"},{"id":"sound","note":"sound reasoning 可靠且有理据，fallacious reasoning 存在谬误。"},{"id":"irrefutable","note":"irrefutable 逻辑无懈可击，fallacious 充满逻辑谬误。"}],"collocations":[{"en":"rest on a fallacious assumption","zh":"建立在错误的假设之上"},{"en":"fallacious causal reasoning","zh":"错误的因果推理"},{"en":"a fundamentally fallacious premise","zh":"根本错误的逻辑前提"},{"en":"expose a fallacious deduction","zh":"揭示错误的推论"}],"examples":[{"type":"IELTS","en":"The belief that extending statutory working hours necessarily boosts national output rests on a fallacious assumption that time spent at a desk directly equates to cognitive productivity.","zh":"认为延长法定工时必然提升国家产出的信念，建立在“伏案时间直接等同于脑力生产率”这一错误假设之上。","highlights":["rests on a fallacious assumption"]},{"type":"IELTS","en":"Equating higher university tuition fees with superior pedagogical quality involves fallacious causal reasoning, since much of the additional revenue is often diverted into administrative expansion.","zh":"将高昂的大学学费等同于卓越的教学质量涉及错误的因果推理，因为大部分额外收入往往被挪用于行政扩张。","highlights":["fallacious causal reasoning"]},{"type":"GRE","en":"The demographic forecast follows from a fundamentally fallacious premise that attributes an aggregate population trend to shifting individual preferences while ignoring cohort replacement effects.","zh":"这一人口预测源于一个根本错误的前提：它将总体人口趋势归因于个人偏好的转变，却忽视了世代更替效应。","highlights":["a fundamentally fallacious premise"]}],"note":"【句型框架】黄金驳论模板：The belief/contention that... rests on a fallacious assumption/premise that...（认为……的观点建立在……这一错误假设之上）。【高阶替换】升级 wrong / mistaken / illogical；源自名词 fallacy（逻辑谬误），相比 erroneous（泛指事实或计算出错），fallacious 专门针对“推理链条、论证结构或前提假设违背逻辑规律”。【避坑指南】注意与 specious 和 deceptive 区分：fallacious 聚焦于逻辑或推理本身的客观谬误，并不一定暗示论证者怀有蓄意欺骗的主观恶意；此外不要用它修饰具体的人（如不能写 *He is fallacious，应写 His argument is fallacious）。","forms":["fallacy","fallacies","fallaciously"],"partners":[{"id":"assumption","rel":"形+名","phrase":"rest on a fallacious assumption","note":"常用搭配：rest on a fallacious assumption（建立在错误的假设之上），与 assumption（假设、假定）构成高频「形+名」词伙。"},{"id":"reasoning","rel":"形+名","phrase":"fallacious causal reasoning","note":"常用搭配：fallacious causal reasoning（错误的因果推理），与 reasoning（推理、论证）构成高频「形+名」词伙。"}]},{"id":"unequivocal","word":"unequivocal","ipa":{"uk":"/ˌʌnɪˈkwɪvəkəl/","us":"/ˌʌnɪˈkwɪvəkəl/"},"pos":"adj.","definition":{"en":"Clear and definite, leaving no doubt about meaning or intention.","zh":"明确的；毫不含糊的；不留疑问的。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["让步转折","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（鲜明立场与确凿定性）· 尤适用于大作文引言段亮明坚定立场、结论段呼吁政府作出明确承诺，或评估科学证据的确定性。","synonyms":[{"id":"unambiguous","note":"明确义接近；unequivocal support 强调毫不保留的支持，unambiguous 强调不会被误解。"},{"id":"incontrovertible","note":"unequivocal 强调态度或表述清晰明确、毫不含糊；incontrovertible 强调事实本身铁证如山、无法争辩。"},{"id":"explicit","note":"unequivocal 强调态度坚定、毫不含糊、不留任何怀疑余地；explicit 强调话语直白明确说出而非暗示。"}],"antonyms":[{"id":"ambiguous","note":"反义对照：unequivocal 表“毫无疑问的”，而 ambiguous 表“含糊其辞的”，二者构成鲜明的语义对立。"},{"id":"equivocal","note":"反义对照：unequivocal 表“毫无疑问的”，而 equivocal 表“暧昧的”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"make an unequivocal commitment to","zh":"对……作出明确无误的承诺"},{"en":"express unequivocal condemnation of","zh":"对……表达毫不含糊的谴责"},{"en":"provide unequivocal evidence that","zh":"提供明确无疑的证据表明……"},{"en":"send an unequivocal message to","zh":"向……传递明确无误的信号"}],"examples":[{"type":"IELTS","en":"National governments must make an unequivocal commitment to phasing out coal-fired power plants if they wish to instil confidence in green energy investors.","zh":"各国政府如果希望提振绿色能源投资者的信心，就必须对逐步淘汰燃煤电厂作出明确无误的承诺。","highlights":["an unequivocal commitment to"]},{"type":"IELTS","en":"Enacting custodial sentences for corporate executives who falsify emissions data sends an unequivocal message that environmental fraud will not be tolerated.","zh":"对伪造排放数据的企业高管判处监禁，传递了一个毫不含糊的信号：环境欺诈绝不被容忍。","highlights":["sends an unequivocal message"]},{"type":"GRE","en":"The particle accelerator experiment did not yield unequivocal evidence for the supersymmetric model, inasmuch as several competing theoretical frameworks predicted comparable decay signatures.","zh":"该粒子加速器实验并未为超对称模型提供明确无疑的证据，因为若干竞争性理论框架也预测了相似的衰变特征。","highlights":["unequivocal evidence"]}],"note":"【句型框架】表态与呼吁的高分句式：Governments must make an unequivocal commitment to doing X；或 Policy Y sends an unequivocal message that...。【高阶替换】强力升级 clear / definite / unambiguous；由否定前缀 un- + equi-（相等）+ voc-（声音 voice）构成，反义词 equivocal 意为“模棱两可的、两面讨好的”，故 unequivocal 强调“立场坚定、绝无二话、不留任何含糊余地”。【避坑指南】与 explicit 区分：explicit 侧重“字面直接说出而非暗示”，而 unequivocal 侧重“态度坚定或证据确凿，排除一切游移与疑问”；在科学论述中修饰 evidence 时常用于否定句（did not provide unequivocal evidence），以体现学术严谨。","forms":["unequivocally"],"partners":[{"id":"commitment","rel":"形+名","phrase":"make an unequivocal commitment to","note":"常用搭配：make an unequivocal commitment to（对……作出明确无误的承诺），与 commitment（承诺、承担义务）构成高频「形+名」词伙。"},{"id":"evidence","rel":"形+名","phrase":"provide unequivocal evidence that","note":"常用搭配：provide unequivocal evidence that（提供明确无疑的证据表明……），与 evidence（证据）构成高频「形+名」词伙。"}]},{"id":"deplete","word":"deplete","ipa":{"uk":"/dɪˈpliːt/","us":"/dɪˈpliːt/"},"pos":"v.","definition":{"en":"To reduce the amount or supply of something substantially.","zh":"大量消耗；使储量明显减少。"},"libraries":["writing"],"topics":["自然与环境","社会与经济"],"functions":["数量与趋势","改善与恶化"],"frequency":{"ielts":5,"gre":5},"register":"正式环境科学与宏观经济语域；适用于大作文讨论自然资源枯竭、生态透支及公共财政消耗","synonyms":[{"id":"exhaust","note":"都表示耗用供应；exhaust 通常是完全耗尽，deplete 可只是大幅减少。"},{"id":"diminish","note":"数量减少义相近；deplete 强调消耗某种储备，diminish 适用范围更广。"},{"id":"drain","note":"deplete 侧重大量消耗自然资源或资金储备使其趋于枯竭；drain 侧重持续不断地抽干精力、财富或人才。"}],"antonyms":[{"id":"conserve","note":"反义对照：deplete 表大量消耗以致枯竭，而 conserve 表保育、节约使用以防耗损。"},{"id":"preserve","note":"反义对照：deplete 表耗减存量，而 preserve 表妥善保护、维持原状。"},{"id":"replenish","note":"最经典的反义搭配：deplete（耗尽/消耗资源）与 replenish（补充/再生资源）。"}],"collocations":[{"en":"deplete finite natural resources","zh":"消耗有限的自然资源"},{"en":"deplete subterranean groundwater reserves","zh":"耗减地下水储量"},{"en":"rapidly deplete the ozone layer","zh":"迅速消耗臭氧层"},{"en":"deplete state pension funds","zh":"耗尽国家养老基金"}],"examples":[{"type":"IELTS","en":"Intensive monoculture farming can rapidly deplete subterranean groundwater reserves when extraction consistently exceeds natural replenishment.","zh":"当抽取量持续超过自然补给量时，密集的单一作物农业会迅速耗减地下水储量。","highlights":["deplete subterranean groundwater reserves"]},{"type":"IELTS","en":"Unless circular-economy principles are adopted globally, unconstrained consumerism will continue to deplete finite natural resources at an unsustainable pace.","zh":"除非在全球范围内采纳循环经济原则，否则无节制的消费主义将以不可持续的速度继续消耗有限的自然资源。","highlights":["deplete finite natural resources"]},{"type":"GRE","en":"Prolonged exposure to thermal stress appeared to deplete cellular energy stores, leaving the marine organisms vulnerable to opportunistic pathogens.","zh":"长期暴露于热应激似乎消耗了细胞能量储备，使这些海洋生物极易受到机会性病原体的侵袭。","highlights":["deplete cellular energy stores"]}],"note":"【句型框架】常用于 `deplete finite/non-renewable resources`（消耗有限/不可再生资源），或用过去分词作定语 `severely depleted fish stocks`（严重枯竭的渔业资源）及名词化 `resource depletion`。【高阶替换】是环境与资源类话题替换 `use up / reduce / consume too much` 的核心学术词；与 `exhaust`（彻底用光归零）相比，`deplete` 强调使存量、储备或供应量大幅削减至危险水平。【避坑指南】宾语通常是“原本有一定储量的资源、资金或能量”（`reserves, stocks, funds, supplies`），不可用于缩减抽象比率或价格（不能写 `deplete the crime rate`）。","forms":["depletes","depleted","depleting","depletion"],"partners":[{"id":"resource","rel":"动+名","phrase":"deplete finite natural resources","note":"常用搭配：deplete finite natural resources（消耗有限的自然资源），与 resource（资源）构成高频「动+名」词伙。"},{"id":"fund","rel":"动+名","phrase":"deplete state pension funds","note":"常用搭配：deplete state pension funds（耗尽国家养老基金），与 fund（基金、资金）构成高频「动+名」词伙。"}]},{"id":"equity","word":"equity","ipa":{"uk":"/ˈekwəti/","us":"/ˈekwəti/"},"pos":"n.","definition":{"en":"Fairness in how people are treated and how opportunities or resources are distributed.","zh":"公平；待遇、机会或资源分配的公正性。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["社会结构","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式公共政策与社会学名词 · 雅思教育公平、医疗资源分配、税收调节及代际公正议题的核心概念词。","synonyms":[{"id":"fairness","note":"公平义近义；equity 更常用于制度与分配，fairness 的日常适用范围更广。"},{"id":"impartiality","note":"equity 侧重制度安排与资源分配结果的公平合理；impartiality 侧重裁决或评估过程中不偏不倚的中立态度。"},{"id":"justice","note":"equity 强调根据实际情况给予合理公允的待遇；justice 强调符合法律或道德准则的正义与公正。"}],"antonyms":[{"id":"inequity","note":"直接反义：不公或不公平分配。"},{"id":"injustice","note":"不公正，适用范围包括待遇、法律与制度。"},{"id":"stratification","note":"社会公平（equity）旨在消减因阶层分化带来的结构性不公。"}],"collocations":[{"en":"promote educational equity","zh":"促进教育公平"},{"en":"equity in healthcare resource allocation","zh":"医疗资源分配中的公正性"},{"en":"intergenerational equity","zh":"代际公平（对后代环境的公正责任）"},{"en":"achieve greater social and economic equity","zh":"实现更大程度的社会与经济公平"}],"examples":[{"type":"IELTS","en":"Genuine educational equity requires channelling additional funding to underprivileged schools rather than distributing identical per-pupil budgets regardless of socioeconomic context.","zh":"真正的教育公平要求向弱势学校倾斜额外资金，而非不顾社会经济背景地按生均发放完全相同的预算。","highlights":["educational equity"]},{"type":"IELTS","en":"Sustainable environmental policies are fundamentally a matter of intergenerational equity, ensuring that present consumption does not deplete the ecological capital of future citizens.","zh":"可持续的环境政策从根本上说是代际公平问题，确保当代的消费不会耗尽后代公民的生态资本。","highlights":["intergenerational equity"]},{"type":"GRE","en":"The legislative dispute centred on equity in resource allocation rather than aggregate output, exposing a philosophical rift between utilitarian efficiency and distributive justice.","zh":"这场立法争议的核心在于资源分配的公正性而非总产出，暴露出功利主义效率与分配正义之间的哲学裂痕。","highlights":["equity in resource allocation"]},{"type":"GRE","en":"Critics of regressive consumption taxes contend that such levies violate vertical equity by imposing a disproportionately heavier burden on low-income households.","zh":"累退式消费税的批评者认为，此类税种对低收入家庭施加了不成比例的沉重负担，违背了纵向公平原则。","highlights":["violate vertical equity"]}],"note":"【句型框架】不可数名词，常用于 `promote / advance social equity`（促进社会公平）或 `strike a balance between economic efficiency and distributive equity`（在经济效率与分配公平之间取得平衡）。【高阶替换】在公共政策语境中精准升级 `fairness` 并与 `equality` 形成深度辨析：`equality`（平等）指“每人分到完全相同数量的东西”，而 `equity`（公平/公正）指“根据不同群体的实际处境与起点差异提供差异化扶持，使其享有实质平等的机会”。【避坑指南】注意多义性：在金融商业语境中 `equity` 指“股权、净资产”（如 `private equity` 私募股权），而在雅思大作文中主要使用其“社会分配公正”之义；形容词为 `equitable`（公正合理的）。","forms":["equitable","equitably","equities"],"partners":[{"id":"promote","rel":"动+名","phrase":"promote educational equity","note":"常用搭配：promote educational equity（促进教育公平），与 promote（促进、推动）构成高频「动+名」词伙。"},{"id":"allocation","rel":"名+名","phrase":"equity in healthcare resource allocation","note":"常用搭配：equity in healthcare resource allocation（医疗资源分配中的公正性），与 allocation（分配、配置）构成高频「名+名」词伙。"}]},{"id":"sedentary","word":"sedentary","ipa":{"uk":"/ˈsedəntəri/","us":"/ˈsedənteri/"},"pos":"adj.","definition":{"en":"Involving much sitting and relatively little physical movement.","zh":"久坐的；身体活动较少的。"},"libraries":["writing"],"topics":["健康与生活","社会与经济"],"functions":["利弊权衡","环境描述"],"frequency":{"ielts":5,"gre":4},"register":"正式（公共卫生、现代都市生活与劳动方式）· 雅思健康、城市规划与科技办公类话题必背高频词，专指现代人缺乏体力活动的久坐状态。","synonyms":[{"id":"inactive","note":"在缺乏身体活动的语境中接近；sedentary 特别强调坐着，inactive 可包含其他不活动状态。"},{"id":"stationary","note":"sedentary 专指生活方式或工作性质需要长期久坐、缺乏身体活动的；stationary 指物体或状态保持静止不动的。"}],"antonyms":[{"id":"active","note":"反义对照：sedentary 表久坐少动的，而 active 表经常活动、积极活跃的。"},{"id":"energetic","note":"反义对照：sedentary 表久坐少动的，而 energetic 表精力充沛、充满活动活力的。"}],"collocations":[{"en":"lead an increasingly sedentary lifestyle","zh":"过着日益久坐少动的生活方式"},{"en":"the proliferation of sedentary occupations","zh":"久坐型职业的激增"},{"en":"curb sedentary screen-based behaviour","zh":"遏制久坐看屏幕的行为"},{"en":"combat the health hazards of sedentary routines","zh":"抗击久坐日常习惯的健康危害"}],"examples":[{"type":"IELTS","en":"Urban planners can counteract the health hazards of an increasingly sedentary lifestyle by integrating continuous cycling lanes and accessible green parks into residential districts.","zh":"城市规划者可以通过将连贯的自行车道和便捷的绿地公园融入居住区，来抵消日益久坐的生活方式所带来的健康危害。","highlights":["an increasingly sedentary lifestyle"]},{"type":"IELTS","en":"Employers can reduce sedentary behaviour among office staff by redesigning workplace routines, rather than assuming that subsidised gym memberships alone will alter daily habits.","zh":"雇主可以通过重新设计工作流程来减少办公室职员的久坐行为，而非假定仅靠补贴健身房会员卡就能改变日常习惯。","highlights":["sedentary behaviour"]},{"type":"GRE","en":"Holding a sedentary occupation does not automatically determine an individual's aggregate metabolic expenditure, since leisure-time physical activity may compensate for daytime inactivity.","zh":"从事久坐型职业并不自动决定一个人的总体代谢消耗，因为业余时间的体力活动可能会弥补白天的缺乏运动。","highlights":["sedentary occupation"]},{"type":"GRE","en":"Archaeobotanical evidence from the alluvial plain indicates that the transition to sedentary settlement preceded, rather than followed, the full domestication of cereal grains.","zh":"来自冲积平原的植物考古学证据表明，向定居聚落的过渡早于而非晚于谷物类作物的完全驯化。","highlights":["sedentary settlement"]}],"note":"【句型框架】健康类议论文王牌因果链：The proliferation of sedentary occupations, coupled with screen-based entertainment, has precipitated a surge in chronic metabolic disorders（久坐职业的普及加上屏幕娱乐，引发了慢性代谢疾病的激增）。【高阶替换】精准替代 sitting too much / physically inactive / desk-bound；词根 sed- / sid- 意为“坐（sit，同 reside 居住 / sediment 沉淀物）”。【避坑指南】一词多义跨越雅思与GRE：在雅思现代生活话题中，sedentary 意为“久坐少动的（a sedentary lifestyle）”；而在GRE人类学、考古学与生态学阅读中，sedentary 常指“（族群或物种）定居的、不迁徙的（反义词为 nomadic 游牧的 / migratory 迁徙的）”，阅读时务必根据学科背景准确切换！","forms":["sedentarily"],"partners":[{"id":"lifestyle","rel":"形+名","phrase":"lead an increasingly sedentary lifestyle","note":"常用搭配：lead an increasingly sedentary lifestyle（过着日益久坐少动的生活方式），与 lifestyle（生活方式）构成高频「形+名」词伙。"},{"id":"occupation","rel":"形+名","phrase":"the proliferation of sedentary occupations","note":"常用搭配：the proliferation of sedentary occupations（久坐型职业的激增），与 occupation（职业、工作）构成高频「形+名」词伙。"}]},{"id":"resilient","word":"resilient","ipa":{"uk":"/rɪˈzɪliənt/","us":"/rɪˈzɪliənt/"},"pos":"adj.","definition":{"en":"Able to recover or adapt effectively after difficulty, damage, or disruption.","zh":"有韧性的；能在冲击或困难后恢复或适应的。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["利弊权衡","改善与恶化"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与政策规划语域；常用于城市基建、气候适应、经济复苏及青少年心理健康话题的正面目标构建","synonyms":[{"id":"robust","note":"承受冲击的语境中近义；resilient 更强调受冲击后的恢复或适应，robust 更强调不易受损。"},{"id":"adaptable","note":"resilient 强调受冲击后迅速复原的韧性；adaptable 强调随环境变化调整自身的能力。"}],"antonyms":[{"id":"fragile","note":"容易因冲击破坏，与恢复力强对照。"},{"id":"vulnerable","note":"在应对冲击能力的语境中对照，但暴露于风险不一定意味着不能恢复。"},{"id":"susceptible","note":"抗逆力强、不易受损的（resilient）与易受伤害影响的（susceptible）相对。"}],"collocations":[{"en":"build resilient infrastructure","zh":"建设有韧性的基础设施"},{"en":"a resilient supply chain","zh":"具有抗冲击韧性的供应链"},{"en":"remain resilient in the face of adversity","zh":"在逆境面前保持韧性"},{"en":"cultivate emotional resilience","zh":"培养心理/情绪韧性"}],"examples":[{"type":"IELTS","en":"Resilient infrastructure should maintain essential services during disruption and support rapid recovery, rather than being judged solely by performance under ideal operating conditions.","zh":"有韧性的基础设施应在扰动期间维持基本服务并支持快速恢复，而不应仅按理想条件下的表现评价。","highlights":["Resilient infrastructure"]},{"type":"IELTS","en":"Experiencing manageable setbacks during childhood helps young people grow into emotionally resilient adults capable of navigating workplace pressures.","zh":"在童年时期经历可控的挫折，有助于年轻人成长为具备心理韧性、能够应对职场压力的成年人。","highlights":["emotionally resilient adults"]},{"type":"GRE","en":"The ecosystem proved resilient after a single disturbance, but repeated shocks shortened the recovery period and eventually altered the relationships among its dominant species.","zh":"该生态系统在一次扰动后表现出韧性，但反复冲击压缩了恢复时间，最终改变了优势物种之间的关系。","highlights":["proved resilient"]}],"note":"【句型框架】① foster a more resilient economy/ecosystem capable of withstanding external shocks（培育更能抵御外部冲击的韧性经济/生态系统）；② remain resilient in the face of adversity（面对逆境保持韧性）。【高阶替换】高级升级 strong、able to recover quickly、adaptable；特别注意与 resistant 和 tough 的细微差别：resistant（抗……的）强调“铁板一块、拒斥外力入侵”，而 resilient 本义为“弹回（re- + salire 跳）”，强调像弹簧或竹子一样“遭受冲击弯曲受损后，能够迅速反弹复原并调适再生”。【避坑指南】名词形式 resilience（如 build urban resilience, emotional resilience）在当代联合国政策文件与雅思范文中出镜率极高；搭配介词通常用 resilient to shocks 或 resilient in the face of crisis。","forms":["resilience","resiliently"],"partners":[{"id":"infrastructure","rel":"形+名","phrase":"build resilient infrastructure","note":"常用搭配：build resilient infrastructure（建设有韧性的基础设施），与 infrastructure（基础设施）构成高频「形+名」词伙。"},{"id":"adversity","rel":"形+名","phrase":"remain resilient in the face of adversity","note":"常用搭配：remain resilient in the face of adversity（在逆境面前保持韧性），与 adversity（逆境、困境）构成高频「形+名」词伙。"}]},{"id":"robust","word":"robust","ipa":{"uk":"/rəʊˈbʌst/","us":"/roʊˈbʌst/"},"pos":"adj.","definition":{"en":"Strong and able to function reliably despite stress, variation, or changing conditions.","zh":"强健的；在压力、变化或不同条件下仍可靠的。"},"libraries":["writing"],"topics":["科技与教育","社会与经济"],"functions":["让步转折","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与实证方法论语域；常用于呼吁建立健全监管制度、评价经济基本面强劲或论证科研证据稳健可靠","synonyms":[{"id":"resilient","note":"在应对冲击的系统语境中近义；robust 强调保持可靠，resilient 还强调受损后的恢复。"},{"id":"sturdy","note":"robust 侧重系统、证据或体质强健且抗冲击能力强；sturdy 侧重物体结构结实耐用或体格健壮。"},{"id":"vigorous","note":"robust 强调体系稳健可靠、经得起考验；vigorous 强调充满生机活力或推行措施果断有力。"}],"antonyms":[{"id":"fragile","note":"容易损坏或失效，与强健可靠相反。"},{"id":"vulnerable","note":"在系统容易受威胁损害的语境中对照，须说明具体威胁。"},{"id":"tenuous","note":"tenuous 脆弱单薄，robust 稳健强有力（如 a robust correlation vs a tenuous link）。"}],"collocations":[{"en":"a robust regulatory framework","zh":"健全强有力的监管框架"},{"en":"robust empirical evidence","zh":"稳健可靠的实证证据"},{"en":"maintain a robust public healthcare system","zh":"维持健全的公共医疗体系"},{"en":"robust to changes in assumptions","zh":"对假设条件变化具有统计稳健性"}],"examples":[{"type":"IELTS","en":"A robust regulatory framework should establish clear responsibilities and credible enforcement, so that environmental protection does not depend entirely on voluntary promises from individual firms.","zh":"健全的监管框架应确立明确责任和可信执法，使环境保护不完全依赖个别企业的自愿承诺。","highlights":["A robust regulatory framework"]},{"type":"IELTS","en":"Without robust empirical evidence demonstrating long-term safety, genetically modified organisms should not be released into open ecosystems.","zh":"在缺乏证明其长期安全性的稳健实证证据之前，转基因生物不应被释放到开放的生态系统中。","highlights":["robust empirical evidence"]},{"type":"GRE","en":"The result was robust to changes in assumptions about missing observations, although its magnitude varied when the researchers altered the definition of the outcome.","zh":"结果对缺失观察的假设变化具有稳健性，但当研究者改变结果变量定义时，其幅度发生变化。","highlights":["robust to changes in assumptions"]}],"note":"【句型框架】① establish a robust regulatory framework to oversee X（建立健全的监管框架以监督 X——大作文政府措施段黄金句型）；② This conclusion is supported by robust empirical evidence（该结论得到了稳健实证证据的支撑）。【高阶替换】精准替代 strong、solid、healthy；相比 vigorous（侧重充满活力和干劲）和 resilient（侧重受创后恢复），robust 兼有两大高分维度：一是制度、经济或体魄“强健有力、根基扎实”，二是统计学与科学研究中模型或证据“抗干扰、在改变参数假设时依然稳健成立”。【避坑指南】切勿将 robust 当成万能的 big 或 severe 来修饰负面事物（不说 a robust crime rate 或 a robust disaster）；在学术论文中，robust to X 意为“对干扰因素 X 不敏感/稳健”，切记介词用 to。","forms":["robustly","robustness"],"partners":[{"id":"framework","rel":"形+名","phrase":"a robust regulatory framework","note":"常用搭配：a robust regulatory framework（健全强有力的监管框架），与 framework（框架、体系）构成高频「形+名」词伙。"},{"id":"evidence","rel":"形+名","phrase":"robust empirical evidence","note":"常用搭配：robust empirical evidence（稳健可靠的实证证据），与 evidence（证据）构成高频「形+名」词伙。"}]},{"id":"autonomy","word":"autonomy","ipa":{"uk":"/ɔːˈtɒnəmi/","us":"/ɑːˈtɑːnəmi/"},"pos":"n.","definition":{"en":"The ability or right to make decisions and govern oneself.","zh":"自主权；自我决定或自我管理的能力与权利。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["社会结构","利弊权衡"],"frequency":{"ielts":5,"gre":5},"register":"正式核心学术名词 · 适用于雅思教育类（培养学生自主学习）、职场类（员工自主权与远程办公）、科技伦理及地方治理议题。","synonyms":[{"id":"independence","note":"自主与独立义接近；autonomy 强调决策权，independence 还可指经济上不依赖他人。"},{"id":"liberty","note":"autonomy 侧重群体或个体自我管理、独立决策的自主权；liberty 侧重免受专制束缚的基本自由权。"},{"id":"freedom","note":"autonomy 强调机构或个人在职责范围内独立作主；freedom 为广义的自由。"}],"antonyms":[{"id":"dependence","note":"在决策受他人支配的语境中相反；接受帮助或资金不一定消除 autonomy。"},{"id":"reliance","note":"在依靠外部决定或支持的语境中对照；二者在现实中可并存。"}],"collocations":[{"en":"foster learner autonomy in the classroom","zh":"在课堂上培养学习者自主性"},{"en":"exercise greater professional autonomy","zh":"行使更大的职业自主权"},{"en":"infringe upon bodily or personal autonomy","zh":"侵犯身体或个人自主权"},{"en":"grant local authorities fiscal autonomy","zh":"赋予地方政府财政自主权"}],"examples":[{"type":"IELTS","en":"Learner autonomy flourishes when educators guide students to formulate their own research questions rather than relying exclusively on rote memorisation.","zh":"当教育者引导学生提出自己的研究问题而非单纯依赖死记硬背时，学习者自主性便会蓬勃发展。","highlights":["Learner autonomy"]},{"type":"IELTS","en":"Granting employees greater professional autonomy over their schedules and workflows often boosts intrinsic motivation and reduces burnout.","zh":"赋予员工对工作日程和流程更大的职业自主权，往往能提升内在动力并减少职业倦怠。","highlights":["greater professional autonomy"]},{"type":"GRE","en":"Municipal autonomy expanded in constitutional statute while remaining severely constrained in practice by fiscal arrangements that left cities dependent on central grants.","zh":"市政自主权在宪政法规层面有所扩大，但在实践中仍受到财政安排的严重制约，使城市依赖于中央拨款。","highlights":["Municipal autonomy"]},{"type":"GRE","en":"Bioethicists contend that persuasive digital architectures can subtly subvert user autonomy by exploiting cognitive biases before conscious deliberation occurs.","zh":"生物伦理学家认为，诱导性的数字架构可以在有意识的深思熟虑发生之前利用认知偏差，在不知不觉中颠覆用户的自主权。","highlights":["subvert user autonomy"]}],"note":"【句型框架】不可数名词，常构成 `grant / afford sb greater autonomy over sth`（赋予某人对某事更大的自主权）或 `foster / undermine personal autonomy`（培养/削弱个人自主性）。【高阶替换】升级泛泛的 `freedom` 或 `independence`。`freedom` 语义过于宽泛（指不受约束），`independence` 强调“不依赖他人、独立生存”，而 `autonomy`（词根 `auto` 自己 + `nomos` 法则）专指“在制度或伦理框架内自我管理、独立作出理性决定的权利与能力”。【避坑指南】不要加不定冠词 `an autonomy`；其形容词 `autonomous` 既可指“有自主权的（人/机构）”，也可指“自动驾驶/自主运行的（机器，如 `autonomous vehicles`）”。","forms":["autonomous","autonomously"],"partners":[{"id":"foster","rel":"动+名","phrase":"foster learner autonomy in the classroom","note":"常用搭配：foster learner autonomy in the classroom（在课堂上培养学习者自主性），与 foster（培养、促进）构成高频「动+名」词伙。"},{"id":"exercise","rel":"动+名","phrase":"exercise greater professional autonomy","note":"常用搭配：exercise greater professional autonomy（行使更大的职业自主权），与 exercise（行使、运用）构成高频「动+名」词伙。"}]},{"id":"segregate","word":"segregate","ipa":{"uk":"/ˈseɡrɪɡeɪt/","us":"/ˈseɡrɪɡeɪt/"},"pos":"v.","definition":{"en":"To keep people or things apart according to categories, often through a systematic rule.","zh":"按类别分开或隔离；常指制度性的分类隔离。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["社会结构","因果与影响"],"frequency":{"ielts":5,"gre":5},"register":"正式社会学与公共政策动词 · 适用于雅思教育分班制度（按能力快慢分班）、城市居住隔离、代际隔离及垃圾分类管理等议题。","synonyms":[{"id":"separate","note":"分开义近义；segregate 更强调按类别系统性隔开，社会语境中常涉及不平等。"},{"id":"isolate","note":"segregate 侧重按种族、阶层或类别将群体系统性分开隔离；isolate 侧重使某人或某物孤立隔绝。"}],"antonyms":[{"id":"integrate","note":"反义对照：segregate 表“隔离”，而 integrate 表“合并”，二者构成鲜明的语义对立。"},{"id":"incorporate","note":"反义对照：segregate 表“隔离”，而 incorporate 表“把…合并”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"segregate students by academic ability","zh":"按学术能力将学生分班隔离"},{"en":"socially and economically segregated neighbourhoods","zh":"在社会与经济上相互隔离的社区"},{"en":"segregate recyclable waste at the source","zh":"在源头对可回收垃圾进行分类"},{"en":"de facto residential segregation","zh":"事实上的居住隔离（名词形式）"}],"examples":[{"type":"IELTS","en":"Educational policies that segregate pupils by perceived academic ability at an early age may entrench self-fulfilling prophecies and widen achievement gaps.","zh":"在幼年时期按被认定的学术能力将学生分班隔离的教育政策，可能会固化自我实现的预言并拉大成绩差距。","highlights":["segregate pupils by perceived academic ability"]},{"type":"IELTS","en":"Municipalities can dramatically improve recycling efficiency if households are required to segregate organic kitchen waste from dry recyclables at the source.","zh":"如果要求家庭在源头将厨余有机垃圾与干可回收物分类存放，市政部门就能大幅提高回收效率。","highlights":["segregate organic kitchen waste from"]},{"type":"GRE","en":"The two sympatric bird species segregate into distinct canopy microhabitats during the breeding season, thereby minimising interspecific competition for foraging resources.","zh":"这两个同域分布的鸟类物种在繁殖季节分别进入不同的树冠微栖息地，从而最大限度地减少了针对觅食资源的种间竞争。","highlights":["segregate into distinct canopy microhabitats"]},{"type":"GRE","en":"Even after the repeal of statutory zoning restrictions, exclusionary mortgage lending practices continued to segregate metropolitan housing markets along racial lines.","zh":"即便在废除了法定的分区限制之后，排他性的抵押贷款做法仍在继续按种族界限分割大都市房地产市场。","highlights":["segregate metropolitan housing markets"]}],"note":"【句型框架】常用 `segregate A from B`（将A与B隔离开/分类分开）或 `segregate [人群] by [ability / gender / income]`（按能力/性别/收入对人群进行分类隔离）。【高阶替换】精准升级 `separate` 或 `divide`。辨析：修饰物品（如 `segregate waste/data`）时呈中性，指严格按类别分开存放；修饰人群（如 `segregate students / neighbourhoods`）时往往带有批判色彩，指“制度性或结构性地将不同群体隔绝开，阻碍融合”。【避坑指南】词根 `greg` 意为“群体（flock）”，`se-` 意为“分开”（对比 `congregate` 聚集、`aggregate` 汇总）；讨论医疗传染病隔离应使用 `quarantine` 或 `isolate`，而非 `segregate`。","forms":["segregates","segregated","segregating","segregation"],"partners":[{"id":"student","rel":"动+名","phrase":"segregate students by academic ability","note":"常用搭配：segregate students by academic ability（按学术能力将学生分班隔离），与 student（学生）构成高频「动+名」词伙。"},{"id":"neighbourhood","rel":"动+名","phrase":"socially and economically segregated neighbourhoods","note":"常用搭配：socially and economically segregated neighbourhoods（在社会与经济上相互隔离的社区），与 neighbourhood（社区、街区）构成高频「动+名」词伙。"}]},{"id":"transparency","word":"transparency","ipa":{"uk":"/trænˈspærənsi/","us":"/trænˈsperənsi/"},"pos":"n.","definition":{"en":"Openness that allows decisions, processes, and relevant information to be examined.","zh":"透明度；使决策、流程及相关信息可以被审查的公开性。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["社会结构","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式公共治理与商业伦理名词 · 适用于雅思政府预算公开、企业社会责任、食品安全溯源以及人工智能“黑箱算法”监管等议题。","synonyms":[{"id":"openness","note":"信息与决策公开时近义；transparency 更强调可理解、可检查，openness 还可指愿意接受新观点。"},{"id":"clarity","note":"transparency 侧重信息与决策流程对外公开、接受监督；clarity 侧重表述或规则本身清晰明了。"}],"antonyms":[{"id":"secrecy","note":"刻意保持信息不公开，与透明对照。"},{"id":"concealment","note":"主动隐藏信息，与允许审查对照。"},{"id":"opacity","note":"反义对照：transparency 表决策与信息的公开透明，而 opacity 表不透明与暗箱操作。"}],"collocations":[{"en":"ensure transparency in public decision-making","zh":"确保公共决策的透明度"},{"en":"enhance corporate and financial transparency","zh":"提高企业与财务透明度"},{"en":"demand algorithmic transparency from tech giants","zh":"要求科技巨头提供算法透明度"},{"en":"foster public trust through greater transparency","zh":"通过更高透明度培育公众信任"}],"examples":[{"type":"IELTS","en":"Greater transparency in municipal budgeting strengthens civic trust by allowing taxpayers to scrutinise how public revenues are allocated.","zh":"市政预算中更高的透明度允许纳税人审查公共财政收入的分配方式，从而增强公民信任。","highlights":["Greater transparency in municipal budgeting"]},{"type":"IELTS","en":"Mandatory food-labelling regulations promote supply-chain transparency, empowering consumers to make informed nutritional and ethical choices.","zh":"强制性的食品标签法规促进了供应链透明度，使消费者能够作出知情的营养和伦理选择。","highlights":["promote supply-chain transparency"]},{"type":"GRE","en":"Nominal transparency did not automatically yield democratic accountability, because the disclosed archival dumps were voluminous yet lacked the metadata required for meaningful interpretation.","zh":"名义上的透明度并未自动产生民主问责，因为公开的档案数据虽然卷帙浩繁，却缺乏进行有效解读所需的元数据。","highlights":["Nominal transparency"]},{"type":"GRE","en":"Advocates of open science contend that methodological transparency—including the preregistration of experimental protocols—is essential to curb publication bias.","zh":"开放科学的倡导者认为，方法论的透明度（包括实验方案的预注册）对于遏制发表偏倚至关重要。","highlights":["methodological transparency"]}],"note":"【句型框架】不可数名词，常与姊妹词 `accountability`（问责制）并列使用：`enhance / ensure transparency and accountability in [governance / corporate practices]`（提升治理/企业实践中的透明度与问责制）。【高阶替换】精准升级 `openness`、`honesty` 或 `making information public`。在科技与社会类大作文中，`supply-chain transparency`（供应链透明度）和 `algorithmic transparency`（算法透明度）是极具时代感的加分词组。【避坑指南】不要加不定冠词 `a transparency`；其形容词形式为 `transparent`（透明公开的；浅显易懂的）。","forms":["transparent","transparently"],"partners":[{"id":"ensure","rel":"动+名","phrase":"ensure transparency in public decision-making","note":"常用搭配：ensure transparency in public decision-making（确保公共决策的透明度），与 ensure（确保、保证）构成高频「动+名」词伙。"},{"id":"enhance","rel":"动+名","phrase":"enhance corporate and financial transparency","note":"常用搭配：enhance corporate and financial transparency（提高企业与财务透明度），与 enhance（提高、增强）构成高频「动+名」词伙。"}]},{"id":"indispensable","word":"indispensable","ipa":{"uk":"/ˌɪndɪˈspensəbəl/","us":"/ˌɪndɪˈspensəbəl/"},"pos":"adj.","definition":{"en":"So necessary that a task or system cannot function properly without it.","zh":"不可或缺的；缺少它就无法正常完成任务或运作的。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["观点评价","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式学术议论语域；适用于大作文绝对必要性论证（强调某要素一旦缺席，整个体系或目标将无法正常运转）","synonyms":[{"id":"essential","note":"都表示必要；indispensable 更明确强调不能省去。"},{"id":"imperative","note":"indispensable 强调不可或缺；imperative 强调行动上的紧迫性与必要性。"},{"id":"integral","note":"indispensable 侧重绝对必要、缺少它便无法运作；integral 侧重作为整体内部不可分割的组成部分。"}],"antonyms":[{"id":"dispensable","note":"直接反义：不能缺少与可以省去。"},{"id":"inessential","note":"不属于必要部分，与 indispensability 相反。"}],"collocations":[{"en":"indispensable to effective democratic governance","zh":"对有效民主治理不可或缺"},{"en":"an indispensable component of modern education","zh":"现代教育不可或缺的组成部分"},{"en":"render human judgement indispensable","zh":"使人类判断力变得不可或缺"},{"en":"an indispensable prerequisite for innovation","zh":"创新不可或缺的先决条件"}],"examples":[{"type":"IELTS","en":"Independent journalistic scrutiny is indispensable to effective governance because public institutions require external mechanisms to expose malfeasance.","zh":"独立的新闻监督对有效治理不可或缺，因为公共机构需要外部机制来揭露渎职行为。","highlights":["indispensable to effective governance"]},{"type":"IELTS","en":"Even in an era of advanced diagnostic algorithms, empathetic bedside communication remains an indispensable component of clinical medicine.","zh":"即便在先进诊断算法时代，富有同理心的临床沟通仍然是临床医学不可或缺的组成部分。","highlights":["an indispensable component of"]},{"type":"GRE","en":"The newly recovered diplomatic dispatches constitute an indispensable source of information regarding negotiations that official chronicles describe only obliquely.","zh":"新发现的外交急件构成了理解那些官方编年史仅隐晦提及的谈判的不可或缺的信息来源。","highlights":["an indispensable source of information"]}],"note":"【句型框架】常用 `X is indispensable to/for Y`（X 对 Y 而言不可或缺）或 `remain an indispensable component/tool of Z`（依然是 Z 不可或缺的组成部分/工具）。【高阶替换】词根 `in-`（不）+ `dispensable`（可省却的、可有可无的），用来升级 `absolutely necessary / essential / cannot do without`；相比 `useful / valuable`（仅仅有用或有价值），`indispensable` 断言“一旦缺少它，系统就会瘫痪或目标无法达成”。【避坑指南】一是注意拼写结尾是 `-able` 而非 `-ible`（易错写成 `indispensible`）；二是注意语义强度，若某事物只是“很有帮助但非唯一必需”，应使用 `conducive` 或 `beneficial` 而非 `indispensable`。","forms":["indispensability"],"partners":[{"id":"governance","rel":"形+名","phrase":"indispensable to effective democratic governance","note":"常用搭配：indispensable to effective democratic governance（对有效民主治理不可或缺），与 governance（治理、管理）构成高频「形+名」词伙。"},{"id":"prerequisite","rel":"形+名","phrase":"an indispensable prerequisite for innovation","note":"常用搭配：an indispensable prerequisite for innovation（创新不可或缺的先决条件），与 prerequisite（先决条件）构成高频「形+名」词伙。"}]},{"id":"substantial","word":"substantial","ipa":{"uk":"/səbˈstænʃəl/","us":"/səbˈstænʃəl/"},"pos":"adj.","definition":{"en":"Large in amount, degree, or importance.","zh":"数量、程度或重要性可观的；相当大的。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["数量与趋势","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式量化与程度论证语域；高频通用于雅思小作文描述显著数据变化及大作文论述可观的资金投入、比例或收益","synonyms":[{"id":"considerable","note":"数量或程度很大时近义；substantial 还可强调实质性。"},{"id":"plentiful","note":"近义辨析：二者在“大量、富裕”义项上相通；substantial 侧重“可观的”，plentiful 侧重“丰富的”。"},{"id":"significant","note":"substantial 侧重数量、规模或程度相当可观；significant 侧重具有重要的现实意义或统计显著性。"}],"antonyms":[{"id":"insignificant","note":"反义对照：substantial 表“可观的”，而 insignificant 表“无关紧要的”，二者构成鲜明的语义对立。"},{"id":"negligible","note":"数量或影响小到可忽略，与可观形成对照。"},{"id":"minimal","note":"在投入或变化幅度上形成大小对照。"}],"collocations":[{"en":"a substantial proportion of the population","zh":"相当大一部分人口"},{"en":"require substantial capital investment in","zh":"需要对……进行可观的资本投资"},{"en":"yield substantial long-term dividends","zh":"产生丰厚的长期回报/红利"},{"en":"achieve a substantial reduction in emissions","zh":"实现排放量的显著削减"}],"examples":[{"type":"IELTS","en":"Substantial investment in electrified public transport can curb private car dependence only when services are frequent, affordable, and reliable.","zh":"只有当公共交通服务班次频繁、价格合理且可靠时，对电气化公共交通的大量投资才能抑制对私家车的依赖。","highlights":["Substantial investment in"]},{"type":"IELTS","en":"Preventive healthcare campaigns can yield substantial long-term dividends by reducing the incidence of chronic cardiovascular and metabolic diseases.","zh":"预防性医疗保健运动可以通过降低慢性心血管疾病和代谢疾病的发病率，产生可观的长期效益。","highlights":["yield substantial long-term dividends"]},{"type":"GRE","en":"A substantial proportion of the observed phenotypic variance remained unexplained even after the geneticists controlled for environmental covariates.","zh":"即便在遗传学家控制了环境协变量之后，所观测到的表型变异中仍有相当大一部分未获解释。","highlights":["A substantial proportion of"]}],"note":"【句型框架】万年高频搭配：`a substantial proportion/number/amount of X`（相当大比例/数量的 X），以及动宾搭配 `require substantial investment / yield substantial benefits`。【高阶替换】是替换口语词 `big / large / a lot of / great` 最稳健、最地道的学术形容词；其副词 `substantially`（大幅地、可观地）也是图表作文修饰 `increase / decline` 的核心高分词。【避坑指南】一是注意 `a substantial reduction` 指“降幅很大”而非“减少后的剩余数量大”；二是切勿在抽象法学或哲学语境中将其与同源词 `substantive`（实质性的、实体法上的，如 `substantive law / substantive negotiations`）混用。","forms":["substantially"],"partners":[{"id":"proportion","rel":"形+名","phrase":"a substantial proportion of the population","note":"常用搭配：a substantial proportion of the population（相当大一部分人口），与 proportion（比例、部分）构成高频「形+名」词伙。"},{"id":"investment","rel":"形+名","phrase":"require substantial capital investment in","note":"常用搭配：require substantial capital investment in（需要对……进行可观的资本投资），与 investment（投资）构成高频「形+名」词伙。"}]},{"id":"negligible","word":"negligible","ipa":{"uk":"/ˈneɡlɪdʒəbəl/","us":"/ˈneɡlɪdʒəbəl/"},"pos":"adj.","definition":{"en":"So small in amount or effect that it can reasonably be ignored.","zh":"微小到可忽略不计的。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["数量与趋势","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式量化评估与反驳语域；适用于大作文让步反驳段（指出对方看重的收益或成本其实微不足道）及小作文极小数据描写","synonyms":[{"id":"insignificant","note":"在影响微小时接近；negligible 更明确表示实际可忽略。"},{"id":"minimal","note":"数量很小时近义，但 minimal 不必意味着可忽略。"},{"id":"inconsequential","note":"negligible 侧重数量或程度小到可忽略不计；inconsequential 侧重价值或后果无足轻重。"},{"id":"marginal","note":"negligible 强调小到完全可以忽略；marginal 强调幅度极小或处于合格/盈利边缘。"}],"antonyms":[{"id":"substantial","note":"反义对照：negligible 表“微不足道的”，而 substantial 表“可观的”，二者构成鲜明的语义对立。"},{"id":"considerable","note":"反义对照：negligible 表“微不足道的”，而 considerable 表“相当大的”，二者构成鲜明的语义对立。"},{"id":"acute","note":"微不足道的（negligible）与极其尖锐严重的（acute）在程度判断上相反。"}],"collocations":[{"en":"exert a negligible impact on","zh":"对……产生微乎其微的影响"},{"en":"remain negligible compared with","zh":"与……相比显得微不足道"},{"en":"at a negligible marginal cost","zh":"以可忽略不计的边际成本"},{"en":"account for a negligible proportion of","zh":"仅占……中微不足道的一小部分"}],"examples":[{"type":"IELTS","en":"The administrative expense of means-testing is negligible compared with the fiscal savings achieved by targeting welfare strictly at indigent families.","zh":"与将福利精准投向贫困家庭所节省的财政开支相比，家计调查的行政成本微不足道。","highlights":["negligible compared with"]},{"type":"IELTS","en":"Banning plastic straws in isolation will exert a negligible impact on marine pollution unless industrial fishing gear and packaging waste are simultaneously regulated.","zh":"如果不对工业渔具和包装废物同时加以监管，孤立地禁用塑料吸管对海洋污染产生的影响将微乎其微。","highlights":["exert a negligible impact on"]},{"type":"GRE","en":"The econometric correction had a negligible effect on the estimated coefficient, suggesting that attrition bias was not decisive in the longitudinal sample.","zh":"该计量经济学修正对估计系数的影响微乎其微，表明样本流失偏差在纵向样本中并非决定性因素。","highlights":["a negligible effect on"]}],"note":"【句型框架】反驳段高频句式：`Action X will exert a negligible impact on Y unless...`（除非……，否则行动 X 对 Y 的影响微乎其微）；小作文句式：`accounted for a negligible fraction (less than 1%)`。【高阶替换】词根与 `neglect`（忽略）同源，意为“小到完全可以忽略不计的”，精准升级 `very small / tiny / insignificant`。【避坑指南】严禁将 `negligible`（微不足道的，修饰数量、成本或影响）与同源词 `negligent`（疏忽大意的、失职的，修饰人或机构态度，如 `negligent parents/officials`）混淆！","forms":["negligibly"],"partners":[{"id":"impact","rel":"形+名","phrase":"exert a negligible impact on","note":"常用搭配：exert a negligible impact on（对……产生微乎其微的影响），与 impact（影响、冲击）构成高频「形+名」词伙。"},{"id":"cost","rel":"形+名","phrase":"at a negligible marginal cost","note":"常用搭配：at a negligible marginal cost（以可忽略不计的边际成本），与 cost（成本、代价）构成高频「形+名」词伙。"}]},{"id":"substantiate","word":"substantiate","ipa":{"uk":"/səbˈstænʃieɪt/","us":"/səbˈstænʃieɪt/"},"pos":"v.","definition":{"en":"To support a claim with facts, evidence, or detailed reasoning.","zh":"用事实、证据或详细论证支持、证实某项主张。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["论证与证据","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与实证论证语域；常用于科研方法论、媒体素养、法律举证及批驳“缺乏实据的空洞主张”","synonyms":[{"id":"justify","note":"支持论点时接近；substantiate 更明确要求证据，不只是提出理由。"},{"id":"bolster","note":"证据均可加强论点；substantiate 更强调建立事实依据。"},{"id":"corroborate","note":"substantiate 强调拿出实质证据使原本空洞的主张成立；corroborate 强调以第二份独立证据“相互印证、佐证”已有说法。"},{"id":"buttress","note":"substantiate 强调证实真伪；buttress 强调增强说服力或稳固性。"}],"antonyms":[{"id":"refute","note":"提供支持证据与证明主张错误形成对照。"},{"id":"rebut","note":"在论证方向上，支持与反驳形成对照。"}],"collocations":[{"en":"substantiate a claim with empirical data","zh":"用实证数据证实某项主张"},{"en":"substantiate an allegation","zh":"为指控提供事实依据"},{"en":"fail to substantiate the hypothesis","zh":"未能证实该假说"},{"en":"independently substantiated","zh":"得到独立证据证实的"}],"examples":[{"type":"IELTS","en":"Companies should substantiate a claim that their products are environmentally friendly by publishing clear evidence about production methods and the use of materials.","zh":"企业声称产品环保时，应公布生产方法和材料使用的清晰证据，以支持这一主张。","highlights":["substantiate a claim"]},{"type":"IELTS","en":"In the absence of peer-reviewed clinical trials to substantiate their efficacy, dietary supplements should not be marketed as cures for chronic illnesses.","zh":"在缺乏同行评审的临床试验来证实其疗效的情况下，膳食补充剂不应作为慢性病的治疗药物进行营销。","highlights":["substantiate their efficacy"]},{"type":"GRE","en":"The newly discovered correspondence helps substantiate the allegation that officials knew about the shortage well before it became a matter of public concern.","zh":"新发现的通信有助于支持该项指控：官员早在短缺引起公众关注前就已知情。","highlights":["substantiate the allegation"]}],"note":"【句型框架】① Proponents of X rarely substantiate their assertions with rigorous empirical data（X 的支持者鲜少用严谨的实证数据来证实其断言——反驳对方观点时的降维打击句式）；② dismiss unsubstantiated allegations（驳回无事实依据的指控）。【高阶替换】精准升级 prove、support、back up；词根源自 substance（实质、实体），故 substantiate 形象地表达“给原本空洞的观点填入坚实的事实血肉（give substance to）”，比普通 support 更强调“拿出真凭实据”。【避坑指南】第一，及物动词，宾语是 claim, allegation, assertion, theory 等观点名词，不能直接接 that 从句（不说 substantiate that it is true，应说 substantiate the claim that...）；第二，切勿将其过去分词 substantiated（有证据支持的）与同根形容词 substantial（大量的、实质性的）混为一谈。","forms":["substantiates","substantiated","substantiating","substantiation"],"partners":[{"id":"claim","rel":"动+名","phrase":"substantiate a claim with empirical data","note":"常用搭配：substantiate a claim with empirical data（用实证数据证实某项主张），与 claim（主张、声称）构成高频「动+名」词伙。"},{"id":"hypothesis","rel":"动+名","phrase":"fail to substantiate the hypothesis","note":"常用搭配：fail to substantiate the hypothesis（未能证实该假说），与 hypothesis（假说、假设）构成高频「动+名」词伙。"}]},{"id":"refute","word":"refute","ipa":{"uk":"/rɪˈfjuːt/","us":"/rɪˈfjuːt/"},"pos":"v.","definition":{"en":"To demonstrate with evidence or reasoning that a statement or argument is false.","zh":"用证据或推理驳倒、证伪某项陈述或论证。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["论证与证据","让步转折"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与反驳论证语域；用于大作文反驳段（Refutation）引用铁证或严密逻辑彻底证伪对方谬误观点","synonyms":[{"id":"rebut","note":"都涉及反驳；严格区分时 refute 表示成功证明错误，rebut 可仅表示提出反驳。"},{"id":"debunk","note":"refute 是严肃的逻辑与证据反驳；debunk 专指揭穿看似煞有介事的“流言、迷思或伪科学”。"},{"id":"belie","note":"当 belie 表“残酷的现实证明了乐观预测是错的”时，与 refute / debunk 近义。"},{"id":"gainsay","note":"refute 指成功用证据驳倒；gainsay 指试图口头否定。"}],"antonyms":[{"id":"justify","note":"反义对照：refute 表“反驳”，而 justify 表“证明…为正当的”，二者构成鲜明的语义对立。"},{"id":"substantiate","note":"反义对照：refute 表“反驳”，而 substantiate 表“证实”，二者构成鲜明的语义对立。"},{"id":"corroborate","note":"corroborate 提供证据佐证，refute 提供证据驳倒。"}],"collocations":[{"en":"conclusively refute the hypothesis","zh":"确凿有力地驳倒该假说"},{"en":"refute the misconception that","zh":"驳斥……的错误观念"},{"en":"empirical data refute the claim","zh":"实证数据驳倒了这一主张"},{"en":"easily refuted by historical evidence","zh":"轻易被历史证据所证伪"}],"examples":[{"type":"IELTS","en":"Evidence from successful recycling schemes can refute the claim that household participation depends entirely on financial rewards rather than convenience or social expectations.","zh":"成功回收项目的证据能驳斥“家庭参与完全取决于金钱奖励，而非便利性或社会期望”的主张。","highlights":["refute the claim that"]},{"type":"IELTS","en":"Longitudinal studies tracking bilingual children conclusively refute the misconception that early exposure to a second language delays native-tongue acquisition.","zh":"追踪双语儿童的纵向研究确凿有力地驳倒了一种错误观念，即过早接触第二语言会延缓母语习得。","highlights":["conclusively refute the misconception"]},{"type":"GRE","en":"A single reliable counterexample would refute the universal claim, whereas repeated confirming instances cannot establish its truth with the same logical certainty.","zh":"一个可靠反例就能驳倒全称主张，而反复出现的支持实例无法以同样的逻辑确定性确立其真实性。","highlights":["refute the universal claim"]}],"note":"【句型框架】① Empirical evidence conclusively refutes the popular misconception that...（实证证据确凿地驳倒了认为……的普遍谬见——反驳段起手王牌句式）；② This argument is easily refuted by pointing to...（指出……即可轻易驳倒这一论点）。【高阶替换】精准替代 prove wrong、disprove；必须严格区分 deny / dispute / rebut 与 refute：deny 与 dispute 仅表示“主观上口头否认或不同意（无需证据）”，rebut 指“在辩论中出言回击”，而 refute 属于结果性动词，意为“用铁证或严密逻辑成功证明某说法是错误的（驳倒、证伪）”。【避坑指南】正因为 refute 已经包含“成功证伪”的结果义，在严谨学术语境中，如果某人只是嘴上不承认某项指控，切勿用 refute（应用 deny or reject the allegation），只有拿出证据真正推翻了该观点时才能用 refute。","forms":["refutes","refuted","refuting","refutation"],"partners":[{"id":"hypothesis","rel":"动+名","phrase":"conclusively refute the hypothesis","note":"常用搭配：conclusively refute the hypothesis（确凿有力地驳倒该假说），与 hypothesis（假说、假设）构成高频「动+名」词伙。"},{"id":"misconception","rel":"动+名","phrase":"refute the misconception that","note":"常用搭配：refute the misconception that（驳斥……的错误观念），与 misconception（错误观念、误解）构成高频「动+名」词伙。"}]},{"id":"obscure","word":"obscure","ipa":{"uk":"/əbˈskjʊə/","us":"/əbˈskjʊr/"},"pos":"v.","definition":{"en":"To make something difficult to see, understand, or recognise.","zh":"使难以看清、理解或辨认；使模糊。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["让步转折","论证与证据"],"frequency":{"ielts":5,"gre":5},"register":"正式（批判性论证与因果辨析）· 常用于大作文驳论段或让步转折句，指出笼统数据、表面繁荣或偏颇言论掩盖了深层结构性矛盾。","synonyms":[{"id":"conceal","note":"信息被掩盖时接近；obscure 可能只使理解变难，不一定完全隐藏。"},{"id":"confuse","note":"在表达清晰度上相关；obscure a distinction 是使区分不明显，confuse 两物常指混淆。"},{"id":"blur","note":"obscure 侧重掩盖深层原因或使概念难以看清；blur 侧重使原本清晰的界限或边缘变得模糊。"}],"antonyms":[{"id":"demonstrate","note":"反义对照：obscure 表“使变模糊”，而 demonstrate 表“论证”，二者构成鲜明的语义对立。"},{"id":"illustrate","note":"反义对照：obscure 表“使变模糊”，而 illustrate 表“说明”，二者构成鲜明的语义对立。"},{"id":"clarify","note":"使模糊与使清楚形成对照。"}],"collocations":[{"en":"obscure the distinction between","zh":"模糊……之间的界限/区别"},{"en":"obscure the underlying structural causes","zh":"掩盖深层结构性原因"},{"en":"obscure crucial disparities among","zh":"掩盖……之间的关键差距"},{"en":"be obscured by sensationalist rhetoric","zh":"被耸人听闻的修辞所掩盖"}],"examples":[{"type":"IELTS","en":"Relying solely on national GDP growth averages can obscure crucial disparities among regions, leaving rural communities chronically underfunded despite apparent macroeconomic prosperity.","zh":"仅仅依赖国家GDP增长均值可能会掩盖地区之间的关键差距，尽管宏观经济表面繁荣，农村社区却长期资金不足。","highlights":["obscure crucial disparities among"]},{"type":"IELTS","en":"Framing juvenile delinquency purely as a failure of individual morality serves to obscure the underlying structural causes, such as neighbourhood deprivation and under-resourced schools.","zh":"将青少年犯罪纯粹定性为个人道德败坏，实际上掩盖了诸如社区贫困和学校资源匮乏等深层结构性原因。","highlights":["obscure the underlying structural causes"]},{"type":"GRE","en":"The revised taxonomy may obscure the distinction between observed behavioural adaptation and genetically fixed instinct, encouraging researchers to treat tentative interpretation as direct empirical proof.","zh":"修订后的分类法可能会模糊观察到的行为适应与基因固定的本能之间的区别，促使研究者将试探性解释当成直接的实证证据。","highlights":["obscure the distinction between"]}],"note":"【句型框架】核心句型为：表象主语（Aggregate statistics / Broad labels / Framing X as Y）+ obscure(s) + 深层事实（the underlying causes / the distinction between A and B / regional disparities）。【高阶替换】完美升级 hide / cover up / make unclear；相比 conceal（常暗含人为蓄意隐瞒），obscure 极具客观学术质感，可指制度、指标或话语体系在客观上造成“遮蔽视野、模糊焦点”的效果。【避坑指南】注意词性与重音：本词条为及物动词（/əbˈskjʊə(r)/），同形形容词意为“晦涩难懂的、鲜为人知的（an obscure poet）”；切勿将 obscure the distinction 误解为“消除了实际差异”，它仅表示在认知或表象上“混淆、掩盖了差异”。","forms":["obscures","obscured","obscuring"],"partners":[{"id":"distinction","rel":"动+名","phrase":"obscure the distinction between","note":"常用搭配：obscure the distinction between（模糊……之间的界限/区别），与 distinction（差别、界限）构成高频「动+名」词伙。"},{"id":"disparity","rel":"动+名","phrase":"obscure crucial disparities among","note":"常用搭配：obscure crucial disparities among（掩盖……之间的关键差距），与 disparity（悬殊差距）构成高频「动+名」词伙。"}]},{"id":"elucidate","word":"elucidate","ipa":{"uk":"/ɪˈluːsɪdeɪt/","us":"/ɪˈluːsɪdeɪt/"},"pos":"v.","definition":{"en":"To explain something complex or obscure so that it becomes clearer.","zh":"阐明、解释复杂或难懂的事物。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["让步转折","论证与证据"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（学术论述与理论剖析）· 尤适用于大作文主体段展开机制分析、澄清因果链条，或引言段界定核心概念。","synonyms":[{"id":"clarify","note":"都使内容清楚；elucidate 语体更正式，常指通过解释增进理解。"},{"id":"illuminate","note":"近义辨析：二者在“阐明”义项上相通；elucidate 侧重“阐明”，illuminate 侧重“照亮”。"},{"id":"illustrate","note":"近义辨析：二者在“阐明”义项上相通；elucidate 侧重“阐明”，illustrate 侧重“说明”。"},{"id":"explicate","note":"elucidate 侧重把晦涩复杂的机制阐释清楚；explicate 侧重对理论或文本进行条分缕析的深入解读。"}],"antonyms":[{"id":"obscure","note":"反义对照：elucidate 表“阐明”，而 obscure 表“使变模糊”，二者构成鲜明的语义对立。"},{"id":"confuse","note":"理解效果相反，但通常说 elucidate a mechanism 与 confuse a reader，不机械替换宾语。"},{"id":"perplex","note":"使人费解与解释清楚形成语境对照。"}],"collocations":[{"en":"elucidate the underlying mechanism","zh":"阐明底层机制"},{"en":"elucidate the causal nexus between","zh":"阐明……之间的因果关联"},{"en":"elucidate a complex phenomenon","zh":"阐释复杂现象"},{"en":"help to elucidate how","zh":"有助于阐明……是如何……的"}],"examples":[{"type":"IELTS","en":"Longitudinal educational studies can elucidate the underlying mechanism by which early childhood bilingualism enhances executive cognitive control in later academic life.","zh":"纵向教育研究能够阐明儿童早期双语习得在日后学业生涯中增强执行认知控制能力的底层机制。","highlights":["elucidate the underlying mechanism"]},{"type":"IELTS","en":"Before enacting punitive fiscal measures, policymakers must elucidate the causal nexus between urban congestion and commercial freight schedules so that regulations target the true bottlenecks.","zh":"在颁布惩罚性财政措施之前，决策者必须阐明城市拥堵与商业货运时刻表之间的因果关联，以便监管措施精准针对真正的瓶颈。","highlights":["elucidate the causal nexus between"]},{"type":"GRE","en":"Rather than merely cataloguing archaic syntactic variants, the monograph seeks to elucidate how demographic upheavals after the plague reshaped vernacular phonology across medieval Europe.","zh":"该专著并非仅仅罗列古老的句法变体，而是试图阐明瘟疫过后的人口剧变如何重塑了中世纪欧洲各地的方言音系。","highlights":["elucidate how"]},{"type":"GRE","en":"Although the spectroscopic data helped to elucidate the chemical composition of the nebula, the precise thermodynamic conditions governing its formation remained tantalisingly opaque.","zh":"尽管光谱数据有助于阐明该星云的化学成分，但支配其形成的精确热力学条件依然令人捉摸不透。","highlights":["helped to elucidate"]}],"note":"【句型框架】常用于及物动词结构：elucidate + 抽象名词（mechanism / relationship / rationale），或接宾语从句 elucidate how/why + 从句（如 Empirical findings elucidate how socioeconomic disparities perpetuate educational inequality）。【高阶替换】用于升级基础词 explain / make clear / show；相比 clarify（侧重消除误解或歧义，使含糊变清楚），elucidate 源自“照亮（lucid）”，强调通过深入剖析、举例或科学论证，把原本深奥、晦涩的机理彻底讲透。【避坑指南】中国考生常受 explain to sb 或 elaborate on 的干扰而误写 *elucidate on the issue；切记 elucidate 在现代学术英语中主要作及物动词，直接接宾语即可，无需加介词 on 或 about；此外日常琐事切勿大词小用，宾语必须是抽象理论、机制或复杂争议。","forms":["elucidates","elucidated","elucidating","elucidation"],"partners":[{"id":"mechanism","rel":"动+名","phrase":"elucidate the underlying mechanism","note":"常用搭配：elucidate the underlying mechanism（阐明底层机制），与 mechanism（机制、机理）构成高频「动+名」词伙。"},{"id":"phenomenon","rel":"动+名","phrase":"elucidate a complex phenomenon","note":"常用搭配：elucidate a complex phenomenon（阐释复杂现象），与 phenomenon（现象）构成高频「动+名」词伙。"}]},{"id":"impartial","word":"impartial","ipa":{"uk":"/ɪmˈpɑːʃəl/","us":"/ɪmˈpɑːrʃəl/"},"pos":"adj.","definition":{"en":"Not favouring any person or side when making a judgement.","zh":"不偏不倚的；作判断时不偏袒任何一方的。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["观点评价","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式（司法公正、媒体伦理与学术评估）· 适用于大作文讨论法律审判、新闻报道、政府监管机构或学术同行评审的客观中立性。","synonyms":[{"id":"objective","note":"中立评价语境中义近；impartial 侧重不偏袒，objective 侧重事实依据，不能完全互换。"},{"id":"evenhanded","note":"impartial 侧重评判或裁决时不偏袒任何一方；evenhanded 侧重对待各方一视同仁、公允平和。"},{"id":"disinterested","note":"impartial 强调立场中立公正；disinterested 强调没有个人私利牵涉其中，因而能保持客观公允。"}],"antonyms":[{"id":"biased","note":"直接对照：不偏袒与有偏向。"},{"id":"subjective","note":"仅作评价依据的语境对照；主观判断仍可能公正，subjective 不是 impartial 的严格反义。"}],"collocations":[{"en":"conduct an impartial inquiry into","zh":"对……开展公正独立的调查"},{"en":"an impartial judicial tribunal","zh":"不偏不倚的司法裁判庭"},{"en":"provide impartial policy advice","zh":"提供公正中立的政策建议"},{"en":"remain strictly impartial","zh":"保持严格的中立公正"}],"examples":[{"type":"IELTS","en":"Public confidence in environmental regulation depends on whether oversight agencies can conduct an impartial inquiry into industrial pollution without bowing to corporate lobbying.","zh":"公众对环境监管的信任，取决于监督机构能否在不屈服于企业游说的情况下对工业污染开展公正调查。","highlights":["conduct an impartial inquiry into"]},{"type":"IELTS","en":"State-funded public broadcasters have a civic duty to remain strictly impartial during electoral campaigns, giving balanced scrutiny to all competing political platforms.","zh":"国家资助的公共广播机构负有在竞选期间保持严格中立公正的公民义务，对所有竞争性政治纲领进行均衡审视。","highlights":["remain strictly impartial"]},{"type":"GRE","en":"An impartial observer might readily acknowledge that both historiographical schools offer valuable insights without treating their conflicting causal claims as equally corroborated.","zh":"公正的观察者或许会欣然承认两个史学流派都提供了宝贵洞见，但不会将其相互冲突的因果主张视为获得了同等程度的印证。","highlights":["An impartial observer"]}],"note":"【句型框架】常修饰调查、评审或机构：conduct an impartial review/inquiry into X；或强调职责：Regulatory bodies must remain strictly impartial when adjudicating disputes between A and B。【高阶替换】精准升级 fair / neutral / unbiased / objective；由否定前缀 im- + partial（偏袒的、偏向一方的）构成，核心强调“作为裁判者、观察者或机构，在利益冲突各方之间不偏袒任何一方”。【避坑指南】务必厘清反义词 partial 的两个截然不同的含义：一是“部分的（反义词 complete/total）”，二是“偏袒的、偏爱的（be partial to sth，反义词 impartial）”；此外，impartial 不等于 indifferent（冷漠不关心的），公正的法官恰恰需要对真相高度关切。","forms":["impartially","impartiality"],"partners":[{"id":"inquiry","rel":"形+名","phrase":"conduct an impartial inquiry into","note":"常用搭配：conduct an impartial inquiry into（对……开展公正独立的调查），与 inquiry（调查、探究）构成高频「形+名」词伙。"},{"id":"advice","rel":"形+名","phrase":"provide impartial policy advice","note":"常用搭配：provide impartial policy advice（提供公正中立的政策建议），与 advice（建议、忠告）构成高频「形+名」词伙。"}]},{"id":"prudent","word":"prudent","ipa":{"uk":"/ˈpruːdənt/","us":"/ˈpruːdənt/"},"pos":"adj.","definition":{"en":"Showing careful judgement about risks and future consequences.","zh":"审慎的；能谨慎判断风险及未来后果的。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["观点评价","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式（风险管理与政策建议）· 雅思大作文建议段与结论段高频高分形容词，用于呼吁政府、企业或个人在面对不确定性时采取审慎、有远见的策略。","synonyms":[{"id":"circumspect","note":"都表示谨慎；prudent 更强调明智实用的判断，circumspect 更强调周全考虑潜在风险。"},{"id":"scrupulous","note":"prudent 强调权衡风险、未雨绸缪的审慎；scrupulous 强调严守道德准则或细节的一丝不苟。"},{"id":"judicious","note":"prudent 侧重权衡长远风险、未雨绸缪的审慎；judicious 侧重判断力敏锐、决策明智得当。"},{"id":"cautious","note":"prudent 强调深谋远虑的明智审慎；cautious 强调小心翼翼以防出错。"}],"antonyms":[{"id":"imprudent","note":"直接反义：审慎与不审慎。"},{"id":"reckless","note":"谨慎判断与不顾明显风险形成对照。"},{"id":"quixotic","note":"prudent 审慎务实、深谋远虑，与盲目浪漫的 quixotic 相反。"}],"collocations":[{"en":"adopt a prudent approach to","zh":"对……采取审慎的做法"},{"en":"prudent fiscal management","zh":"审慎的财政管理"},{"en":"it would be prudent for policymakers to","zh":"决策者明智/审慎的做法是……"},{"en":"exercise prudent restraint","zh":"保持审慎的克制"}],"examples":[{"type":"IELTS","en":"Prudent fiscal management requires municipal authorities to calculate long-term maintenance liabilities before approving prestigious infrastructure projects.","zh":"审慎的财政管理要求市政当局在批准撑门面的大型基础设施项目之前，先核算长期的维护负债。","highlights":["Prudent fiscal management"]},{"type":"IELTS","en":"Given the unresolved ethical dilemmas surrounding germline gene editing, it would be prudent for international regulators to impose a temporary moratorium on clinical applications.","zh":"鉴于生殖系基因编辑存在尚未解决的伦理困境，国际监管机构审慎的做法是对临床应用实施暂时禁令。","highlights":["it would be prudent for"]},{"type":"GRE","en":"A prudent methodological stance treats the observed correlation as provisional until independent replication can disentangle the proposed mechanism from confounding variables.","zh":"审慎的方法论立场会将观察到的相关性视为暂时性的，直到独立重复实验能够将所提出的机制与混杂变量区分开来。","highlights":["A prudent methodological stance"]}],"note":"【句型框架】满分政策建议句型：Given the potential risks of X, it would be prudent for governments to...（鉴于X的潜在风险，政府审慎明智的做法是……，比 governments should 委婉高级得多！）。【高阶替换】升级 wise / sensible / cautious / careful；源自拉丁语 provident-（foreseeing 远见），因此 prudent 绝非胆小怕事（timid），而是结合了“深谋远虑的智慧（wisdom）”与“规避未来风险的谨慎（caution）”。【避坑指南】不要将 prudent 与保守刻板的 prude / prudish（在道德或性观念上过分正经、道貌岸然的）混淆！在经济与公共政策中，prudent 是一等一的褒义词（如 prudent monetary policy 稳健审慎的货币政策）。","forms":["prudently","prudence"],"partners":[{"id":"management","rel":"形+名","phrase":"prudent fiscal management","note":"常用搭配：prudent fiscal management（审慎的财政管理），与 management（管理、经营）构成高频「形+名」词伙。"},{"id":"fiscal","rel":"形+名","phrase":"prudent fiscal management","note":"常用搭配：prudent fiscal management（审慎的财政管理），与 fiscal（财政的）构成高频「形+名」词伙。"}]},{"id":"viable","word":"viable","ipa":{"uk":"/ˈvaɪəbəl/","us":"/ˈvaɪəbəl/"},"pos":"adj.","definition":{"en":"Able to work successfully or continue existing under the relevant conditions.","zh":"可行的；能够成功运作或持续存在的。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["利弊权衡","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与政策对策语域；常用于大作文结尾段或措施段评估改革方案、清洁能源或商业模式的现实可行性","synonyms":[{"id":"feasible","note":"方案可行时近义；viable 常带持续运作、经济生存或成功前景的意味。"},{"id":"sustainable","note":"viable 强调方案在现实或经济上“切实可行、能存活”，sustainable 强调在长期时间维度上“可维持、不透支未来”。"},{"id":"tenable","note":"viable 侧重方案在实际操作中切实可行；tenable 侧重观点或防线在逻辑与争论中立得住。"},{"id":"practicable","note":"viable 侧重方案在经济或现实环境中能长期存活运作；practicable 侧重计划在实践中能够顺利推行。"}],"antonyms":[{"id":"unviable","note":"反义对照：viable 表“可行的”，而 unviable 表“无法成功运作或持续存在的”，二者构成鲜明的语义对立。"},{"id":"unfeasible","note":"实际无法实施，与 viable 的可运作性相对，侧重点不同。"}],"collocations":[{"en":"an economically viable alternative","zh":"经济上可行的替代方案"},{"en":"a viable long-term solution","zh":"可行的长远解决方案"},{"en":"remain commercially viable","zh":"保持商业上的可持续运营"},{"en":"a viable business model","zh":"可持续经营的商业模式"}],"examples":[{"type":"IELTS","en":"A local bus service may remain viable if neighbouring communities coordinate timetables and share costs instead of operating several underused routes independently.","zh":"邻近社区若协调时刻表、分担成本，而非独立运营多条低利用率线路，地方公交服务便可能持续运营。","highlights":["remain viable"]},{"type":"IELTS","en":"Without substantial government subsidies for grid storage, solar and wind power alone may not yet constitute an economically viable alternative to baseload nuclear energy.","zh":"如果没有政府对电网储能的大力补贴，仅靠太阳能和风能可能尚不足以构成替代基荷核电的经济可行方案。","highlights":["an economically viable alternative"]},{"type":"GRE","en":"The population is unlikely to remain viable if habitat fragmentation prevents individuals from finding mates beyond a small and increasingly isolated group.","zh":"如果栖息地碎片化阻止个体在越来越孤立的小群体之外寻找配偶，该种群就不太可能持续生存。","highlights":["remain viable"]}],"note":"【句型框架】① offer an economically/practically viable alternative to X（提供替代 X 的经济/现实可行方案）；② For public transit to remain financially viable, ...（若要让公共交通保持财务上的可持续运转……）。【高阶替换】全方位升级 workable、possible、can succeed；相比 feasible（侧重某项计划在技术、资源上“做得到、行得通”），viable 源自法语 vie（生命），本义为“（胚胎、种子或种群）能存活发育的”，因此引申到政策或商业中不仅指“能启动”，更强调“投入运转后能自我维持、长久生存并取得成功”。【避坑指南】不要用人作主语（不能写 I am viable to finish the task，人作主语表“能够”用 able）；viable 只修饰 plan, solution, alternative, model, economy, population 等客观方案或系统。","forms":["viably","viability"],"partners":[{"id":"solution","rel":"形+名","phrase":"a viable long-term solution","note":"常用搭配：a viable long-term solution（可行的长远解决方案），与 solution（解决方案）构成高频「形+名」词伙。"},{"id":"model","rel":"形+名","phrase":"a viable business model","note":"常用搭配：a viable business model（可持续经营的商业模式），与 model（模式、模型）构成高频「形+名」词伙。"}]},{"id":"efficacious","word":"efficacious","ipa":{"uk":"/ˌefɪˈkeɪʃəs/","us":"/ˌefɪˈkeɪʃəs/"},"pos":"adj.","definition":{"en":"Capable of producing the intended beneficial effect, especially as a treatment or intervention.","zh":"有效的；尤指治疗或干预能够产生预期有益作用的。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["利弊权衡","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式学术与医药政策语域；常用于评估公共卫生干预、教育改革或司法矫治手段能否达成预期有益成效","synonyms":[{"id":"effective","note":"产生预期效果时近义；efficacious 语体更正式，适用对象通常较具体。"},{"id":"efficient","note":"efficient 强调投入产出比高、不浪费资源；efficacious 强调药效或政策措施能产生预期效力。"},{"id":"potent","note":"efficacious 侧重医药或政策干预能产生预期的良性功效；potent 侧重药力、证据或影响极其强劲有力。"},{"id":"productive","note":"efficacious 强调措施行之有效；productive 强调能产生丰硕成果或高产出。"}],"antonyms":[{"id":"ineffective","note":"能产生预期作用与不能产生预期作用相反。"},{"id":"futile","note":"有用效力与徒劳形成对照；futile 更强调难以产生任何有价值结果。"}],"collocations":[{"en":"demonstrably efficacious interventions","zh":"有确凿证据表明有效的干预措施"},{"en":"prove efficacious in curbing","zh":"在遏制……方面被证明行之有效"},{"en":"an efficacious medical treatment","zh":"有效的医疗方案"},{"en":"highly efficacious at reducing","zh":"在减少……方面极为有效"}],"examples":[{"type":"IELTS","en":"Public funding should prioritise demonstrably efficacious interventions while allowing sufficient flexibility to adapt programmes to the needs of different communities and age groups.","zh":"公共资金应优先支持有证据证明有效的干预，同时保留足够灵活性，以适应不同社区和年龄群体的需求。","highlights":["demonstrably efficacious"]},{"type":"IELTS","en":"Preventive vaccination campaigns have proved far more efficacious in curbing infectious diseases than costly emergency quarantines implemented after an outbreak.","zh":"事实证明，在遏制传染病方面，预防性疫苗接种运动远比疫情爆发后实施的高昂紧急隔离更为行之有效。","highlights":["efficacious in curbing"]},{"type":"GRE","en":"A treatment may be efficacious under tightly controlled conditions without delivering comparable benefits when routine practice introduces variation in adherence and patient characteristics.","zh":"一种疗法在严格控制条件下可能有效，却未必在依从性和患者特征变化的日常实践中带来相同收益。","highlights":["be efficacious under"]}],"note":"【句型框架】① X has proved far more efficacious in curbing Y than Z（在遏制 Y 方面，X 被证明远比 Z 更为行之有效）；② evaluate the long-term efficacy of punitive measures（评估惩罚性措施的长期效力，名词 efficacy 极高频）。【高阶替换】替换 effective、useful、working well 的C2级学术词汇；注意区分 effective（通用词，产生预期效果）、efficient（高效的，强调投入产出比高、不浪费时间资源）与 efficacious（专指药物、疗法、公共政策或制度干预“具备产生预期良性疗效的内在效力”）。【避坑指南】efficacious 永远只能修饰“药物、疗法、政策、措施、手段”等无生命工具或制度，绝对不能修饰人（不能写 an efficacious worker/leader，修饰人干练高效必须用 efficient 或 capable）。","forms":["efficacy","efficaciously"],"partners":[{"id":"intervention","rel":"形+名","phrase":"demonstrably efficacious interventions","note":"常用搭配：demonstrably efficacious interventions（有确凿证据表明有效的干预措施），与 intervention（干预措施）构成高频「形+名」词伙。"},{"id":"treatment","rel":"形+名","phrase":"an efficacious medical treatment","note":"常用搭配：an efficacious medical treatment（有效的医疗方案），与 treatment（治疗、疗法）构成高频「形+名」词伙。"}]},{"id":"futile","word":"futile","ipa":{"uk":"/ˈfjuːtaɪl/","us":"/ˈfjuːtəl/"},"pos":"adj.","definition":{"en":"Unable to achieve a useful result or the purpose for which an effort is made.","zh":"徒劳的；无法产生有用结果或达成努力目标的。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["利弊权衡","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式议论与批判语域；常用于条件论证或反驳段，指出脱离结构性改革或现实前提的单方面努力是徒劳无功的","synonyms":[{"id":"ineffective","note":"无效义接近；futile 常强调尝试注定难有成果或没有实际意义。"},{"id":"pointless","note":"futile 侧重付诸努力却注定徒劳无功；pointless 侧重行为本身毫无意义或目标。"}],"antonyms":[{"id":"effective","note":"反义对照：futile 表徒劳无功的，而 effective 表行之有效的。"},{"id":"efficacious","note":"反义对照：futile 表毫无成效的，而 efficacious 表能产生预期良性功效的。"},{"id":"fruitful","note":"反义对照：futile 表徒劳无益的，而 fruitful 表硕果累累、富有成效的。"}],"collocations":[{"en":"a futile attempt to","zh":"徒劳地试图……"},{"en":"prove utterly futile","zh":"最终被证明完全徒劳无功"},{"en":"render individual efforts futile","zh":"使个人努力化为徒劳"},{"en":"it is futile to expect","zh":"指望……是徒劳的"}],"examples":[{"type":"IELTS","en":"It may be futile to encourage recycling without convenient collection facilities, particularly when households lack space to store separated waste.","zh":"如果没有便利收集设施，鼓励回收可能徒劳，尤其在家庭缺乏储存分类垃圾的空间时。","highlights":["futile to encourage"]},{"type":"IELTS","en":"Unilateral national carbon taxes will remain a futile gesture unless major industrial powers coordinate to prevent corporations from relocating to pollution havens.","zh":"单方面的国家碳税仍将是徒劳之举，除非主要工业大国协同行动以防止企业迁往“污染避风港”。","highlights":["a futile gesture"]},{"type":"GRE","en":"Attempts to reconstruct the original sequence proved futile because later disturbances had erased the relationships on which reliable chronological inference depended.","zh":"重建原始顺序的尝试最终徒劳，因为后来的扰动消除了可靠年代推断所依赖的关系。","highlights":["proved futile"]}],"note":"【句型框架】① It is futile to expect X without first addressing Y（如果不先解决根本原因 Y，指望达成 X 是徒劳的——大作文深度归因句式）；② Uncoordinated efforts will prove utterly futile in the face of...（面对……，缺乏协调的努力将被证明完全徒劳）。【高阶替换】强力替换 useless、pointless、in vain；相比 ineffective（仅陈述未能见效的客观事实）和 counterproductive（产生反效果、帮倒忙），futile 词源意为“底部漏水的容器”，强调因为缺乏必要前提或违背客观规律而“注定竹篮打水一场空”。【避坑指南】futile 带有强烈的“彻底无望、完全白费力气”的绝对化判断，在学术写作中常搭配条件句（without..., unless...）使用以保持逻辑严密；修饰对象是行动、尝试或抗争（attempt, effort, gesture, resistance），不可修饰人。","forms":["futility","futilely"],"partners":[{"id":"attempt","rel":"形+名","phrase":"a futile attempt to","note":"常用搭配：a futile attempt to（徒劳地试图……），与 attempt（尝试、企图）构成高频「形+名」词伙。"},{"id":"effort","rel":"形+名","phrase":"render individual efforts futile","note":"常用搭配：render individual efforts futile（使个人努力化为徒劳），与 effort（努力）构成高频「形+名」词伙。"}]},{"id":"compelling","word":"compelling","ipa":{"uk":"/kəmˈpelɪŋ/","us":"/kəmˈpelɪŋ/"},"pos":"adj.","definition":{"en":"So convincing or forceful that it is difficult to dismiss.","zh":"令人信服的；理由或力量强大到难以忽视的。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["论证与证据","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式（强力立论与证据权重）· 适用于大作文核心论点段（阐述己方支持理由极具说服力）或让步段（承认对方具备有力论据）。","synonyms":[{"id":"persuasive","note":"有说服力义近义；compelling 通常更强，暗示难以忽视或反驳。"},{"id":"incontrovertible","note":"compelling 指极具说服力的；incontrovertible 程度更强，指彻底终结争论的。"},{"id":"eloquent","note":"在修饰证据或演说时相近；compelling 强调令人信服得无法抗拒，eloquent 强调表达力强。"},{"id":"cogent","note":"compelling 侧重论据强有力得令人难以抗拒；cogent 侧重逻辑严密、说理透彻而令人信服。"}],"antonyms":[{"id":"unconvincing","note":"令人信服与无法使人信服形成对照。"},{"id":"unpersuasive","note":"说服力强与缺乏说服力相反。"}],"collocations":[{"en":"provide a compelling argument for","zh":"为……提供令人信服的论据"},{"en":"amass compelling empirical evidence","zh":"积累强有力的实证证据"},{"en":"a compelling moral imperative","zh":"不容推辞的道德要务"},{"en":"a compelling reason to prioritise","zh":"优先考虑……的充分理由"}],"examples":[{"type":"IELTS","en":"The proven cognitive and social benefits of early childhood literacy provide a compelling argument for subsidising public libraries in economically disadvantaged districts.","zh":"儿童早期读写能力已被证实的认知与社会益处，为在经济欠发达地区补贴公共图书馆提供了令人信服的论据。","highlights":["a compelling argument for"]},{"type":"IELTS","en":"Accelerating biodiversity loss across tropical ecosystems creates a compelling moral imperative for affluent nations to finance global conservation treaties.","zh":"热带生态系统生物多样性的加速丧失，为富裕国家资助全球生态保护条约创造了不容推辞的道德要务。","highlights":["a compelling moral imperative"]},{"type":"GRE","en":"The newly unearthed diplomatic correspondence offers compelling evidence that the two sovereigns coordinated their monetary reforms, even though no formal treaty survives.","zh":"新出土的外交信函提供了强有力的证据，表明两位君主协调了其货币改革，尽管没有任何正式条约留存下来。","highlights":["compelling evidence"]}],"note":"【句型框架】立论核心句式：X provides a compelling argument/case for doing Y；或 There is compelling evidence that + 同位语从句。【高阶替换】全方位升级 convincing / strong / persuasive / powerful；源于动词 compel（迫使、使不得不），因此 compelling argument 字面暗示“论据强有力到迫使理性之人不得不信服”。【避坑指南】注意区分 compelling（极具说服力的；引人入胜的）与 compulsory / mandatory（法律或制度强制规定的）：a compelling reason 是“令人信服的充分理由”，而非“强制性的制度要求”；此外，语气极强，后文必须紧跟扎实的逻辑或事实支撑。","forms":["compellingly"],"partners":[{"id":"argument","rel":"形+名","phrase":"provide a compelling argument for","note":"常用搭配：provide a compelling argument for（为……提供令人信服的论据），与 argument（论点、论据）构成高频「形+名」词伙。"},{"id":"evidence","rel":"形+名","phrase":"amass compelling empirical evidence","note":"常用搭配：amass compelling empirical evidence（积累强有力的实证证据），与 evidence（证据）构成高频「形+名」词伙。"}]},{"id":"converge","word":"converge","ipa":{"uk":"/kənˈvɜːdʒ/","us":"/kənˈvɜːrdʒ/"},"pos":"v.","definition":{"en":"To move towards the same point or become more similar in position, value, or conclusion.","zh":"汇聚；位置、数值或结论逐渐接近。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["比较与对照","数量与趋势"],"frequency":{"ielts":5,"gre":5},"register":"正式核心学术动词 · 适用于雅思小作文（多条趋势线逐渐靠拢交汇）及大作文（不同学科证据、文化习俗或政策目标趋同匯聚）。","synonyms":[{"id":"coalesce","note":"事物趋于汇合时义近；converge 是接近同一点，coalesce 更强调结合成一个整体。"},{"id":"integrate","note":"converge 指从不同方向汇集趋同；integrate 指将不同部分融合成完整系统。"},{"id":"merge","note":"converge 侧重从不同方向朝着同一目标或结论汇集靠拢；merge 侧重两个事物彻底融合并入同一整体。"}],"antonyms":[{"id":"diverge","note":"直接方向相反：趋近与分离。"},{"id":"fragment","note":"在群体整合语境中形成汇聚与分裂的对照，不适用于所有数值用法。"},{"id":"emanate","note":"emanate 指从中心向外散发或衍生，converge 指从四面八方向中心汇聚。"}],"collocations":[{"en":"converge on a common goal","zh":"汇聚到共同目标上"},{"en":"converge towards a shared standard","zh":"逐渐趋向共同标准"},{"en":"converging lines of empirical evidence","zh":"相互印证的多条实证证据链"},{"en":"rapidly converge with Western consumption patterns","zh":"与西方消费模式迅速趋同"}],"examples":[{"type":"IELTS","en":"Local transport plans can converge on a common goal of carbon neutrality while still allowing neighbourhoods to choose solutions that reflect their distinct geography.","zh":"地方交通规划可以汇聚到碳中和这一共同目标上，同时允许各社区依据自身独特的地理条件选择方案。","highlights":["converge on a common goal"]},{"type":"IELTS","en":"As globalisation accelerates, youth lifestyles across developing and developed nations have begun to converge towards homogeneous digital habits.","zh":"随着全球化加速，发展中国家与发达国家青年的生活方式已开始趋同，走向同质化的数字习惯。","highlights":["converge towards"]},{"type":"GRE","en":"Converging lines of empirical evidence from ice cores, tree rings, and marine sediments confirm that the fourteenth-century cooling event was hemispheric in scope.","zh":"来自冰芯、树轮和海洋沉积物的多条相互印证的实证证据链证实，十四世纪的降温事件波及了整个半球。","highlights":["Converging lines of empirical evidence"]},{"type":"GRE","en":"Although the two econometric models start from disparate behavioural premises, their long-run equilibrium predictions converge as sample size increases.","zh":"尽管这两个计量经济学模型出发自截然不同的行为前提，但随着样本量的增加，它们的长期均衡预测逐渐趋同。","highlights":["predictions converge"]}],"note":"【句型框架】不及物动词，核心结构为 `A and B converge on / upon [某一点/共识]`（汇聚于某点）或 `A converges with B / towards [某标准]`（与B趋同/趋向某标准）。【高阶替换】高分替换 `meet`、`become similar` 或 `come together`。在学术论证中，`converging lines of evidence`（相互印证的多方证据）是极具说服力的C2级表达；名词形式 `convergence`（趋同/交汇）常用于全球化与科技融合话题。【避坑指南】`converge` 是不及物动词，切勿直接加宾语（不可写 `converge different ideas`）；若要表达反义“分道扬镳、出现分歧”，应使用同源反义词 `diverge`。","forms":["converges","converged","converging","convergence"],"partners":[{"id":"goal","rel":"动+名","phrase":"converge on a common goal","note":"常用搭配：converge on a common goal（汇聚到共同目标上），与 goal（目标）构成高频「动+名」词伙。"},{"id":"evidence","rel":"动+名","phrase":"converging lines of empirical evidence","note":"常用搭配：converging lines of empirical evidence（相互印证的多条实证证据链），与 evidence（证据）构成高频「动+名」词伙。"}]},{"id":"diverge","word":"diverge","ipa":{"uk":"/daɪˈvɜːdʒ/","us":"/daɪˈvɜːrdʒ/"},"pos":"v.","definition":{"en":"To move apart or become increasingly different in direction, value, or opinion.","zh":"分离；方向、数值或观点逐渐不同。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["比较与对照","数量与趋势"],"frequency":{"ielts":5,"gre":5},"register":"正式核心学术动词 · 适用于雅思小作文（两条数据线差距拉大、走向分化）及大作文（公众利益分化、理论预测偏离现实）。","synonyms":[{"id":"separate","note":"diverge 指发展路径或观点分道扬镳；separate 指将原本相连的事物分开。"},{"id":"deviate","note":"diverge 侧重两条路径、趋势或观点逐渐分叉背离；deviate 侧重偏离既定的标准、常规或航向。"},{"id":"differ","note":"diverge 强调随时间推移差距越来越大；differ 静态描述事物之间存在不同。"}],"antonyms":[{"id":"converge","note":"反义对照：diverge 表“分开”，而 converge 表“会聚”，二者构成鲜明的语义对立。"},{"id":"coalesce","note":"反义对照：diverge 表“分开”，而 coalesce 表“联合”，二者构成鲜明的语义对立。"},{"id":"homogenise","note":"homogenise 使趋同单一，diverge 使向不同方向分化。"}],"collocations":[{"en":"diverge sharply from initial expectations","zh":"与最初预期出现显著偏差"},{"en":"diverging socioeconomic trajectories","zh":"日益分化的社会经济轨迹"},{"en":"diverge over the long term","zh":"在长期内逐渐分化/背离"},{"en":"where public opinion and expert consensus diverge","zh":"公众舆论与专家共识出现分歧之处"}],"examples":[{"type":"IELTS","en":"Residents' priorities may diverge sharply when an urban redevelopment project promises new employment opportunities yet threatens affordable housing.","zh":"当城市重建项目承诺带来新就业机会却威胁到可负担住房时，居民的优先诉求可能会出现显著分化。","highlights":["diverge sharply"]},{"type":"IELTS","en":"Without equitable access to early childhood education, the academic trajectories of affluent and disadvantaged pupils begin to diverge before primary school even starts.","zh":"如果无法公平获得早期幼儿教育，富裕学生与弱势学生的学业轨迹甚至在小学开始前就会走向分化。","highlights":["begin to diverge"]},{"type":"GRE","en":"The two theoretical predictions diverge under extreme barometric pressures, providing a decisive experimental test to distinguish models that otherwise fit observations equally well.","zh":"这两项理论预测在极端气压条件下出现分歧，从而提供了一项决定性的实验检验，以区分在常规条件下同样符合观测结果的模型。","highlights":["predictions diverge"]},{"type":"GRE","en":"Linguistic records indicate that the insular dialect began to diverge from mainland vernaculars shortly after maritime trade routes were severed in the ninth century.","zh":"语言学记录表明，在九世纪海上贸易路线中断后不久，这种海岛方言便开始与大陆方言产生分化。","highlights":["diverge from mainland vernaculars"]}],"note":"【句型框架】不及物动词，核心结构为 `A and B diverge (sharply / markedly)`（A与B显著分化）或 `A diverges from B`（A偏离/背离B）。【高阶替换】精准升级 `become different`、`go in different directions` 或 `differ`。相比静态的 `differ`（存在不同），`diverge` 强调“从原本相近或同源的状态随时间推移而动态分离、差距越拉越大”。【避坑指南】在小作文中，哪怕两条曲线都在上升，只要一条陡增而另一条缓增导致差距拉大，就可以地道使用 `their trajectories began to diverge`；注意不可用作及物动词。","forms":["diverges","diverged","diverging","divergence"],"partners":[{"id":"expectation","rel":"动+名","phrase":"diverge sharply from initial expectations","note":"常用搭配：diverge sharply from initial expectations（与最初预期出现显著偏差），与 expectation（预期、期望）构成高频「动+名」词伙。"},{"id":"consensus","rel":"动+名","phrase":"where public opinion and expert consensus diverge","note":"常用搭配：where public opinion and expert consensus diverge（公众舆论与专家共识出现分歧之处），与 consensus（共识）构成高频「动+名」词伙。"}]},{"id":"consequently","word":"consequently","ipa":{"uk":"/ˈkɒnsɪkwəntli/","us":"/ˈkɑːnsəkwəntli/"},"pos":"adv.","definition":{"en":"As a result of the situation or action previously described.","zh":"因此；作为前述情况或行为的结果。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["因果与影响","让步转折"],"frequency":{"ielts":5,"gre":5},"register":"正式学术逻辑连接副词 · 适用于雅思小作文与大作文主体段中严谨推导因果链条（由前文客观事实或政策原因推导出深远结果）。","synonyms":[{"id":"therefore","note":"结果或推论义近义；consequently 常更突出前述情况实际导致的后果。"},{"id":"thereby","note":"consequently 引出独立结果句（因此）；thereby 常接现在分词表示“从而实现……”。"},{"id":"hence","note":"consequently 侧重承接前文事态发展所导致的客观后果；hence 侧重由前文事实直接推导出逻辑结论，语体极凝练。"}],"antonyms":[],"collocations":[{"en":"; consequently, governments must","zh":"；因此，政府必须……"},{"en":"and consequently reduce the burden on","zh":"并因此减轻对……的负担"},{"en":"consequently leading to a decline in","zh":"从而导致……的下降"},{"en":"suffered a severe drought and consequently faced","zh":"遭遇严重干旱，因而面临……"}],"examples":[{"type":"IELTS","en":"Rural schools often serve widely dispersed communities; consequently, improving educational access requires reliable school bus networks as well as classroom investment.","zh":"农村学校通常服务于居住分散的社区；因此，改善教育可达性既需要可靠的校车网络，也需要教室设施投资。","highlights":["consequently, improving educational access"]},{"type":"IELTS","en":"Automated manufacturing has drastically reduced the demand for routine manual labour, and consequently many mid-career factory workers require state-funded retraining.","zh":"自动化制造大幅减少了对常规体力劳动的需求，因此许多处于职业中期的工厂工人需要政府资助的再培训。","highlights":["and consequently many mid-career"]},{"type":"GRE","en":"The core samples were stored at fluctuating ambient temperatures; consequently, the observed isotopic variation cannot be attributed solely to differences in original sediment composition.","zh":"这些岩芯样本储存在波动的环境温度下；因此，观察到的同位素变异不能仅仅归因于原始沉积物成分的差异。","highlights":["consequently, the observed isotopic variation"]},{"type":"GRE","en":"Early modern maritime insurers lacked actuarial tables for tropical hurricanes and consequently charged prohibitive premiums for Caribbean voyages during late summer.","zh":"早期现代海事保险商缺乏热带飓风的精算表，因此在夏末时节对加勒比海航线收取高昂得令人望而却步的保费。","highlights":["and consequently charged prohibitive premiums"]}],"note":"【句型框架】句间衔接黄金标点格式：`完整句A; consequently, 完整句B.` 或 `完整句A. Consequently, 完整句B.`，亦可置于连词后：`... did A, and consequently did B`。【高阶替换】高雅替换口语化的 `so` 或机械重复的 `therefore`、`as a result`。相比侧重逻辑演绎推论的 `therefore`，`consequently`（词根 `consequence` 后果）更强调“实际事件发展所引发的实质性后果”。【避坑指南】语法铁律：`consequently` 是副词而非连词（`so` 才是连词），绝对不能仅用逗号连接两个完整句子（写出 `It rained heavily, consequently the match was cancelled` 属于严重的 Comma Splice 逗号粘连语法错误，必须把逗号改为分号、句号或加 `and`）！","forms":[],"partners":[{"id":"reduce","rel":"副+动","phrase":"and consequently reduce the burden on","note":"常用搭配：and consequently reduce the burden on（并因此减轻对……的负担），与 reduce（减少、减轻）构成高频「副+动」词伙。"},{"id":"decline","rel":"副+动","phrase":"consequently leading to a decline in","note":"常用搭配：consequently leading to a decline in（从而导致……的下降），与 decline（下降、衰退）构成高频「副+动」词伙。"}]},{"id":"nonetheless","word":"nonetheless","ipa":{"uk":"/ˌnʌnðəˈles/","us":"/ˌnʌnðəˈles/"},"pos":"adv.","definition":{"en":"In spite of what has just been said or acknowledged.","zh":"虽然如此；尽管如此仍然。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["让步转折"],"frequency":{"ielts":5,"gre":5},"register":"正式学术让步连接副词 · 雅思大作文让步转折段（先退一步承认对方合理性或某措施的局限，再强力转折回到核心论点）的核心逻辑路标词。","synonyms":[{"id":"nevertheless","note":"让步用法基本近义，二者不要求句式完全不同。"},{"id":"albeit","note":"nonetheless 为让步副词（依然）；albeit 为精炼的让步连词（尽管，后接形容词或短语）。"},{"id":"notwithstanding","note":"nonetheless 仅作副词；notwithstanding 既可前置接名词，也可放在名词短语之后（These obstacles notwithstanding）。"}],"antonyms":[],"collocations":[{"en":"; nonetheless, its long-term benefits outweigh","zh":"；尽管如此，其长期收益远大于……"},{"en":"remains a vital policy tool nonetheless","zh":"尽管如此，仍是一项至关重要的政策工具"},{"en":"While costly, the programme is nonetheless essential","zh":"虽然成本高昂，该项目却依然必不可少"},{"en":"nonetheless warrants serious consideration","zh":"尽管如此，仍值得认真考量"}],"examples":[{"type":"IELTS","en":"Public consultations require considerable time and administrative expenditure; nonetheless, they prevent costly social friction by surfacing residents' concerns before construction begins.","zh":"公众咨询需要相当多的时间和行政开支；尽管如此，它们能在施工开始前揭示居民的顾虑，从而防止代价高昂的社会摩擦。","highlights":["nonetheless, they prevent costly social friction"]},{"type":"IELTS","en":"Strict carbon taxes may initially burden energy-intensive manufacturers; nonetheless, such levies are indispensable for accelerating the transition to renewable power.","zh":"严格的碳税起初可能会加重高耗能制造商的负担；尽管如此，此类税种对于加速向可再生能源转型是不可或缺的。","highlights":["nonetheless, such levies are indispensable"]},{"type":"GRE","en":"The two historiographical accounts disagree sharply regarding the immediate trigger of the revolt; nonetheless, both recognise that agrarian indebtedness had rendered the province unstable for decades.","zh":"这两种史学解释对起义的直接导火索存在尖锐分歧；尽管如此，双方都承认农业债务问题早已使该行省动荡了数十年。","highlights":["nonetheless, both recognise that"]},{"type":"GRE","en":"Although the vaccine did not confer sterilising immunity against mucosal infection, it nonetheless reduced severe hospitalisation rates by over eighty percent.","zh":"尽管该疫苗未能提供针对黏膜感染的完全清除性免疫，但它仍然将重症住院率降低了80%以上。","highlights":["it nonetheless reduced severe hospitalisation"]}],"note":"【句型框架】常用于分号后引出转折主句：`让步陈述句A; nonetheless, 核心主张句B.`，或紧贴于主句谓语动词前：`Although A is true, B nonetheless remains valid.`。【高阶替换】完美升级高频重复的 `however`、`still` 或 `even so`，与 `nevertheless` 同义但音节更紧凑干脆。它专门用于“先大方承认前文事实或缺点，随后指出这一缺点并不能推翻后文的核心价值”。【避坑指南】标点规则同 `however` 与 `consequently`：单独连接两个分句时前面必须用分号或句号，后面加逗号；注意合成词拼写是一个完整单词 `nonetheless`（不要拆开写成三个词）。","forms":[],"partners":[{"id":"warrant","rel":"副+动","phrase":"nonetheless warrants serious consideration","note":"常用搭配：nonetheless warrants serious consideration（尽管如此，仍值得认真考量），与 warrant（值得、需要）构成高频「副+动」词伙。"},{"id":"essential","rel":"副+形","phrase":"While costly, the programme is nonetheless essential","note":"常用搭配：While costly, the programme is nonetheless essential（虽然成本高昂，该项目却依然必不可少），与 essential（必不可少的）构成高频「副+形」词伙。"}]},{"id":"conversely","word":"conversely","ipa":{"uk":"/ˈkɒnvɜːsli/","us":"/ˈkɑːnvɜːrsli/"},"pos":"adv.","definition":{"en":"From the opposite direction or in the opposite situation to the one just described.","zh":"反过来；在相反的情况或方向上。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["比较与对照","让步转折"],"frequency":{"ielts":5,"gre":5},"register":"正式学术反向对比副词 · 适用于雅思小作文（对比趋势完全相反的两组数据）及大作文（从正反两个相反方向论证同一逻辑机制）。","synonyms":[{"id":"contrariwise","note":"反向或相反情况义近义；contrariwise 较少见、语体较旧或更书面。"}],"antonyms":[{"id":"similarly","note":"反义对照：conversely 引出方向或情况相反的对照，而 similarly 引出性质相似的平行类比。"},{"id":"likewise","note":"反义对照：conversely 表反过来、相反地，而 likewise 表同样地、照样。"}],"collocations":[{"en":"Conversely, a failure to invest in","zh":"反过来，若不投资于……"},{"en":"; conversely, in rural areas,","zh":"；反过来，在农村地区，"},{"en":"Conversely, when regulations are lax,","zh":"相反地，当监管松懈时，"},{"en":"benefit skilled graduates; conversely, low-skilled workers","zh":"使高技能毕业生受益；反过来，低技能工人……"}],"examples":[{"type":"IELTS","en":"Reliable suburban rail networks make distant employment hubs accessible; conversely, inadequate public transit traps low-income residents in isolated neighbourhoods.","zh":"可靠的市郊铁路网使远处的就业中心变得触手可及；反过来，不足的公共交通则将低收入居民困在与世隔绝的社区中。","highlights":["conversely, inadequate public transit"]},{"type":"IELTS","en":"In the chart, the proportion of renewable energy rose steadily in Sweden; conversely, coal consumption in the neighbouring region experienced a marked decline.","zh":"在图表中，瑞典的可再生能源比例稳步上升；反过来，邻近地区的煤炭消费量则经历了显著下降。","highlights":["conversely, coal consumption"]},{"type":"GRE","en":"If the foundational axiom holds, the empirical prediction follows necessarily; conversely, observing the predicted phenomenon does not prove that the axiom is the sole valid explanation.","zh":"如果基础公理成立，经验预测便必然成立；反过来，观察到预测的现象并不能证明该公理是唯一合理的解释。","highlights":["conversely, observing the predicted phenomenon"]},{"type":"GRE","en":"During periods of monetary expansion, speculative credit flowed freely into peripheral markets; conversely, the slightest tightening at the central bank triggered abrupt capital flight.","zh":"在货币扩张时期，投机信贷自由流入外围市场；反过来，央行最轻微的紧缩也会触发突然的资本外逃。","highlights":["conversely, the slightest tightening"]}],"note":"【句型框架】置于句首或分号后（后接逗号）：`正向机制句A; conversely, 反向机制句B.`（正面做好A会带来好结果X；反过来，不做A则会招致恶果Y）。【高阶替换】精准升级 `on the other hand` 或 `on the contrary`。辨析：`on the contrary` 用于否定前文刚刚说过的错误命题（“恰恰相反，事实不是这样”），而 `conversely` 用于两个并存事实或正反两种情形之间的“镜像反向对照（反过来说）”。【避坑指南】不要在普通的转折（仅仅是引出另一个不同角度）中滥用 `conversely`——只有当前后两句存在明确的“方向相反、增减相反或条件正反对称”时，用 `conversely` 才最地道。","forms":[],"partners":[{"id":"invest","rel":"副+动","phrase":"Conversely, a failure to invest in","note":"常用搭配：Conversely, a failure to invest in（反过来，若不投资于……），与 invest（投资、投入）构成高频「副+动」词伙。"},{"id":"benefit","rel":"副+动","phrase":"benefit skilled graduates; conversely, low-skilled workers","note":"常用搭配：benefit skilled graduates; conversely, low-skilled workers（使高技能毕业生受益；反过来，低技能工人……），与 benefit（使受益）构成高频「副+动」词伙。"}]},{"id":"concede","word":"concede","ipa":{"uk":"/kənˈsiːd/","us":"/kənˈsiːd/"},"pos":"v.","definition":{"en":"To accept that a point is true or valid, often reluctantly or during disagreement.","zh":"让步承认某观点真实或成立，常带不情愿或争论背景。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["让步转折","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与辩证议论语域；雅思大作文让步段（Concession）核心引述动词，展现客观公允、以退为进的论证风范","synonyms":[{"id":"acknowledge","note":"承认事实时近义；concede 更常带让步或原先不同意的意味。"},{"id":"yield","note":"当 yield 表示“让步、屈服”（yield to）时，与 concede（承认、退让）近义。"},{"id":"admit","note":"concede 侧重在争辩或权衡中退一步承认对方某点成立；admit 为承认事实或过错的通用词。"},{"id":"grant","note":"concede 与 grant 均可构建让步论证（如 I grant/concede that...），concede 语气中不情愿的色彩略浓。"}],"antonyms":[{"id":"deny","note":"承认某陈述与否认其真实性形成对照。"},{"id":"dispute","note":"接受某点与对其提出质疑形成对照。"},{"id":"gainsay","note":"gainsay 否认反驳，concede 承认退让。"}],"collocations":[{"en":"readily concede that","zh":"坦然承认……"},{"en":"concede a valid point","zh":"承认一个合理的观点"},{"en":"even staunch critics concede that","zh":"就连坚定的批评者也不得不承认……"},{"en":"be forced to concede","zh":"被迫承认"}],"examples":[{"type":"IELTS","en":"Critics may concede that tourism creates employment while maintaining that local communities need stronger protection against rising housing costs and environmental damage.","zh":"批评者可以承认旅游业创造就业，同时坚持当地社区需要更强保护，以应对住房成本上涨与环境损害。","highlights":["concede that"]},{"type":"IELTS","en":"Even staunch proponents of free-market deregulation must concede that unbridled financial speculation can precipitate systemic economic crises.","zh":"就连自由市场放松管制的坚定拥护者也不得不承认，肆无忌惮的金融投机可能会引发系统性经济危机。","highlights":["must concede that"]},{"type":"GRE","en":"The author concedes a valid point about the evidence but argues that it weakens only the broadest version of the opposing interpretation.","zh":"作者承认对证据的一项成立意见，但认为它只削弱对方解读中最宽泛的版本。","highlights":["concedes a valid point"]}],"note":"【句型框架】① Even staunch proponents of X must concede that...（就连 X 的坚定支持者也不得不承认……——极具压迫感的让步反击句型）；② While conceding that X yields immediate economic gains, one must recognise that...（在退一步承认 X 带来眼前经济收益的同时，我们必须认识到……）。【高阶替换】精准升级 admit、agree reluctantly；相比 acknowledge（客观中立地认知或致谢）和 admit（常指承认错误或罪责），concede 专用于辩论或学术交锋中“在证据或逻辑面前退让一步，承认对方论点有局部合理之处，以便随后引出更核心的转折主张”。【避坑指南】concede 后可接 that 从句或名词（concede a point），但绝不可接不定式 to do（不能写 concede to be wrong，应写 concede that one is wrong）；让步后务必搭配 while/but/yet 守住自己的核心主旨，切勿让步过度导致立场崩塌。","forms":["concedes","conceded","conceding","concession"],"partners":[{"id":"critic","rel":"动+名","phrase":"even staunch critics concede that","note":"常用搭配：even staunch critics concede that（就连坚定的批评者也不得不承认……），与 critic（批评者）构成高频「动+名」词伙。"},{"id":"readily","rel":"副+动","phrase":"readily concede that","note":"常用搭配：readily concede that（坦然承认……），与 readily（欣然地、坦然地）构成高频「副+动」词伙。"}]},{"id":"meticulous","word":"meticulous","ipa":{"uk":"/məˈtɪkjələs/","us":"/məˈtɪkjələs/"},"pos":"adj.","definition":{"en":"Extremely attentive to small details and the accuracy of one’s work.","zh":"细致入微的；在细节上极其认真的。"},"libraries":["writing"],"topics":["科技与教育","逻辑与论证"],"functions":["观点评价","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式且通常为褒义（科研严谨性、城市规划与文化遗产修复）· 适用于大作文强调复杂工程、科学实验或历史保护需要精益求精、周密部署。","synonyms":[{"id":"scrupulous","note":"都表示一丝不苟；meticulous 强调细节精确，scrupulous 也可强调道德审慎。"},{"id":"circumspect","note":"circumspect 强调言行谨慎小心、顾及周全；meticulous 强调处理细节极其精细。"},{"id":"thorough","note":"meticulous 强调对每个微小细节精益求精；thorough 强调全面彻底、不留死角。"},{"id":"fastidious","note":"都指极其注重细节；meticulous 偏褒义（严谨细致），fastidious 常带“挑剔、洁癖般讲究、难以取悦”的色彩。"}],"antonyms":[{"id":"careless","note":"careless 忽略细节，meticulous 认真检查细节。"},{"id":"negligent","note":"negligent 未尽注意义务，与细致负责的工作方式相反。"},{"id":"perfunctory","note":"反义对照：meticulous 表“谨小慎微的”，而 perfunctory 表“例行公事般的”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"require meticulous urban planning","zh":"需要周密的城市规划"},{"en":"meticulous attention to detail","zh":"对细节的一丝不苟"},{"en":"conduct meticulous archival research","zh":"开展细致的档案研究"},{"en":"meticulous craftsmanship and restoration","zh":"精湛细致的工艺与修复"}],"examples":[{"type":"IELTS","en":"Integrating high-density affordable housing into historic city centres requires meticulous urban planning to preserve architectural heritage while upgrading public transit capacity.","zh":"将高密度保障性住房融入历史悠久的市中心，需要周密的城市规划，以便在保护建筑遗产的同时提升公共交通运力。","highlights":["requires meticulous urban planning"]},{"type":"IELTS","en":"Preserving fragile ancient manuscripts demands meticulous craftsmanship and climate-controlled facilities that few municipal museums can fund without state subsidies.","zh":"保存脆弱的古代手稿需要一丝不苟的精湛工艺和恒温恒湿设施，若无国家补贴，鲜有市立博物馆能够负担。","highlights":["meticulous craftsmanship"]},{"type":"GRE","en":"Her meticulous reconstruction of the diplomatic correspondence established the precise chronology of the crisis without resolving the thornier question of each envoy's ulterior motives.","zh":"她对往来外交信函的细致重建确定了危机的精确时间线，却未能解决每位特使背后隐秘动机这一更棘手的问题。","highlights":["meticulous reconstruction"]}],"note":"【句型框架】常作定语修饰规划、研究或过程：X requires meticulous planning / attention to detail；作表语时可用 be meticulous in doing sth / about sth。【高阶替换】全方位升级 very careful / thorough / precise / painstaking；与近义词 scrupulous（既可指细节严谨，更常指道德上恪守良知、不越雷池一步）和 fastidious（常含贬义，指吹毛求疵、过分挑剔难伺候）相比，meticulous 聚焦于“工作、规划或学术研究在细节与准确度上的一丝不苟”。【避坑指南】逻辑边界提醒：meticulous 仅评价做事过程的“细致程度”，并不等同于结论在逻辑上 valid（有效）或宏观方向上 prudent（审慎明智）——GRE阅读常考“某学者考据极其 meticulous，但核心大前提却 fallacious”。","forms":["meticulously","meticulousness"],"partners":[{"id":"detail","rel":"形+名","phrase":"meticulous attention to detail","note":"常用搭配：meticulous attention to detail（对细节的一丝不苟），与 detail（细节）构成高频「形+名」词伙。"},{"id":"research","rel":"形+名","phrase":"conduct meticulous archival research","note":"常用搭配：conduct meticulous archival research（开展细致的档案研究），与 research（研究、调查）构成高频「形+名」词伙。"}]},{"id":"negligent","word":"negligent","ipa":{"uk":"/ˈneɡlɪdʒənt/","us":"/ˈneɡlədʒənt/"},"pos":"adj.","definition":{"en":"Failing to give something the care or attention that it requires.","zh":"疏忽失职的；未尽应有注意的。"},"libraries":["writing"],"topics":["社会与经济","健康与生活"],"functions":["观点评价","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"正式且具强烈贬义（法律追责、企业监管与公共安全）· 适用于大作文谴责污染企业、违规平台或失职监管机构未能履行应尽的注意义务。","synonyms":[{"id":"careless","note":"都表示不够仔细；negligent 往往强调未尽责任，语气比 careless 更严重。"},{"id":"cursory","note":"negligent 指失职疏忽，常表现只做 cursory（草率走过场）的检查。"},{"id":"culpable","note":"negligent 指玩忽职守；culpable 强调对损害后果负有不可推卸的过错责任（常连用 culpable negligence）。"},{"id":"lax","note":"lax 强调制度、纪律或监管松弛不严；negligent 强调个人或机构未尽法定注意义务而失职。"}],"antonyms":[{"id":"scrupulous","note":"反义对照：negligent 表“疏忽的”，而 scrupulous 表“多顾虑的”，二者构成鲜明的语义对立。"},{"id":"meticulous","note":"反义对照：negligent 表“疏忽的”，而 meticulous 表“谨小慎微的”，二者构成鲜明的语义对立。"},{"id":"punctilious","note":"negligent 疏忽大意、玩忽职守，与恪守规矩细节的 punctilious 直接相反。"}],"collocations":[{"en":"negligent maintenance of infrastructure","zh":"对基础设施疏于维护"},{"en":"hold corporations liable for negligent conduct","zh":"追究企业疏忽失职行为的法律责任"},{"en":"be grossly negligent in","zh":"在……方面存在重大过失/严重失职"},{"en":"negligent oversight of food safety","zh":"对食品安全的失职监管"}],"examples":[{"type":"IELTS","en":"Negligent maintenance of ageing railway networks can impose catastrophic safety risks on commuters, even when the original tracks were engineered to exemplary standards.","zh":"即使最初的轨道是按高标准设计建造的，对老化铁路网疏于维护仍可能给通勤者带来灾难性的安全风险。","highlights":["Negligent maintenance of"]},{"type":"IELTS","en":"Stringent tort laws are essential to hold chemical manufacturers financially liable when they are found grossly negligent in disposing of hazardous industrial effluent.","zh":"当化工厂在处理危险工业废水方面被发现存在严重失职时，严格的侵权法对于追究其经济赔偿责任至关重要。","highlights":["grossly negligent in"]},{"type":"GRE","en":"The parliamentary inquiry characterised the ministry's recordkeeping as culpably negligent, yet carefully distinguished administrative incompetence from the deliberate destruction of evidence.","zh":"议会调查将该部门的档案管理定性为难辞其咎的失职，但审慎地将行政无能与蓄意销毁证据区分开来。","highlights":["culpably negligent"]}],"note":"【句型框架】追责论证句式：be (grossly) negligent in doing sth / in one's duties（在履行……职责时严重失职）；或名词短语作主语：Negligent oversight/maintenance of X can lead to catastrophic consequences。【高阶替换】升级 careless / irresponsible / lax / remiss；在法律与公共治理语境中，negligent 特指“未能履行合理注意义务（duty of care）而导致他人受损的失职行为”。【避坑指南】极高频同根形近词死穴：务必区分 negligent（疏忽失职的，修饰人、机构或管理行为）与 negligible（微不足道的、小到可以忽略不计的，如 a negligible amount of carbon / negligible impact）！千万不要把“微不足道的影响”写成 *negligent impact！","forms":["negligence","negligently"],"partners":[{"id":"maintenance","rel":"形+名","phrase":"negligent maintenance of infrastructure","note":"常用搭配：negligent maintenance of infrastructure（对基础设施疏于维护），与 maintenance（维护、保养）构成高频「形+名」词伙。"},{"id":"safety","rel":"形+名","phrase":"negligent oversight of food safety","note":"常用搭配：negligent oversight of food safety（对食品安全的失职监管），与 safety（安全）构成高频「形+名」词伙。"}]},{"id":"altruistic","word":"altruistic","ipa":{"uk":"/ˌæltruˈɪstɪk/","us":"/ˌæltruˈɪstɪk/"},"pos":"adj.","definition":{"en":"Motivated by concern for other people’s welfare rather than personal advantage.","zh":"利他的；出于他人福祉而非个人利益的。"},"libraries":["writing"],"topics":["社会与经济","健康与生活"],"functions":["观点评价","因果与影响"],"frequency":{"ielts":5,"gre":5},"register":"正式（社会伦理、志愿服务与行为经济学）· 适用于大作文探讨慈善捐赠、无偿志愿服务、企业社会责任（CSR）或人类合作行为背后的动机。","synonyms":[{"id":"selfless","note":"都强调顾及他人而非自身利益；selfless 更强烈暗示不计较个人得失。"},{"id":"philanthropic","note":"altruistic 强调不求回报的无私利他动机；philanthropic 强调外在的公益捐赠行为。"},{"id":"benevolent","note":"altruistic 强调不计个人得失的利他动机；benevolent 强调心地仁慈、关怀弱者的善意。"}],"antonyms":[{"id":"selfish","note":"selfish 只顾自身利益，与 altruistic 对他人福祉的关切相反。"},{"id":"egocentric","note":"egocentric 以自我为中心，和以他人福祉为目标形成对照。"},{"id":"avaricious","note":"贪婪逐利与无私利他相对。"}],"collocations":[{"en":"driven by purely altruistic motives","zh":"受纯粹利他动机的驱使"},{"en":"foster altruistic behaviour among","zh":"在……中培养利他行为"},{"en":"an altruistic commitment to community welfare","zh":"对社区福祉的无私奉献"},{"en":"transcend narrow self-interest for altruistic ends","zh":"超越狭隘私利以追求利他目标"}],"examples":[{"type":"IELTS","en":"Secondary schools can foster altruistic behaviour by integrating community service into the curriculum without reducing civic engagement to a mere checklist for university admission.","zh":"中学可以通过将社区服务融入课程来培养利他行为，而不把公民参与降格为仅仅是大学录取的打卡清单。","highlights":["foster altruistic behaviour"]},{"type":"IELTS","en":"Even when corporate philanthropy is not driven by purely altruistic motives, tax-deductible donations can still channel vital resources toward underfunded medical research.","zh":"即便企业慈善并非受纯粹利他动机的驱使，可抵税的捐赠依然能够将关键资源导向资金不足的医学研究。","highlights":["purely altruistic motives"]},{"type":"GRE","en":"While the merchant guild's endowment of the hospital may have reflected altruistic impulses, surviving municipal ledgers do not permit historians to exclude reputational calculation entirely.","zh":"尽管商人行会捐资兴建该医院可能反映了利他冲动，但现存的市政账簿尚不足以让历史学家完全排除声誉算计的因素。","highlights":["altruistic impulses"]}],"note":"【句型框架】常用于动机辨析：While X may not be driven by purely altruistic motives, it nonetheless generates tangible social benefits；或 foster/encourage altruistic behaviour among youth。【高阶替换】完美升级 unselfish / selfless / philanthropic / public-spirited；词根 alter 意为“他人（other）”，与 egoistic / self-serving / mercenary（自私的、唯利是图的）形成精准反义关系。【避坑指南】学术审慎性提示：在议论文分析志愿服务或企业慈善时，避免一刀切地断言其完全 altruistic 或完全 hypocritical，使用 a blend of altruistic concern and pragmatic self-interest（利他关怀与务实私利的结合）能直接展现 Band 8.5+ 的辩证思维深度。","forms":["altruism","altruistically"],"partners":[{"id":"motive","rel":"形+名","phrase":"driven by purely altruistic motives","note":"常用搭配：driven by purely altruistic motives（受纯粹利他动机的驱使），与 motive（动机、目的）构成高频「形+名」词伙。"},{"id":"behaviour","rel":"形+名","phrase":"foster altruistic behaviour among","note":"常用搭配：foster altruistic behaviour among（在……中培养利他行为），与 behaviour（行为）构成高频「形+名」词伙。"}]},{"id":"receptive","word":"receptive","ipa":{"uk":"/rɪˈseptɪv/","us":"/rɪˈseptɪv/"},"pos":"adj.","definition":{"en":"Willing to listen to and consider suggestions, information, or new ideas.","zh":"乐于听取和考虑意见的；愿意接纳新想法的。"},"libraries":["writing"],"topics":["科技与教育","社会与经济"],"functions":["观点评价","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"正式（观念采纳、教育心理与组织变革）· 适用于大作文探讨青年群体对新事物的接纳度、职场反馈文化或公众对改革政策的接受意愿。","synonyms":[{"id":"open-minded","note":"都不排斥新观点；receptive 常接 to 指明接受的对象，open-minded 更概括地描述态度。"},{"id":"amenable","note":"都可能愿意配合；amenable 更偏接受建议或安排，receptive 更偏听取信息与观念。"}],"antonyms":[{"id":"dogmatic","note":"反义对照：receptive 表“善于接受的”，而 dogmatic 表“教条的”，二者构成鲜明的语义对立。"},{"id":"doctrinaire","note":"反义对照：receptive 表“善于接受的”，而 doctrinaire 表“教条的”，二者构成鲜明的语义对立。"},{"id":"insular","note":"receptive 对新观点持开放态度，insular 则拒绝外部影响。"}],"collocations":[{"en":"prove receptive to new ideas","zh":"证明乐于接纳新观念"},{"en":"be receptive to constructive criticism","zh":"愿意听取建设性批评"},{"en":"cultivate a receptive mindset","zh":"培养开放接纳的心态"},{"en":"find a receptive audience among","zh":"在……之中找到愿意倾听的受众"}],"examples":[{"type":"IELTS","en":"Employees are far more likely to be receptive to constructive criticism when performance appraisals focus on actionable professional growth rather than punitive ranking.","zh":"当绩效评估聚焦于可操作的职业成长而非惩罚性排名时，员工更有可能愿意听取建设性批评。","highlights":["receptive to constructive criticism"]},{"type":"IELTS","en":"Because younger generations have grown up in multicultural digital environments, they generally prove more receptive to cosmopolitan values and cross-border collaboration.","zh":"由于年轻一代在多元文化的数字环境中成长，他们通常对世界主义价值观和跨国协作表现出更高的接纳度。","highlights":["receptive to cosmopolitan values"]},{"type":"GRE","en":"The heterodox economic treatise found a surprisingly receptive audience among municipal reformers, largely because it addressed fiscal bottlenecks central to their administrative practice.","zh":"这部非正统的经济学专著在市政改革者中找到了出人意料地乐于接受的受众，很大程度上因为它切中了他们行政实践中最核心的财政瓶颈。","highlights":["a surprisingly receptive audience"]}],"note":"【句型框架】固定表语搭配：be/prove/remain (more) receptive to + 名词/动名词（如 be receptive to pedagogical innovations / to adopting renewable energy）。【高阶替换】升级 open-minded / willing to listen / accepting；相比 passive（消极被动接受的）或 gullible（轻信易受骗的），receptive 是积极的褒义词，指“心胸开阔、乐于倾听并认真考量新思想或外部建议”。【避坑指南】介词与词形辨析：receptive 后接对象时必须搭配介词 to（这里的 to 是介词，后接名词或 doing，绝不能接动词原形！）；另外切勿将其与形近高频词混淆：receptive（乐于接受新思想的）vs. reciprocal（互惠的、双向的）vs. respective（各自的）。","forms":["receptivity","receptively"],"partners":[{"id":"criticism","rel":"形+名","phrase":"be receptive to constructive criticism","note":"常用搭配：be receptive to constructive criticism（愿意听取建设性批评），与 criticism（批评、评论）构成高频「形+名」词伙。"},{"id":"audience","rel":"形+名","phrase":"find a receptive audience among","note":"常用搭配：find a receptive audience among（在……之中找到愿意倾听的受众），与 audience（受众、听众）构成高频「形+名」词伙。"}]},{"id":"sceptical","word":"sceptical","ipa":{"uk":"/ˈskeptɪkəl/","us":"/ˈskeptɪkəl/"},"pos":"adj.","definition":{"en":"Not readily convinced that a claim is true and wanting adequate supporting evidence.","zh":"持怀疑态度的；不轻易相信而要求证据的。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["让步转折","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式（批判性思维与审慎质疑）· 适用于大作文表达对夸大宣传、单一技术万能论或未经证实假设的理性存疑态度。","synonyms":[{"id":"doubtful","note":"都不确信；sceptical 常涉及对他人主张的怀疑，doubtful 也可对结果是否会发生不确定。"},{"id":"dubious","note":"形容人的态度时相近；dubious 还可形容事物本身可疑，sceptical 通常描述判断者。"},{"id":"cynical","note":"sceptical 指讲求证据、不轻信片面之词的理性怀疑态度；cynical 指愤世嫉俗、认为人人皆出于私利的犬儒态度。"}],"antonyms":[{"id":"credulous","note":"credulous 容易相信，sceptical 不轻信。"},{"id":"gullible","note":"gullible 容易受骗，sceptical 通常要求证据。"},{"id":"impressionable","note":"sceptical 要求确凿证据、不轻易盲从，与缺乏批判力而易受他人左右的 impressionable 相对。"}],"collocations":[{"en":"remain deeply sceptical of","zh":"对……保持深切怀疑"},{"en":"sceptical about sweeping promises","zh":"对笼统夸大的承诺持怀疑态度"},{"en":"persuade sceptical policymakers","zh":"说服持怀疑态度的决策者"},{"en":"view the claim with healthy scepticism","zh":"以理性的怀疑态度看待该主张"}],"examples":[{"type":"IELTS","en":"Citizens should remain sceptical of sweeping promises that carbon capture technology alone can neutralise industrial emissions without any reduction in fossil fuel consumption.","zh":"对于声称仅靠碳捕获技术就能在不减少化石燃料消耗的情况下中和工业排放的笼统承诺，公民应当保持怀疑态度。","highlights":["sceptical of sweeping promises"]},{"type":"IELTS","en":"Many educators are rightly sceptical about the pedagogical value of replacing qualified classroom teachers with automated tutoring software.","zh":"许多教育工作者完全有理由怀疑用自动化辅导软件取代合格课堂教师的教学价值。","highlights":["sceptical about the pedagogical value"]},{"type":"GRE","en":"Although initially sceptical of the painting's attribution to the Renaissance master, the curator revised her assessment after examining infrared reflectograms and archival provenance records.","zh":"尽管馆长最初对该画作归于这位文艺复兴大师名下持怀疑态度，但在检验了红外反射图像与档案流传记录后，她修正了自己的评估。","highlights":["sceptical of the painting's attribution"]}],"note":"【句型框架】表语结构最为地道：remain/be rightly sceptical of/about + 名词（如 remain sceptical of technological panaceas），或接 that 从句。名词形式可构成 with healthy scepticism（秉持健康的理性怀疑精神）。【高阶替换】升级 doubtful / unconvinced / questioning；务必区分 sceptical 与 cynical（愤世嫉俗的）：sceptical 是科学理性精神的体现——“在看到确凿证据前不轻信”；而 cynical 则是消极阴暗地认为“人人皆自私、动机皆虚伪”。【避坑指南】英美拼写与发音注意：英式拼作 sceptical，美式拼作 skeptical，两者在首音节均发 /sk/（千万不要发成 /s/！）；在同一篇雅思作文中请保持英式或美式拼写一致。","forms":["skeptical","scepticism","skepticism","sceptically","skeptically"],"partners":[{"id":"persuade","rel":"动+形","phrase":"persuade sceptical policymakers","note":"常用搭配：persuade sceptical policymakers（说服持怀疑态度的决策者），与 persuade（说服）构成高频「动+形」词伙。"},{"id":"claim","rel":"形+名","phrase":"view the claim with healthy scepticism","note":"常用搭配：view the claim with healthy scepticism（以理性的怀疑态度看待该主张），与 claim（主张、声称）构成高频「形+名」词伙。"}]},{"word":"peripheral","ipa":{"uk":"/pəˈrɪfərəl/","us":"/pəˈrɪfərəl/"},"definition":{"en":"Of secondary importance or situated away from the central part of an issue.","zh":"外围的；对核心议题而言次要的。"},"collocations":[{"en":"distract attention with peripheral issues","zh":"因次要枝节问题而分散注意力"},{"en":"remain peripheral to the core debate","zh":"处于核心争论的边缘/次要地位"},{"en":"of purely peripheral importance","zh":"仅具有纯粹次要的意义"},{"en":"marginalize economically peripheral regions","zh":"使经济外围地区边缘化"}],"examples":[{"type":"IELTS","en":"Public policy debates should focus on structural housing shortages rather than allowing peripheral issues to distract attention from affordability.","zh":"公共政策讨论应聚焦于结构性住房短缺，而不应让次要枝节问题转移人们对住房可负担性的注意力。","highlights":["peripheral issues"]},{"type":"IELTS","en":"Without high-speed rail links and digital infrastructure, geographically peripheral regions risk falling further behind metropolitan centres.","zh":"如果缺乏高铁连接和数字基础设施，地理上处于外围的偏远地区将面临进一步落后于大都市中心的风险。","highlights":["geographically peripheral regions"]},{"type":"GRE","en":"Initially dismissed by orthodox historians as peripheral to the debate, the guild ledgers later proved central to explaining why the tax revolt failed.","zh":"这些行会账簿起初被正统历史学家视为与争论核心无关的边缘材料，后来却成为解释抗税起义为何失败的关键。","highlights":["peripheral to the debate"]}],"note":"【句型框架】常用于主次对比句：`Focus on core structural causes rather than peripheral issues`（聚焦核心结构性原因而非边缘枝节问题），或作表语 `be peripheral to X`（对 X 而言是次要/边缘的）。【高阶替换】源自希腊语“圆周外围”，是替换 `secondary / minor / less important / side (issue)` 的高阶学术词，常与 `central / pivotal / paramount` 构成鲜明对比。【避坑指南】作表语表示“对……而言次要”时，后接介词 `to`（`peripheral to the main argument`）；此外在城乡发展类话题中，`peripheral regions/areas` 指“外围/周边偏远地区”，属于空间地理中性义。","forms":["peripherally"],"frequency":{"ielts":5,"gre":4},"id":"peripheral","pos":"adj.","libraries":["writing"],"topics":["科技与教育","逻辑与论证"],"functions":["观点评价","替换基础词"],"register":"正式学术论证与议题主次辨析语域；适用于大作文指出不应让次要枝节问题转移对核心结构性矛盾的注意力","synonyms":[{"id":"incidental","note":"peripheral 指处于核心之外；incidental 指附带发生、并非主要目的或部分，不一定是空间上的外围。"},{"id":"tangential","note":"peripheral 强调处于空间或系统的外围；tangential（源自几何“切线”）强调仅与核心议题擦边接触、近乎离题。"},{"id":"marginal","note":"peripheral 侧重处于核心议题或区域的外围；marginal 侧重重要程度微小或处于边缘位置。"},{"id":"secondary","note":"peripheral 强调非核心的枝节地位；secondary 强调优先级排在次要位置。"}],"antonyms":[{"id":"fundamental","note":"反义对照：peripheral 表“外围的”，而 fundamental 表“基础的”，二者构成鲜明的语义对立。"},{"id":"foundational","note":"反义对照：peripheral 表“外围的”，而 foundational 表“基础性的”，二者构成鲜明的语义对立。"},{"id":"pivotal","note":"peripheral 指外围的、枝节的，与中枢关键的 pivotal 相对。"}],"partners":[{"id":"issue","rel":"形+名","phrase":"distract attention with peripheral issues","note":"常用搭配：distract attention with peripheral issues（因次要枝节问题而分散注意力），与 issue（议题、问题）构成高频「形+名」词伙。"},{"id":"region","rel":"形+名","phrase":"marginalize economically peripheral regions","note":"常用搭配：marginalize economically peripheral regions（使经济外围地区边缘化），与 region（地区、区域）构成高频「形+名」词伙。"}]},{"word":"inherent","ipa":{"uk":"/ɪnˈhɪərənt/","us":"/ɪnˈhɪrənt/"},"definition":{"en":"Existing as a natural or inseparable part of something.","zh":"固有的；作为事物自然或不可分离的一部分而存在的。"},"collocations":[{"en":"the inherent limitations of","zh":"……的固有局限性"},{"en":"mitigate the inherent risks of","zh":"缓解……的固有风险"},{"en":"contradictions inherent in the system","zh":"体制内固有的矛盾"},{"en":"possess inherent dignity and worth","zh":"拥有与生俱来的尊严与价值"}],"examples":[{"type":"IELTS","en":"Educational reformers should acknowledge the inherent limitations of timed written examinations and evaluate students through a broader portfolio of collaborative projects.","zh":"教育改革者应当承认限时笔试的固有局限性，并通过更广泛的协作项目作品集来评估学生。","highlights":["inherent limitations"]},{"type":"IELTS","en":"Strict financial oversight cannot wholly eliminate the speculative volatility inherent in deregulated cryptocurrency markets.","zh":"严格的金融监管无法彻底消除放松管制的加密货币市场中固有的投机波动性。","highlights":["inherent in"]},{"type":"GRE","en":"The measurement uncertainty is inherent in the quantum mechanical system itself rather than attributable to imprecise laboratory apparatus or observer error.","zh":"这种测量不确定性是量子力学系统本身所固有的，而不能归因于实验室仪器不够精密或观察者误差。","highlights":["inherent in the quantum mechanical system"]}],"note":"【句型框架】既可作前置定语（acknowledge the inherent limitations/risks of X），更推荐作后置定语：the volatility/bias inherent in X（X中固有的波动性/偏见）。【高阶替换】升级 built-in / intrinsic / natural；与近义词 innate / inborn（仅指生物或人“天生的、与生俱来的”）相比，inherent 适用面广得多，尤其擅长修饰抽象制度、技术、市场或方法论的“内生属性”。【避坑指南】介词搭配铁律：传统严谨学术英语中首选 inherent in（黏附在事物内部的），尽量避免写 inherent to；另外，“固有风险（inherent risk）”指该事物本质上自带某种风险属性，并不等于“必然会发生灾难（inevitable disaster）”。","forms":["inherently"],"frequency":{"ielts":5,"gre":5},"id":"inherent","pos":"adj.","libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["观点评价","因果与影响"],"register":"正式（本质属性与结构性局限）· 常用于大作文剖析某项技术、制度或经济模式自身携带、无法彻底剥离的固有风险或缺陷。","synonyms":[{"id":"intrinsic","note":"inherent 表示随事物性质而有；intrinsic 强调属于事物自身、非借助外部评价或作用而来。"},{"id":"fundamental","note":"inherent 指事物生来固有的属性，往往也是其最根本（fundamental）的特征。"},{"id":"immanent","note":"inherent 侧重事物本身固有的属性、缺陷或风险；immanent 侧重内在于整个系统或自然之中的本质规律。"}],"antonyms":[{"id":"extrinsic","note":"在解释特征或动因的来源时形成内在与外在的对照；不能把外部影响简单视为不重要。"},{"id":"external","note":"语境对照：inherent（固有的）与 external（外部的）在论证方向上构成反义或鲜明对比。"}],"partners":[{"id":"limitation","rel":"形+名","phrase":"the inherent limitations of","note":"常用搭配：the inherent limitations of（……的固有局限性），与 limitation（局限性）构成高频「形+名」词伙。"},{"id":"risk","rel":"形+名","phrase":"mitigate the inherent risks of","note":"常用搭配：mitigate the inherent risks of（缓解……的固有风险），与 risk（风险）构成高频「形+名」词伙。"}]},{"word":"explicit","ipa":{"uk":"/ɪkˈsplɪsɪt/","us":"/ɪkˈsplɪsɪt/"},"definition":{"en":"Stated clearly and directly, without leaving the intended meaning merely implied.","zh":"明确说出的；清晰直接而非仅靠暗示传达的。"},"collocations":[{"en":"obtain explicit consent from","zh":"获得来自……的明确同意"},{"en":"draw an explicit distinction between","zh":"在……之间作出明确区分"},{"en":"make explicit the assumptions underlying","zh":"明确揭示……背后的假设"},{"en":"provide explicit guidelines on","zh":"就……提供明确的指导方针"}],"examples":[{"type":"IELTS","en":"Commercial digital platforms should be legally required to obtain explicit consent from users before monetising their browsing histories for targeted advertising.","zh":"法律应当要求商业数字平台在将用户的浏览记录变现用于定向广告之前，必须获得用户的明确同意。","highlights":["obtain explicit consent from"]},{"type":"IELTS","en":"To prevent academic misconduct in the age of generative AI, universities must provide explicit guidelines on the permissible boundaries of algorithmic assistance.","zh":"为了在生成式人工智能时代防止学术不端，大学必须就算法辅助的允许边界提供明确的指导方针。","highlights":["provide explicit guidelines on"]},{"type":"GRE","en":"Although the treatise makes an explicit commitment to materialist explanation, its concluding chapters surreptitiously reintroduce teleological metaphors to account for evolutionary novelty.","zh":"尽管该专著明确承诺采用唯物主义解释，但其最后几章却暗中重新引入了目的论隐喻来解释演化新颖性。","highlights":["an explicit commitment to"]}],"note":"【句型框架】常用于宾补结构或名词前：make it explicit that... / make X explicit（使……明确化）；或 obtain explicit consent from sb before doing sth。【高阶替换】升级 direct / clear / stated；词根 ex-（向外）+ plic-（折叠 fold），字面即“完全展开平铺在明面上的”，与 implicit（折叠在里面的、隐含的）构成绝对反义词对。【避坑指南】explicit 强调“在言语或文字上直白写出、不靠猜测”，并不等同于 detailed（详尽繁琐的）——一句简短的禁止标语同样是 explicit；另外在影视分级语境中 explicit content 指“露骨/少儿不宜的内容”，学术写作中注意语境区分。","forms":["explicitly"],"frequency":{"ielts":5,"gre":4},"id":"explicit","pos":"adj.","libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["观点评价"],"register":"正式（规则界定与数字伦理）· 常用于大作文讨论法律法规、数据隐私授权、教育指导或学术文本中的明示前提。","synonyms":[{"id":"overt","note":"explicit 指用语言明确表达、不留歧义；overt 指行为或态度公开可见、不加掩饰。"},{"id":"lucid","note":"explicit 强调话语直白明确、不留弦外之音；lucid 强调逻辑条理清晰易懂。"},{"id":"definite","note":"explicit 侧重用语言直白清晰地表述出来；definite 侧重结论或安排确切无疑。"}],"antonyms":[{"id":"implicit","note":"在立场、同意或表达的显露程度上对照：公开或明确表达，与含蓄、未明说。"},{"id":"clandestine","note":"明确公开表达（explicit）与隐秘不宣（clandestine）形成对照。"},{"id":"covert","note":"explicit 明确直白的，与隐藏不露的 covert 相反。"}],"partners":[{"id":"distinction","rel":"形+名","phrase":"draw an explicit distinction between","note":"常用搭配：draw an explicit distinction between（在……之间作出明确区分），与 distinction（区分、差别）构成高频「形+名」词伙。"},{"id":"guideline","rel":"形+名","phrase":"provide explicit guidelines on","note":"常用搭配：provide explicit guidelines on（就……提供明确的指导方针），与 guideline（指导方针、准则）构成高频「形+名」词伙。"}]},{"word":"implicit","ipa":{"uk":"/ɪmˈplɪsɪt/","us":"/ɪmˈplɪsɪt/"},"definition":{"en":"Suggested or understood without being stated directly.","zh":"含蓄的；未明确说出但可理解或推知的。"},"collocations":[{"en":"an implicit assumption underlying","zh":"潜藏于……背后的隐含假设"},{"en":"perpetuate implicit bias against","zh":"延续针对……的隐性偏见"},{"en":"remain implicit in the argument","zh":"隐含在该论证之中"},{"en":"rely on an implicit social contract","zh":"依赖隐性的社会契约"}],"examples":[{"type":"IELTS","en":"Automated recruitment algorithms trained on historical hiring records frequently perpetuate implicit bias against female applicants in male-dominated engineering sectors.","zh":"基于历史招聘记录训练的自动化招聘算法，往往会在男性主导的工程领域延续针对女性求职者的隐性偏见。","highlights":["perpetuate implicit bias against"]},{"type":"IELTS","en":"Implicit in the proposal to privatise municipal water supplies is the questionable assumption that profit-driven corporations will prioritise equitable public access over shareholder dividends.","zh":"将市政供水私有化的提议中隐含着一个存疑的假设，即逐利企业会将公平的公众获取权置于股东分红之上。","highlights":["Implicit in the proposal"]},{"type":"GRE","en":"An implicit assumption that consumer preferences remain invariant over time explains why the neoclassical model falters when households revise their expectations during prolonged recessions.","zh":"新古典模型隐含地假定消费者偏好随时间保持不变，这解释了为何当家庭在长期衰退期间修正其预期时，该模型便会失效。","highlights":["An implicit assumption"]}],"note":"【句型框架】满分倒装句型：Implicit in this argument/policy is the assumption that...（隐含在这一论点/政策之中的是……这一假设，直接将形容词短语置于句首倒装，极具冲击力！）。【高阶替换】升级 implied / unspoken / tacit / underlying；词根 im-（向内）+ plic-（折叠），指未直接写出但可通过逻辑推导或语境领悟的含义。【避坑指南】介词搭配必考：表示“隐含在……之中”必须用 implicit in（如 the values implicit in the curriculum），切勿受 imply 影响误加介词 by 或 from；此外熟词僻义 implicit trust/faith 意为“毫无疑问的绝对信任”，需结合宾语识别。","forms":["implicitly"],"frequency":{"ielts":5,"gre":5},"id":"implicit","pos":"adj.","libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["观点评价"],"register":"正式（深层逻辑挖掘与意识形态批判）· 极适合在大作文分析段挖掘某种政策、广告或社会现象背后“未明言的隐含假设或偏见”。","synonyms":[{"id":"tacit","note":"implicit 指含义隐含在言辞或行动中未直接点明；tacit 指心照不宣、默许的（如 tacit agreement）。"},{"id":"covert","note":"在表示不直接言明时相近；implicit 指含蓄蕴含，covert 指刻意隐藏不露。"}],"antonyms":[{"id":"explicit","note":"反义对照：implicit 表“含蓄的”，而 explicit 表“清楚的”，二者构成鲜明的语义对立。"},{"id":"overt","note":"语境对照：implicit（含蓄的）与 overt（公开的）在论证方向上构成反义或鲜明对比。"}],"partners":[{"id":"assumption","rel":"形+名","phrase":"an implicit assumption underlying","note":"常用搭配：an implicit assumption underlying（潜藏于……背后的隐含假设），与 assumption（假设、假定）构成高频「形+名」词伙。"},{"id":"argument","rel":"形+名","phrase":"remain implicit in the argument","note":"常用搭配：remain implicit in the argument（隐含在该论证之中），与 argument（论证、论点）构成高频「形+名」词伙。"}]},{"word":"rigorous","ipa":{"uk":"/ˈrɪɡərəs/","us":"/ˈrɪɡərəs/"},"definition":{"en":"Conducted with careful attention to strict standards of reasoning or method.","zh":"严谨的；严格遵守推理或方法标准的。"},"collocations":[{"en":"subject to rigorous scrutiny","zh":"接受严格的审查/审视"},{"en":"a rigorous methodological framework","zh":"严谨的方法论框架"},{"en":"enforce rigorous safety standards","zh":"执行严格的安全标准"},{"en":"undergo rigorous clinical testing","zh":"经历严格的临床测试"}],"examples":[{"type":"IELTS","en":"Before approving genetically modified crops for commercial cultivation, regulatory agencies must subject them to rigorous testing to rule out unforeseen ecological repercussions.","zh":"在批准转基因作物进行商业化种植之前，监管机构必须对其进行严格测试，以排除不可预见的生态后果。","highlights":["rigorous testing"]},{"type":"IELTS","en":"Maintaining rigorous academic standards in secondary schools does not require subjecting adolescents to relentless rote memorisation and high-stakes standardized exams.","zh":"在中学维持严谨的学术标准，并不意味着要让青少年承受无休止的死记硬背和高风险的标准化考试。","highlights":["rigorous academic standards"]},{"type":"GRE","en":"Although the revisionist hypothesis is intuitively appealing, rigorous archival analysis is required to distinguish its predictions from those of conventional institutional histories.","zh":"尽管修正主义假说在直觉上颇具吸引力，但仍需严谨的档案分析，方能将其预测与传统制度史的预测区分开来。","highlights":["rigorous archival analysis"]}],"note":"【句型框架】常作定语修饰研究、审查或标准：commission/conduct a rigorous analysis of...；或被动结构：be subjected to rigorous scrutiny/testing before implementation。【高阶替换】强力升级 strict / careful / thorough；相比 harsh / severe（侧重惩罚严厉冷酷，常含贬义），rigorous 是典型的学术褒义词，强调“逻辑严密、程序规范、一丝不苟”。【避坑指南】拼写与派生词极易出错：形容词 rigorous 中间是 -or-（没有 u！），但英式名词形式为 rigour（美式 rigor）；此外不要用 rigorous 修饰惩罚措施（如不说 *rigorous punishment，应说 severe/stringent punishment）。","forms":["rigorously","rigour","rigor"],"frequency":{"ielts":5,"gre":5},"id":"rigorous","pos":"adj.","libraries":["writing"],"topics":["科技与教育","逻辑与论证"],"functions":["观点评价","替换基础词"],"register":"正式（学术标准与制度规范）· 适用于教育评估、科研方法、食品安全或法律监管等议题，强调过程严密、标准严格、绝不流于形式。","synonyms":[{"id":"thorough","note":"rigorous 强调方法或推理的严格性；thorough 强调覆盖充分、细节不遗漏，周全并不自动保证方法正确。"},{"id":"scrupulous","note":"scrupulous 强调操守或核查一丝不苟；rigorous 强调方法论与逻辑极其严密。"},{"id":"stringent","note":"rigorous 侧重科研方法、逻辑推理或学术标准极其严密；stringent 侧重法律法规或准入条件严格硬性。"},{"id":"meticulous","note":"rigorous 强调体系与方法论层面的严格；meticulous 强调对微小细节的一丝不苟。"}],"antonyms":[{"id":"superficial","note":"在检查与分析的深度上构成对照：严格周全与表面、草率简略。"},{"id":"anecdotal","note":"rigorous 严谨系统的，与零散个案式的 anecdotal 相反。"},{"id":"desultory","note":"rigorous 严密系统的，与松散随意的 desultory 相对。"}],"partners":[{"id":"scrutiny","rel":"形+名","phrase":"subject to rigorous scrutiny","note":"常用搭配：subject to rigorous scrutiny（接受严格的审查/审视），与 scrutiny（审查、细察）构成高频「形+名」词伙。"},{"id":"framework","rel":"形+名","phrase":"a rigorous methodological framework","note":"常用搭配：a rigorous methodological framework（严谨的方法论框架），与 framework（框架、体系）构成高频「形+名」词伙。"}]},{"word":"superficial","ipa":{"uk":"/ˌsuːpəˈfɪʃəl/","us":"/ˌsuːpɚˈfɪʃəl/"},"definition":{"en":"Concerned only with obvious surface features and lacking deeper understanding.","zh":"肤浅的；仅关注表面特征而缺乏深入理解的。"},"collocations":[{"en":"a superficial understanding of","zh":"对……肤浅的理解"},{"en":"beneath the superficial similarities","zh":"在表面的相似之处背后"},{"en":"offer only a superficial remedy","zh":"仅提供治标不治本的表面补救"},{"en":"a superficial engagement with","zh":"对……流于表面的接触/参与"}],"examples":[{"type":"IELTS","en":"Consuming fragmented news clips on algorithm-driven platforms often fosters a superficial understanding of intricate geopolitical conflicts that demand historical context.","zh":"在算法驱动的平台上消费碎片化新闻短视频，往往会导致人们对需要历史背景的复杂地缘政治冲突形成肤浅的理解。","highlights":["a superficial understanding of"]},{"type":"IELTS","en":"Merely repainting dilapidated tenements without upgrading sewage and electrical grids offers only a superficial remedy for urban housing deprivation.","zh":"仅仅重新粉刷破旧的廉租公寓而不升级排污与电力管网，对城市住房贫困而言只提供了治标不治本的表面补救。","highlights":["a superficial remedy"]},{"type":"GRE","en":"Despite their superficial similarities in ceremonial architecture, the two agrarian polities evolved under markedly different ecological constraints and exhibited divergent kinship structures.","zh":"尽管这两个农耕政体在礼仪建筑上具有表面相似性，但它们在截然不同的生态约束下演化，并呈现出迥异的亲属结构。","highlights":["superficial similarities"]}],"note":"【句型框架】常用于揭示表象与本质的冲突：Despite their superficial similarities, A and B differ fundamentally in...；或 X provides only a superficial remedy rather than addressing the root causes。【高阶替换】升级 shallow / surface-level / skin-deep；词根 super-（在……上面）+ fac-（表面 face），既可作贬义指认知或措施“浮于表面的、治标不治本的”，也可作中性客观描述“表层的（如 superficial similarities）”。【避坑指南】注意语境感情色彩：在批评理解或政策时（superficial analysis/solution）为明确贬义；但在对比两个事物的表层特征（superficial resemblance）或医学描述表皮创伤（superficial wound）时属于客观中性表达，不可一概视为贬低。","forms":["superficially"],"frequency":{"ielts":5,"gre":5},"id":"superficial","pos":"adj.","libraries":["writing"],"topics":["科技与教育","逻辑与论证"],"functions":["观点评价","替换基础词"],"register":"正式（深度批判与现象剖析）· 常用于大作文指出某项政策治标不治本（superficial remedy），或批评碎片化媒介导致认知肤浅。","synonyms":[{"id":"cursory","note":"superficial 强调只触及表面、缺少深度；cursory 强调匆忙简略，可能导致分析肤浅。"},{"id":"sketchy","note":"近义辨析：二者在“粗略”义项上相通；superficial 侧重“表面的”，sketchy 侧重“粗略的”。"},{"id":"shallow","note":"superficial 侧重停留在表面特征而未触及深层本质；shallow 侧重思考、见识或感情浅薄。"}],"antonyms":[{"id":"rigorous","note":"反义对照：superficial 表“表面的”，而 rigorous 表“严密的”，二者构成鲜明的语义对立。"},{"id":"holistic","note":"头痛医头、流于表面的（superficial）处理方式与标本兼治的整体方案（holistic）相反。"},{"id":"profound","note":"反义对照：superficial 表“表面的”，而 profound 表“深切的”，二者构成鲜明的语义对立。"}],"partners":[{"id":"remedy","rel":"形+名","phrase":"offer only a superficial remedy","note":"常用搭配：offer only a superficial remedy（仅提供治标不治本的表面补救），与 remedy（补救措施、疗法）构成高频「形+名」词伙。"},{"id":"similarity","rel":"形+名","phrase":"beneath the superficial similarities","note":"常用搭配：beneath the superficial similarities（在表面的相似之处背后），与 similarity（相似点、类似之处）构成高频「形+名」词伙。"}]},{"word":"cohesion","ipa":{"uk":"/kəʊˈhiːʒən/","us":"/koʊˈhiːʒən/"},"definition":{"en":"The degree to which members or parts remain closely connected as a whole.","zh":"凝聚力；成员或各部分紧密联系成整体的程度。"},"collocations":[{"en":"foster or strengthen social cohesion","zh":"培育或增强社会凝聚力"},{"en":"erode community cohesion","zh":"侵蚀社区凝聚力"},{"en":"threaten national cohesion and stability","zh":"威胁国家凝聚力与稳定"},{"en":"promote group cohesion among diverse peers","zh":"在多元同辈群体间促进团队凝聚力"}],"examples":[{"type":"IELTS","en":"Welfare policies that narrow extreme wealth disparities strengthen social cohesion by ensuring that all citizens feel a shared stake in national prosperity.","zh":"缩小极端财富差距的福利政策通过确保所有公民都能感受到自身与国家繁荣休戚与共，从而增强社会凝聚力。","highlights":["strengthen social cohesion"]},{"type":"IELTS","en":"Well-designed public parks and civic libraries serve as vital gathering spaces that foster community cohesion across generational and ethnic lines.","zh":"设计精良的公共公园和市民图书馆充当了重要的聚会场所，促进了跨代际和跨族裔的社区凝聚力。","highlights":["foster community cohesion"]},{"type":"GRE","en":"Internal group cohesion intensified when members adopted shared rituals, although this heightened solidarity occasionally stifled constructive methodological dissent.","zh":"当成员采纳共同仪式后，内部群体凝聚力显著增强，尽管这种高度团结有时压制了建设性的方法论异议。","highlights":["group cohesion"]},{"type":"GRE","en":"Sociologists warn that residential segregation along socioeconomic lines corrodes civic cohesion by depriving affluent and underprivileged citizens of everyday contact.","zh":"社会学家警告称，按社会经济阶层划分的居住隔离剥夺了富裕公民与弱势公民日常接触的机会，从而腐蚀了公民社会的凝聚力。","highlights":["corrodes civic cohesion"]}],"note":"【句型框架】不可数名词，黄金搭配为 `foster / cultivate / bolster social cohesion`（增强社会凝聚力）与 `erode / undermine / fracture social cohesion`（破坏社会凝聚力）。【高阶替换】高分替换 `unity`、`togetherness` 或 `solidarity`。相比带有政治动员色彩的 `solidarity`（团结一致对抗外力），`social cohesion` 是社会学与公共政策的标准术语，强调社会各阶层、各群体之间彼此信任、和谐共处且不产生撕裂的状态。【避坑指南】区分语言学评分标准中的 `cohesion`（句子间的形式衔接）与 `coherence`（段落逻辑的连贯）；形容词为 `cohesive`（如 `a cohesive society`）。","forms":["cohesive"],"frequency":{"ielts":5,"gre":4},"id":"cohesion","pos":"n.","libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["利弊权衡","因果与影响"],"register":"正式核心学术名词 · 雅思社会类大作文（多元文化融合、贫富分化、社区建设、国民教育功能）中的核心立论概念。","synonyms":[{"id":"unity","note":"unity 强调整体一致或团结；cohesion 强调各部分结合紧密的程度，不要求成员观点完全一致。"},{"id":"integration","note":"良好的社会融合（social integration）直接促进社会凝聚力（social cohesion）。"},{"id":"solidarity","note":"cohesion 侧重社会或群体内部各部分紧密结合的凝聚力；solidarity 侧重群体成员为共同利益而同舟共济的团结。"}],"antonyms":[{"id":"fragmentation","note":"社会或组织的结合状态对照：团结与凝聚，相对于分裂与碎片化；division 的分工义不属于本组。"},{"id":"polarisation","note":"社会凝聚团结（cohesion）与两极撕裂（polarisation）互为反义。"}],"partners":[{"id":"foster","rel":"动+名","phrase":"foster or strengthen social cohesion","note":"常用搭配：foster or strengthen social cohesion（培育或增强社会凝聚力），与 foster（培育、促进）构成高频「动+名」词伙。"},{"id":"erode","rel":"动+名","phrase":"erode community cohesion","note":"常用搭配：erode community cohesion（侵蚀社区凝聚力），与 erode（侵蚀、削弱）构成高频「动+名」词伙。"}]},{"word":"consensus","ipa":{"uk":"/kənˈsensəs/","us":"/kənˈsensəs/"},"definition":{"en":"Broad agreement within a group about a judgement or course of action.","zh":"共识；群体对判断或行动方案的广泛一致意见。"},"collocations":[{"en":"reach a broad consensus on","zh":"就……达成广泛共识"},{"en":"an overwhelming scientific consensus","zh":"压倒性的科学共识"},{"en":"forge a bipartisan or political consensus","zh":"凝聚两党或政治共识"},{"en":"challenge the prevailing consensus that","zh":"挑战认为……的主流共识"}],"examples":[{"type":"IELTS","en":"Despite an overwhelming scientific consensus regarding anthropogenic climate change, international negotiations often stall over how to apportion financial responsibility.","zh":"尽管科学界对人为气候变化已达成压倒性共识，但国际谈判往往在如何分摊资金责任的问题上陷入僵局。","highlights":["an overwhelming scientific consensus"]},{"type":"IELTS","en":"Transparent public consultations can help municipal planners reach a broad consensus on transport priorities before disruptive construction begins.","zh":"透明的公众咨询可以在具有干扰性的施工开始前，帮助市政规划者就交通优先事项达成广泛共识。","highlights":["reach a broad consensus on"]},{"type":"GRE","en":"A scholarly consensus emerged concerning the manuscript's provenance, although philologists continued to debate the ideological motives behind its redaction.","zh":"学界就该手稿的出处达成了共识，但语文学家们仍在争论其编纂背后的意识形态动机。","highlights":["A scholarly consensus"]},{"type":"GRE","en":"Revisionist historians shattered the post-war consensus that industrialization had uniformly elevated living standards during the early nineteenth century.","zh":"修正主义历史学家打破了战后的主流共识，即认为工业化在十九世纪初期普遍提升了民众的生活水平。","highlights":["the post-war consensus"]}],"note":"【句型框架】常用于 `There is a growing / broad consensus among [学者/公众] that + 同位语从句`（在……中已形成广泛共识），或动词搭配 `reach / build / forge a consensus on sth`。【高阶替换】完美升级 `most people agree` 或 `general agreement`。【避坑指南】由于 `consensus` 本身就包含“共同意见（con-共同 + sensus感觉/意见）”之义，严禁写出 `consensus of opinion` 或 `mutual consensus` 这类语义赘余（Chinglish 常见扣分项）；另外该词无复数用法，搭配介词用 `on / about / regarding`。","forms":[],"frequency":{"ielts":5,"gre":5},"id":"consensus","pos":"n.","libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["观点评价","让步转折"],"register":"正式核心学术名词 · 适用于雅思大作文导言段背景引入（如“科学界已达成广泛共识”）或主体段讨论民主协商与公共决策。","synonyms":[{"id":"agreement","note":"consensus 是群体中的广泛共识，不必全员一致；agreement 可指两方同意，也可指具体协议。"},{"id":"accord","note":"consensus 侧重群体内部经讨论达成的广泛共识；accord 侧重各方立场协调一致或正式达成的协定。"}],"antonyms":[{"id":"dissent","note":"对同一主张的意见状态对照：形成共识或同意，与持异议或存在分歧。"},{"id":"polarisation","note":"达成广泛共识（consensus）与观点两极对立（polarisation）在政治与舆论议题中直接相反。"}],"partners":[{"id":"reach","rel":"动+名","phrase":"reach a broad consensus on","note":"常用搭配：reach a broad consensus on（就……达成广泛共识），与 reach（达成、到达）构成高频「动+名」词伙。"},{"id":"scientific","rel":"形+名","phrase":"an overwhelming scientific consensus","note":"常用搭配：an overwhelming scientific consensus（压倒性的科学共识），与 scientific（科学的）构成高频「形+名」词伙。"}]},{"word":"dissent","ipa":{"uk":"/dɪˈsent/","us":"/dɪˈsent/"},"definition":{"en":"The expression or holding of opinions opposed to a prevailing or official position.","zh":"异议；持有或表达与主流或官方立场相反的意见。"},"collocations":[{"en":"stifle or suppress political dissent","zh":"扼杀或压制政治异议"},{"en":"tolerate constructive dissent","zh":"容忍建设性的不同意见"},{"en":"a solitary voice of dissent","zh":"孤独的反对声音"},{"en":"express sharp dissent from the prevailing orthodoxy","zh":"对主流正统观念表达强烈异议"}],"examples":[{"type":"IELTS","en":"Organisations that stifle constructive dissent often achieve superficial harmony while losing the critical feedback required to avert strategic blunders.","zh":"扼杀建设性异议的组织或许能取得表面的和谐，却会失去避免重大战略失误所需的批判性反馈。","highlights":["stifle constructive dissent"]},{"type":"IELTS","en":"In a healthy democratic society, independent journalism serves as a vital forum where citizens can voice legitimate dissent against flawed public policies.","zh":"在健康的民主社会中，独立新闻业充当着至关重要的论坛，使公民能够针对有缺陷的公共政策表达合理的异议。","highlights":["voice legitimate dissent"]},{"type":"GRE","en":"Surviving correspondence reveals considerable methodological dissent among naturalists whom later textbook authors mistakenly portrayed as a monolithic school.","zh":"现存书信揭示出这些博物学家之间存在相当大的方法论分歧，而后世教科书作者却误将他们描绘成一个铁板一块的学派。","highlights":["methodological dissent"]},{"type":"GRE","en":"Whereas the majority ruling upheld the regulatory statute, the chief justice issued a trenchant dissent warning of unchecked administrative overreach.","zh":"多数派裁决维持了该监管法规，而首席大法官则发表了一份犀利的反对意见书，警告行政权力可能出现不受制约的越界。","highlights":["a trenchant dissent"]}],"note":"【句型框架】作不可数名词时常搭配 `suppress / stifle / brook no dissent`（压制/不容忍异议）或 `voice / express dissent`（表达异议）；作不及物动词时用 `dissent from [主流观点/裁决]`。【高阶替换】升级普通的 `disagreement` 或 `opposition`。相比日常的 `disagreement`，`dissent` 专指“针对官方立场、主流共识（`consensus`）或权威决定的公开不赞同与异议”。【避坑指南】千万不要与发音完全相同但拼写不同的 `descent`（下降；血统）以及重音在首音节的 `decent`（体面的）混淆！","forms":["dissenting"],"frequency":{"ielts":5,"gre":5},"id":"dissent","pos":"n.","libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["观点评价","让步转折"],"register":"正式学术与政法名词/动词 · 适用于雅思媒体审查、言论自由、企业组织文化（容忍异见以防群体盲思）及 GRE 科学史与思想史语境。","synonyms":[{"id":"disagreement","note":"dissent 通常表示反对主流、官方或共同立场；disagreement 泛指意见不一致，并不必然涉及权威。"},{"id":"objection","note":"dissent 侧重对官方决议或主流共识持有异议；objection 侧重针对某项具体提议或做法提出反对理由。"}],"antonyms":[{"id":"consensus","note":"反义对照：dissent 表“异议”，而 consensus 表“共识”，二者构成鲜明的语义对立。"},{"id":"agreement","note":"反义对照：dissent 表“异议”，而 agreement 表“同意”，二者构成鲜明的语义对立。"}],"partners":[{"id":"suppress","rel":"动+名","phrase":"stifle or suppress political dissent","note":"常用搭配：stifle or suppress political dissent（扼杀或压制政治异议），与 suppress（压制、镇压）构成高频「动+名」词伙。"},{"id":"tolerate","rel":"动+名","phrase":"tolerate constructive dissent","note":"常用搭配：tolerate constructive dissent（容忍建设性的不同意见），与 tolerate（容忍、宽容）构成高频「动+名」词伙。"}]},{"word":"mandatory","ipa":{"uk":"/ˈmændətəri/","us":"/ˈmændətɔːri/"},"definition":{"en":"Required by an authoritative rule rather than left to individual choice.","zh":"强制性的；由有权制定的规则要求而非自由选择的。"},"collocations":[{"en":"make community service mandatory","zh":"将社区服务设为强制性要求"},{"en":"mandatory sentencing laws","zh":"强制性量刑法律"},{"en":"mandatory corporate disclosure","zh":"企业强制信息披露"},{"en":"impose mandatory quotas","zh":"实施强制性配额"}],"examples":[{"type":"IELTS","en":"Mandatory training can improve workplace safety, provided that employers give staff sufficient time to practise the procedures rather than merely complete forms.","zh":"强制培训能够改善职场安全，前提是雇主给员工足够时间练习相关程序，而不只是填写表格。","highlights":["Mandatory training"]},{"type":"IELTS","en":"Making unpaid community service mandatory for high school graduation risks turning genuine civic altruism into a resentful bureaucratic chore.","zh":"将无偿社区服务列为高中毕业的强制性要求，可能会使真正的公民利他主义沦为令人反感的应付差事。","highlights":["mandatory for high school graduation"]},{"type":"GRE","en":"The introduction of mandatory disclosure altered the information available to participants, complicating comparisons with behaviour observed under the previous institutional arrangement.","zh":"强制披露的引入改变了参与者可获得的信息，使其行为与此前制度安排下的行为更难直接比较。","highlights":["mandatory disclosure"]}],"note":"【句型框架】① Making X mandatory for all citizens/students can...（动名词主语句：将 X 设为全员强制要求能够……）；② shift from voluntary guidelines to mandatory regulations（从自愿性指南转向强制性法规——环保/企业责任类话题核心对比框架）。【高阶替换】全面替换 must-do、required by law、forced；与 compulsory 同为“强制的”，但细微语感上，compulsory 常用于普及性的制度义务（如 compulsory education 义务教育、compulsory voting 强制投票），而 mandatory 源自 mandate（法令/授权），更强调“法规条文、行业准则或合同硬性规定、不执行即受罚”。【避坑指南】mandatory 已有“必须要求”之意，若写 a mandatory requirement 在极为严格的学术编辑眼中略显语义重复（更凝练的写法是 a statutory mandate 或 mandatory compliance）；搭配介词用 mandatory for sb to do sth。","forms":[],"frequency":{"ielts":5,"gre":4},"id":"mandatory","pos":"adj.","libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["观点评价","利弊权衡"],"register":"正式法律与公共政策语域；常用于教育课程设置、公共卫生、职场安全及环保法规类大作文中讨论“强制推行 vs 自愿选择”","synonyms":[{"id":"compulsory","note":"mandatory 与 compulsory 都表示被要求必须执行；mandatory 常见于制度规定，compulsory 常见于教育、训练或服务。"},{"id":"imperative","note":"mandatory 指法律或规章强制规定的；imperative 指客观形势迫切要求必须做的。"},{"id":"obligatory","note":"mandatory 侧重法律法规或管理制度明文规定必须执行的；obligatory 侧重法律条文或社会道义上义不容辞的。"}],"antonyms":[{"id":"optional","note":"就参与是否属于强制要求进行对照；自愿参与可能需要报名，但报名要求不改变其自愿性质。"},{"id":"voluntary","note":"语境对照：voluntary（自愿的）与 mandatory（强制性的）在论证方向上构成反义或鲜明对比。"},{"id":"discretionary","note":"反义对照：mandatory 表规则强制要求必须执行的，而 discretionary 表可由当事人自由裁量决定的。"}],"partners":[{"id":"law","rel":"形+名","phrase":"mandatory sentencing laws","note":"常用搭配：mandatory sentencing laws（强制性量刑法律），与 law（法律、法规）构成高频「形+名」词伙。"},{"id":"quota","rel":"形+名","phrase":"impose mandatory quotas","note":"常用搭配：impose mandatory quotas（实施强制性配额），与 quota（配额、定额）构成高频「形+名」词伙。"}]},{"word":"homogeneous","ipa":{"uk":"/ˌhɒməˈdʒiːniəs/","us":"/ˌhoʊmoʊˈdʒiːniəs/"},"definition":{"en":"Composed of parts that are similar with respect to a specified characteristic.","zh":"同质的；组成部分在所讨论特征上相似的。"},"collocations":[{"en":"treat learners as a homogeneous group","zh":"将学习者视为同质化群体"},{"en":"a culturally homogeneous society","zh":"文化高度同质化的社会"},{"en":"create a homogeneous urban landscape","zh":"造成千篇一律的同质化城市景观"},{"en":"draw from a homogeneous sample","zh":"从同质样本中抽样"}],"examples":[{"type":"IELTS","en":"Standardised national curricula often fail because they treat students as a homogeneous group, ignoring vast regional disparities in prior literacy and linguistic background.","zh":"标准化的国家课程往往会失败，因为它们将学生视为同质群体，忽视了学生在先前读写能力和语言背景上的巨大地区差异。","highlights":["treat students as a homogeneous group"]},{"type":"IELTS","en":"The relentless expansion of multinational retail chains threatens to transform distinctive historic towns into a homogeneous commercial landscape devoid of local character.","zh":"跨国零售连锁店的无休止扩张，恐将独具特色的历史城镇变成缺乏地方特色的同质化商业景观。","highlights":["a homogeneous commercial landscape"]},{"type":"GRE","en":"Recruiting experimental subjects from a demographically homogeneous sample may reduce statistical variance while severely limiting the generalisability of the clinical findings.","zh":"从人口特征同质化的样本中招募实验受试者或许能减少统计方差，但会严重限制临床研究结论的普适推广性。","highlights":["a demographically homogeneous sample"]}],"note":"【句型框架】教育与文化类高频高分句：One-size-fits-all policies erroneously assume that citizens form a homogeneous group（一刀切的政策错误地假定公民构成一个同质群体）；名词形式 homogeneity 可用于 cultural homogeneity（文化同质化）。【高阶替换】精准替代 uniform / all the same / identical；词根 homo-（相同 same）+ gen-（种类 kind），其绝对反义词为 heterogeneous（异质的、多元混杂的，a heterogeneous population）。【避坑指南】高频拼写陷阱：标准学术拼写为 homogeneous（结尾是 -neous，有 e！），切勿漏掉 e 写成 *homogenous（虽部分词典收录为生物学术语变体，但在雅思与GRE标准评分中均以 homogeneous 为正统）。","forms":["homogeneously","homogeneity"],"frequency":{"ielts":5,"gre":5},"id":"homogeneous","pos":"adj.","libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["观点评价","比较与对照"],"register":"正式（社会人口学、教育分层与全球化文化同质化）· 雅思文化类（全球化导致商业与街景千篇一律）与教育类（拒绝将学生视为同质群体）超核心形容词。","synonyms":[{"id":"uniform","note":"homogeneous 强调组成部分在特定性质上相似；uniform 强调各处一致或标准相同，可指规则、分布与外观。"},{"id":"monolithic","note":"homogeneous 指内部成分同类同质；monolithic 强调庞大且铁板一块、毫无内部差异。"},{"id":"kindred","note":"近义辨析：二者在“同类、同族”义项上相通；homogeneous 侧重“同种类的”，kindred 侧重“同类的”。"}],"antonyms":[{"id":"heterogeneous","note":"按明确指定的特征比较相似性与差异性；同一群体可能在某一特征上同质、在另一特征上多样。"},{"id":"dichotomous","note":"homogeneous 均质同一的，与一分为二的 dichotomous 相对。"},{"id":"pluralistic","note":"homogeneous 强调内部同质均一，与多元异质相对。"}],"partners":[{"id":"group","rel":"形+名","phrase":"treat learners as a homogeneous group","note":"常用搭配：treat learners as a homogeneous group（将学习者视为同质化群体），与 group（群体、组）构成高频「形+名」词伙。"},{"id":"sample","rel":"形+名","phrase":"draw from a homogeneous sample","note":"常用搭配：draw from a homogeneous sample（从同质样本中抽样），与 sample（样本、抽样）构成高频「形+名」词伙。"}]},{"word":"heterogeneous","ipa":{"uk":"/ˌhetərəˈdʒiːniəs/","us":"/ˌhetəroʊˈdʒiːniəs/"},"definition":{"en":"Composed of parts that differ in type, background, or relevant characteristics.","zh":"异质的；由类型、背景或相关特征不同的部分组成的。"},"collocations":[{"en":"a culturally heterogeneous population","zh":"文化背景多元异质的人口"},{"en":"heterogeneous learning needs","zh":"异质化的学习需求"},{"en":"exhibit heterogeneous effects across subgroups","zh":"在不同子群体间呈现出异质性效应"},{"en":"a heterogeneous array of stakeholders","zh":"由多元异质利益相关者组成的群体"}],"examples":[{"type":"IELTS","en":"Public healthcare systems must adapt to a culturally heterogeneous population, offering tailored preventative programmes rather than assuming that every community faces identical health risks.","zh":"公共医疗体系必须适应文化背景多元异质的人口，提供量身定制的预防项目，而不应假定每个社区都面临完全相同的健康风险。","highlights":["a culturally heterogeneous population"]},{"type":"IELTS","en":"Standardised curricula often fail because classrooms comprise learners with heterogeneous learning needs, cognitive styles, and socioeconomic backgrounds.","zh":"标准化课程之所以常常失效，是因为课堂由具有异质化学习需求、认知风格和社会经济背景的学习者组成。","highlights":["heterogeneous learning needs"]},{"type":"GRE","en":"The aggregate statistic obscured markedly heterogeneous effects across subgroups, with the fiscal stimulus invigorating urban technology hubs while leaving rural manufacturing districts stagnant.","zh":"总体统计数据掩盖了不同子群体之间显著的异质性效应：财政刺激计划激活了城市科技中心，却使农村制造业地区停滞不前。","highlights":["heterogeneous effects across subgroups"]},{"type":"GRE","en":"Far from representing a unified ideological bloc, the reform movement was a heterogeneous coalition of agrarian populists, urban guild artisans, and disaffected clerics.","zh":"这场改革运动远非一个统一的意识形态阵营，而是由农业民粹主义者、城市行会工匠和心怀不满的神职人员组成的异质联盟。","highlights":["a heterogeneous coalition"]}],"note":"【句型框架】常用于 `cater to a heterogeneous population / student body`（满足异质人群/学生群体的需求）或 `exhibit heterogeneous effects across...`（在……间呈现异质性效应）。【高阶替换】直接升级 Band 6 的 `different kinds of`、`mixed` 或泛泛的 `diverse`。相比 `diverse`（侧重多样性且常带褒义），`heterogeneous` 更具客观冷峻的学术分析色彩，强调内部组成部分在性质、结构或背景上存在本质差异，反义词为 `homogeneous`（同质的）。【避坑指南】注意拼写中包含 `gene`（词根意为“种类”），切勿漏写字母 `e` 写成 `heterogenous`；此外该词修饰集合名词（如 `population`, `group`, `workforce`）而非单个个体。","forms":["heterogeneously","heterogeneity"],"frequency":{"ielts":5,"gre":5},"id":"heterogeneous","pos":"adj.","libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["观点评价","比较与对照"],"register":"正式学术形容词 · 常用于雅思大作文主体段驳斥“一刀切”政策（如因材施教、多元文化治理、公共医疗供给）及 GRE 统计学与社会学语境。","synonyms":[{"id":"diverse","note":"heterogeneous 指由不同类型或性质的部分组成；diverse 更广泛地强调种类、经历或观点的多样性。"},{"id":"pluralistic","note":"heterogeneous 强调构成成分性质各异，pluralistic 强调多元共生。"},{"id":"dissimilar","note":"近义辨析：二者在“异质的”义项上相通；heterogeneous 侧重“异类的”，dissimilar 侧重“不同的”。"}],"antonyms":[{"id":"homogeneous","note":"反义对照：heterogeneous 表“异类的”，而 homogeneous 表“同种类的”，二者构成鲜明的语义对立。"},{"id":"monolithic","note":"GRE 阅读常考逻辑：证明看似 monolithic 的传统实际上是 heterogeneous 的。"}],"partners":[{"id":"population","rel":"形+名","phrase":"a culturally heterogeneous population","note":"常用搭配：a culturally heterogeneous population（文化背景多元异质的人口），与 population（人口、群体）构成高频「形+名」词伙。"},{"id":"effect","rel":"形+名","phrase":"exhibit heterogeneous effects across subgroups","note":"常用搭配：exhibit heterogeneous effects across subgroups（在不同子群体间呈现出异质性效应），与 effect（效应、影响）构成高频「形+名」词伙。"}]},{"id":"precipitate","word":"precipitate","ipa":{"uk":"/prɪˈsɪpɪteɪt/","us":"/prɪˈsɪpɪteɪt/"},"pos":"v.","definition":{"en":"To cause an event or situation, typically one that is bad or undesirable, to happen suddenly, unexpectedly, or prematurely.","zh":"促成，加速引发（通常指突然引发危机、冲突或恶果）；（气象）形成降水；（化学）沉淀。"},"libraries":["writing"],"topics":["自然与环境","逻辑与论证"],"functions":["让步转折","因果与影响"],"frequency":{"ielts":5,"gre":5},"register":"极正式历史、经济与学术因果语域；适用于大作文分析突发导火索如何骤然引发危机、衰退或社会动荡","synonyms":[{"id":"trigger","note":"二者均指突然引发；precipitate 更正式，强调使本在酝酿中的危机或剧变提前骤然爆发。"},{"id":"catalyse","note":"catalyse 常指催化变革或积极进程，precipitate 极常接负面宾语（如 crisis, collapse, war, decline）。"},{"id":"spark","note":"precipitate 侧重使原本酝酿中的危机或剧变提前骤然爆发；spark 侧重像火星一样点燃争论、抗议或创意。"},{"id":"hasten","note":"precipitate 强调突然促成（多为不良后果）；hasten 强调加快原有进程使其早日发生。"}],"antonyms":[{"id":"impede","note":"反义对照：precipitate 表加速促成、骤然引发，而 impede 表阻碍、延缓进程。"},{"id":"retard","note":"反义对照：precipitate 表使危机或结果提前爆发，而 retard 表迟滞、减缓发展。"},{"id":"forestall","note":"反义对照：precipitate 表促成突发事件，而 forestall 表先发制人、预先阻止。"}],"collocations":[{"en":"precipitate a severe macroeconomic recession","zh":"引发严重的宏观经济衰退"},{"en":"precipitate the sudden collapse of","zh":"加速促成……的突然崩溃"},{"en":"precipitate a constitutional or diplomatic crisis","zh":"引发宪政或外交危机"},{"en":"precipitate widespread social unrest","zh":"骤然引发广泛的社会动荡"}],"examples":[{"type":"IELTS","en":"A sudden surge in global energy prices can precipitate a severe macroeconomic recession by driving up manufacturing costs and curbing household consumption.","zh":"全球能源价格的突然飙升会推高制造成本并抑制家庭消费，从而引发严重的宏观经济衰退。","highlights":["precipitate a severe macroeconomic recession"]},{"type":"IELTS","en":"Unregulated speculative lending in the housing sector may precipitate a systemic banking crisis if property values abruptly contract.","zh":"如果房地产价值突然萎缩，住房领域不受监管的投机性放贷可能会引发系统性银行业危机。","highlights":["precipitate a systemic banking crisis"]},{"type":"GRE","en":"Although the envoy's assassination precipitated the outbreak of hostilities, historians agree that deep-seated imperial rivalries had long rendered conflict probable.","zh":"尽管特使遇刺促发了战事的爆发，但历史学家一致认为，根深蒂固的帝国竞争早已使冲突成为大概率事件。","highlights":["precipitated the outbreak of hostilities"]},{"type":"GRE","en":"Critics warned that such a precipitate withdrawal of price controls would destabilize grain markets before domestic harvests could recover.","zh":"批评人士警告称，如此仓促地取消价格管制，会在国内收成恢复之前破坏谷物市场的稳定。","highlights":["precipitate withdrawal"]}],"note":"【句型框架】常用于因果句 `Sudden shock X can precipitate + 负面突发事件（crisis / collapse / recession / unrest）`。【高阶替换】用于替换 `cause suddenly / trigger / bring on`；与 `engender`（缓慢孕育心理或氛围）和 `catalyse`（积极催化变革）不同，`precipitate` 作动词时专指“使糟糕、危险或不受欢迎的局面比预期更早、更猛烈地突然降临”。【避坑指南】GRE 与雅思阅读核心一词多义：作动词读 `/prɪˈsɪpɪteɪt/`（加速引发）；作形容词读 `/prɪˈsɪpɪtət/`，意为“仓促鲁莽的、欠考虑的”（同 `hasty / impetuous`，注意不要与 `precipitous`“陡峭的、暴跌的”混同）；派生名词 `precipitation` 在地理小作文中指“降水量”。","forms":["precipitates","precipitated","precipitating","precipitation"],"partners":[{"id":"recession","rel":"动+名","phrase":"precipitate a severe macroeconomic recession","note":"常用搭配：precipitate a severe macroeconomic recession（引发严重的宏观经济衰退），与 recession（经济衰退）构成高频「动+名」词伙。"},{"id":"crisis","rel":"动+名","phrase":"precipitate a constitutional or diplomatic crisis","note":"常用搭配：precipitate a constitutional or diplomatic crisis（引发宪政或外交危机），与 crisis（危机）构成高频「动+名」词伙。"}]},{"id":"marginalise","word":"marginalise","ipa":{"uk":"/ˈmɑːdʒɪnəlaɪz/","us":"/ˈmɑːrdʒɪnəlaɪz/"},"pos":"v.","definition":{"en":"To treat a person, social group, or concept as insignificant or peripheral, thereby excluding them from mainstream power and resources.","zh":"使边缘化，排挤，轻视（使某群体或观点处于次要、无权的边缘地位）。"},"libraries":["writing"],"topics":["社会与经济","文化与历史"],"functions":["社会结构","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"正式社会政策与文化批评动词 · 适用于雅思老龄化数字鸿沟、少数族裔与残障人士权益、传统手工艺或小语种消亡等议题。","synonyms":[{"id":"alienate","note":"marginalise 侧重在权力、资源或社会地位上将某群体推向边缘（客观结构性排斥）；alienate 侧重在心理与情感上使人产生疏离感与隔阂。"},{"id":"segregate","note":"segregate 指物理空间或制度上的隔离，marginalise 指社会影响力与话语权的边缘化。"},{"id":"exclude","note":"marginalise 侧重将某群体推向社会权力与资源的边缘；exclude 侧重将其直接排斥在某个范围或体制之外。"}],"antonyms":[{"id":"integrate","note":"反义对照：marginalise 表“使边缘化”，而 integrate 表“合并”，二者构成鲜明的语义对立。"},{"id":"incorporate","note":"反义对照：marginalise 表“使边缘化”，而 incorporate 表“把…合并”，二者构成鲜明的语义对立。"},{"id":"lionise","note":"marginalise 将某人边缘化、冷落排挤，与把某人捧为中心名流的 lionise 相反。"}],"collocations":[{"en":"marginalised groups or communities","zh":"边缘化群体或弱势社区"},{"en":"systematically marginalise minority languages","zh":"系统性地使少数民族语言边缘化"},{"en":"feel socially and economically marginalised","zh":"在社会与经济上感到被边缘化"},{"en":"risk marginalising elderly citizens without digital skills","zh":"面临将缺乏数字技能的老年人边缘化的风险"}],"examples":[{"type":"IELTS","en":"The rapid digitisation of banking, ticketing, and municipal services risks marginalising elderly citizens who lack smartphones or digital literacy.","zh":"银行业、票务和市政服务的快速数字化，可能会使缺乏智能手机或数字素养的老年公民陷入被边缘化的境地。","highlights":["risks marginalising elderly citizens"]},{"type":"IELTS","en":"Inclusive urban planning must ensure that low-income tenants are not marginalised and displaced when historic inner-city neighbourhoods undergo commercial gentrification.","zh":"包容性的城市规划必须确保，当历史悠久的市中心街区经历商业绅士化改造时，低收入租户不会被边缘化和驱逐。","highlights":["are not marginalised"]},{"type":"GRE","en":"Revisionist literary histories recover the voices of vernacular women writers whom canonical anthologies had systematically marginalised for generations.","zh":"修正主义文学史重新发掘了那些被经典选集系统性地边缘化了数代之久的方言女性作家的声音。","highlights":["systematically marginalised"]},{"type":"GRE","en":"By privileging quantitative econometric modelling above ethnographic fieldwork, the department gradually marginalised qualitative sociologists within its faculty ranks.","zh":"由于推崇定量计量经济学建模而轻视民族志田野调查，该系在其教职队伍中逐渐将定性社会学家边缘化。","highlights":["gradually marginalised qualitative sociologists"]}],"note":"【句型框架】及物动词（英式 `marginalise`，美式 `marginalize`），常用 `risk marginalising [某群体]`（可能使某群体边缘化）或过去分词作前置定语 `marginalised groups / communities / populations`（边缘化/弱势群体）。【高阶替换】在雅思社会类大作文中，用 `marginalised groups` 替代单薄且略显居高临下的 `poor people`、`weak people` 或 `the disadvantaged`，瞬间体现出政策分析的专业人文关怀。【避坑指南】词根 `margin` 指“页边空白”，引申为把人或事物推向权力与主流关注的边缘；注意它是及物动词，直接接人、群体或文化概念作宾语，无需加介词。","forms":["marginalize","marginalises","marginalised","marginalized","marginalising","marginalisation","marginalization"],"partners":[{"id":"community","rel":"动+名","phrase":"marginalised groups or communities","note":"常用搭配：marginalised groups or communities（边缘化群体或弱势社区），与 community（社区、群体）构成高频「动+名」词伙。"},{"id":"minority","rel":"动+名","phrase":"systematically marginalise minority languages","note":"常用搭配：systematically marginalise minority languages（系统性地使少数民族语言边缘化），与 minority（少数群体、少数民族）构成高频「动+名」词伙。"}]},{"id":"stratification","word":"stratification","ipa":{"uk":"/ˌstrætɪfɪˈkeɪʃn/","us":"/ˌstrætɪfɪˈkeɪʃn/"},"pos":"n.","definition":{"en":"The arrangement or classification of something into different layers or strata, especially the division of society into socioeconomic classes.","zh":"（社会）阶层化，等级分化；（地质或水体的）成层，分层。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["社会结构","比较与对照"],"frequency":{"ielts":5,"gre":4},"register":"正式社会学与教育学高阶名词 · 专用于雅思教育收费、私立学校利弊、贫富代际传递等话题中剖析“社会阶层固化与等级分化”。","synonyms":[{"id":"hierarchy","note":"stratification 强调社会群体按财富、地位像岩层（strata）一样划分为不同阶层的现象；hierarchy 强调上下级从属与权力支配的金字塔体系。"},{"id":"differentiation","note":"stratification 专指社会群体按财富或地位形成纵向等级分层；differentiation 指事物或社会功能向不同方向分化。"}],"antonyms":[{"id":"equity","note":"反义对照：stratification 表“分层”，而 equity 表“公平”，二者构成鲜明的语义对立。"},{"id":"integration","note":"反义对照：stratification 表社会阶层分化与隔离，而 integration 表各群体融为一体的社会融合。"}],"collocations":[{"en":"reinforce or entrenched social stratification","zh":"加剧或根深蒂固的社会阶层分化"},{"en":"socioeconomic stratification in urban housing","zh":"城市住房中的社会经济阶层分化"},{"en":"perpetuate educational stratification across generations","zh":"使教育阶层固化在代际间延续"},{"en":"rigid class stratification","zh":"僵化的阶级分层"}],"examples":[{"type":"IELTS","en":"When elite universities charge exorbitant tuition fees without adequate need-based scholarships, higher education risks reinforcing social stratification rather than promoting upward mobility.","zh":"当精英大学收取高昂学费却未提供充足的助学金时，高等教育可能会加剧社会阶层分化，而非促进向上流动。","highlights":["reinforcing social stratification"]},{"type":"IELTS","en":"The proliferation of exclusive private hospitals and gated communities has deepened socioeconomic stratification in many rapidly industrialising cities.","zh":"高档私立医院和封闭式豪宅社区的激增，加深了许多快速工业化城市中的社会经济阶层分化。","highlights":["deepened socioeconomic stratification"]},{"type":"GRE","en":"Archaeological excavations of mortuary goods revealed pronounced social stratification in a Neolithic settlement previously assumed to be strictly egalitarian.","zh":"对随葬品的考古发掘揭示了在一个此前被认为严格平等的新石器时代聚落中，存在着显著的社会阶层分化。","highlights":["pronounced social stratification"]},{"type":"GRE","en":"Limnologists warn that rising surface temperatures prolong the summer thermal stratification of deep lakes, preventing oxygen-rich surface waters from mixing with the hypolimnion.","zh":"湖泊学家警告称，表层水温升高会延长深水湖泊夏季的热分层现象，阻碍富含氧气的表层水与深水层混合。","highlights":["thermal stratification of deep lakes"]}],"note":"【句型框架】不可数名词，黄金搭配为 `reinforce / perpetuate / entrench social stratification`（强化/延续/固化社会阶层分化），常与 `hinder upward social mobility`（阻碍社会向上流动）对举使用。【高阶替换】将口语化的 `the gap between rich and poor classes` 或 `dividing people into classes` 升级为地道社会学术语。词根 `stratum` 意为“岩层、阶层”（复数形式为 `strata`，如 `people from all social strata` 社会各阶层人士）。【避坑指南】注意单复数变化：抽象过程用 `stratification`（不可数），具体“某一个社会阶层”用 `a social stratum`，多个阶层用 `social strata`（切勿给 `strata` 再加 `s`！）。","forms":["stratify","stratified","stratum","strata"],"partners":[{"id":"reinforce","rel":"动+名","phrase":"reinforce or entrenched social stratification","note":"常用搭配：reinforce or entrenched social stratification（加剧或根深蒂固的社会阶层分化），与 reinforce（强化、加剧）构成高频「动+名」词伙。"},{"id":"perpetuate","rel":"动+名","phrase":"perpetuate educational stratification across generations","note":"常用搭配：perpetuate educational stratification across generations（使教育阶层固化在代际间延续），与 perpetuate（使延续、使固化）构成高频「动+名」词伙。"}]},{"id":"egalitarian","word":"egalitarian","ipa":{"uk":"/ɪˌɡælɪˈteəriən/","us":"/ɪˌɡælɪˈteriən/"},"pos":"adj.","definition":{"en":"Believing in or based on the principle that all people are equal and deserve equal rights, status, and opportunities.","zh":"平等主义的，倡导人人平等的（亦作名词：平等主义者）。"},"libraries":["writing"],"topics":["社会与经济","文化与历史"],"functions":["社会结构","观点评价"],"frequency":{"ielts":5,"gre":4},"register":"正式社会学与政治哲学高阶形容词 · 适用于雅思贫富差距、免费高等教育、全民基本医疗与组织扁平化管理议题。","synonyms":[{"id":"equitable","note":"egalitarian 侧重主张人人在权利与社会地位上生而平等；equitable 侧重资源分配或制度安排公正合理。"},{"id":"democratic","note":"egalitarian 强调消除特权与等级差异的平等主义原则；democratic 强调多数人参与决策的民主原则。"}],"antonyms":[{"id":"hierarchical","note":"反义对照：egalitarian 表主张人人平等的，而 hierarchical 表按等级高低层层划分的。"}],"collocations":[{"en":"an egalitarian society or social order","zh":"人人平等的社会或社会秩序"},{"en":"egalitarian education systems","zh":"平等主义的教育体系"},{"en":"promote a more egalitarian distribution of wealth","zh":"促进更趋均等的财富分配"},{"en":"uphold strictly egalitarian principles","zh":"奉行严格的平等主义原则"}],"examples":[{"type":"IELTS","en":"Nordic nations are widely admired for their egalitarian education systems, which provide high-quality schooling to all children regardless of parental income.","zh":"北欧国家因其平等主义的教育体系而广受赞誉，该体系无论父母收入如何，均向所有儿童提供高质量的学校教育。","highlights":["egalitarian education systems"]},{"type":"IELTS","en":"Progressive taxation and universal healthcare are indispensable policy instruments for building a more egalitarian society.","zh":"累进税制和全民医疗保健是构建更加平等的社会的不可或缺的政策工具。","highlights":["a more egalitarian society"]},{"type":"GRE","en":"Although the nineteenth-century utopian commune professed strictly egalitarian ideals, informal status hierarchies rapidly crystallised around its charismatic founders.","zh":"尽管这个十九世纪的乌托邦公社宣称奉行严格的平等主义理想，但围绕其魅力型创始人的非正式地位等级还是迅速形成了。","highlights":["strictly egalitarian ideals"]},{"type":"GRE","en":"Anthropological studies of nomadic hunter-gatherer bands suggest that fierce resource-sharing norms actively suppressed individual accumulation to preserve an egalitarian ethos.","zh":"对游牧狩猎采集部落的人类学研究表明，严格的资源共享规范主动抑制了个人财富积累，以维护平等主义的群体精神。","highlights":["an egalitarian ethos"]}],"note":"【句型框架】常作前置定语修饰制度、社会或理念：`foster / build a more egalitarian society`（构建更加平等的社会）或 `pursue egalitarian educational policies`（推行平等主义的教育政策）。【高阶替换】全方位升级 `equal` 或 `fair`。辨析：`equal` 仅指客观数值或权利相等（不能说 `an equal society`，因为人与人不可能完全相同），而 `egalitarian`（源自法语 `égal` 平等）专指“政治、社会或经济制度致力于消除特权阶层、保障人人享有平等地位与机会的”。【避坑指南】切勿写出 `an equal society` 或 `equal distribution of wealth`（财富不可能绝对均分），改为 `an egalitarian society` 或 `a more equitable / egalitarian distribution of wealth` 才是地道的C2级表达。","forms":["egalitarianism"],"partners":[{"id":"system","rel":"形+名","phrase":"egalitarian education systems","note":"常用搭配：egalitarian education systems（平等主义的教育体系），与 system（体系、制度）构成高频「形+名」词伙。"},{"id":"principle","rel":"形+名","phrase":"uphold strictly egalitarian principles","note":"常用搭配：uphold strictly egalitarian principles（奉行严格的平等主义原则），与 principle（原则、准则）构成高频「形+名」词伙。"}]},{"id":"disparity","word":"disparity","ipa":{"uk":"/dɪˈspærəti/","us":"/dɪˈspærəti/"},"pos":"n.","definition":{"en":"A great and often unfair difference or inequality between two or more groups in status, wealth, or treatment.","zh":"悬殊，巨大差距，不平等（尤指收入、城乡、医疗或教育资源上的不公差异）。"},"libraries":["writing"],"topics":["社会与经济"],"functions":["比较与对照","社会结构"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与经济统计名词 · 适用于雅思小作文（描述显著数据差距）及大作文（剖析城乡差距、贫富悬殊、性别薪酬差距与数字鸿沟）。","synonyms":[{"id":"inequity","note":"disparity 强调客观数据或规模上的“悬殊差距”（如 income disparity），inequity 强调道德或制度上的“不公正”。"},{"id":"difference","note":"disparity 强调收入、资源或待遇上令人不安的悬殊差距；difference 为中性普通词，泛指一切差异。"}],"antonyms":[{"id":"equity","note":"反义对照：disparity 表悬殊差距与分配失衡，而 equity 表资源与待遇的公平公正。"},{"id":"uniformity","note":"一致与均等（uniformity）同悬殊差异（disparity）相对。"}],"collocations":[{"en":"widening income or wealth disparity","zh":"不断扩大的收入或财富差距"},{"en":"stark regional disparities between urban and rural areas","zh":"城乡之间鲜明的地区发展差距"},{"en":"bridge or narrow the socioeconomic disparity","zh":"弥合或缩小社会经济差距"},{"en":"gender disparity in senior leadership","zh":"高层领导职位中的性别比例悬殊"}],"examples":[{"type":"IELTS","en":"Targeted state investment in rural broadband and clinics is indispensable to narrow the growing disparity between metropolitan centres and remote provinces.","zh":"政府对农村宽带和诊所进行有针对性的投资，对于缩小大都市中心与偏远省份之间日益扩大的差距至关重要。","highlights":["narrow the growing disparity"]},{"type":"IELTS","en":"Subsidised vocational training can help bridge the income disparity between university graduates and manual workers displaced by industrial automation.","zh":"有补贴的职业培训有助于弥合大学毕业生与因工业自动化而失业的体力劳动者之间的收入差距。","highlights":["bridge the income disparity"]},{"type":"GRE","en":"Epidemiological cohorts revealed a stark disparity in postoperative survival rates across socioeconomic strata, even after researchers controlled for baseline comorbidities.","zh":"流行病学队列研究显示，即便在研究人员控制了基线合并症因素之后，不同社会经济阶层之间的术后存活率仍存在巨大差距。","highlights":["a stark disparity in"]},{"type":"GRE","en":"The glaring disparity between the empire's naval expenditure and its meagre agrarian tax base ultimately precipitated a sovereign debt crisis.","zh":"该帝国庞大的海军开支与其微薄的农业税基之间的悬殊差距，最终引发了一场主权债务危机。","highlights":["The glaring disparity between"]}],"note":"【句型框架】既可数也不可数，黄金结构为 `narrow / bridge / exacerbate the disparity between A and B`（缩小/弥合/加剧A与B之间的差距）或 `stark disparities in [income / healthcare access]`（在收入/医疗获取上的悬殊差距）。【高阶替换】完美升级 Band 6 的 `big gap`、`large difference` 或 `inequality`。相比中性的 `difference`，`disparity` 蕴含“数量或质量上极不均衡、往往伴随着社会不公”的深层含义。【避坑指南】注意介词搭配：指“在某方面的差距”用 `disparity in sth`，指“二者之间的差距”用 `disparity between A and B`；形容词形式为 `disparate`（截然不同的、迥异的）。","forms":["disparities","disparate"],"partners":[{"id":"income","rel":"名+名","phrase":"widening income or wealth disparity","note":"常用搭配：widening income or wealth disparity（不断扩大的收入或财富差距），与 income（收入）构成高频「名+名」词伙。"},{"id":"regional","rel":"形+名","phrase":"stark regional disparities between urban and rural areas","note":"常用搭配：stark regional disparities between urban and rural areas（城乡之间鲜明的地区发展差距），与 regional（地区的、区域性的）构成高频「形+名」词伙。"}]},{"id":"polarisation","word":"polarisation","ipa":{"uk":"/ˌpəʊləraɪˈzeɪʃn/","us":"/ˌpoʊlərəˈzeɪʃn/"},"pos":"n.","definition":{"en":"The division of a population, political body, or labour market into two sharply contrasting and mutually antagonistic groups or extremes.","zh":"两极分化，对立化（观点、政治阵营或收入阶层向两个极端分裂的过程）。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["社会结构","比较与对照"],"frequency":{"ielts":5,"gre":4},"register":"正式社会学与政治学核心名词 · 适用于雅思社交媒体“信息茧房/回音室效应”、政治舆论撕裂、AI导致就业市场两极分化等高分议题。","synonyms":[{"id":"fragmentation","note":"fragmentation 指分裂为许多零散碎片（多元碎裂），polarisation 专指分裂并集结到截然对立的“两个极端”。"},{"id":"division","note":"polarisation 强调群体或观点向截然对立的两个极端集结；division 泛指群体内部的分裂与隔阂。"}],"antonyms":[{"id":"cohesion","note":"反义对照：polarisation 表社会或观点向两极撕裂分化，而 cohesion 表紧密团结的社会凝聚力。"},{"id":"consensus","note":"反义对照：polarisation 表立场极端对立，而 consensus 表达成广泛共识。"},{"id":"assimilation","note":"反义对照：polarisation 表两极分化对立，而 assimilation 表不同群体相互同化融合。"}],"collocations":[{"en":"exacerbate political and ideological polarisation","zh":"加剧政治与意识形态两极分化"},{"en":"labour market or occupational polarisation","zh":"劳动力市场或职业两极分化"},{"en":"wealth polarisation between the affluent and the poor","zh":"富人与穷人之间的财富两极分化"},{"en":"fuel social polarisation through algorithmic echo chambers","zh":"通过算法回音室助长社会对立分化"}],"examples":[{"type":"IELTS","en":"Social media algorithms that prioritise outrage-inducing content have been widely criticised for exacerbating political polarisation and eroding civic trust.","zh":"优先推荐煽动性内容的社交媒体算法因加剧政治两极分化和侵蚀公民信任而广受批评。","highlights":["exacerbating political polarisation"]},{"type":"IELTS","en":"Without progressive taxation and robust labour protections, rapid technological disruption risks deepening wealth polarisation within metropolitan economies.","zh":"如果缺乏累进税制和强有力的劳工保护，快速的技术颠覆可能会加深大都市经济体内部的财富两极分化。","highlights":["deepening wealth polarisation"]},{"type":"GRE","en":"Labour economists observe that workplace automation has driven occupational polarisation, hollowing out middle-skill clerical roles while expanding high-wage and low-wage extremes.","zh":"劳动经济学家观察到，工作场所自动化推动了职业两极分化，掏空了中等技能的文职岗位，同时扩大了高薪和低薪两端的规模。","highlights":["occupational polarisation"]},{"type":"GRE","en":"Rather than moderating partisan animus, the proliferation of niche cable news channels accelerated the ideological polarisation of the electorate.","zh":"小众有线新闻频道的激增非但没有缓和党派敌意，反而加速了选民在意识形态上的两极分化。","highlights":["ideological polarisation"]}],"note":"【句型框架】不可数名词（英式 `polarisation`，美式 `polarization`），常搭配动词 `accelerate / exacerbate / deepen / fuel polarisation`（加速/加剧两极分化）。【高阶替换】精准升级 `division into two extremes` 或 `extreme disagreement`。该词在三大高频场景中堪称降维打击：① 社交媒体导致的舆论对立（`ideological polarisation`）；② 自动化掏空中产岗位导致的就业分化（`job polarisation`）；③ 贫富两极分化（`wealth polarisation`）。【避坑指南】不要把所有的“分歧（`disagreement`）”都写成 `polarisation`——只有当群体或数据“向两个截然对立的极端聚集、中间派消失”时才适用。","forms":["polarization","polarise","polarize","polarised"],"partners":[{"id":"exacerbate","rel":"动+名","phrase":"exacerbate political and ideological polarisation","note":"常用搭配：exacerbate political and ideological polarisation（加剧政治与意识形态两极分化），与 exacerbate（加剧、使恶化）构成高频「动+名」词伙。"},{"id":"wealth","rel":"名+名","phrase":"wealth polarisation between the affluent and the poor","note":"常用搭配：wealth polarisation between the affluent and the poor（富人与穷人之间的财富两极分化），与 wealth（财富）构成高频「名+名」词伙。"}]},{"id":"incentivise","word":"incentivise","ipa":{"uk":"/ɪnˈsentɪvaɪz/","us":"/ɪnˈsentɪvaɪz/"},"pos":"v.","definition":{"en":"To motivate or encourage someone to do something by offering them a financial reward or other advantage.","zh":"激励，用奖励激发（尤指通过经济利益或政策优惠引导某种行为）。"},"libraries":["writing"],"topics":["社会与经济"],"functions":["因果与影响","社会结构"],"frequency":{"ielts":5,"gre":3},"register":"正式经济学与公共政策核心动词 · 雅思大作文“措施建议段（Solutions）”阐述政府如何通过税收减免、补贴或奖励引导企业和公众行为的皇冠动词。","synonyms":[{"id":"foster","note":"foster 侧重长期培育某种风气或关系，incentivise 侧重通过具体的利益机制（如减税、补贴、奖金）刺激行为主体的积极性。"},{"id":"promote","note":"promote 是广义的促进，incentivise 明确点出“利用激励机制来推动”。"},{"id":"motivate","note":"incentivise 侧重通过财政补贴、减税或奖励机制引导行为；motivate 泛指激发人的内在动力或积极性。"},{"id":"stimulate","note":"incentivise 强调以具体利益诱因激励行为主体；stimulate 强调刺激经济增长、消费或思维活力。"}],"antonyms":[{"id":"hinder","note":"反义对照：incentivise 表“激励”，而 hinder 表“阻碍”，二者构成鲜明的语义对立。"},{"id":"inhibit","note":"反义对照：incentivise 表“激励”，而 inhibit 表“抑制”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"incentivise businesses to adopt green technologies","zh":"激励企业采用绿色技术"},{"en":"financially incentivised to reduce carbon emissions","zh":"受到经济利益激励而减少碳排放"},{"en":"incentivise commuters to switch to public transit","zh":"激励通勤者改乘公共交通工具"},{"en":"perversely incentivise short-term risk-taking","zh":"反常地激励短期冒险行为"}],"examples":[{"type":"IELTS","en":"Tax rebates and low-interest green loans can effectively incentivise small businesses to invest in energy-efficient machinery.","zh":"税收回扣和低息绿色贷款可以有效激励小企业投资于节能机械设备。","highlights":["effectively incentivise small businesses to"]},{"type":"IELTS","en":"Rather than relying solely on punitive fines, municipalities should incentivise households to recycle by offering deposit-refund schemes.","zh":"市政当局不应仅仅依赖惩罚性罚款，而应通过提供押金退还计划来激励家庭进行垃圾回收。","highlights":["incentivise households to recycle"]},{"type":"GRE","en":"When executive compensation is tied exclusively to quarterly share prices, corporate managers are perversely incentivised to sacrifice long-term research for immediate cost-cutting.","zh":"当高管薪酬完全与季度股价挂钩时，企业管理者会受到反常的激励，为眼前的成本削减而牺牲长期研发。","highlights":["perversely incentivised to"]},{"type":"GRE","en":"Fee-for-service healthcare reimbursement models inadvertently incentivise clinics to maximise the volume of diagnostic procedures rather than patient recovery outcomes.","zh":"按服务项目付费的医疗报销模式在无意中激励诊所最大化诊断程序的数量，而非患者的康复效果。","highlights":["inadvertently incentivise clinics to"]}],"note":"【句型框架】及物动词（英式 `incentivise`，美式 `incentivize`），黄金句型为 `Governments should incentivise [某群体] to do sth by [具体经济/政策手段]`。【高阶替换】在政策建议段完美替换用烂了的 `encourage`。相比泛泛的口头或精神鼓励（`encourage`），`incentivise`（源自名词 `incentive` 激励物/诱因）明确传达出“通过设计制度性的物质奖励、税收优惠或利益导向来驱动目标行为”，极具经济学专业度。【避坑指南】当激励机制设计不当导致“适得其反的诱导”时，搭配副词 `perversely incentivise`（产生逆向激励）是GRE与雅思9分级别的亮点表达。","forms":["incentivize","incentivises","incentivised","incentivized","incentivising","incentive"],"partners":[{"id":"business","rel":"动+名","phrase":"incentivise businesses to adopt green technologies","note":"常用搭配：incentivise businesses to adopt green technologies（激励企业采用绿色技术），与 business（企业、商业机构）构成高频「动+名」词伙。"},{"id":"commuter","rel":"动+名","phrase":"incentivise commuters to switch to public transit","note":"常用搭配：incentivise commuters to switch to public transit（激励通勤者改乘公共交通工具），与 commuter（通勤者）构成高频「动+名」词伙。"}]},{"id":"deregulate","word":"deregulate","ipa":{"uk":"/ˌdiːˈreɡjuleɪt/","us":"/ˌdiːˈreɡjuleɪt/"},"pos":"v.","definition":{"en":"To remove state regulations, price controls, or restrictions from an industry or sector to increase market competition.","zh":"放松管制，解除（国家对某行业或市场的）监管与限制。"},"libraries":["writing"],"topics":["社会与经济"],"functions":["社会结构","利弊权衡"],"frequency":{"ielts":5,"gre":3},"register":"正式宏观经济学与政府职能动词 · 适用于雅思讨论“政府监管与自由市场竞争、金融危机成因、医疗教育商业化利弊”等议题。","synonyms":[{"id":"relax","note":"deregulate 专指解除国家对特定行业或市场的法规限制；relax 泛指放宽限制、规定或政策尺度（如 relax controls）。"},{"id":"loosen","note":"deregulate 为正式经济政策术语，表放松行业管制；loosen 为通用词，表松绑或放宽约束。"}],"antonyms":[{"id":"regulate","note":"直接反义：deregulate 表放松或解除行业管制，而 regulate 表依法实施监管与控制。"},{"id":"restrict","note":"deregulate 放宽市场准入与限制，与施加限制约束的 restrict 相对。"}],"collocations":[{"en":"deregulate the financial or banking sector","zh":"放松对金融或银行部门的管制"},{"en":"a deregulated energy or telecommunications market","zh":"解除管制的能源或电信市场"},{"en":"sweeping deregulation of labour markets","zh":"对劳动力市场大刀阔斧的放松管制（名词形式）"},{"en":"prematurely deregulate monopolistic industries","zh":"过早解除对垄断行业的监管"}],"examples":[{"type":"IELTS","en":"Although decisions to deregulate the civil aviation industry lowered ticket prices for passengers, critics argue that fierce competition has eroded safety margins.","zh":"尽管放松对民航业管制的决定降低了乘客的票价，但批评人士认为，激烈的竞争侵蚀了安全裕度。","highlights":["deregulate the civil aviation industry"]},{"type":"IELTS","en":"When governments deregulate the housing market without maintaining rent controls, speculative investment often prices low-income families out of urban centres.","zh":"当政府放松对房地产市场的管制却不维持租金管制时，投机性投资往往会使低收入家庭因房价过高而被挤出市中心。","highlights":["deregulate the housing market"]},{"type":"GRE","en":"Economic historians contend that the legislative rush to deregulate over-the-counter derivatives in the late twentieth century sowed the seeds of subsequent systemic instability.","zh":"经济史学家认为，二十世纪末立法机构急于放松对场外衍生品交易的监管，为随后的系统性动荡埋下了祸根。","highlights":["deregulate over-the-counter derivatives"]},{"type":"GRE","en":"Proponents of neoliberal reform promised that deregulating grain prices would stimulate smallholder productivity, yet the immediate effect was acute volatility in urban bread markets.","zh":"新自由主义改革的支持者承诺，放开粮食价格管制将刺激小农生产力，然而直接后果却是城市面包市场的剧烈波动。","highlights":["deregulating grain prices"]}],"note":"【句型框架】及物动词，结构为 `deregulate [某行业/市场，如 the financial sector / the labour market]`，或其派生不可数名词 `deregulation`（如 `excessive financial deregulation` 过度的金融去监管化）。【高阶替换】精准升级 `remove government rules from` 或 `make the market freer`。【避坑指南】前缀 `de-` 表示“移除、解除”，因此 `deregulate` 的宾语是“原本受政府规章管辖的行业、市场或价格”，切勿把“违法行为”当作宾语（让某种轻微违法行为合法化应使用 `decriminalise` 或 `legalise`，而非 `deregulate`）。","forms":["deregulates","deregulated","deregulating","deregulation"],"partners":[{"id":"sector","rel":"动+名","phrase":"deregulate the financial or banking sector","note":"常用搭配：deregulate the financial or banking sector（放松对金融或银行部门的管制），与 sector（部门、行业）构成高频「动+名」词伙。"},{"id":"industry","rel":"动+名","phrase":"prematurely deregulate monopolistic industries","note":"常用搭配：prematurely deregulate monopolistic industries（过早解除对垄断行业的监管），与 industry（行业、产业）构成高频「动+名」词伙。"}]},{"id":"holistic","word":"holistic","ipa":{"uk":"/həˈlɪstɪk/","us":"/hoʊˈlɪstɪk/"},"pos":"adj.","definition":{"en":"Characterised by the belief that the parts of something are intimately interconnected and explicable only by reference to the whole.","zh":"整体的，全面的，全局性的，全人发展的（强调各部分相互关联而非孤立看待）。"},"libraries":["writing"],"topics":["科技与教育","健康与生活"],"functions":["观点评价","论证与证据"],"frequency":{"ielts":5,"gre":4},"register":"正式（全人教育、整合医疗与系统治理）· 雅思大作文结尾段（Conclusion）和建议段点睛神词，呼吁打破头痛医头的碎片化治理，采取全局统筹方案。","synonyms":[{"id":"thorough","note":"thorough 强调细致彻底、不遗漏细节；holistic 强调超越局部视角，从系统整体及各要素的互动关系出发（如 a holistic approach to healthcare）。"},{"id":"comprehensive","note":"holistic 侧重将各部分视为有机整体、注重系统关联（如整体医疗或全人教育）；comprehensive 侧重覆盖面广、内容详尽。"}],"antonyms":[{"id":"superficial","note":"反义对照：holistic 表立足全局、标本兼治的整体视角，而 superficial 表只看表面的肤浅处理。"},{"id":"dichotomous","note":"dichotomous 采取割裂的二元对立视角，holistic 采取整体综合视角。"},{"id":"parochial","note":"反义对照：holistic 表胸怀全局的系统观，而 parochial 表只顾局部利益的狭隘视野。"}],"collocations":[{"en":"adopt a holistic approach to","zh":"对……采取全面统筹的方法"},{"en":"foster holistic child development","zh":"促进儿童全人/全面发展"},{"en":"a holistic regulatory framework","zh":"全局性的监管框架"},{"en":"take a holistic view of","zh":"对……秉持全局观"}],"examples":[{"type":"IELTS","en":"Primary schools should foster holistic child development by balancing rigorous literacy instruction with artistic expression, outdoor physical play, and emotional resilience.","zh":"小学应当通过平衡严格的读写教学与艺术表达、户外体育活动及心理韧性培养，来促进儿童的全人发展。","highlights":["holistic child development"]},{"type":"IELTS","en":"Combating escalating urban obesity requires public health authorities to adopt a holistic approach that combines nutritional labelling, sugar taxation, and pedestrian-friendly urban planning.","zh":"应对不断加剧的城市肥胖问题，需要公共卫生当局采取全面统筹的方案，将营养标签、糖税与行人友好型城市规划结合起来。","highlights":["adopt a holistic approach"]},{"type":"GRE","en":"Rejecting reductionist paradigms that isolate individual genetic loci, contemporary systems biologists advocate a holistic framework for modelling emergent properties within cellular networks.","zh":"当代系统生物学家摒弃了孤立单个基因位点的还原论范式，倡导采用整体性框架来模拟细胞网络中的涌现特性。","highlights":["a holistic framework"]}],"note":"【句型框架】建议段与结尾段黄金句式：Addressing X requires policymakers to adopt a holistic approach that integrates A, B, and C, rather than relying on piecemeal measures。【高阶替换】高阶升级 comprehensive / all-round / overall；但相比 comprehensive（仅指覆盖面广、包含细节多），holistic（源自希腊语 holos“整体”）蕴含深刻的哲学与系统论思想——强调“各组成部分有机联动、不可割裂看待（反义词为 reductionist 还原论的 / piecemeal 零敲碎打的）”。【避坑指南】高频拼写错误：受 whole 影响，许多考生会误拼成 *wholistic；切记标准拼写词首没有 w，写作 holistic！","forms":["holistically","holism"],"partners":[{"id":"development","rel":"形+名","phrase":"foster holistic child development","note":"常用搭配：foster holistic child development（促进儿童全人/全面发展），与 development（发展、成长）构成高频「形+名」词伙。"},{"id":"framework","rel":"形+名","phrase":"a holistic regulatory framework","note":"常用搭配：a holistic regulatory framework（全局性的监管框架），与 framework（框架、体系）构成高频「形+名」词伙。"}]},{"id":"outmoded","word":"outmoded","ipa":{"uk":"/ˌaʊtˈməʊdɪd/","us":"/ˌaʊtˈmoʊdɪd/"},"pos":"adj.","definition":{"en":"No longer in fashion or no longer practically useful due to changing conditions; old-fashioned and obsolete.","zh":"过时的，落伍的，不再适用的（尤指观念、方法、法规或设备）。"},"libraries":["writing"],"topics":["科技与教育","文化与历史"],"functions":["观点评价","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式（制度革新、教育转型与技术迭代）· 适用于大作文批判陈旧落伍的法律法规、死板的应试教学法或不再适应时代的传统观念。","synonyms":[{"id":"archaic","note":"outmoded 指因环境变化而变得“落伍、不合时宜”（如 outmoded teaching methods）；archaic 程度更夸张，指像古代文物一样“古老陈腐”。"},{"id":"fusty","note":"近义辨析：二者均含陈旧过时之意；outmoded 侧重方法或法规不再适用，fusty 侧重思想或作风腐朽守旧。"},{"id":"obsolete","note":"近义辨析：二者均表过时；outmoded 侧重落伍不合时宜，obsolete 侧重已被新技术彻底淘汰废弃。"},{"id":"outdated","note":"outmoded 侧重观念、方法或制度因时代变迁而落伍不适用；outdated 侧重信息、数据或设施陈旧过时。"}],"antonyms":[{"id":"cutting-edge","note":"反义对照：outmoded 表“过时的”，而 cutting-edge 表“最前沿的”，二者构成鲜明的语义对立。"},{"id":"state-of-the-art","note":"反义对照：outmoded 表过时落伍的，而 state-of-the-art 表最先进的、达到当前最高技术水平的。"},{"id":"modern","note":"反义对照：outmoded 表过时落伍的，而 modern 表现代的、新式的。"}],"collocations":[{"en":"abandon outmoded pedagogical methods","zh":"摒弃过时的教学方法"},{"en":"replace outmoded statutory regulations","zh":"取代不再适用的旧法规"},{"en":"cling to outmoded social conventions","zh":"墨守落伍的陈规旧俗"},{"en":"render traditional skills outmoded","zh":"使传统技能变得过时"}],"examples":[{"type":"IELTS","en":"To prepare graduates for an unpredictable knowledge economy, universities must abandon outmoded pedagogical methods that prioritise rote memorisation over critical inquiry.","zh":"为了让学生为充满变数的知识经济做好准备，大学必须摒弃那种将死记硬背置于批判性探究之上的过时教学方法。","highlights":["abandon outmoded pedagogical methods"]},{"type":"IELTS","en":"Rigid nine-to-five office mandates are increasingly viewed as an outmoded management convention that ignores both digital connectivity and diverse family responsibilities.","zh":"僵化的朝九晚五坐班规定正日益被视为一种过时的管理惯例，它既忽视了数字互联能力，也无视多样化的家庭责任。","highlights":["an outmoded management convention"]},{"type":"GRE","en":"Legal scholars contended that nineteenth-century copyright statutes had become hopelessly outmoded in an era of instantaneous algorithmic reproduction and decentralised distribution.","zh":"法学学者认为，在即时算法复制与去中心化传播的时代，十九世纪的版权法规已经变得无可救药地过时了。","highlights":["hopelessly outmoded"]}],"note":"【句型框架】常用于呼吁改革的主体段：To adapt to X, institutions must abandon/overhaul outmoded methods/regulations that...；或作宾补：Rapid automation has rendered manual bookkeeping outmoded。【高阶替换】完美升级 old-fashioned / outdated / behind the times；与近义词 obsolete（彻底报废、被淘汰而不再使用的，如算盘或软盘）相比，outmoded（out + mode 模式/风尚）更侧重“观念、制度、方法或习俗因时代变迁而落伍、不再合宜”，但现实中可能仍有人在顽固沿用。【避坑指南】注意词尾有 -d（outmoded），它本身是由分词转化而来的纯形容词，不要漏写末尾的 d 而误写成 *outmode。","forms":[],"partners":[{"id":"method","rel":"形+名","phrase":"abandon outmoded pedagogical methods","note":"常用搭配：abandon outmoded pedagogical methods（摒弃过时的教学方法），与 method（方法）构成高频「形+名」词伙。"},{"id":"regulation","rel":"形+名","phrase":"replace outmoded statutory regulations","note":"常用搭配：replace outmoded statutory regulations（取代不再适用的旧法规），与 regulation（法规、规章）构成高频「形+名」词伙。"}]},{"id":"susceptible","word":"susceptible","ipa":{"uk":"/səˈseptəbl/","us":"/səˈseptəbl/"},"pos":"adj.","definition":{"en":"Likely or liable to be influenced or harmed by a particular thing (such as a disease, persuasion, or environmental hazard).","zh":"易受影响的，易感染（疾病）的，易受伤害的；过敏的；容许……的（susceptible of）。"},"libraries":["writing"],"topics":["健康与生活","逻辑与论证"],"functions":["改善与恶化","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与医学社科语域；常用于青少年教育（受媒体/同伴影响）、公共卫生（易感人群）及生态经济脆弱性论述","synonyms":[{"id":"vulnerable","note":"vulnerable 强调因为缺乏防御或处于弱势而“脆弱、易遭攻击损害”；susceptible 强调生理体质或心理特质上对某种特定病菌、诱惑或暗示“敏感、易受感染或影响”。"},{"id":"impressionable","note":"susceptible 侧重对疾病、压力或外部诱因缺乏抵抗力而易受影响；impressionable 侧重（尤指青少年）心智未熟而易受他人感化或左右。"},{"id":"prone","note":"susceptible 常接 to + 名词，强调易受外部侵害；prone 常接 to + 名词或不定式，强调自身具有某种不良倾向。"}],"antonyms":[{"id":"resilient","note":"反义对照：susceptible 表“易受影响的”，而 resilient 表“有弹性的”，二者构成鲜明的语义对立。"},{"id":"immune","note":"反义对照：susceptible 表易受感染或易受外部影响的，而 immune 表具有免疫力或不受影响的。"},{"id":"resistant","note":"反义对照：susceptible 表缺乏抵抗力的，而 resistant 表有抵抗力的、耐受的。"}],"collocations":[{"en":"particularly susceptible to peer pressure","zh":"极易受到同辈压力的影响"},{"en":"highly susceptible to infection","zh":"极易感染疾病"},{"en":"susceptible to algorithmic manipulation","zh":"易受算法操纵"},{"en":"genetically susceptible individuals","zh":"具有遗传易感性的个体"}],"examples":[{"type":"IELTS","en":"Adolescents are particularly susceptible to persuasive celebrity endorsements on social media because their critical judgment is still developing.","zh":"青少年特别容易受到社交媒体上极具说服力的名人代言的影响，因为他们的批判性判断力仍在发展中。","highlights":["particularly susceptible to"]},{"type":"IELTS","en":"Monoculture farming renders agricultural ecosystems highly susceptible to devastating pest outbreaks and climate extremes.","zh":"单一作物种植模式使农业生态系统极易受到毁灭性虫害爆发和极端气候的侵害。","highlights":["highly susceptible to"]},{"type":"GRE","en":"Unlike the ambiguous fragments recovered from the lower stratum, the intact bronze inscription is susceptible of only one plausible philological interpretation.","zh":"与从下层地层出土的模棱两可的残片不同，这段完整的青铜铭文只容许一种合理的语文学解释。","highlights":["susceptible of only one"]}],"note":"【句型框架】① Young people / Developing economies are particularly susceptible to X（青少年/发展中经济体极易受到负面因素 X 的影响或冲击）；② render A highly susceptible to B（使 A 极易遭受 B 的侵害）。【高阶替换】精准替代 easily influenced by、easy to get hurt by；相比 vulnerable（侧重防线薄弱、暴露在外而易受实质性攻击或伤害）和 prone（be prone to 侧重由于习惯或天性“倾向于发生某坏事或犯错”），susceptible 强调“缺乏内部抵抗力或免疫力，因而极易被外界病菌、情绪、蛊惑所感染或左右”。【避坑指南】牢记两大介词分工：① be susceptible to + 名词/动名词（注意 to 是介词，后面不可接动词原形！意为“易受……影响/易患……病”）；② be susceptible of + 名词（GRE高频熟词僻义，意为“容许有……的可能、可予以……的”，如 susceptible of proof 可加以证明的）。","forms":["susceptibility"],"partners":[{"id":"pressure","rel":"形+名","phrase":"particularly susceptible to peer pressure","note":"常用搭配：particularly susceptible to peer pressure（极易受到同辈压力的影响），与 pressure（压力）构成高频「形+名」词伙。"},{"id":"infection","rel":"形+名","phrase":"highly susceptible to infection","note":"常用搭配：highly susceptible to infection（极易感染疾病），与 infection（感染、传染）构成高频「形+名」词伙。"}]},{"id":"engender","word":"engender","ipa":{"uk":"/ɪnˈdʒendə(r)/","us":"/ɪnˈdʒendər/"},"pos":"v.","definition":{"en":"To cause or give rise to a feeling, situation, or condition.","zh":"产生、引起、催生（某种情感、局势或状态）。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["因果与影响","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"极正式学术与人文社科语域；适用于大作文分析制度设计、教育方式或社会变迁所催生的深层心理与社会氛围","synonyms":[{"id":"foster","note":"foster 强调长期培育积极事物；engender 中性偏正式，可接信任或敌意等抽象状态。"},{"id":"induce","note":"induce 侧重通过外部刺激或劝说诱发结果；engender 侧重结构性条件催生某种氛围。"},{"id":"breed","note":"breed 常用于负面衍生（如滋生腐败或怨恨）；engender 语域更高雅客观。"},{"id":"yield","note":"engender 强调催生氛围或情感；yield 强调经过投入、实验或耕作后产出具体成果或结论。"}],"antonyms":[{"id":"inhibit","note":"反义对照：engender 表“产生”，而 inhibit 表“抑制”，二者构成鲜明的语义对立。"},{"id":"quell","note":"engender 催生某种情绪或局面，quell 则强力平息或压制它。"}],"collocations":[{"en":"engender mutual trust and civic cooperation","zh":"催生互信与公民合作"},{"en":"engender widespread resentment among citizens","zh":"在公民中引起普遍怨恨"},{"en":"engender a pervasive sense of insecurity","zh":"产生普遍的不安全感"},{"en":"engender fierce ideological controversy","zh":"引发激烈的意识形态争议"}],"examples":[{"type":"IELTS","en":"Participatory urban planning can engender mutual trust between residents and municipal authorities, whereas opaque decision-making often breeds cynicism.","zh":"参与式城市规划能够在居民与市政当局之间催生互信，而不透明的决策往往会滋生冷嘲热讽的怀疑情绪。","highlights":["engender mutual trust"]},{"type":"IELTS","en":"Relentless exposure to idealized lifestyles on social media tends to engender a pervasive sense of inadequacy among impressionable adolescents.","zh":"在社交媒体上持续接触被理想化的生活方式，往往会在易受影响的青少年中产生普遍的自卑感。","highlights":["engender a pervasive sense of inadequacy"]},{"type":"GRE","en":"Far from resolving the doctrinal dispute, the synod's deliberately ambiguous pronouncement served only to engender further schism among provincial clerics.","zh":"宗教会议刻意模棱两可的声明非但没有解决教义争端，反而只在地方神职人员中引发了进一步的分裂。","highlights":["engender further schism"]}],"note":"【句型框架】标准句式为 `Macro-factor X tends to engender + 抽象情感/氛围/局面（trust / hostility / complacency / debate）`。【高阶替换】是替换低幼词 `cause / make / create / bring about` 的顶级学术动词；相比 `precipitate`（突然引发危机）和 `produce`（生产具体结果），`engender` 强调某种制度、环境或行为像孕育生命一样自然催生出某种抽象的社会心理、情绪或关系状态。【避坑指南】宾语必须是抽象的心理状态、社会气氛或争议，切勿用于产生具体物质或数值（如不可写 `engender electricity` 或 `engender more jobs`，此时应用 `generate`）。","forms":["engenders","engendered","engendering"],"partners":[{"id":"cooperation","rel":"动+名","phrase":"engender mutual trust and civic cooperation","note":"常用搭配：engender mutual trust and civic cooperation（催生互信与公民合作），与 cooperation（合作、协作）构成高频「动+名」词伙。"},{"id":"controversy","rel":"动+名","phrase":"engender fierce ideological controversy","note":"常用搭配：engender fierce ideological controversy（引发激烈的意识形态争议），与 controversy（争议、争论）构成高频「动+名」词伙。"}]},{"id":"catalyse","word":"catalyse","ipa":{"uk":"/ˈkætəlaɪz/","us":"/ˈkætəlaɪz/"},"pos":"v.","definition":{"en":"To accelerate or trigger a significant change or action.","zh":"催化、加速促成（重大变革或行动）。"},"libraries":["writing"],"topics":["科技与教育","社会与经济"],"functions":["因果与影响","数量与趋势"],"frequency":{"ielts":5,"gre":4},"register":"正式科技与政策分析语域；适用于大作文论述技术突破、危机事件或政府激励如何加速制度改革与产业转型","synonyms":[{"id":"accelerate","note":"accelerate 泛指加快速度；catalyse 强调作为关键契机引发并加速质变。"},{"id":"precipitate","note":"precipitate 多指促成突发乃至负面的骤变；catalyse 多用于积极或深远的变革。"},{"id":"spark","note":"spark 强调点燃起点；catalyse 兼有触发与持续加速双重含义。"},{"id":"induce","note":"catalyse 强调加速变革；induce 强调直接诱发某种状态或诱导某人行动。"}],"antonyms":[{"id":"impede","note":"反义对照：catalyse 表“催化、加速促成”，而 impede 表“阻碍”，二者构成鲜明的语义对立。"},{"id":"retard","note":"反义对照：catalyse 表“催化、加速促成”，而 retard 表“妨碍”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"catalyse structural economic reform","zh":"催化结构性经济改革"},{"en":"catalyse technological innovation in clean energy","zh":"催化清洁能源领域的技术创新"},{"en":"catalyse private-sector investment","zh":"催化私营部门投资"},{"en":"catalyse a paradigm shift in education","zh":"催化教育领域的范式转移"}],"examples":[{"type":"IELTS","en":"Targeted government subsidies for renewable energy can catalyse private-sector investment in green infrastructure across developing regions.","zh":"针对可再生能源的政府定向补贴，可以催化发展中地区私营部门对绿色基础设施的投资。","highlights":["catalyse private-sector investment"]},{"type":"IELTS","en":"The global shift toward remote work during the pandemic helped to catalyse a fundamental reassessment of urban office space and commuting patterns.","zh":"疫情期间向远程办公的全球性转变，加速促成了人们对城市办公空间与通勤模式的根本性重新评估。","highlights":["catalyse a fundamental reassessment of"]},{"type":"GRE","en":"The unexpected archival discovery helped catalyse a methodological reassessment of how nineteenth-century agrarian credit markets operated.","zh":"这一出人意料的档案发现帮助催化了对十九世纪农业信贷市场运作方式的方法论重估。","highlights":["catalyse a methodological reassessment"]}],"note":"【句型框架】常用于 `Seed funding/Crisis X can catalyse + 宏观变革名词（transition / reform / innovation / reassessment）`，或用名词形式 `act as a catalyst for...`（充当……的催化剂）。【高阶替换】源自化学“催化反应”，是升级 `speed up / trigger / encourage / stimulate` 的高分学术词汇；相比 `cause`（单纯引起），`catalyse` 强调某因素注入后大幅加快了原本缓慢或停滞的变革进程。【避坑指南】英式拼写为 `catalyse`，美式拼写为 `catalyze`；其宾语应为正面的创新、改革或中性的重大转型，一般不用于催化具体的犯罪或灾难（后者宜用 `precipitate`）。","forms":["catalyses","catalysed","catalysing","catalyze","catalyst","catalysis"],"partners":[{"id":"reform","rel":"动+名","phrase":"catalyse structural economic reform","note":"常用搭配：catalyse structural economic reform（催化结构性经济改革），与 reform（改革）构成高频「动+名」词伙。"},{"id":"innovation","rel":"动+名","phrase":"catalyse technological innovation in clean energy","note":"常用搭配：catalyse technological innovation in clean energy（催化清洁能源领域的技术创新），与 innovation（创新）构成高频「动+名」词伙。"}]},{"id":"emanate","word":"emanate","ipa":{"uk":"/ˈeməneɪt/","us":"/ˈeməneɪt/"},"pos":"v.","definition":{"en":"To originate from or be produced by a particular source, or to radiate a quality or feeling.","zh":"源自、发自（某源头）；散发出、流露出（某种气质或信号）。"},"libraries":["writing"],"topics":["逻辑与论证","文化与历史"],"functions":["因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"极正式书面与学术语域；适用于大作文溯源虚假信息、污染排放、政令法规或思想潮流的出处","synonyms":[{"id":"originate","note":"emanate 侧重气体、信号、指令或气质从某一源头向外散发流出；originate 侧重事物、思想或制度起源于某时某地。"},{"id":"derive","note":"emanate 强调由源头向外辐射散发；derive 强调从某源头汲取、衍生或推导出。"}],"antonyms":[{"id":"converge","note":"反义对照：emanate 表“散发”，而 converge 表“会聚”，二者构成鲜明的语义对立。"},{"id":"culminate","note":"一为起源散发（emanate from），一为终局收束（culminate in），构成因果链条的首尾对照。"}],"collocations":[{"en":"emanate from a handful of unregulated platforms","zh":"源自少数缺乏监管的平台"},{"en":"policy directives emanating from central authorities","zh":"出自中央主管部门的政策指令"},{"en":"greenhouse gases emanating from agricultural livestock","zh":"来自农业牲畜的温室气体"},{"en":"emanate an aura of quiet authority","zh":"散发出沉稳的威严气质"}],"examples":[{"type":"IELTS","en":"Much of the health misinformation circulating on social media appears to emanate from a handful of unregulated commercial accounts.","zh":"在社交媒体上流传的大量健康虚假信息，似乎源自少数缺乏监管的商业账号。","highlights":["emanate from a handful of unregulated"]},{"type":"IELTS","en":"Top-down urban renewal directives emanating from central authorities often overlook the distinct vernacular heritage of historic neighbourhoods.","zh":"出自中央主管部门的自上而下的城市更新指令，往往忽视了历史街区独特的地方文化遗产。","highlights":["directives emanating from central authorities"]},{"type":"GRE","en":"The egalitarian ideals that emanated from provincial dissenting academies gradually reshaped the political discourse of the entire commonwealth.","zh":"源自地方非国教学院的平等主义理想，逐渐重塑了整个联邦的政治话语体系。","highlights":["emanated from provincial dissenting academies"]}],"note":"【句型框架】核心用法为不及物结构 `emanate from + 源头名词`（源自/发自……），尤常以现在分词形式作后置定语：`regulations/emissions/ideas emanating from...`（出自/来自……的法规/排放/思想）。【高阶替换】是升级口语词 `come from` 及常见词 `originate from / stem from` 的高雅学术词汇；相比 `stem from`（侧重因果追溯），`emanate from` 带有从中心源头向外持续“散发、辐射或流出”的意象。【避坑指南】在学术写作中几乎总作不及物动词并与介词 `from` 绑定；无被动语态（不可写 `is emanated from`）。","forms":["emanates","emanated","emanating","emanation"],"partners":[{"id":"authority","rel":"动+名","phrase":"policy directives emanating from central authorities","note":"常用搭配：policy directives emanating from central authorities（出自中央主管部门的政策指令），与 authority（主管部门、权威）构成高频「动+名」词伙。"},{"id":"platform","rel":"动+名","phrase":"emanate from a handful of unregulated platforms","note":"常用搭配：emanate from a handful of unregulated platforms（源自少数缺乏监管的平台），与 platform（平台）构成高频「动+名」词伙。"}]},{"id":"culminate","word":"culminate","ipa":{"uk":"/ˈkʌlmɪneɪt/","us":"/ˈkʌlmɪneɪt/"},"pos":"v.","definition":{"en":"To reach a climax or point of highest development, or to end with a particular final result.","zh":"以……告终；达到顶点、推向高潮。"},"libraries":["writing"],"topics":["文化与历史","逻辑与论证"],"functions":["因果与影响","数量与趋势"],"frequency":{"ielts":5,"gre":4},"register":"正式历史叙事与进程总结语域；适用于大作文阐述长期积累的矛盾、技术演进或政策推进最终达到顶点或酿成结局","synonyms":[{"id":"conclude","note":"culminate 侧重长期积累的过程最终达到高潮或演变为重大结局（常接 in）；conclude 侧重事情结束或推导出结论。"},{"id":"peak","note":"culminate 强调过程收束于某个标志性顶点或结局；peak 强调数值、强度或表现在某一时刻达到最高峰。"}],"antonyms":[{"id":"trigger","note":"反义对照：culminate 表“告终”，而 trigger 表“引发”，二者构成鲜明的语义对立。"},{"id":"emanate","note":"反义对照：culminate 表“告终”，而 emanate 表“散发”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"culminate in irreversible ecological degradation","zh":"最终演变为不可逆转的生态退化"},{"en":"culminate in a landmark multilateral treaty","zh":"最终促成一项里程碑式的多边条约"},{"en":"decades of incremental research culminating in","zh":"数十年渐进研究最终凝结为……"},{"en":"culminate in widespread civic unrest","zh":"最终酿成广泛的公民动荡"}],"examples":[{"type":"IELTS","en":"Decades of unchecked industrial effluent discharge can culminate in irreversible ecological degradation that destroys local fisheries.","zh":"数十年不受控制的工业废水排放最终会导致不可逆转的生态退化，进而摧毁当地渔业。","highlights":["culminate in irreversible ecological degradation"]},{"type":"IELTS","en":"Sustained public health campaigns against tobacco use, culminating in comprehensive indoor smoking bans, have markedly reduced cardiovascular mortality.","zh":"持续开展的控烟公共卫生运动最终促成了全面的室内禁烟令，显著降低了心血管疾病死亡率。","highlights":["culminating in comprehensive indoor smoking bans"]},{"type":"GRE","en":"The simmering jurisdictional tensions between royal courts and municipal guilds ultimately culminated in a protracted constitutional crisis.","zh":"皇家法院与市政行会之间酝酿已久的管辖权紧张局势，最终演变成了一场旷日持久的宪政危机。","highlights":["culminated in a protracted constitutional crisis"]}],"note":"【句型框架】常作谓语 `Long-term process X culminated in Y`（长期过程 X 最终以 Y 告终/达到高潮 Y），或在句尾用现在分词作结果状语 `, culminating in...`（最终促成/导致……）。【高阶替换】替换简单的 `end up with / finally lead to / reach the highest point`；与普通因果词 `result in` 相比，`culminate in` 强调经过漫长酝酿、层层递进后“推向顶点或终局”，既可用于丰硕成果（如条约、突破），也可用于危机总爆发。【避坑指南】`culminate` 是严格的不及物动词，后接结果时必须加介词 `in`（偶用 `with`），切勿直接接宾语写出 `culminated a crisis`。","forms":["culminates","culminated","culminating","culmination"],"partners":[{"id":"degradation","rel":"动+名","phrase":"culminate in irreversible ecological degradation","note":"常用搭配：culminate in irreversible ecological degradation（最终演变为不可逆转的生态退化），与 degradation（退化、恶化）构成高频「动+名」词伙。"},{"id":"treaty","rel":"动+名","phrase":"culminate in a landmark multilateral treaty","note":"常用搭配：culminate in a landmark multilateral treaty（最终促成一项里程碑式的多边条约），与 treaty（条约、协定）构成高频「动+名」词伙。"}]},{"id":"ramification","word":"ramification","ipa":{"uk":"/ˌræmɪfɪˈkeɪʃn/","us":"/ˌræmɪfɪˈkeɪʃn/"},"pos":"n.","definition":{"en":"A complex or unwelcome consequence of an action or event, spreading out like branches.","zh":"（复杂深远的）衍生后果、连锁影响、分支影响。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["让步转折","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"极正式政策评估、伦理与法学语域；适用于大作文深入剖析某项政策或技术变革在社会、经济、伦理层面的深远连锁后果","synonyms":[{"id":"repercussion","note":"repercussion 偏重负面反弹或余波；ramification 强调后果像树枝分叉般复杂、广泛。"},{"id":"corollary","note":"corollary 强调逻辑上的必然推论或伴随结果；ramification 强调实际层面衍生出的多方面影响。"},{"id":"aftermath","note":"aftermath 指灾难或重大事件后的“余波时期/状态”；ramification 指具体延伸出的后果。"},{"id":"by-product","note":"ramification 强调复杂深远的连锁后果；by-product 强调伴随主过程而生的附带品。"}],"antonyms":[{"id":"determinant","note":"determinant 是决定性前因，ramification 是衍生出的复杂后果。"},{"id":"precursor","note":"precursor 是先导与前兆，与事后延伸的 ramification 方向相反。"}],"collocations":[{"en":"far-reaching socioeconomic ramifications","zh":"深远的社会经济连锁影响"},{"en":"profound ethical and legal ramifications","zh":"深远的伦理与法律衍生后果"},{"en":"unintended geopolitical ramifications","zh":"始料未及的地缘政治连锁反应"},{"en":"evaluate the long-term ramifications of","zh":"评估……的长期衍生影响"}],"examples":[{"type":"IELTS","en":"Policymakers must carefully evaluate the far-reaching socioeconomic ramifications of replacing human labour with autonomous systems.","zh":"政策制定者必须审慎评估用自主系统取代人类劳动所带来的深远社会经济连锁后果。","highlights":["far-reaching socioeconomic ramifications"]},{"type":"IELTS","en":"Allowing commercial entities to patent human genetic sequences carries profound ethical and legal ramifications for equitable healthcare access.","zh":"允许商业实体对人类基因序列申请专利，对公平获取医疗服务具有深远的伦理与法律衍生影响。","highlights":["profound ethical and legal ramifications"]},{"type":"GRE","en":"While the armistice resolved the immediate territorial dispute, its broader geopolitical ramifications across the peninsula remained difficult to foresee.","zh":"尽管停战协定解决了眼前的领土争端，但其在整个半岛引发的更广泛地缘政治连锁影响仍难以预料。","highlights":["broader geopolitical ramifications"]}],"note":"【句型框架】常用于 `have/carry far-reaching ramifications for X`（对 X 产生深远的连锁影响）或 `consider the ethical/social ramifications of doing Y`（考量做 Y 的伦理/社会衍生后果）。【高阶替换】词根 `ram-` 意为“树枝”，形象地表达一个决定像树枝分叉一样衍生出复杂、多维且往往棘手的后续影响；是替换普通词 `result / effect / consequence` 的 Band 9 利器。【避坑指南】在学术议论文中，几乎总是以复数形式 `ramifications` 出现；后接影响对象时用介词 `for`，后接原因事件时用介词 `of`。","forms":["ramifications"],"partners":[{"id":"profound","rel":"形+名","phrase":"profound ethical and legal ramifications","note":"常用搭配：profound ethical and legal ramifications（深远的伦理与法律衍生后果），与 profound（深远的、深刻的）构成高频「形+名」词伙。"},{"id":"evaluate","rel":"动+名","phrase":"evaluate the long-term ramifications of","note":"常用搭配：evaluate the long-term ramifications of（评估……的长期衍生影响），与 evaluate（评估、评价）构成高频「动+名」词伙。"}]},{"id":"determinant","word":"determinant","ipa":{"uk":"/dɪˈtɜːmɪnənt/","us":"/dɪˈtɜːrmɪnənt/"},"pos":"n.","definition":{"en":"A factor which decisively affects the nature or outcome of something.","zh":"决定因素、决定性条件。"},"libraries":["writing"],"topics":["社会与经济","健康与生活"],"functions":["因果与影响","论证与证据"],"frequency":{"ielts":5,"gre":4},"register":"正式社会学、经济学与流行病学语域；适用于大作文归因段剖析决定个人成败、健康水平或国家竞争力的核心要素","synonyms":[{"id":"catalyst","note":"catalyst 指加速变化的催化剂；determinant 指从根本上决定结果走向的核心因素。"},{"id":"factor","note":"determinant 强调对结果走向起决定性作用的核心变量；factor 为中性通用词，泛指一般因素。"}],"antonyms":[{"id":"ramification","note":"反义对照：determinant 表决定事态走向的前因变量，而 ramification 表事后延伸出的复杂连锁后果。"},{"id":"repercussion","note":"反义对照：determinant 表决定性原因，而 repercussion 表引发的负面回响与恶果。"},{"id":"corollary","note":"反义对照：determinant 表决定因素，而 corollary 表随之产生的必然推论或伴随结果。"}],"collocations":[{"en":"a primary determinant of socioeconomic mobility","zh":"社会经济流动性的主要决定因素"},{"en":"crucial social determinants of health","zh":"健康的诸多关键社会决定因素"},{"en":"remain the single most important determinant of","zh":"仍然是……唯一最重要的决定因素"},{"en":"structural determinants of educational attainment","zh":"学业成就的结构性决定因素"}],"examples":[{"type":"IELTS","en":"Access to high-quality early childhood education remains a primary determinant of an individual's future socioeconomic mobility.","zh":"获得优质早期教育的机会，仍然是决定个人未来社会经济流动性的主要因素。","highlights":["a primary determinant of"]},{"type":"IELTS","en":"While genetic predisposition influences longevity, environmental quality and dietary habits are far more potent determinants of public health.","zh":"尽管遗传易感性会影响寿命，但环境质量与饮食习惯是远为强效的公共健康决定因素。","highlights":["more potent determinants of"]},{"type":"GRE","en":"Urban epidemiologists increasingly recognise neighbourhood walkability and green-space density as crucial determinants of cardiovascular disease prevalence.","zh":"城市流行病学家越来越认识到，社区步行友好度与绿地密度是心血管疾病患病率的关键决定因素。","highlights":["crucial determinants of"]}],"note":"【句型框架】大作文主题句黄金模板：`X remains a primary/crucial determinant of Y`（X 依然是决定 Y 的主要/关键因素）。【高阶替换】直接升级万年高频烂大街词 `important factor / main reason / key element`；相比普通名词 `factor`（仅表示众多参与因素之一），`determinant` 强调该因素对最终结果的性质或走向具有“决定性、支配性”的影响力。【避坑指南】作为可数名词，前常加冠词及形容词修饰（`a major/key/critical determinant`），后固定搭配介词 `of` 而非 `for` 或 `to`。","forms":["determinants"],"partners":[{"id":"primary","rel":"形+名","phrase":"a primary determinant of socioeconomic mobility","note":"常用搭配：a primary determinant of socioeconomic mobility（社会经济流动性的主要决定因素），与 primary（首要的、主要的）构成高频「形+名」词伙。"},{"id":"health","rel":"名+名","phrase":"crucial social determinants of health","note":"常用搭配：crucial social determinants of health（健康的诸多关键社会决定因素），与 health（健康）构成高频「名+名」词伙。"}]},{"id":"conducive","word":"conducive","ipa":{"uk":"/kənˈdjuːsɪv/","us":"/kənˈduːsɪv/"},"pos":"adj.","definition":{"en":"Making a certain situation or outcome likely or possible; providing the right conditions for something good.","zh":"有助于……的、有利于促成……的。"},"libraries":["writing"],"topics":["科技与教育","健康与生活"],"functions":["因果与影响","利弊权衡"],"frequency":{"ielts":5,"gre":4},"register":"正式教育、管理与社会环境评估语域；适用于大作文讨论何种制度氛围、城市设计或家庭环境有利于积极结果的产生","synonyms":[{"id":"beneficial","note":"beneficial 泛指有益的；conducive to 特指环境或条件“有助于促成”某种理想状态。"},{"id":"salutary","note":"salutary 强调（虽可能严厉但）对身心或社会风气有益；conducive 强调氛围适宜。"},{"id":"advantageous","note":"advantageous 侧重竞争或利益上的优势；conducive 侧重客观条件对结果的支持。"},{"id":"congenial","note":"在 congenial to innovation 语境中，与 conducive to（有助于）语义高度接近。"}],"antonyms":[{"id":"detrimental","note":"反义对照：conducive 表“有助于的”，而 detrimental 表“不利的”，二者构成鲜明的语义对立。"},{"id":"deleterious","note":"deleterious 指有害的，与 conducive 的有利促成相反。"}],"collocations":[{"en":"create an environment conducive to innovation","zh":"营造有利于创新的环境"},{"en":"highly conducive to intellectual inquiry","zh":"非常有助于学术探究"},{"en":"foster a regulatory climate conducive to investment","zh":"培育有利于投资的监管氛围"},{"en":"scarcely conducive to long-term social harmony","zh":"几乎不利于长期社会和谐"}],"examples":[{"type":"IELTS","en":"Quiet communal spaces and flexible teleworking arrangements are highly conducive to employee productivity and psychological well-being.","zh":"安静的公共空间和灵活的远程办公安排，非常有利于提高员工生产力和心理健康水平。","highlights":["highly conducive to"]},{"type":"IELTS","en":"Hyper-competitive examination systems are scarcely conducive to holistic child development, as they often marginalize physical education and the arts.","zh":"过度竞争的考试制度几乎不利于儿童的全面发展，因为它们往往将体育和艺术边缘化。","highlights":["scarcely conducive to"]},{"type":"GRE","en":"Historians of science argue that institutional autonomy was far more conducive to theoretical breakthroughs than rigid court patronage.","zh":"科学史学家认为，制度自治比僵化的宫廷赞助更有利于催生理论突破。","highlights":["more conducive to theoretical breakthroughs"]}],"note":"【句型框架】两大满分位置：一是作表语 `X is highly/scarcely conducive to Y`（X 极有利于/几乎不利于 Y）；二是作后置定语 `foster an environment/atmosphere conducive to Y`（营造有利于 Y 的环境）。【高阶替换】专门升级 `good for / helpful to / beneficial to`；相比泛泛的 `beneficial`（有益的），`conducive` 强调外部环境、氛围或制度条件“有助于促成或孵化出”某种理想结果。【避坑指南】中国考生必背铁律：`conducive` 几乎不作前置定语（不说 `a conducive environment`），且后面跟的 `to` 是介词而非不定式符号，必须接名词或动名词 `doing`（严禁写 `conducive to improve`！）。","forms":[],"partners":[{"id":"environment","rel":"形+名","phrase":"create an environment conducive to innovation","note":"常用搭配：create an environment conducive to innovation（营造有利于创新的环境），与 environment（环境）构成高频「形+名」词伙。"},{"id":"innovation","rel":"形+名","phrase":"create an environment conducive to innovation","note":"常用搭配：create an environment conducive to innovation（营造有利于创新的环境），与 innovation（创新）构成高频「形+名」词伙。"}]},{"id":"attributable","word":"attributable","ipa":{"uk":"/əˈtrɪbjʊtəbl/","us":"/əˈtrɪbjətəbl/"},"pos":"adj.","definition":{"en":"Regarded as being caused by a particular factor, person, or event.","zh":"可归因于……的、由……引起的。"},"libraries":["writing"],"topics":["逻辑与论证","自然与环境"],"functions":["因果与影响","论证与证据"],"frequency":{"ielts":5,"gre":4},"register":"极正式学术归因与数据分析语域；通用于雅思大作文因果剖析及小作文（Task 1）图表变化趋势的严谨归因","synonyms":[{"id":"associated","note":"associated with 表关联；attributable to 强调某结果主要或部分由某原因导致。"},{"id":"due","note":"attributable 语域高度正式，常用于学术归因（attributable to）；due 更为常见（due to），广泛用于日常与书面因果说明。"}],"antonyms":[{"id":"uncorrelated","note":"反义对照：attributable 表“可归因于的”，而 uncorrelated 表“在指定度量下相关系数为零的”，二者构成鲜明的语义对立。"},{"id":"unrelated","note":"反义对照：attributable 表“可归因于的”，而 unrelated 表“在相关意义上没有联系的”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"largely attributable to anthropogenic emissions","zh":"主要归因于人为排放"},{"en":"directly attributable to policy intervention","zh":"直接归因于政策干预"},{"en":"partly attributable to demographic shifts","zh":"部分归因于人口结构变化"},{"en":"premature mortality attributable to air pollution","zh":"归因于空气污染的过早死亡"}],"examples":[{"type":"IELTS","en":"The recent deterioration in metropolitan air quality is largely attributable to surging private vehicle ownership and peri-urban industrial emissions.","zh":"近期大都市空气质量的恶化，主要归因于私家车保有量的激增以及城郊工业排放。","highlights":["largely attributable to"]},{"type":"IELTS","en":"Declining birth rates across East Asian economies are partly attributable to exorbitant housing costs and intense educational competition.","zh":"东亚经济体出生率的下降，部分归因于高昂的住房成本和激烈的教育竞争。","highlights":["partly attributable to"]},{"type":"GRE","en":"Labor economists struggled to isolate the fraction of wage stagnation directly attributable to algorithmic automation rather than declining unionization.","zh":"劳动经济学家难以剥离出工资停滞中直接归因于算法自动化而非工会化率下降的那部分比例。","highlights":["directly attributable to"]}],"note":"【句型框架】常作表语 `Phenomenon A is largely/partly/directly attributable to B`（现象 A 主要/部分/直接归因于 B），或作后置定语 `illnesses attributable to occupational hazards`（归因于职业危害的疾病）。【高阶替换】是替换低分词组 `because of / caused by / due to` 的高阶学术形容词；通过搭配程度副词 `largely / partly / primarily`，能展现出考官极为赞赏的“避免绝对化（hedging）”学术严谨度。【避坑指南】固定搭配介词 `to`（后面接名词或动名词）；注意区分动词主动结构 `attribute A to B`（把果 A 归因于因 B）与形容词结构 `A is attributable to B`。","forms":["attribute","attribution"],"partners":[{"id":"emissions","rel":"形+名","phrase":"largely attributable to anthropogenic emissions","note":"常用搭配：largely attributable to anthropogenic emissions（主要归因于人为排放），与 emissions（排放物、排放）构成高频「形+名」词伙。"},{"id":"intervention","rel":"形+名","phrase":"directly attributable to policy intervention","note":"常用搭配：directly attributable to policy intervention（直接归因于政策干预），与 intervention（干预、介入）构成高频「形+名」词伙。"}]},{"id":"paramount","word":"paramount","ipa":{"uk":"/ˈpærəmaʊnt/","us":"/ˈpærəmaʊnt/"},"pos":"adj.","definition":{"en":"More important than anything else; supreme.","zh":"至高无上的、首要的、最重要的。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["利弊权衡","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式政策优先级与伦理准则语域；适用于大作文确立核心立场（强调在利弊冲突中某项价值居于至高无上的地位）","synonyms":[{"id":"pivotal","note":"pivotal 强调像枢轴一样决定走向的关键作用；paramount 强调地位或优先级高于一切。"},{"id":"cardinal","note":"cardinal 常修饰基本准则或重罪（cardinal rule）；paramount 常用于 of paramount importance。"},{"id":"crucial","note":"crucial 强调紧要关头的决定性；paramount 强调至高无上的首要地位。"},{"id":"imperative","note":"paramount 强调重要性排第一；imperative 强调必须立即付诸行动。"}],"antonyms":[{"id":"trivial","note":"反义对照：paramount 表至高无上、首要的，而 trivial 表微不足道、琐碎的。"},{"id":"inconsequential","note":"paramount 为首要重大，inconsequential 为无关紧要。"},{"id":"ancillary","note":"paramount 为首要至上的，与从属辅助的 ancillary 相对。"}],"collocations":[{"en":"remain of paramount importance","zh":"始终至关重要、居于首位"},{"en":"treat public safety as a paramount concern","zh":"将公共安全视为首要关切"},{"en":"the paramount objective of criminal justice","zh":"刑事司法的首要目标"},{"en":"ecological integrity must be paramount","zh":"生态完整性必须居于首位"}],"examples":[{"type":"IELTS","en":"When deploying autonomous transportation systems on public roads, ensuring pedestrian and passenger safety must remain of paramount importance.","zh":"在公共道路上部署自动驾驶交通系统时，确保行人和乘客的安全必须始终放在首位。","highlights":["of paramount importance"]},{"type":"IELTS","en":"While commercial viability cannot be ignored, preserving historical authenticity should be the paramount consideration in urban heritage restoration.","zh":"尽管商业可行性不容忽视，但在城市遗产修复中，保护历史真实性应当成为首要考量。","highlights":["the paramount consideration"]},{"type":"GRE","en":"Although fiscal solvency weighed heavily on the cabinet, preserving the constitutional legitimacy of the judiciary remained the statesman's paramount objective.","zh":"尽管财政偿付能力令内阁倍感压力，但维护司法机构的宪法合法性仍然是这位政治家的首要目标。","highlights":["paramount objective"]}],"note":"【句型框架】雅思大作文立论段与结尾段王牌句型：`Ensuring X must remain of paramount importance`（确保 X 必须始终居于首要地位），或 `X is the paramount consideration when...`（当……时 X 是首要考量）。【高阶替换】用 `be of paramount importance` 替换烂大街的 `be very important / be the most important`；相比 `important / significant`，`paramount` 意为“至高无上的、高于一切其他因素的”。【避坑指南】因为 `paramount` 本身已蕴含“最高级（supreme）”语义，切勿在前面叠加 `very, more, most` 等程度副词（不能写 `most paramount`）。","forms":[],"partners":[{"id":"importance","rel":"形+名","phrase":"remain of paramount importance","note":"常用搭配：remain of paramount importance（始终至关重要、居于首位），与 importance（重要性）构成高频「形+名」词伙。"},{"id":"safety","rel":"形+名","phrase":"treat public safety as a paramount concern","note":"常用搭配：treat public safety as a paramount concern（将公共安全视为首要关切），与 safety（安全）构成高频「形+名」词伙。"}]},{"id":"pivotal","word":"pivotal","ipa":{"uk":"/ˈpɪvətl/","us":"/ˈpɪvətl/"},"pos":"adj.","definition":{"en":"Of crucial importance in relation to the development or success of something else.","zh":"中枢的、关键性的、起决定性转折作用的。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["因果与影响","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与历史评论语域；适用于大作文强调某一主体、技术或制度在系统运转与社会转型中扮演的中枢关键角色","synonyms":[{"id":"paramount","note":"paramount 强调优先级最高；pivotal 强调处于中心支点位置、决定成败走向。"},{"id":"crucial","note":"crucial 通用性广；pivotal 带有“支点/中枢”（pivot）的形象感，极常修饰 role 或 moment。"},{"id":"momentous","note":"momentous 强调事件本身重大的历史分量；pivotal 强调其在因果链中的枢纽地位。"},{"id":"consequential","note":"pivotal 强调转折枢纽地位；consequential 强调后续影响波及范围广、分量重。"}],"antonyms":[{"id":"peripheral","note":"反义对照：pivotal 表“中枢的”，而 peripheral 表“外围的”，二者构成鲜明的语义对立。"},{"id":"marginal","note":"pivotal 处于核心枢纽地位，marginal 则处于边缘次要地位。"},{"id":"tangential","note":"pivotal 处于核心支点位置，与边缘擦边的 tangential 相反。"}],"collocations":[{"en":"play a pivotal role in mitigating","zh":"在缓解……方面发挥中枢关键作用"},{"en":"mark a pivotal juncture in human history","zh":"标志着人类历史上的关键转折点"},{"en":"prove pivotal to the success of","zh":"被证明对……的成功至关重要"},{"en":"occupy a pivotal position in global supply chains","zh":"在全球供应链中占据中枢地位"}],"examples":[{"type":"IELTS","en":"Grassroots community organisations play a pivotal role in conserving local biodiversity and managing shared natural resources sustainably.","zh":"基层社区组织在保护当地生物多样性和可持续管理共享自然资源方面发挥着关键作用。","highlights":["play a pivotal role in"]},{"type":"IELTS","en":"Parental involvement during early childhood proves pivotal to cultivating lifelong reading habits and emotional resilience.","zh":"童年早期的父母参与，对于培养终身阅读习惯和心理韧性起着至关重要的作用。","highlights":["proves pivotal to"]},{"type":"GRE","en":"The invention of movable metal type proved pivotal in democratising vernacular literacy across early modern European urban centres.","zh":"金属活字印刷术的发明，在早期现代欧洲城市中心普及本族语读写能力方面发挥了中枢作用。","highlights":["proved pivotal in"]}],"note":"【句型框架】高频高分结构：`play a pivotal role in doing X`（在做 X 中发挥中枢作用）或 `prove pivotal to/in Y`（被证明对 Y 起关键转折作用）。【高阶替换】源自名词 `pivot`（支点、枢轴），是升级 `play an important role` 的首选词汇；相比泛泛的 `important / vital`，`pivotal` 强调像门轴或杠杆支点一样，决定了整个局面的运转方向与成败转折。【避坑指南】与 `paramount` 类似，`pivotal` 表达极高程度的关键性，一般不用 `very` 修饰；作表语时后接介词 `in` 或 `to` 均可（接动词时用 `in doing sth`）。","forms":["pivot"],"partners":[{"id":"role","rel":"形+名","phrase":"play a pivotal role in mitigating","note":"常用搭配：play a pivotal role in mitigating（在缓解……方面发挥中枢关键作用），与 role（作用、角色）构成高频「形+名」词伙。"},{"id":"position","rel":"形+名","phrase":"occupy a pivotal position in global supply chains","note":"常用搭配：occupy a pivotal position in global supply chains（在全球供应链中占据中枢地位），与 position（地位、位置）构成高频「形+名」词伙。"}]},{"id":"imperative","word":"imperative","ipa":{"uk":"/ɪmˈperətɪv/","us":"/ɪmˈperətɪv/"},"pos":"adj.","definition":{"en":"Of vital importance; crucial and demanding immediate attention or action.","zh":"势在必行的、急迫必要的；同作名词表“当务之急、必然要求”。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["观点评价","利弊权衡"],"frequency":{"ielts":5,"gre":4},"register":"极正式政策倡议与危机呼吁语域；适用于大作文结尾段或对策段强调形势紧迫、政府或社会必须立即采取行动","synonyms":[{"id":"mandatory","note":"mandatory 指法律或规章强制规定的；imperative 指客观形势迫切要求必须做的。"},{"id":"indispensable","note":"indispensable 强调不可或缺；imperative 强调行动上的紧迫性与必要性。"},{"id":"paramount","note":"paramount 强调重要性排第一；imperative 强调必须立即付诸行动。"},{"id":"urgent","note":"imperative 侧重客观形势或准则要求势在必行、不容推卸；urgent 侧重时间紧迫、亟待立即处理。"}],"antonyms":[{"id":"dispensable","note":"反义对照：imperative 表势在必行、必不可少的，而 dispensable 表可有可无、可以省去的。"},{"id":"optional","note":"反义对照：imperative 表急迫必要、必须执行的，而 optional 表可自由选择的。"}],"collocations":[{"en":"it is imperative that governments enact","zh":"政府制定……已是势在必行"},{"en":"a moral and economic imperative","zh":"道义与经济上的必然要求/当务之急"},{"en":"become increasingly imperative to address","zh":"解决……变得日益紧迫必要"},{"en":"balance competing fiscal and social imperatives","zh":"平衡相互竞争的财政与社会当务之急"}],"examples":[{"type":"IELTS","en":"Given the accelerating pace of planetary warming, it is imperative that industrialised nations phase out fossil fuel subsidies immediately.","zh":"鉴于全球变暖速度不断加快，工业化国家立即逐步淘汰化石燃料补贴已是势在必行。","highlights":["it is imperative that"]},{"type":"IELTS","en":"Bridging the urban-rural digital divide is not merely a matter of charity, but an economic imperative for sustained national competitiveness.","zh":"弥合城乡数字鸿沟不仅关乎慈善，更是维持国家持久竞争力的经济当务之急。","highlights":["an economic imperative for"]},{"type":"GRE","en":"Caught between bond-market discipline and demographic ageing, the administration faced the competing imperatives of fiscal solvency and social welfare.","zh":"在债券市场纪律与人口老龄化的夹击下，该政府面临着财政偿付能力与社会福利这两大相互竞争的当务之急。","highlights":["competing imperatives"]}],"note":"【句型框架】大作文结尾段高分虚拟语气句型：`It is imperative that authorities (should) + 动词原形`（当局做……是势在必行的）；亦可作可数名词：`X is a moral/categorical/economic imperative`（X 是道义/绝对/经济上的当务之急）。【高阶替换】完美升级死板的 `Governments must / should / need to...`；相比 `important`，`imperative` 蕴含着“迫在眉睫、不容拖延或推卸的命令感”。【避坑指南】当使用 `It is imperative that...` 从句时，从句谓语动词必须使用虚拟语气，即“动词原形”或 `should + 动词原形`（如 `It is imperative that the law be reformed`，切勿写成 `is reformed`）。","forms":["imperatives","imperatively"],"partners":[{"id":"enact","rel":"动+形","phrase":"it is imperative that governments enact","note":"常用搭配：it is imperative that governments enact（政府制定……已是势在必行），与 enact（制定、颁布）构成高频「动+形」词伙。"},{"id":"moral","rel":"形+名","phrase":"a moral and economic imperative","note":"常用搭配：a moral and economic imperative（道义与经济上的必然要求/当务之急），与 moral（道义上的、道德的）构成高频「形+名」词伙。"}]},{"id":"formidable","word":"formidable","ipa":{"uk":"/ˈfɔːmɪdəbl/","us":"/fərˈmɪdəbl/"},"pos":"adj.","definition":{"en":"Inspiring fear or respect through being impressively large, powerful, intense, or capable.","zh":"艰巨的、难以克服的；令人敬畏的、强大的。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["观点评价","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与政策挑战评估语域；适用于大作文承认改革阻力巨大、技术壁垒高企或对手实力强劲","synonyms":[{"id":"monumental","note":"monumental 强调规模宏大或具有不朽历史意义；formidable 强调挑战艰巨或力量强大得令人望而生畏。"},{"id":"intractable","note":"修饰困难挑战时相近；formidable 强调规模巨大令人敬畏，intractable 强调盘根错节、久治不愈。"},{"id":"forbidding","note":"formidable 侧重挑战艰巨或对手强大得令人敬畏；forbidding 侧重外表冷峻严厉或环境险恶得令人望而却步。"}],"antonyms":[{"id":"trivial","note":"formidable challenge 是艰巨挑战，trivial task 是微不足道的小事。"}],"collocations":[{"en":"pose a formidable technical and financial challenge","zh":"构成严峻的技术与财务挑战"},{"en":"confront formidable institutional obstacles","zh":"面临艰巨的制度障碍"},{"en":"overcome formidable logistical barriers","zh":"克服艰巨的物流壁垒"},{"en":"emerge as a formidable economic competitor","zh":"崛起为强大的经济竞争对手"}],"examples":[{"type":"IELTS","en":"Decarbonising heavy industries such as steel manufacturing and long-haul aviation remains a formidable technical and financial challenge.","zh":"使钢铁制造和远程航空等重工业实现脱碳，仍然是一项艰巨的技术与财务挑战。","highlights":["a formidable technical and financial challenge"]},{"type":"IELTS","en":"First-generation university students from rural backgrounds often confront formidable socioeconomic obstacles when competing for elite internships.","zh":"来自农村背景的第一代大学生在竞争精英实习机会时，往往面临艰巨的社会经济障碍。","highlights":["confront formidable socioeconomic obstacles"]},{"type":"GRE","en":"Despite the archival compiler's formidable erudition, several chronological inconsistencies crept into the posthumously published volume.","zh":"尽管这位档案编纂者学识渊博得令人敬畏，但在其身故后出版的卷册中还是混入了几处年代前后的矛盾。","highlights":["formidable erudition"]}],"note":"【句型框架】常用于承认困难的让步句或主题句：`Doing X poses a formidable challenge / obstacle / barrier to Y`（做 X 对 Y 构成了严峻的挑战/障碍）。【高阶替换】是升级 `very difficult / hard / tough / huge (challenge)` 的 Band 9 标志词；修饰抽象困难（`challenge, obstacle, task`）时意为“极其艰巨、需要付出巨大努力才能克服的”，修饰人或智力（`opponent, intellect, erudition`）时意为“令人敬畏的、实力极其强大的”。【避坑指南】不要望文生义将其等同于 `horrible / terrifying`（恐怖片式的吓人）；在学术写作中它带有“因体量庞大、难度极高或实力超群而令人肃然起敬/不敢轻视”的庄重色彩。","forms":["formidably"],"partners":[{"id":"challenge","rel":"形+名","phrase":"pose a formidable technical and financial challenge","note":"常用搭配：pose a formidable technical and financial challenge（构成严峻的技术与财务挑战），与 challenge（挑战）构成高频「形+名」词伙。"},{"id":"obstacle","rel":"形+名","phrase":"confront formidable institutional obstacles","note":"常用搭配：confront formidable institutional obstacles（面临艰巨的制度障碍），与 obstacle（障碍）构成高频「形+名」词伙。"}]},{"id":"plethora","word":"plethora","ipa":{"uk":"/ˈpleθərə/","us":"/ˈpleθərə/"},"pos":"n.","definition":{"en":"A large or excessive amount of something.","zh":"过多、过剩；大量、繁多。"},"libraries":["writing"],"topics":["科技与教育","社会与经济"],"functions":["数量与趋势","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式学术语域；常用于描述信息时代的选择过载、繁文缛节或多元因素交织的现象","synonyms":[{"id":"surfeit","note":"surfeit 强调过度摄取或供应带来的腻烦与不适；plethora 现代用法常泛指“极多、应接不暇”。"},{"id":"glut","note":"glut 特指市场供应严重过剩导致积压贬值；plethora 可修饰信息、选择、观点等抽象名词。"},{"id":"excess","note":"excess 泛指超标过量；plethora 常用于 a plethora of + 复数名词。"},{"id":"surplus","note":"surplus 指超出实际需求的盈余或顺差；plethora 指数量过多甚至过剩。"}],"antonyms":[{"id":"paucity","note":"plethora（过多）与 paucity（匮乏、稀少）是 GRE 与雅思写作中经典的反义词对。"},{"id":"dearth","note":"dearth 指严重短缺，与过剩繁多的 plethora 直接相反。"}],"collocations":[{"en":"a plethora of information","zh":"海量的（甚至过载的）信息"},{"en":"a plethora of choices","zh":"眼花缭乱的众多选择"},{"en":"face a plethora of regulations","zh":"面对繁多的规章制度"},{"en":"a plethora of empirical studies","zh":"大量的实证研究"}],"examples":[{"type":"IELTS","en":"While the internet provides a plethora of educational resources, students often struggle to distinguish credible sources from misinformation.","zh":"尽管互联网提供了海量的教育资源，但学生往往难以区分可靠来源与虚假信息。","highlights":["a plethora of educational resources"]},{"type":"IELTS","en":"Confronted with a plethora of consumer choices in modern supermarkets, shoppers frequently experience decision fatigue rather than heightened satisfaction.","zh":"在现代超市中面对眼花缭乱的消费选择，购物者往往会感到决策疲劳，而非更高的满足感。","highlights":["a plethora of consumer choices"]},{"type":"GRE","en":"Ironically, the plethora of competing explanatory models has obscured rather than elucidated the underlying demographic trend.","zh":"具有讽刺意味的是，过多相互竞争的解释模型掩盖而非阐明了潜在的人口变化趋势。","highlights":["plethora of competing explanatory models"]}],"note":"【句型框架】① While X provides a plethora of Y, ...（让步从句：虽然 X 提供了海量/繁多的 Y，但往往带来筛选困难或过载问题）；② Confronted with a plethora of choices/information, ...（分词状语，描述现代人的信息或选择焦虑）。【高阶替换】高级替换 a lot of、many、plenty of；相比 abundance（侧重丰沛充足，纯褒义）和 myriad（侧重种类繁多、不计其数），plethora 源自古希腊医学“多血症（体液过剩）”，在最地道的学术写作中常暗含“多得超出所需、甚至令人无所适从”的微妙语感。【避坑指南】固定搭配为 a plethora of + 可数名词复数或不可数名词；由于其暗含“过剩、繁杂”的底色，在表达纯粹的“急需物资充足”时用 an abundance of 更妥帖，而在谈论“信息爆炸、法规繁琐、商品泛滥”时用 a plethora of 最为惊艳。","forms":[],"partners":[{"id":"information","rel":"名+名","phrase":"a plethora of information","note":"常用搭配：a plethora of information（海量的（甚至过载的）信息），与 information（信息、资料）构成高频「名+名」词伙。"},{"id":"regulation","rel":"名+名","phrase":"face a plethora of regulations","note":"常用搭配：face a plethora of regulations（面对繁多的规章制度），与 regulation（规章制度、法规）构成高频「名+名」词伙。"}]},{"id":"paucity","word":"paucity","ipa":{"uk":"/ˈpɔːsəti/","us":"/ˈpɔːsəti/"},"pos":"n.","definition":{"en":"The presence of something only in small or insufficient quantities or amounts; scarcity.","zh":"匮乏、稀少、不足（尤指证据、数据或资源少得可怜）。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["数量与趋势","论证与证据"],"frequency":{"ielts":5,"gre":5},"register":"高度正式学术语域；常用于科研方法论评估、历史考据及大作文批评公共投入或实证数据匮乏","synonyms":[{"id":"dearth","note":"dearth 与 paucity 极近义；dearth 更强调本应有却极度缺乏的荒芜感，paucity 常修饰信息、证据或样本数量太少。"},{"id":"scarcity","note":"scarcity 多用于自然资源或商品的稀缺；paucity 多用于学术证据、资金或思想的贫乏。"},{"id":"shortfall","note":"shortfall 指未达到预期目标的差额缺口；paucity 指数量极少、匮乏。"},{"id":"shortage","note":"paucity 语域极正式，多指实证数据、学术证据或资源的匮乏稀少；shortage 为通用词，常指物资、住房或劳动力短缺。"}],"antonyms":[{"id":"plethora","note":"反义对照：paucity 表数量匮乏稀少，而 plethora 表过多、过剩。"},{"id":"surfeit","note":"反义对照：paucity 表极度短缺不足，而 surfeit 表过量、过剩。"}],"collocations":[{"en":"a paucity of empirical evidence","zh":"实证证据的匮乏"},{"en":"a paucity of reliable data","zh":"可靠数据的缺乏"},{"en":"lament the paucity of funding","zh":"感叹资金的匮乏"},{"en":"a paucity of affordable housing","zh":"平价住房的严重短缺"}],"examples":[{"type":"IELTS","en":"Despite growing public concern over microplastics, there remains a paucity of longitudinal studies on their human health impacts.","zh":"尽管公众对微塑料的担忧日益加剧，但关于其对人类健康影响的纵向研究仍然匮乏。","highlights":["a paucity of longitudinal studies"]},{"type":"IELTS","en":"The paucity of recreational facilities in deprived urban neighbourhoods exacerbates youth delinquency and social alienation.","zh":"贫困城市社区娱乐设施的匮乏，加剧了青少年越轨行为与社会疏离感。","highlights":["The paucity of recreational facilities"]},{"type":"GRE","en":"Given the paucity of surviving vernacular manuscripts from the eighth century, philologists must rely on indirect epigraphic evidence.","zh":"鉴于八世纪留存至今的方言手稿极为匮乏，语文学家必须依赖间接的碑铭证据。","highlights":["paucity of surviving vernacular manuscripts"]}],"note":"【句型框架】① There remains a paucity of empirical evidence/funding regarding X（关于 X 仍存在实证证据/资金的匮乏）；② Given the paucity of X, policymakers/researchers must...（鉴于 X 的匮乏，决策者/研究者必须……）。【高阶替换】替换 a lack of、shortage of、too few/little 的顶级C2学术名词（与 dearth 同级）；相比 shortage（常指生活物资或劳动力的暂时性短缺）和 scarcity（经济学中的资源稀缺性），paucity 更强调“数量少得可怜、远不足以支撑结论或满足基本需求”。【避坑指南】通常只用单数形式（a paucity of... 或 the paucity of...），无复数用法；请注意主谓一致：当 the paucity of + 复数名词作主语时，核心词是单数名词 paucity，谓语动词必须用单数（The paucity of studies is... 而非 are）。","forms":[],"partners":[{"id":"evidence","rel":"名+名","phrase":"a paucity of empirical evidence","note":"常用搭配：a paucity of empirical evidence（实证证据的匮乏），与 evidence（证据）构成高频「名+名」词伙。"},{"id":"data","rel":"名+名","phrase":"a paucity of reliable data","note":"常用搭配：a paucity of reliable data（可靠数据的缺乏），与 data（数据）构成高频「名+名」词伙。"}]},{"id":"escalate","word":"escalate","ipa":{"uk":"/ˈeskəleɪt/","us":"/ˈeskəleɪt/"},"pos":"v.","definition":{"en":"To become or cause to become more intense, serious, or costly.","zh":"（冲突、危机或成本）升级、加剧、逐步扩大。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["让步转折","改善与恶化"],"frequency":{"ielts":5,"gre":4},"register":"正式议论与新闻学术语域；常用于因果论证段揭示危机、社会矛盾、冲突或公共开支失控的逐步恶化","synonyms":[{"id":"exacerbate","note":"exacerbate 为及物动词“使……恶化”；escalate 常作不及物动词“（事态本身）升级、激化”。"},{"id":"soar","note":"soar 单纯指数值高涨；escalate 强调事态严重性或对抗烈度步步升级（如 escalating tensions）。"},{"id":"surge","note":"surge 指突然涌起；escalate 强调像自动扶梯（escalator）一样节节攀升、失控扩大。"}],"antonyms":[{"id":"abate","note":"escalate 事态升级加剧，abate 事态减弱平息。"},{"id":"subside","note":"subside 指危机或冲突逐渐平息消退，与升级的 escalate 相对。"}],"collocations":[{"en":"escalate into a full-scale crisis","zh":"升级为全面危机"},{"en":"escalating healthcare expenditure","zh":"节节攀升的医疗支出"},{"en":"escalating trade tensions","zh":"不断升级的贸易紧张局势"},{"en":"escalate at an alarming rate","zh":"以惊人的速度升级/飙升"}],"examples":[{"type":"IELTS","en":"Without timely diplomatic intervention, minor resource disputes can rapidly escalate into destructive regional conflicts.","zh":"如果没有及时的外交干预，微小的资源争端可能会迅速升级为破坏性的地区冲突。","highlights":["escalate into destructive regional conflicts"]},{"type":"IELTS","en":"Confronted with escalating healthcare expenditure brought about by an ageing demographic, governments must shift their focus from acute treatment to chronic disease prevention.","zh":"面对人口老龄化带来的节节攀升的医疗支出，政府必须将重心从急症治疗转向慢性病预防。","highlights":["escalating healthcare expenditure"]},{"type":"GRE","en":"As the infrastructure project encountered unforeseen geological obstacles, construction costs escalated far beyond initial parliamentary appropriations.","zh":"随着基础设施项目遇到未曾预料的地质障碍，建设成本节节攀升，远远超出了最初的议会拨款。","highlights":["construction costs escalated"]}],"note":"【句型框架】① Without timely intervention, X can rapidly escalate into Y（若无及时干预，小问题 X 会迅速升级为大危机 Y）；② Confronted with escalating costs/tensions, ...（分词状语置于句首，引出应对之策）。【高阶替换】精准替换 get worse、increase fast、become more serious；相比 intensify（单纯指程度加深）和 surge（瞬间激增），escalate（与 escalator 自动扶梯同源）形象地刻画出“阶梯式步步升级、愈演愈烈直至失控”的动态过程。【避坑指南】语义极性鲜明偏负面，专用于修饰 conflicts、tensions、violence、crime、costs、prices 等令人担忧的事态，切忌用于正面事物的增长（不能说 Living standards escalated 或 Happiness escalated）。","forms":["escalates","escalated","escalating","escalation"],"partners":[{"id":"crisis","rel":"动+名","phrase":"escalate into a full-scale crisis","note":"常用搭配：escalate into a full-scale crisis（升级为全面危机），与 crisis（危机）构成高频「动+名」词伙。"},{"id":"tension","rel":"动+名","phrase":"escalating trade tensions","note":"常用搭配：escalating trade tensions（不断升级的贸易紧张局势），与 tension（紧张局势）构成高频「动+名」词伙。"}]},{"id":"burgeon","word":"burgeon","ipa":{"uk":"/ˈbɜːdʒən/","us":"/ˈbɜːrdʒən/"},"pos":"v.","definition":{"en":"To begin to grow or increase rapidly; to flourish.","zh":"蓬勃发展、迅速成长、急剧增长。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["改善与恶化","数量与趋势"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与经济评论语域；常用于描述新兴产业、城市人口、中产阶级或市场需求方兴未艾的蓬勃态势","synonyms":[{"id":"proliferate","note":"proliferate 强调数量裂变繁殖；burgeon（词源为嫩芽萌发）强调生机勃勃地崛起与壮大。"},{"id":"mushroom","note":"mushroom 偏口语形象化；burgeon 语域高度正式，极常以 burgeoning 形式出现。"},{"id":"expand","note":"expand 为普通词“扩大”；burgeon 强调从初生阶段迅速繁盛起来。"},{"id":"flourish","note":"burgeon 侧重从初生阶段迅速萌发壮大；flourish 侧重处于全盛期的繁荣兴旺。"}],"antonyms":[{"id":"dwindle","note":"burgeon 蓬勃壮大，dwindle 日渐式微萎缩。"},{"id":"wane","note":"wane 指由盛转衰、减弱，与蓬勃兴起的 burgeon 相对。"},{"id":"ebb","note":"burgeon 蓬勃高涨，与衰退低落的 ebb 相反。"}],"collocations":[{"en":"a burgeoning middle class","zh":"迅速壮大的中产阶级"},{"en":"burgeoning demand for","zh":"对……日益高涨的需求"},{"en":"burgeoning urban populations","zh":"迅速增长的城市人口"},{"en":"burgeon into a global hub","zh":"蓬勃发展成为全球枢纽"}],"examples":[{"type":"IELTS","en":"To accommodate their burgeoning urban populations, developing nations must invest heavily in sustainable public transit.","zh":"为了容纳迅速增长的城市人口，发展中国家必须大力投资可持续的公共交通。","highlights":["burgeoning urban populations"]},{"type":"IELTS","en":"Fuelled by the burgeoning demand for renewable energy, solar photovoltaic manufacturing has evolved from a niche subsidised sector into a cornerstone of the global economy.","zh":"在对可再生能源日益高涨的需求推动下，太阳能光伏制造业已从一个依赖补贴的小众行业演变为全球经济的基石。","highlights":["burgeoning demand for"]},{"type":"GRE","en":"The burgeoning field of epigenetics has challenged deterministic models of heredity that once dominated molecular biology.","zh":"蓬勃发展的表观遗传学领域向曾主宰分子生物学的遗传决定论模型发起了挑战。","highlights":["burgeoning field of epigenetics"]}],"note":"【句型框架】① accommodate / meet the burgeoning demand for X（满足对 X 日益高涨的需求）；② X has burgeoned from a small settlement into a thriving metropolis（X 已从小聚落蓬勃发展为繁荣的大都市）。【高阶替换】高级替换 fast-growing、booming、rapidly developing；相比 flourish/thrive（侧重已经处于繁盛成熟期），burgeon 本义为“抽芽、萌发”，尤为强调“处于上升初期、生机勃勃地迅速壮大”。【避坑指南】作动词时为不及物动词（vi.），不可直接接宾语；在现代学术英语中，其现在分词形容词形式 burgeoning（如 burgeoning population / market）的使用频率远高于动词原形，且多带积极或中偏正面的成长色彩，不宜修饰纯粹的灾祸。","forms":["burgeons","burgeoned","burgeoning"],"partners":[{"id":"population","rel":"动+名","phrase":"burgeoning urban populations","note":"常用搭配：burgeoning urban populations（迅速增长的城市人口），与 population（人口）构成高频「动+名」词伙。"},{"id":"class","rel":"动+名","phrase":"a burgeoning middle class","note":"常用搭配：a burgeoning middle class（迅速壮大的中产阶级），与 class（阶层、阶级）构成高频「动+名」词伙。"}]},{"id":"plummet","word":"plummet","ipa":{"uk":"/ˈplʌmɪt/","us":"/ˈplʌmɪt/"},"pos":"v.","definition":{"en":"To fall or drop straight down at high speed; to decrease rapidly in value or amount.","zh":"暴跌、骤降、垂直坠落。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["数量与趋势","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与数据分析语域；小作文（Task 1）图表大幅下跌及大作文（Task 2）出生率、信任度骤降的标志性高分词","synonyms":[{"id":"plunge","note":"plunge 与 plummet 均可表骤降；plunge 还常带 into 表“使陷入（危机/混乱）”，plummet 则纯粹聚焦垂直坠落。"},{"id":"nosedive","note":"nosedive 偏新闻比喻（机头向下俯冲）；plummet（词源为铅锤）在学术与统计写作中更正式。"},{"id":"slump","note":"slump 强调因乏力而瘫软跌落并陷入长期低迷；plummet 强调下跌速度极快、幅度极陡。"}],"antonyms":[{"id":"surge","note":"反义对照：plummet 表垂直暴跌、骤降，而 surge 表激增、猛涨。"},{"id":"soar","note":"反义对照：plummet 表急剧暴跌，而 soar 表高涨、飙升。"},{"id":"skyrocket","note":"反义对照：plummet 表直线坠落暴跌，而 skyrocket 表火箭式暴涨飙升。"}],"collocations":[{"en":"fertility rates have plummeted","zh":"生育率已大幅骤降"},{"en":"plummet to an all-time low","zh":"暴跌至历史最低点"},{"en":"consumer confidence plummeted","zh":"消费者信心暴跌"},{"en":"plummet by nearly half","zh":"暴跌近一半"}],"examples":[{"type":"IELTS","en":"Fertility rates across many industrialised nations have plummeted as the cost of raising children continues to soar.","zh":"随着抚养子女的成本持续飙升，许多工业化国家的生育率已大幅骤降。","highlights":["have plummeted"]},{"type":"IELTS","en":"Public trust in traditional news outlets has plummeted to an all-time low, driven largely by partisan polarisation and sensationalist reporting.","zh":"主要受党派极化和耸人听闻报道的驱使，公众对传统新闻媒体的信任度已暴跌至历史最低点。","highlights":["plummeted to an all-time low"]},{"type":"GRE","en":"When the central bank abruptly contracted the money supply, industrial output plummeted within a single fiscal quarter.","zh":"当央行突然紧缩货币供应时，工业产出在一个财政季度内便骤然暴跌。","highlights":["industrial output plummeted"]}],"note":"【句型框架】① X has plummeted from [高点] to [低点] / to an all-time low（X 从高点暴跌至低点/历史新低）；② As X continues to soar, Y has plummeted（与 soar/skyrocket 构成鲜明反差对比句）。【高阶替换】强力替代 drop sharply、fall quickly、go down a lot；相比 decline/decrease（可缓可急的中性词）和 dwindle（缓慢渐进地萎缩减少），plummet 原意为“测深铅锤垂直坠落”，强调“高速度、大幅度的断崖式下跌”。【避坑指南】第一，plummet 是不及物动词（vi.），不可用于被动语态；第二，该词词义中已内置了“rapidly and sharply”的程度义，切忌画蛇添足地写成 plummet rapidly / sharply / slightly（语义矛盾或冗余）。","forms":["plummets","plummeted","plummeting"],"partners":[{"id":"confidence","rel":"动+名","phrase":"consumer confidence plummeted","note":"常用搭配：consumer confidence plummeted（消费者信心暴跌），与 confidence（信心）构成高频「动+名」词伙。"},{"id":"consumer","rel":"动+名","phrase":"consumer confidence plummeted","note":"常用搭配：consumer confidence plummeted（消费者信心暴跌），与 consumer（消费者）构成高频「动+名」词伙。"}]},{"id":"wane","word":"wane","ipa":{"uk":"/weɪn/","us":"/weɪn/"},"pos":"v.","definition":{"en":"To decrease in vigour, power, or extent; to become weaker, especially after reaching a peak.","zh":"衰落、减弱、消退（尤指权势、影响力或热情由盛转衰）。"},"libraries":["writing"],"topics":["文化与历史","社会与经济"],"functions":["数量与趋势","改善与恶化"],"frequency":{"ielts":5,"gre":4},"register":"正式书面与历史评论语域；常用于描述霸权地位、文化传统影响力、公众热情或公信力由盛转衰","synonyms":[{"id":"dwindle","note":"dwindle 常指具体数量或存量日渐缩减；wane（本义月亏）常指抽象权势、声望或热情消退。"},{"id":"ebb","note":"ebb（退潮）与 wane（月亏）极近义，常并列成习语 ebb and flow / on the wane。"},{"id":"diminish","note":"diminish 为通用词；wane 更强调盛极之后的缓慢衰减。"},{"id":"abate","note":"wane 侧重影响力或热情的缓慢衰退；abate 侧重恶劣态势或剧烈程度的缓和。"}],"antonyms":[{"id":"burgeon","note":"反义对照：wane 表由盛转衰、日渐消退，而 burgeon 表蓬勃发展、迅速壮大。"},{"id":"surge","note":"surge 强劲高涨，与渐趋衰弱的 wane 相反。"},{"id":"revive","note":"反义对照：wane 表渐趋衰弱消退，而 revive 表复苏、重焕生机。"}],"collocations":[{"en":"waning public enthusiasm","zh":"日益消退的公众热情"},{"en":"influence is on the wane","zh":"影响力正在衰退"},{"en":"waning geopolitical hegemony","zh":"日渐式微的地缘政治霸权"},{"en":"begin to wane","zh":"开始走下坡路/消退"}],"examples":[{"type":"IELTS","en":"Public enthusiasm for large-scale sporting events has waned considerably due to concerns over excessive taxpayer expenditure.","zh":"由于担心纳税人支出过多，公众对大型体育赛事的热情已大幅消退。","highlights":["has waned considerably"]},{"type":"IELTS","en":"Although the influence of print newspapers is undeniably on the wane, investigative journalism remains indispensable to democratic accountability.","zh":"尽管纸质报纸的影响力无可否认正在衰退，但调查性新闻对于民主问责制而言依然不可或缺。","highlights":["on the wane"]},{"type":"GRE","en":"As the guild's monopoly over maritime trade began to wane, provincial merchants established independent credit networks.","zh":"随着该行会对海上贸易的垄断开始衰落，地方商人建立了独立的信贷网络。","highlights":["began to wane"]}],"note":"【句型框架】① X's influence / popularity has waned considerably over the past decade（X 的影响力/热度在过去十年大幅消退）；② While traditional X is on the wane, ...（名词语块 be on the wane 意为“正在走下坡路”，用于让步段极地道）。【高阶替换】文雅替代 become weaker、lose popularity、fade away；本义指“月亏、月相渐缺”（与 wax 月盈相对），引申指抽象的“力量、声望、权威、热情达到顶峰后逐渐黯淡式微”。【避坑指南】第一，wane 为不及物动词；第二，它的主语通常是非物质的抽象力量（power, enthusiasm, influence, popularity, interest），不宜用来描述具体物质或价格数量的减少（不说 Oil reserves waned 或 Prices waned，前者用 dwindle，后者用 fall/drop）。","forms":["wanes","waned","waning"],"partners":[{"id":"enthusiasm","rel":"动+名","phrase":"waning public enthusiasm","note":"常用搭配：waning public enthusiasm（日益消退的公众热情），与 enthusiasm（热情）构成高频「动+名」词伙。"},{"id":"hegemony","rel":"动+名","phrase":"waning geopolitical hegemony","note":"常用搭配：waning geopolitical hegemony（日渐式微的地缘政治霸权），与 hegemony（霸权、主导权）构成高频「动+名」词伙。"}]},{"id":"fluctuate","word":"fluctuate","ipa":{"uk":"/ˈflʌktʃueɪt/","us":"/ˈflʌktʃueɪt/"},"pos":"v.","definition":{"en":"To rise and fall irregularly in number or amount.","zh":"波动、起伏不定、上下浮动。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["数量与趋势"],"frequency":{"ielts":5,"gre":3},"register":"正式学术与统计分析语域；雅思小作文（Task 1）动态图核心词，亦用于大作文描述宏观经济、能源供给的不稳定性","synonyms":[{"id":"oscillate","note":"oscillate 强调像钟摆一样在两个端点或两种极端态度之间来回摆动；fluctuate 强调数值不规则地上下起伏。"},{"id":"vary","note":"近义辨析：二者在“变化”义项上相通；fluctuate 侧重“涨落”，vary 侧重“改变”。"},{"id":"vacillate","note":"fluctuate 侧重价格、汇率或温度等数值不规则地上下浮动；vacillate 侧重人在不同立场或决定之间犹豫摇摆。"}],"antonyms":[{"id":"stabilise","note":"反义对照：fluctuate 表“涨落”，而 stabilise 表“稳定”，二者构成鲜明的语义对立。"},{"id":"plateau","note":"plateau 指维持在平稳高原期不再明显起伏，与波动的 fluctuate 相对。"}],"collocations":[{"en":"fluctuate wildly between","zh":"在……之间剧烈波动"},{"en":"fluctuate around an average","zh":"围绕平均值上下浮动"},{"en":"fluctuating commodity prices","zh":"波动不定的大宗商品价格"},{"en":"fluctuate according to seasonal demand","zh":"随季节性需求而波动"}],"examples":[{"type":"IELTS","en":"Solar and wind power generation can fluctuate significantly depending on seasonal and daily weather conditions.","zh":"太阳能和风力发电量会根据季节和每日天气状况而出现显著波动。","highlights":["fluctuate significantly"]},{"type":"IELTS","en":"When global commodity prices fluctuate wildly, economies that rely overwhelmingly on raw material exports suffer severe fiscal instability.","zh":"当全球大宗商品价格剧烈波动时，过度依赖原材料出口的经济体便会遭受严重的财政动荡。","highlights":["fluctuate wildly"]},{"type":"GRE","en":"Because grain yields fluctuated wildly from harvest to harvest, medieval municipalities maintained communal granaries against famine.","zh":"由于每次收成的谷物产量剧烈波动，中世纪市政当局维持着公共粮仓以防饥荒。","highlights":["fluctuated wildly"]}],"note":"【句型框架】① X fluctuated wildly/moderately between A and B（X 在数值 A 与 B 之间剧烈/温和波动）；② be vulnerable to price/economic fluctuations（易受价格/经济波动冲击，用于大作文抗风险能力论证）。【高阶替换】精准升级 go up and down、change irregularly；相比 vary（泛指不同或变化，未必随时间上下起伏）和 oscillate（物理或钟摆式有规律摆动），fluctuate 专指数量、价格、比率、温度等在不确定的区间内“不规则地上下起伏”。【避坑指南】不及物动词（vi.），无被动语态；主语必须是“数值指标”（如 the price of oil, unemployment rates, temperatures），切忌将实体事物直接作主语（不能写 Cars fluctuated from 1990 to 2000，应写 The number/sales of cars fluctuated）。","forms":["fluctuates","fluctuated","fluctuating","fluctuation"],"partners":[{"id":"price","rel":"动+名","phrase":"fluctuating commodity prices","note":"常用搭配：fluctuating commodity prices（波动不定的大宗商品价格），与 price（价格）构成高频「动+名」词伙。"},{"id":"commodity","rel":"动+名","phrase":"fluctuating commodity prices","note":"常用搭配：fluctuating commodity prices（波动不定的大宗商品价格），与 commodity（大宗商品、货物）构成高频「动+名」词伙。"}]},{"id":"stagnate","word":"stagnate","ipa":{"uk":"/stæɡˈneɪt/","us":"/ˈstæɡneɪt/"},"pos":"v.","definition":{"en":"To cease developing, advancing, or being active; to become dull and sluggish.","zh":"停滞不前、陷入萧条、不景气。"},"libraries":["writing"],"topics":["社会与经济"],"functions":["数量与趋势","改善与恶化"],"frequency":{"ielts":5,"gre":4},"register":"正式经济与社会评论语域；常用于收入差距、生产力瓶颈、社会阶层固化及文化思想僵化的深度剖析","synonyms":[{"id":"plateau","note":"plateau 中性指上升后进入平台期；stagnate 贬义指像死水一样失去活力、长期停滞不前。"},{"id":"languish","note":"stagnate 侧重经济、工资或发展进程如死水般停滞不前；languish 侧重长期处于萧条、受冷落或缺乏活力的萎靡状态。"}],"antonyms":[{"id":"proliferate","note":"反义对照：stagnate 表“停滞”，而 proliferate 表“激增”，二者构成鲜明的语义对立。"},{"id":"burgeon","note":"反义对照：stagnate 表“停滞”，而 burgeon 表“迅速成长”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"real wages have stagnated","zh":"实际工资一直停滞不前"},{"en":"a stagnating economy","zh":"陷入停滞的经济"},{"en":"living standards stagnated","zh":"生活水平停滞不前"},{"en":"economic stagnation","zh":"经济停滞/萧条"}],"examples":[{"type":"IELTS","en":"When median household incomes stagnate while housing costs soar, social mobility inevitably declines.","zh":"当家庭收入中位数停滞不前而住房成本飙升时，社会流动性不可避免地会下降。","highlights":["incomes stagnate"]},{"type":"IELTS","en":"Deprived of external competition and technological innovation, state-protected monopolies tend to stagnate, delivering inferior services at inflated prices.","zh":"一旦缺乏外部竞争与技术创新，受国家保护的垄断企业往往会停滞不前，以虚高的价格提供劣质服务。","highlights":["tend to stagnate"]},{"type":"GRE","en":"Cut off from transcontinental trade routes, the once-prosperous port city stagnated culturally and economically for two centuries.","zh":"被切断跨大陆贸易路线后，这座曾经繁荣的港口城市在文化和经济上停滞了两个世纪。","highlights":["stagnated culturally and economically"]}],"note":"【句型框架】① When real wages stagnate while living costs soar, ...（一静一动对比从句，剖析民生困境的满分模板）；② suffer from prolonged economic stagnation（遭受长期的经济停滞）。【高阶替换】有力替换 stop growing、stay the same、not develop；相比 plateau（图表题中性词，指增长达到高位后进入平稳期），stagnate 本义是“水不流动而发臭（死水一潭）”，带有强烈的负面色彩，指原本应该增长或进步的事物因丧失活力而陷入僵化萧条。【避坑指南】stagnate 是不及物动词（vi.），不能写 stagnate the economy；若要作定语修饰名词，除了现在分词 stagnating，更地道的同根形容词是 stagnant（如 stagnant wages 停滞的工资，stagnant water 死水）。","forms":["stagnates","stagnated","stagnating","stagnant","stagnation"],"partners":[{"id":"economy","rel":"动+名","phrase":"a stagnating economy","note":"常用搭配：a stagnating economy（陷入停滞的经济），与 economy（经济）构成高频「动+名」词伙。"},{"id":"economic","rel":"形+名","phrase":"economic stagnation","note":"常用搭配：economic stagnation（经济停滞/萧条），与 economic（经济的）构成高频「形+名」词伙。"}]},{"id":"rectify","word":"rectify","ipa":{"uk":"/ˈrektɪfaɪ/","us":"/ˈrektɪfaɪ/"},"pos":"v.","definition":{"en":"To put right; to correct a mistake, fault, or unsatisfactory situation.","zh":"纠正、矫正、整改（错误、缺陷或制度漏洞）。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["改善与恶化","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式行政与法政语域；适用于大作文对策段提出制度纠偏、监管漏洞修补与历史不公矫正","synonyms":[{"id":"redress","note":"redress 强调赔偿不公或扭转失衡（redress the balance / grievance）；rectify 强调把错的改对（rectify an error / omission）。"},{"id":"ameliorate","note":"ameliorate 侧重改善恶劣状况；rectify 侧重彻底修正具体错误或缺陷。"},{"id":"correct","note":"rectify 语域正式，常指整顿纠正制度漏洞、结构性缺陷或历史不公；correct 为纠正错误的通用词。"},{"id":"amend","note":"rectify 强调把偏差或错误彻底改过来；amend 强调对法律法规、法案或文稿进行修改完善。"}],"antonyms":[{"id":"exacerbate","note":"rectify 纠正问题，exacerbate 则使问题恶化。"},{"id":"aggravate","note":"aggravate 加重过失或困境，与修正错误的 rectify 相对。"}],"collocations":[{"en":"rectify structural flaws in the system","zh":"纠正体制中的结构性缺陷"},{"en":"rectify historical injustices","zh":"矫正历史不公"},{"en":"rectify market failures through regulation","zh":"通过监管纠正市场失灵"},{"en":"take decisive steps to rectify the anomaly","zh":"采取果断措施纠正反常现象"}],"examples":[{"type":"IELTS","en":"Targeted macroprudential regulations are urgently needed to rectify the market failures that have priced young families out of urban homeownership.","zh":"亟需采取有针对性的宏观审慎监管措施，以纠正导致年轻家庭买不起城市住房的市场失灵问题。","highlights":["rectify the market failures"]},{"type":"IELTS","en":"Unless educational authorities rectify the chronic underfunding of rural schools, regional disparities in academic attainment will continue to widen.","zh":"除非教育主管部门纠正农村学校长期经费不足的问题，否则学业成就上的地区差距将继续扩大。","highlights":["rectify the chronic underfunding"]},{"type":"GRE","en":"Subsequent editors sought to rectify the chronological errors and partisan distortions that had marred the first edition of the chronicle.","zh":"后来的编者试图纠正损害该编年史第一版质量的年代错误与党派偏见。","highlights":["rectify the chronological errors"]}],"note":"【句型框架】常用搭配为 `take steps/measures to rectify + 抽象缺陷名词`（采取措施纠正……）或 `rectify the imbalance between A and B`（纠正 A 与 B 之间的失衡）。【高阶替换】完美升级口语化的 `fix / put right` 以及普通词汇 `correct`；与 `amend`（侧重修订法律条文或文本）相比，`rectify` 强调将偏离正轨的制度、错误或失衡状态彻底“拨乱反正”。【避坑指南】`rectify` 是及物动词，无需加介词；其宾语应为抽象的错误、漏洞或不公（`error, flaw, omission, inequity`），不能用于修理具体损坏的物品（如不可写 `rectify a broken computer`）。","forms":["rectifies","rectified","rectifying","rectification"],"partners":[{"id":"flaw","rel":"动+名","phrase":"rectify structural flaws in the system","note":"常用搭配：rectify structural flaws in the system（纠正体制中的结构性缺陷），与 flaw（缺陷、漏洞）构成高频「动+名」词伙。"},{"id":"injustice","rel":"动+名","phrase":"rectify historical injustices","note":"常用搭配：rectify historical injustices（矫正历史不公），与 injustice（不公正）构成高频「动+名」词伙。"}]},{"id":"deteriorate","word":"deteriorate","ipa":{"uk":"/dɪˈtɪəriəreɪt/","us":"/dɪˈtɪriəreɪt/"},"pos":"v.","definition":{"en":"To become progressively worse in quality, condition, or value.","zh":"恶化、变坏、退化。"},"libraries":["writing"],"topics":["自然与环境","健康与生活"],"functions":["改善与恶化"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与报告语域；适用于大作文环境退化、老旧基建失修或国际关系下滑的过程描写","synonyms":[{"id":"degenerate","note":"degenerate 强调从高尚、有序状态堕落或蜕变为低劣混乱状态；deteriorate 客观描述质量、健康或局势逐步变差。"},{"id":"erode","note":"erode 强调像水土流失一样被缓慢侵蚀削弱；deteriorate 强调状况本身日益恶化。"},{"id":"exacerbate","note":"语法大不同：deteriorate 主要作不及物动词（状况自己恶化）；exacerbate 是及物动词（使状况恶化）。"},{"id":"decline","note":"deteriorate 侧重质量、局势或关系实质性变差恶化；decline 侧重数量、比率或影响力逐步下降。"}],"antonyms":[{"id":"ameliorate","note":"反义对照：deteriorate 表“变坏”，而 ameliorate 表“改善”，二者构成鲜明的语义对立。"},{"id":"improve","note":"反义对照：deteriorate 表“变坏”，而 improve 表“改善”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"deteriorate at an alarming rate","zh":"以惊人的速度恶化"},{"en":"steadily deteriorating air quality","zh":"持续恶化的空气质量"},{"en":"deteriorate into open hostility","zh":"恶化为公开敌对状态"},{"en":"rapid deterioration of public infrastructure","zh":"公共基础设施的迅速退化"}],"examples":[{"type":"IELTS","en":"Without ring-fenced maintenance budgets, municipal transit infrastructure in older industrial cities inevitably begins to deteriorate at an alarming rate.","zh":"如果缺乏专款专用的维护预算，老工业城市的市政交通基础设施不可避免地会开始以惊人的速度退化。","highlights":["deteriorate at an alarming rate"]},{"type":"IELTS","en":"As sedentary lifestyles and ultra-processed diets become the norm, public metabolic health continues to deteriorate across both affluent and developing nations.","zh":"随着久坐不动的生活方式和超加工饮食成为常态，无论在富裕国家还是发展中国家，公众的代谢健康状况都在持续恶化。","highlights":["continues to deteriorate"]},{"type":"GRE","en":"As diplomatic communications deteriorated into mutual recrimination, minor border skirmishes were increasingly interpreted as preludes to full-scale mobilization.","zh":"随着外交沟通恶化为相互指责，微小的边境冲突越来越被解读为全面军事动员的前奏。","highlights":["deteriorated into mutual recrimination"]}],"note":"【句型框架】核心句式为不及物结构 `X continues to deteriorate`（X 持续恶化）、`deteriorate into Y`（恶化演变为 Y）或分词定语 `deteriorating environmental conditions`（日益恶化的环境状况）。【高阶替换】替换口语化的 `get worse / go bad / decline in quality`；与 `decline`（侧重数量、比例或影响力的下降）不同，`deteriorate` 强调事物内在品质、健康状况、功能或关系质量的蜕变与退化。【避坑指南】中国雅思考生最高频语法错误是将其误作及物动词，写出 `Industrial emissions deteriorated air quality`（错误！应改为 `Industrial emissions degraded air quality` 或 `caused air quality to deteriorate`）。","forms":["deteriorates","deteriorated","deteriorating","deterioration"],"partners":[{"id":"infrastructure","rel":"动+名","phrase":"rapid deterioration of public infrastructure","note":"常用搭配：rapid deterioration of public infrastructure（公共基础设施的迅速退化），与 infrastructure（基础设施）构成高频「动+名」词伙。"},{"id":"hostility","rel":"动+名","phrase":"deteriorate into open hostility","note":"常用搭配：deteriorate into open hostility（恶化为公开敌对状态），与 hostility（敌意、敌对状态）构成高频「动+名」词伙。"}]},{"id":"erode","word":"erode","ipa":{"uk":"/ɪˈrəʊd/","us":"/ɪˈroʊd/"},"pos":"v.","definition":{"en":"To gradually wear away soil or rock by natural agents, or to gradually destroy or diminish confidence, rights, or value.","zh":"侵蚀、腐蚀；逐渐削弱、蚕食（信任、购买力或权利）。"},"libraries":["writing"],"topics":["自然与环境","社会与经济"],"functions":["改善与恶化","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"正式议论与社会批评语域；适用于大作文分析长期负面趋势对信任、购买力或传统价值的渐进蚕食","synonyms":[{"id":"corrode","note":"corrode（化学腐蚀）语气更尖锐，强调带毒性的破坏力（如腐败或嫉妒）；erode（物理风化侵蚀）强调日积月累的蚕食。"},{"id":"undermine","note":"undermine 强调从根基处暗中破坏；erode 强调表面与存量随时间慢慢磨损流失。"},{"id":"deteriorate","note":"deteriorate 仅不及物；erode 既可及物（erode trust）也可不及物（Living standards eroded）。"},{"id":"ravage","note":"erode 是渐进侵蚀，ravage 则是猛烈而广泛的破坏。"}],"antonyms":[{"id":"bolster","note":"反义对照：erode 表“侵蚀”，而 bolster 表“支持”，二者构成鲜明的语义对立。"},{"id":"restore","note":"反义对照：erode 表“侵蚀”，而 restore 表“恢复”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"erode public trust in institutions","zh":"侵蚀公众对机构的信任"},{"en":"inflation erodes household purchasing power","zh":"通货膨胀蚕食家庭购买力"},{"en":"gradually erode social cohesion","zh":"逐渐削弱社会凝聚力"},{"en":"erode traditional cultural identity","zh":"侵蚀传统文化认同"}],"examples":[{"type":"IELTS","en":"Persistent price inflation gradually erodes household purchasing power, disproportionately burdening low-income families and pensioners on fixed incomes.","zh":"持续的物价通胀会逐渐蚕食家庭购买力，给低收入家庭和靠固定收入生活的养老金领取者带来不成比例的沉重负担。","highlights":["erodes household purchasing power"]},{"type":"IELTS","en":"When algorithmic news feeds prioritize sensationalism over factual accuracy, they steadily erode public trust in democratic institutions.","zh":"当算法新闻推送将耸人听闻置于事实准确性之上时，它们便会稳步侵蚀公众对民主制度的信任。","highlights":["erode public trust in"]},{"type":"GRE","en":"Repeated fiscal concessions to provincial warlords steadily eroded the central bureaucracy's judicial authority, leaving the monarchy nominal at best.","zh":"对地方军阀的一再财政妥协稳步侵蚀了中央官僚机构的司法权威，使君主政体最多只剩名义上的躯壳。","highlights":["steadily eroded"]}],"note":"【句型框架】常用 `gradually/steadily erode + 抽象正面价值（trust/confidence/cohesion/authority）` 或名词化短语 `accelerate the erosion of...`（加速……的流失/削弱）。【高阶替换】由地质学“水土风化侵蚀”引申而来，是替换 `weaken / reduce / damage` 的极具画面感的 Band 8.5 动词；与 `destroy`（瞬间摧毁）相比，`erode` 精准传达了“日积月累、潜移默化地蚕食与瓦解”的过程。【避坑指南】既可作及物动词（`Inflation erodes savings`），也可作不及物动词（`Confidence eroded rapidly`）；在社会议题中搭配 `gradually / steadily / slowly` 等渐进副词最为地道。","forms":["erodes","eroded","eroding","erosion"],"partners":[{"id":"cohesion","rel":"动+名","phrase":"gradually erode social cohesion","note":"常用搭配：gradually erode social cohesion（逐渐削弱社会凝聚力），与 cohesion（凝聚力）构成高频「动+名」词伙。"},{"id":"identity","rel":"动+名","phrase":"erode traditional cultural identity","note":"常用搭配：erode traditional cultural identity（侵蚀传统文化认同），与 identity（身份认同）构成高频「动+名」词伙。"}]},{"id":"corroborate","word":"corroborate","ipa":{"uk":"/kəˈrɒbəreɪt/","us":"/kəˈrɑːbəreɪt/"},"pos":"v.","definition":{"en":"To confirm or give support to a statement, theory, or finding, especially with independent evidence.","zh":"证实、佐证、确证（尤指通过独立证据支持某说法或理论）。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["论证与证据","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"高度正式学术、司法与科研语域；常用于描述多源独立数据、实验结果或历史文献之间的相互印证与确证","synonyms":[{"id":"substantiate","note":"substantiate 强调拿出实质证据使原本空洞的主张成立；corroborate 强调以第二份独立证据“相互印证、佐证”已有说法。"},{"id":"buttress","note":"buttress 强调像扶壁一样从外部加固论点；corroborate 强调事实或数据层面的核实印证。"},{"id":"verify","note":"verify 泛指核对真伪；corroborate 专指提供补充证据予以支持确认。"},{"id":"demonstrate","note":"demonstrate 指用证据或实例清楚证明；corroborate 指用新证据印证并加强已有结论。"}],"antonyms":[{"id":"refute","note":"反义对照：corroborate 表“支持或证实”，而 refute 表“反驳”，二者构成鲜明的语义对立。"},{"id":"belie","note":"belie 证明某表面说法是错的，与佐证属实的 corroborate 相反。"},{"id":"hypothesise","note":"corroborate 提供确凿证据证实，与尚处假说阶段的 hypothesise 相对。"}],"collocations":[{"en":"corroborate the hypothesis","zh":"佐证该科学假说"},{"en":"independently corroborated by","zh":"得到……的独立佐证"},{"en":"corroborating empirical evidence","zh":"起佐证作用的实证证据"},{"en":"corroborate a witness's testimony","zh":"佐证证人的证词"}],"examples":[{"type":"IELTS","en":"Recent satellite measurements of polar ice melt corroborate climate models that predicted accelerating sea-level rise.","zh":"近期对极地冰川融化的卫星测量结果佐证了预测海平面加速上升的气候模型。","highlights":["corroborate climate models"]},{"type":"IELTS","en":"Before sharing sensational news stories online, responsible citizens should check whether the allegations are corroborated by independent journalistic sources.","zh":"在网络上转发耸人听闻的新闻报道之前，负责任的公民应当核实相关说法是否得到了独立新闻信源的佐证。","highlights":["corroborated by independent journalistic sources"]},{"type":"GRE","en":"Archaeological excavations at the frontier outpost corroborated the chronicler's hitherto disputed account of the siege.","zh":"在该边疆哨所进行的考古发掘佐证了编年史家此前饱受争议的围城记述。","highlights":["corroborated the chronicler's"]}],"note":"【句型框架】① Empirical findings from [领域A] corroborate the hypothesis that...（来自 A 领域的实证发现佐证了……的假说）；② ensure that claims are independently corroborated by multiple sources（确保主张得到多方独立信源的佐证）。【高阶替换】confirm、verify、support 的C2级高阶学术词；与 substantiate 的精微区别在于：substantiate 侧重“为某项主张提供第一手事实证据（从无到有地证实）”，而 corroborate（cor- 共同 + robur 力量）侧重“用另一份独立的外部证据与既有说法相互印证、使其更加确凿（锦上添花地佐证）”。【避坑指南】及物动词，宾语必须是 statement, account, testimony, theory, finding 等表示“陈述或结论”的名词，绝对不能以“人”作宾语（切忌写 corroborate the witness，正确写法是 corroborate the witness's account）。","forms":["corroborates","corroborated","corroborating","corroboration","corroborative"],"partners":[{"id":"hypothesis","rel":"动+名","phrase":"corroborate the hypothesis","note":"常用搭配：corroborate the hypothesis（佐证该科学假说），与 hypothesis（假说、假设）构成高频「动+名」词伙。"},{"id":"evidence","rel":"动+名","phrase":"corroborating empirical evidence","note":"常用搭配：corroborating empirical evidence（起佐证作用的实证证据），与 evidence（证据）构成高频「动+名」词伙。"}]},{"id":"posit","word":"posit","ipa":{"uk":"/ˈpɒzɪt/","us":"/ˈpɑːzɪt/"},"pos":"v.","definition":{"en":"To put forward as fact or as a basis for argument.","zh":"提出（观点、模型或假说）；假定、断定（作为论证基础）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["论证与证据","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"高度正式学术与理论建构语域；常用于大作文引言段或主体段首句引述经济学家、社会学家或科学理论的核心假说","synonyms":[{"id":"postulate","note":"postulate 偏重数理或大型理论的前提公设；posit 简短精悍，广泛用于引述学者提出的理论观点（posit that...）。"},{"id":"hypothesise","note":"hypothesise 强调待检验性；posit 强调把某命题摆放出来作为立论出发点。"},{"id":"propose","note":"posit 侧重提出某项理论假定作为后续推理论证的起点；propose 侧重提出计划、议案或解释方案供讨论。"}],"antonyms":[{"id":"refute","note":"posit 提出命题，refute 驳倒命题。"},{"id":"debunk","note":"debunk 揭穿拆毁某理论，与建构提出命题的 posit 相对。"}],"collocations":[{"en":"posit that","zh":"提出/假定……"},{"en":"posit a direct correlation between","zh":"提出……之间存在直接关联"},{"en":"as classical economic models posit","zh":"正如古典经济学模型所假定的那样"},{"en":"posit an alternative mechanism","zh":"提出一种替代性的解释机制"}],"examples":[{"type":"IELTS","en":"Many criminologists posit that rehabilitative justice is far more effective at reducing recidivism than punitive incarceration.","zh":"许多犯罪学家提出，在降低再犯率方面，修复性司法远比惩罚性监禁有效。","highlights":["criminologists posit that"]},{"type":"IELTS","en":"Proponents of universal basic income posit a positive correlation between financial security and entrepreneurial risk-taking.","zh":"全民基本收入的支持者提出，经济安全感与创业冒险精神之间存在正相关关系。","highlights":["posit a positive correlation"]},{"type":"GRE","en":"Whereas earlier anthropologists posited a linear progression of human societies, contemporary scholars emphasise contingent historical pathways.","zh":"早期的文化人类学家假定人类社会呈线性演进，而当代学者则强调偶然的历史发展路径。","highlights":["posited a linear progression"]}],"note":"【句型框架】① Sociologists / Economists posit that + 完整从句（社会学家/经济学家提出……——完美替换老套的 Some people think that）；② posit a causal link between A and B（提出 A 与 B 之间存在因果联系）。【高阶替换】替换 think、believe、say、suggest 的C2级学术引述动词；相比 argue/contend（侧重在争论中力主己见）和 assume（日常假定，有时暗含未经证实的臆测），posit 指学者或理论模型“将某项命题作为严谨推演的逻辑起点或科学假说正式摆出来”。【避坑指南】posit 是及物动词（vt.），主语通常是学者、研究者、学派或理论模型（scholars, economists, theories, models），不宜用于普通大众的日常闲聊想法（不说 My friend posited that the movie was boring）；过去式与过去分词为 posited（单写一个 t，重音在第一音节 /ˈpɒzɪt/）。","forms":["posits","posited","positing"],"partners":[{"id":"correlation","rel":"动+名","phrase":"posit a direct correlation between","note":"常用搭配：posit a direct correlation between（提出……之间存在直接关联），与 correlation（相关性、关联）构成高频「动+名」词伙。"},{"id":"mechanism","rel":"动+名","phrase":"posit an alternative mechanism","note":"常用搭配：posit an alternative mechanism（提出一种替代性的解释机制），与 mechanism（机制、机理）构成高频「动+名」词伙。"}]},{"id":"belie","word":"belie","ipa":{"uk":"/bɪˈlaɪ/","us":"/bɪˈlaɪ/"},"pos":"v.","definition":{"en":"To fail to give a true impression of something; or to contradict or show that something cannot be true.","zh":"掩饰（真实情况）、给人以假象；证明……为假、与（表面印象）相悖。"},"libraries":["writing"],"topics":["逻辑与论证","文化与历史"],"functions":["让步转折","论证与证据"],"frequency":{"ielts":5,"gre":5},"register":"高度正式学术与GRE核心思辨语域；常用于揭示“亮眼数据或温和表象背后掩盖着残酷现实”的深层反差论证","synonyms":[{"id":"conceal","note":"当 belie 表“外表的平静掩盖了内心的焦虑”时，与 conceal / obscure 近义，但含有“表象与真相相反”的张力。"},{"id":"refute","note":"当 belie 表“残酷的现实证明了乐观预测是错的”时，与 refute / debunk 近义。"},{"id":"debunk","note":"belie 指事实本身掩盖或证明表象错误；debunk 指学者或记者主动公开揭穿谬误。"}],"antonyms":[{"id":"corroborate","note":"反义对照：belie 表“掩饰”，而 corroborate 表“支持或证实”，二者构成鲜明的语义对立。"},{"id":"demonstrate","note":"demonstrate 真实展现，belie 则制造假象或证伪。"}],"collocations":[{"en":"belie the underlying complexity","zh":"掩盖了潜在的复杂性"},{"en":"figures that belie official optimism","zh":"证明官方乐观态度不实的统计数据"},{"en":"belie the severity of the crisis","zh":"掩饰了危机的严重程度"},{"en":"apparent simplicity belies","zh":"表面上的简单掩盖了……"}],"examples":[{"type":"IELTS","en":"Impressive national GDP growth figures often belie severe regional disparities and stagnating household incomes.","zh":"亮眼的国家GDP增长数据往往掩盖了严重的地区差距和停滞不前的家庭收入。","highlights":["often belie severe regional disparities"]},{"type":"IELTS","en":"The glossy sustainability pledges issued by fast-fashion conglomerates are belied by the mounting volume of non-biodegradable textile waste in landfills.","zh":"垃圾填埋场中不断堆积的不可降解纺织废料，证明了快时尚巨头发布的华丽可持续发展承诺名不副实。","highlights":["are belied by"]},{"type":"GRE","en":"The apparent simplicity of the folk melody belies an intricate rhythmic structure that has long fascinated ethnomusicologists.","zh":"这首民谣表面上的简单掩盖了长期令民族音乐学家着迷的复杂节奏结构。","highlights":["belies an intricate rhythmic structure"]}],"note":"【句型框架】① Impressive macroeconomic indicators often belie severe structural inequalities（亮眼的宏观经济指标往往掩盖了严重的结构性不平等——经济民生类大作文满分转折句）；② The apparent simplicity of X belies its underlying complexity（X 表面的简单掩盖了其内在的复杂性）。【高阶替换】极具哲学思辨张力地替代 hide、conceal、contradict；涵盖正反两套方向一致的逻辑：一是“虚假表象 belie 残酷真相”（掩盖真相、给人假象），二是“残酷事实 belie 虚假承诺”（证明承诺为假、戳穿假象）。【避坑指南】第一，注意现在分词拼写为 belying（ie 变 y 加 ing）；第二，belie 是及物动词（vt.），直接接宾语；第三，切勿因字面含 lie 就误以为是“对某人撒谎（lie to sb）”，它的主语通常是“表象、外观、统计数据或客观事实”，而非人。","forms":["belies","belied","belying"],"partners":[{"id":"complexity","rel":"动+名","phrase":"belie the underlying complexity","note":"常用搭配：belie the underlying complexity（掩盖了潜在的复杂性），与 complexity（复杂性）构成高频「动+名」词伙。"},{"id":"optimism","rel":"动+名","phrase":"figures that belie official optimism","note":"常用搭配：figures that belie official optimism（证明官方乐观态度不实的统计数据），与 optimism（乐观态度）构成高频「动+名」词伙。"}]},{"id":"empirical","word":"empirical","ipa":{"uk":"/ɪmˈpɪrɪkl/","us":"/ɪmˈpɪrɪkl/"},"pos":"adj.","definition":{"en":"Based on, concerned with, or verifiable by observation or experience rather than pure theory or logic.","zh":"实证的、经验主义的（基于实验观测或调查数据而非纯理论推演的）。"},"libraries":["writing"],"topics":["科技与教育","逻辑与论证"],"functions":["论证与证据"],"frequency":{"ielts":5,"gre":5},"register":"正式（科研方法论与实证分析）· 学术写作超核心词汇，广泛用于教育、政策、医疗与社会议题，强调论据源于客观观测与实验数据而非空想。","synonyms":[{"id":"objective","note":"objective 强调不受主观偏见影响；empirical 强调证据来源于实际观测、实验或统计数据。"},{"id":"descriptive","note":"empirical 强调基于观察或实验数据；descriptive 强调如实描绘现状而不附加应然规定或因果推论。"},{"id":"experimental","note":"empirical 泛指基于观察、调查或实验等经验事实的；experimental 专指通过科学实验设计来进行检验的。"}],"antonyms":[{"id":"anecdotal","note":"在学术论证中，empirical evidence（实证数据）与 anecdotal evidence（个案传闻证据）构成最经典的对立。"},{"id":"theoretical","note":"学术论证核心对立：empirical 基于实验观测与经验数据，而 theoretical 基于纯理论推演或假说。"},{"id":"hypothetical","note":"反义对照：empirical 表有实证事实支撑的，而 hypothetical 表仅存于假设之中的。"}],"collocations":[{"en":"rigorous empirical research","zh":"严密的实证研究"},{"en":"corroborate with empirical evidence","zh":"用实证证据加以印证"},{"en":"subject to empirical verification","zh":"接受实证检验"},{"en":"lack empirical support","zh":"缺乏实证支持"}],"examples":[{"type":"IELTS","en":"National curriculum reforms should be grounded in rigorous empirical research into cognitive development rather than ideological preferences or passing pedagogical fads.","zh":"国家课程改革应当建立在对认知发展的严密实证研究基础之上，而非意识形态偏好或一时的教学潮流。","highlights":["rigorous empirical research"]},{"type":"IELTS","en":"Before scaling up universal basic income schemes nationwide, governments should evaluate empirical evidence gathered from municipal pilot programmes.","zh":"在全国范围内推广全民基本收入计划之前，政府应当评估从市政试点项目中收集到的实证证据。","highlights":["empirical evidence"]},{"type":"GRE","en":"Although the macroeconomist's equilibrium model was mathematically elegant and internally coherent, it lacked the empirical support needed to persuade sceptical central bankers.","zh":"尽管这位宏观经济学家的均衡模型在数学上优美且内部自洽，但它缺乏说服持怀疑态度的央行官员所需的实证支持。","highlights":["empirical support"]},{"type":"GRE","en":"Popperian philosophy of science stipulates that any hypothesis impervious to empirical verification or falsification falls outside the domain of genuine scientific inquiry.","zh":"波普尔科学哲学规定，任何无法接受实证检验或证伪的假说均不属于真正科学探究的范畴。","highlights":["empirical verification"]}],"note":"【句型框架】高频学术句式：Policies/Claims should be grounded in rigorous empirical evidence rather than ideological assumptions；或 The hypothesis lacks empirical support。【高阶替换】精准替代 data-based / observational / experimental / factual；在学术语境中，它与 theoretical（纯理论推导的）、normative（规范性/价值判断的）以及 anecdotal（零星个案传闻的）构成三大经典对立关系。【避坑指南】中国学生最易犯的望文生义错误：切勿把 empirical 译为中文日常口语里贬义的“凭老经验办事的、经验主义教条的”！在现代英语学术界，empirical 是高度褒义/中性的科学术语，专指“基于系统实验观测与统计数据的（实证的）”。","forms":["empirically","empiricism","empiricist"],"partners":[{"id":"research","rel":"形+名","phrase":"rigorous empirical research","note":"常用搭配：rigorous empirical research（严密的实证研究），与 research（研究）构成高频「形+名」词伙。"},{"id":"evidence","rel":"形+名","phrase":"corroborate with empirical evidence","note":"常用搭配：corroborate with empirical evidence（用实证证据加以印证），与 evidence（证据）构成高频「形+名」词伙。"}]},{"id":"anecdotal","word":"anecdotal","ipa":{"uk":"/ˌænɪkˈdəʊtl/","us":"/ˌænɪkˈdoʊtl/"},"pos":"adj.","definition":{"en":"Not necessarily true or reliable, because based on personal accounts or isolated stories rather than systematic facts or research.","zh":"传闻性质的、个案轶事的（基于零星个人经历而非系统科学统计的）。"},"libraries":["writing"],"topics":["逻辑与论证","健康与生活"],"functions":["论证与证据","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式（证据效力评估与驳论）· 雅思写作攻击对方“以偏概全”的王牌词汇，指出某观点仅凭身边个例或道听途说，缺乏科学统计代表性。","synonyms":[{"id":"subjective","note":"subjective 泛指主观的；anecdotal 特指论据仅靠身边几个道听途说的个例（anecdotes）支撑。"},{"id":"unreliable","note":"unreliable 泛指不可靠；anecdotal 指出不可靠的具体原因是缺乏科学抽样。"},{"id":"apocryphal","note":"常在同一语境出现；anecdotal 指属于个人趣闻轶事的，apocryphal 指该轶事本身很可能是后人杜撰的。"}],"antonyms":[{"id":"rigorous","note":"反义对照：anecdotal 表“轶话的”，而 rigorous 表“严密的”，二者构成鲜明的语义对立。"},{"id":"empirical","note":"反义对照：anecdotal 表“轶话的”，而 empirical 表“经验主义的”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"rely on merely anecdotal evidence","zh":"仅仅依赖个案传闻证据"},{"en":"purely anecdotal accounts","zh":"纯粹个案性质的叙述"},{"en":"move beyond anecdotal observations","zh":"超越零星的个案观察"},{"en":"dismiss as anecdotal","zh":"以纯属个例传闻为由不予采信"}],"examples":[{"type":"IELTS","en":"Public scepticism toward childhood vaccination is frequently fuelled by sensationalised anecdotal accounts circulating on social media rather than peer-reviewed clinical trials.","zh":"公众对儿童疫苗接种的怀疑，往往是由社交媒体上流传的耸人听闻的个案传闻所煽动的，而非基于同行评审的临床试验。","highlights":["anecdotal accounts"]},{"type":"IELTS","en":"While stories of self-taught billionaires dropping out of university are inspiring, educational policymakers must not base funding decisions on merely anecdotal evidence.","zh":"尽管亿万富翁大学辍学自学成才的故事令人鼓舞，但教育决策者绝不能把经费决策建立在纯粹的个案传闻证据之上。","highlights":["merely anecdotal evidence"]},{"type":"GRE","en":"Whereas nineteenth-century naturalists relied heavily on anecdotal reports from maritime traders, modern marine ecology demands systematic transect surveys and telemetry data.","zh":"十九世纪的博物学家高度依赖海上商人提供的零星传闻报告，而现代海洋生态学则要求系统的样带调查与遥测数据。","highlights":["anecdotal reports"]}],"note":"【句型框架】黄金对比驳论句式：Such claims rely on merely anecdotal evidence rather than systematic empirical research（此类主张仅依赖个案传闻，而非系统的实证研究）。【高阶替换】高阶替代 isolated examples / personal stories / hearsay；源自名词 anecdote（轶事、趣闻），在科学论证中作形容词时专指“基于非系统的孤立个案、样本量极小且未经统计验证的”。【避坑指南】注意不要把 anecdotal evidence 译为“有趣的故事证据”，在学术评审与雅思议论文中，它特指“个例/传闻证据”，常与 empirical / statistical / clinical evidence 形成鲜明对比，用来消解对方举例的普遍适用性。","forms":["anecdotally","anecdote"],"partners":[{"id":"evidence","rel":"形+名","phrase":"rely on merely anecdotal evidence","note":"常用搭配：rely on merely anecdotal evidence（仅仅依赖个案传闻证据），与 evidence（证据）构成高频「形+名」词伙。"},{"id":"observation","rel":"形+名","phrase":"move beyond anecdotal observations","note":"常用搭配：move beyond anecdotal observations（超越零星的个案观察），与 observation（观察）构成高频「形+名」词伙。"}]},{"id":"irrefutable","word":"irrefutable","ipa":{"uk":"/ˌɪrɪˈfjuːtəbl/","us":"/ˌɪrɪˈfjuːtəbl/"},"pos":"adj.","definition":{"en":"Impossible to deny or disprove; completely certain.","zh":"不可反驳的、驳不倒的、确凿的。"},"libraries":["writing"],"topics":["逻辑与论证"],"functions":["论证与证据","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（强力定性与科学确证）· 适用于大作文强调科学共识、流行病学铁证或严密逻辑推论，赋予论点不容置疑的权威感。","synonyms":[{"id":"incontrovertible","note":"incontrovertible 侧重无法开启争端；irrefutable 侧重任何反驳（refute）尝试都会失败。"},{"id":"unambiguous","note":"unambiguous 强调无歧义；irrefutable 强调无懈可击、无法推翻。"},{"id":"valid","note":"valid 指逻辑有效；irrefutable 指绝对不可推翻。"},{"id":"unquestionable","note":"近义辨析：二者在“不可反驳的、驳不倒的、确凿的”义项上相通；irrefutable 侧重“无可辩驳的”，unquestionable 侧重“毫无疑问的”。"}],"antonyms":[{"id":"fallacious","note":"反义对照：irrefutable 表铁证如山、无可辩驳的，而 fallacious 表推理错误、基于谬误的。"},{"id":"indefensible","note":"indefensible 指站不住脚、无法辩护的，与驳不倒的 irrefutable 相反。"}],"collocations":[{"en":"irrefutable scientific evidence","zh":"确凿无疑的科学证据"},{"en":"furnish irrefutable proof of","zh":"提供关于……的铁证"},{"en":"an irrefutable logical deduction","zh":"无懈可击的逻辑推论"},{"en":"advance an irrefutable case for","zh":"提出支持……的不可辩驳的论据"}],"examples":[{"type":"IELTS","en":"Decades of epidemiological research have furnished irrefutable proof of the link between secondhand tobacco smoke and chronic cardiovascular disease, justifying strict bans in public venues.","zh":"数十年的流行病学研究已提供二手烟与慢性心血管疾病关联的确凿铁证，使公共场所的严格禁烟令完全合理。","highlights":["furnished irrefutable proof of"]},{"type":"IELTS","en":"Rising sea levels and retreating glaciers constitute irrefutable scientific evidence that anthropogenic greenhouse gas emissions are destabilising the global climate.","zh":"海平面上升与冰川退缩构成了确凿无疑的科学证据，表明人为温室气体排放正在破坏全球气候稳定。","highlights":["irrefutable scientific evidence"]},{"type":"GRE","en":"What the scholastic philosopher presented as an irrefutable logical deduction actually rested upon an unexamined metaphysical premise that modern logicians reject.","zh":"这位经院哲学家作为无懈可击的逻辑推论所呈现的内容，实际上建立在一个现代逻辑学家所摒弃的未经审视的形而上学前提之上。","highlights":["an irrefutable logical deduction"]}],"note":"【句型框架】常与修饰证据或论证的名词搭配：There is irrefutable (scientific / empirical) evidence that...；或 X furnishes irrefutable proof of Y。【高阶替换】升级 undeniable / indisputable / certain；由否定前缀 ir-（in- 在 r 前的同化）+ 动词词根 refute（反驳、驳倒）+ -able 构成，字面即“无法被驳倒的”。【避坑指南】由于 irrefutable 语义极度绝对（100% 不可驳倒），在雅思写作中仅建议用于已获科学界公认的客观事实（如吸烟危害、气候变化、疫苗作用），切勿用于仍存广泛价值争议的社会主观议题（如死刑存废或艺术资助），否则会违反学术审慎性（Hedging）原则。","forms":["irrefutably"],"partners":[{"id":"evidence","rel":"形+名","phrase":"irrefutable scientific evidence","note":"常用搭配：irrefutable scientific evidence（确凿无疑的科学证据），与 evidence（证据）构成高频「形+名」词伙。"},{"id":"case","rel":"形+名","phrase":"advance an irrefutable case for","note":"常用搭配：advance an irrefutable case for（提出支持……的不可辩驳的论据），与 case（论据、理由）构成高频「形+名」词伙。"}]},{"id":"tenable","word":"tenable","ipa":{"uk":"/ˈtenəbl/","us":"/ˈtenəbl/"},"pos":"adj.","definition":{"en":"Able to be maintained or defended against attack or objection.","zh":"（论点、理论或立场）站得住脚的、可维持的、经得起推敲的。"},"libraries":["writing"],"topics":["逻辑与论证"],"functions":["论证与证据","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（理论存废与立场评估）· 极常用于否定或半否定结构（no longer tenable / scarcely tenable），宣告某种传统观念或政策立场已站不住脚。","synonyms":[{"id":"plausible","note":"plausible 指表面看似合理的；tenable 指在遭遇质疑和反驳时依然“守得住、站得住脚的”。"},{"id":"viable","note":"viable 侧重方案在实际操作中切实可行；tenable 侧重观点或防线在逻辑与争论中立得住。"},{"id":"sound","note":"sound 指逻辑严密稳健；tenable 指可被合理辩护的。"}],"antonyms":[{"id":"indefensible","note":"tenable 可辩护、站得住脚，indefensible 无法辩护、站不住脚。"},{"id":"tenuous","note":"注意区分形近反义词：tenable（站得住脚的）vs tenuous（单薄脆弱的、牵强的）！"},{"id":"untenable","note":"反义对照：tenable 表论点站得住脚的、可维持的，而 untenable 表逻辑破绽百出、站不住脚的。"}],"collocations":[{"en":"no longer scientifically tenable","zh":"在科学上已不再站得住脚"},{"en":"a scarcely tenable position","zh":"几乎站不住脚的立场"},{"en":"render the hypothesis scarcely tenable","zh":"使该假说几乎无法成立"},{"en":"remain politically tenable","zh":"在政治上依然维持得住"}],"examples":[{"type":"IELTS","en":"The twentieth-century assumption that perpetual industrial expansion is compatible with finite planetary boundaries is no longer scientifically tenable.","zh":"二十世纪认为无限工业扩张与有限地球生态边界相容的假设，在科学上已不再站得住脚。","highlights":["no longer scientifically tenable"]},{"type":"IELTS","en":"Expecting individual consumers to resolve systemic plastic pollution without binding corporate packaging mandates is a scarcely tenable position.","zh":"在缺乏对企业包装的强制性约束下，指望消费者个人去解决系统性的塑料污染，是一个几乎站不住脚的立场。","highlights":["a scarcely tenable position"]},{"type":"GRE","en":"Once high-precision radiometric dating pushed the settlement's origin back two millennia, the traditional diffusionist hypothesis ceased to be tenable.","zh":"一旦高精度放射性测年将该聚落的起源往前推了两千年，传统的文化传播论假说便不再站得住脚。","highlights":["ceased to be tenable"]}],"note":"【句型框架】黄金否定评估句型：The view/assumption that... is no longer (scientifically / morally / economically) tenable in light of...（鉴于……，认为……的观点在科学/道德/经济上已不再站得住脚）；或直接使用其反义词 untenable（completely untenable 完全站不住脚的）。【高阶替换】高阶替换 defensible / sustainable / justifiable；词根 ten- 意为“守住、握住（hold，同 maintain/retain）”，把论点比作需要防守的阵地，tenable 即“在反驳或事实冲击下依然守得住、经得起推敲的”。【避坑指南】GRE与雅思头号形近词陷阱：千万不要把 tenable（站得住脚的，褒义/正面）与 tenuous（薄弱的、牵强的，贬义/负面）混淆！记住：ten-able = able to be held（能守住的阵地）；tenu-ous = thin（稀薄纤细的联系）。","forms":["untenable","tenably"],"partners":[{"id":"position","rel":"形+名","phrase":"a scarcely tenable position","note":"常用搭配：a scarcely tenable position（几乎站不住脚的立场），与 position（立场、观点）构成高频「形+名」词伙。"},{"id":"hypothesis","rel":"形+名","phrase":"render the hypothesis scarcely tenable","note":"常用搭配：render the hypothesis scarcely tenable（使该假说几乎无法成立），与 hypothesis（假说）构成高频「形+名」词伙。"}]},{"id":"tenuous","word":"tenuous","ipa":{"uk":"/ˈtenjuəs/","us":"/ˈtenjuəs/"},"pos":"adj.","definition":{"en":"Very weak or slight; having little substance or strength.","zh":"（联系、证据或理由）薄弱的、牵强的、单薄的；纤细稀薄的。"},"libraries":["writing"],"topics":["逻辑与论证"],"functions":["论证与证据","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（因果解构与证据批判）· 专用于大作文驳论段质疑两个变量之间的相关性，指出其因果链条极其脆弱牵强。","synonyms":[{"id":"fragile","note":"fragile 指易碎脆弱；tenuous 特指逻辑链条、证据或关联极其单薄牵强（a tenuous link）。"},{"id":"dubious","note":"dubious 指可疑的；tenuous 指缺乏实质支撑、若有若无的。"},{"id":"exiguous","note":"近义辨析：二者在“薄弱的、牵强的、单薄的”义项上相通；tenuous 侧重“纤细的”，exiguous 侧重“太少的”。"}],"antonyms":[{"id":"robust","note":"反义对照：tenuous 表证据或联系单薄牵强的，而 robust 表稳健可靠、强有力的。"},{"id":"incontrovertible","note":"反义对照：tenuous 表证据微弱单薄的，而 incontrovertible 表确凿无疑、无可争辩的。"},{"id":"tenable","note":"反义对照：tenuous 表理由牵强脆弱的，而 tenable 表经得起推敲、站得住脚的。"}],"collocations":[{"en":"a tenuous causal link between","zh":"……之间牵强的因果联系"},{"en":"rest on tenuous empirical evidence","zh":"建立在单薄的实证证据之上"},{"en":"remain empirically tenuous at best","zh":"充其量在实证上依然十分薄弱"},{"en":"maintain a tenuous grasp on","zh":"对……仅维持脆弱的掌控"}],"examples":[{"type":"IELTS","en":"The alleged causal link between exposure to violent video games and real-world juvenile delinquency remains empirically tenuous at best.","zh":"所谓接触暴力电子游戏与现实青少年犯罪之间的因果联系，充其量在实证上仍是十分牵强的。","highlights":["empirically tenuous at best"]},{"type":"IELTS","en":"Proposals to eliminate arts education in favour of extra mathematics classes rest on tenuous evidence that creative subjects detract from quantitative attainment.","zh":"主张取消艺术教育以增加数学课时的提议，建立在“创意学科会削弱数理成绩”这一单薄牵强的证据之上。","highlights":["rest on tenuous evidence"]},{"type":"GRE","en":"Because the multilateral treaty's enforcement mechanism was so tenuous, signatory states routinely violated its maritime tariff provisions with virtual impunity.","zh":"由于该多边条约的执行机制极为薄弱，缔约国经常违反其海事关税条款而几乎不受任何惩罚。","highlights":["enforcement mechanism was so tenuous"]},{"type":"GRE","en":"The philologist's attempt to trace both dialects to a single Bronze Age inscription relies on phonological parallels too tenuous to withstand rigorous scrutiny.","zh":"这位语文学家试图将两种方言追溯至同一块青铜时代铭文的尝试，依赖了过于牵强、经不起严格审视的语音相似性。","highlights":["too tenuous to withstand"]}],"note":"【句型框架】核心批判句式：The alleged link/connection between A and B remains (empirically) tenuous at best（所谓的A与B之间的联系充其量在实证上极为牵强）；或 The argument rests on tenuous evidence（该论点建立在单薄的证据之上）。【高阶替换】完美替换 weak / flimsy / questionable / shaky；词根 tenu- 意为“薄、细（thin，同 attenuate 削弱）”，常修饰抽象的因果联系（link / connection）、证据（evidence）或控制力（hold / grasp）。【避坑指南】务必与形近词 tenable（站得住脚的）和 tenacious（顽强坚韧的）严格区分！记忆口诀：tenuous link（纤细脆弱、牵强的联系）、tenable theory（守得住、站得住脚的理论）、tenacious effort（百折不挠的顽强努力）。","forms":["tenuously","tenuousness"],"partners":[{"id":"evidence","rel":"形+名","phrase":"rest on tenuous empirical evidence","note":"常用搭配：rest on tenuous empirical evidence（建立在单薄的实证证据之上），与 evidence（证据）构成高频「形+名」词伙。"},{"id":"empirical","rel":"副+形","phrase":"remain empirically tenuous at best","note":"常用搭配：remain empirically tenuous at best（充其量在实证上依然十分薄弱），与 empirical（实证上的）构成高频「副+形」词伙。"}]},{"id":"analogous","word":"analogous","ipa":{"uk":"/əˈnæləɡəs/","us":"/əˈnæləɡəs/"},"pos":"adj.","definition":{"en":"Comparable in certain respects, typically in a way which makes clearer the nature of the things compared.","zh":"类似的、相似的、可类比的（尤指在结构或功能上具有可比性）。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["比较与对照","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（跨领域类比论证与科学比较）· 适用于大作文通过历史先例或相近行业进行类比说理，建立深刻的结构性关联。","synonyms":[{"id":"akin","note":"akin to 侧重性质或血缘气质相近；analogous to 侧重两个不同领域的事物在运行机制或逻辑结构上“可作类比”。"},{"id":"comparable","note":"近义辨析：二者在“类似”义项上相通；analogous 侧重“类似的”，comparable 侧重“可比较的”。"},{"id":"parallel","note":"近义辨析：二者在“类似”义项上相通；analogous 侧重“类似的”，parallel 侧重“平行的”。"},{"id":"similar","note":"analogous 侧重两个不同领域的事物在机制或功能上具有可比性；similar 为泛指相似的通用词。"}],"antonyms":[{"id":"antithetical","note":"analogous 结构相似可类比，antithetical 根本对立相悖。"},{"id":"incongruous","note":"incongruous 指格格不入、不相称的，与协调可类比的 analogous 相对。"},{"id":"divergent","note":"反义对照：analogous 表结构或机制相似可类比的，而 divergent 表分叉背离、截然不同的。"}],"collocations":[{"en":"closely analogous to","zh":"与……高度相似/可类比"},{"en":"function in an analogous manner","zh":"以类似的方式运作"},{"en":"draw insights from analogous historical episodes","zh":"从可类比的历史事件中汲取洞见"},{"en":"play an analogous role in","zh":"在……中扮演类似的角色"}],"examples":[{"type":"IELTS","en":"Regulating algorithm-driven social media platforms today is in many respects analogous to regulating monopolistic railway and telegraph networks in the nineteenth century.","zh":"如今监管算法驱动的社交媒体平台，在许多方面类似于十九世纪对垄断性铁路和电报网络的监管。","highlights":["analogous to regulating"]},{"type":"IELTS","en":"Mandatory digital literacy courses play a role in modern civic education closely analogous to that of basic numeracy during the industrial era.","zh":"必修数字素养课程在现代公民教育中所扮演的角色，与工业时代基础算术能力的作用高度相似。","highlights":["closely analogous to"]},{"type":"GRE","en":"Evolutionary biologists scrupulously distinguish between homologous structures inherited from a common ancestor and analogous traits arising independently through convergent evolution.","zh":"进化生物学家严谨地区分继承自共同祖先的同源结构与通过趋同进化独立演化出的同功（类似）性状。","highlights":["analogous traits"]}],"note":"【句型框架】跨学科类比论证神句：Regulating/Managing A in the digital age is in many respects analogous to regulating/managing B in the industrial era（数字时代对A的治理在诸多方面可类比于工业时代对B的治理）。【高阶替换】升级 similar to / comparable to / like；但相比泛泛而谈外观相像的 similar，analogous（源自 analogy 类比）专指两个表面属于不同领域的事物，在“内部逻辑结构、功能机制或关系模式上具有高度可比性”。【避坑指南】1. 介词铁律：be analogous to sth（这里的 to 是介词，若接动词必须用动名词 doing！切勿用 with）；2. 发音易错点：名词 analogy 中 g 发软音 /dʒ/，但形容词 analogous 中 g 必须发硬音 /ɡ/（/əˈnæləɡəs/）。","forms":["analogously","analogy","analogies"],"partners":[{"id":"manner","rel":"形+名","phrase":"function in an analogous manner","note":"常用搭配：function in an analogous manner（以类似的方式运作），与 manner（方式）构成高频「形+名」词伙。"},{"id":"role","rel":"形+名","phrase":"play an analogous role in","note":"常用搭配：play an analogous role in（在……中扮演类似的角色），与 role（角色、作用）构成高频「形+名」词伙。"}]},{"id":"tantamount","word":"tantamount","ipa":{"uk":"/ˈtæntəmaʊnt/","us":"/ˈtæntəmaʊnt/"},"pos":"adj.","definition":{"en":"Equivalent in seriousness to; virtually the same as (typically something bad).","zh":"无异于、相当于、等同于（某件严重或负面的事）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["比较与对照","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式且具强烈批判锋芒（定性负面后果）· 专用于大作文指出某种看似温和的政策、不作为或妥协，在实质效果上“无异于、等同于”某种严重恶果。","synonyms":[{"id":"synonymous","note":"近义辨析：二者在“无异于、相当于、等同于”义项上相通；tantamount 侧重“同等的”，synonymous 侧重“同义的”。"},{"id":"equivalent","note":"tantamount 专用于负面语境，表在性质或严重程度上“无异于、简直等于”（tantamount to）；equivalent 为中性词，表价值、数量或意义相等。"}],"antonyms":[{"id":"antithetical","note":"tantamount to 等同于，antithetical to 与……截然相反。"},{"id":"incongruous","note":"incongruous 不相称、不一致，与完全等价的 tantamount 相对。"}],"collocations":[{"en":"be tantamount to censorship","zh":"无异于审查制度"},{"en":"inaction is tantamount to complicity","zh":"不作为无异于同谋"},{"en":"tantamount to denying citizens' basic rights","zh":"相当于剥夺公民的基本权利"},{"en":"be considered tantamount to","zh":"被认为无异于……"}],"examples":[{"type":"IELTS","en":"Public health advocates contend that pricing life-saving pharmaceuticals beyond the reach of low-income households is tantamount to denying their fundamental right to survival.","zh":"公共卫生倡导者认为，将救命药品定价在低收入家庭承受能力之外，无异于剥夺他们基本的生存权。","highlights":["tantamount to denying"]},{"type":"IELTS","en":"In the face of irreversible ecological tipping points, delaying binding carbon reduction targets is tantamount to shifting a catastrophic debt onto future generations.","zh":"面对不可逆转的生态临界点，推迟具有约束力的减碳目标无异于将灾难性的债务转嫁给子孙后代。","highlights":["tantamount to shifting"]},{"type":"GRE","en":"Within the rigid ceremonial hierarchy of the imperial court, declining the sovereign's patronage was tantamount to a public declaration of factional defiance.","zh":"在帝国宫廷等级森严的礼仪体制内，婉拒君主的恩宠资助无异于公开宣示派系抗命。","highlights":["tantamount to a public declaration"]}],"note":"【句型框架】极具震慑力的批判句式：Doing A / Failure to do A is tantamount to + 名词 / 动名词短语（doing B）（做A／不做A在实质上无异于做B）。【高阶替换】强力升级 equal to / as bad as / virtually the same as；源自盎格鲁-诺曼语 tant amunter（amount to as much），强调虽无其名、却有其实。【避坑指南】三大必考细节：1. 语法位置：tantamount 只能作表语或后置定语（be tantamount to...），绝不能作前置定语（不能写 *a tantamount failure）；2. 介词搭配：to 是介词，后面接动词时必须用 -ing 形式（tantamount to abandoning）；3. 感情色彩：几乎清一色用于负面、消极或严重的定性（如背叛、剥夺、失败、共谋），切勿用于夸奖好事！","forms":[],"partners":[{"id":"censorship","rel":"形+名","phrase":"be tantamount to censorship","note":"常用搭配：be tantamount to censorship（无异于审查制度），与 censorship（审查制度）构成高频「形+名」词伙。"},{"id":"complicity","rel":"形+名","phrase":"inaction is tantamount to complicity","note":"常用搭配：inaction is tantamount to complicity（不作为无异于同谋），与 complicity（共谋、同谋）构成高频「形+名」词伙。"}]},{"id":"commensurate","word":"commensurate","ipa":{"uk":"/kəˈmenʃərət/","us":"/kəˈmensərət/"},"pos":"adj.","definition":{"en":"Corresponding in size or degree; in proportion.","zh":"相称的、成比例的、相匹配的（在规模、程度或报酬上相当）。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["比较与对照","利弊权衡"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（公平正义、薪酬回报与法律量刑）· 适用于大作文犯罪类（罪责刑相适应）、经济职场类（薪酬与贡献匹配）及公共投资类（收益与成本相称）。","synonyms":[{"id":"equivalent","note":"commensurate 强调成比例相称（commensurate with）；equivalent 强调二者在数值或效用上对等。"},{"id":"corresponding","note":"commensurate 侧重报酬、处罚与贡献、罪责在规模程度上按比例匹配；corresponding 侧重在位置、功能或数量上相对应。"}],"antonyms":[{"id":"disproportionate","note":"commensurate（相称的、成比例的）与 disproportionate（不成比例的、失衡的）是直接反义词对。"},{"id":"incongruous","note":"incongruous 指不协调、不相称的。"},{"id":"incommensurate","note":"反义对照：commensurate 表规模或程度相称匹配的，而 incommensurate 表不成比例、不相称的。"}],"collocations":[{"en":"penalties commensurate with the gravity of the offence","zh":"与罪行严重程度相称的处罚"},{"en":"remuneration commensurate with qualifications","zh":"与资历能力相匹配的薪酬"},{"en":"yield commensurate social benefits","zh":"产生相称的社会效益"},{"en":"bear responsibilities commensurate with one's power","zh":"承担与权力相称的责任"}],"examples":[{"type":"IELTS","en":"In an equitable criminal justice system, the severity of a custodial sentence must be strictly commensurate with the gravity of the offence and the harm inflicted on society.","zh":"在公正的刑事司法制度中，监禁刑罚的严厉程度必须与罪行的严重程度及对社会造成的伤害严格相称。","highlights":["commensurate with the gravity"]},{"type":"IELTS","en":"Multinational tech giants that extract immense profits from local digital markets should shoulder tax obligations commensurate with their economic footprint.","zh":"从本土数字市场攫取巨额利润的跨国科技巨头，应当承担与其经济足迹相称的纳税义务。","highlights":["commensurate with their economic footprint"]},{"type":"GRE","en":"Although the polar expedition entailed an astronomical fiscal outlay, the fragmentary meteorological data it recovered were scarcely commensurate with the human and financial toll.","zh":"尽管这次极地远征耗费了天文数字般的财政支出，但其收集到的零碎气象数据与所付出的人力和财力代价几乎不相称。","highlights":["scarcely commensurate with"]}],"note":"【句型框架】犯罪与公平类满分句型：The severity of X should be commensurate with the gravity/scale of Y；或作后置定语：shoulder responsibilities commensurate with their influence。【高阶替换】升级 proportional to / matching / corresponding to / in line with；由 com-（共同）+ mensura（测量 measure）构成，字面即“放在同一把尺子下衡量是匹配的”。【避坑指南】介词搭配首选 commensurate with（偶用 commensurate to，但学术写作中 with 占绝对主流）；注意区分同根词：commensurate 在日常学术写作中表示“程度或规模相称的”，而在科学哲学（库恩范式理论）中 incommensurable 则专指两个理论体系“不可通约的、缺乏共同衡量标准的”。","forms":["commensurately"],"partners":[{"id":"remuneration","rel":"形+名","phrase":"remuneration commensurate with qualifications","note":"常用搭配：remuneration commensurate with qualifications（与资历能力相匹配的薪酬），与 remuneration（报酬、薪酬）构成高频「形+名」词伙。"},{"id":"penalty","rel":"形+名","phrase":"penalties commensurate with the gravity of the offence","note":"常用搭配：penalties commensurate with the gravity of the offence（与罪行严重程度相称的处罚），与 penalty（处罚、刑罚）构成高频「形+名」词伙。"}]},{"id":"disproportionate","word":"disproportionate","ipa":{"uk":"/ˌdɪsprəˈpɔːʃənət/","us":"/ˌdɪsprəˈpɔːrʃənət/"},"pos":"adj.","definition":{"en":"Too large or too small in comparison with something else; out of proportion.","zh":"不成比例的、不相称的、偏重失衡的（过大或过小的）。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["比较与对照","社会结构"],"frequency":{"ielts":5,"gre":4},"register":"正式（社会不公、分配失衡与环境正义）· 雅思大作文揭露结构性不平等的标志性高分词，常指弱势群体承受过大冲击，或少数群体占据过多资源。","synonyms":[{"id":"unreasonable","note":"unreasonable 泛指不合理；disproportionate 强调相对于基准而言过大或过小。"},{"id":"incommensurate","note":"近义辨析：二者均表不成比例；disproportionate 侧重负担或影响偏重失衡，incommensurate 侧重与标准或付出不相称。"},{"id":"excessive","note":"disproportionate 强调相对于基准或其他群体而言比例失衡、偏大或偏小；excessive 单纯强调超出合理限度的过多。"},{"id":"lopsided","note":"disproportionate 为正式学术词，指比例严重失调；lopsided 形象地指结构或分配向一方倾斜、极不平衡。"}],"antonyms":[{"id":"egalitarian","note":"反义对照：disproportionate 表“不成比例的”，而 egalitarian 表“主张人人平等的”，二者构成鲜明的语义对立。"},{"id":"commensurate","note":"反义对照：disproportionate 表偏重失衡、不成比例的，而 commensurate 表按比例相称匹配的。"}],"collocations":[{"en":"bear a disproportionate burden","zh":"承受不成比例的沉重负担"},{"en":"exert a disproportionate influence on","zh":"对……施加不成比例的过大影响"},{"en":"allocate a disproportionate share of resources to","zh":"将不成比例的资源份额分配给……"},{"en":"have a disproportionate impact on vulnerable groups","zh":"对弱势群体产生不成比例的巨大冲击"}],"examples":[{"type":"IELTS","en":"Regressive consumption taxes on essential utilities have a disproportionate impact on low-income households, who must spend a far larger fraction of their earnings on basic survival.","zh":"对基本公用事业征收的累退性消费税对低收入家庭产生了不成比例的巨大冲击，因为他们必须将收入中大得多的比例用于基本生存。","highlights":["a disproportionate impact on"]},{"type":"IELTS","en":"Concentrating a disproportionate share of national healthcare funding in tertiary metropolitan hospitals leaves rural clinics chronically ill-equipped to manage preventable diseases.","zh":"将国家医疗经费中不成比例的巨大份额集中在都市三级大医院，导致农村诊所长期缺乏防治可预防疾病的设备。","highlights":["a disproportionate share of"]},{"type":"GRE","en":"By channelling a disproportionate share of imperial tribute into monumental frontier fortifications, the dynasty starved interior agrarian provinces of vital irrigation maintenance.","zh":"由于将帝国贡赋中不成比例的巨大份额投入宏伟的边疆防御工事，该王朝使内陆农耕省份得不到至关重要的灌溉维护资金。","highlights":["disproportionate share of imperial tribute"]}],"note":"【句型框架】社会公平与环境类万能高分句：Policy/Crisis X has a disproportionate impact on (或 disproportionately affects) vulnerable populations；或 Group A bears a disproportionate burden of B。【高阶替换】强力升级 unequal / unfair / excessive / too much；当你想表达某项政策“对穷人伤害尤其大”或“富人占了太多便宜”时，用 disproportionate / disproportionately 比简单说 unfair 客观、精准且极具经济学质感。【避坑指南】拼写虽长但构词极有规律：dis-（否定）+ pro- + portion（比例/份额）+ -ate；用作定语时常接介词 to（disproportionate to the actual risk 与实际风险不成比例）。","forms":["disproportionately"],"partners":[{"id":"burden","rel":"形+名","phrase":"bear a disproportionate burden","note":"常用搭配：bear a disproportionate burden（承受不成比例的沉重负担），与 burden（负担）构成高频「形+名」词伙。"},{"id":"impact","rel":"形+名","phrase":"have a disproportionate impact on vulnerable groups","note":"常用搭配：have a disproportionate impact on vulnerable groups（对弱势群体产生不成比例的巨大冲击），与 impact（冲击、影响）构成高频「形+名」词伙。"}]},{"id":"antithetical","word":"antithetical","ipa":{"uk":"/ˌæntɪˈθetɪkl/","us":"/ˌæntɪˈθetɪkl/"},"pos":"adj.","definition":{"en":"Directly opposed or contrasted; mutually incompatible.","zh":"根本对立的、截然相反的、背道而驰的。"},"libraries":["writing"],"topics":["逻辑与论证","文化与历史"],"functions":["让步转折","比较与对照"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（价值冲突与理念对立）· 适用于大作文批判某种商业操作、监控手段或应试机制与教育本质、民主精神或科学伦理“背道而驰、水火不容”。","synonyms":[{"id":"dichotomous","note":"dichotomous 强调一分为二、非此即彼的结构；antithetical to 强调两事物在精神或本质上水火不容、直接对立。"},{"id":"incongruous","note":"incongruous 侧重放在一起显得突兀不协调；antithetical 侧重核心原则完全相反。"},{"id":"contrary","note":"antithetical 语域极正式，强调两种理念或目标在本质上水火不容、直接对立；contrary 为通用词，指方向或观点相反。"}],"antonyms":[{"id":"analogous","note":"反义对照：antithetical 表“相反的”，而 analogous 表“类似的”，二者构成鲜明的语义对立。"},{"id":"akin","note":"反义对照：antithetical 表本质上截然对立的，而 akin 表性质近似、同类的。"},{"id":"tantamount","note":"反义对照：antithetical 表背道而驰、完全相反的，而 tantamount 表在严重程度上无异于、等同于的。"}],"collocations":[{"en":"fundamentally antithetical to","zh":"与……从根本上背道而驰"},{"en":"antithetical to the spirit of free inquiry","zh":"与自由探究精神水火不容"},{"en":"mutually antithetical ideological goals","zh":"相互对立的意识形态目标"},{"en":"prove antithetical to long-term sustainability","zh":"证明与长期可持续性背道而驰"}],"examples":[{"type":"IELTS","en":"Intrusive algorithmic surveillance of remote workers is fundamentally antithetical to a modern corporate culture predicated on professional autonomy and mutual trust.","zh":"对远程办公人员进行侵入式的算法监控，与建立在职业自主权和相互信任之上的现代企业文化从根本上是背道而驰的。","highlights":["fundamentally antithetical to"]},{"type":"IELTS","en":"Turning university education into a purely transactional credential market is antithetical to the pedagogical mission of cultivating independent critical thinkers.","zh":"将大学教育变成纯粹交易性质的文凭市场，与培养独立批判性思考者的教育使命是背道而驰的。","highlights":["antithetical to the pedagogical mission"]},{"type":"GRE","en":"For the early Romantic poets, utilitarian industrialisation was not merely aesthetically blighting but antithetical to human spiritual emancipation.","zh":"对于早期浪漫主义诗人而言，功利主义工业化不仅在美学上大煞风景，而且与人类精神解放水火不容。","highlights":["antithetical to human spiritual emancipation"]}],"note":"【句型框架】极具批判张力的句型：Practice X is (fundamentally / diametrically) antithetical to the core mission/spirit of Y；也可使用同根名词：X is the exact antithesis of Y（X恰恰是Y的对立面）。【高阶替换】升级 opposite to / contrary to / in conflict with / incompatible with；源自希腊语 anti-（反对）+ tithenai（放置 set），指两个命题或价值体系处于直接对立的两极。【避坑指南】介词搭配铁律：be antithetical to + 名词/动名词（切勿接 with 或 against！）；注意该词语气极重，仅用于指代深层理念、原则或目标的根本冲突，日常小分歧切勿滥用。","forms":["antithetically","antithesis","antitheses"],"partners":[{"id":"inquiry","rel":"形+名","phrase":"antithetical to the spirit of free inquiry","note":"常用搭配：antithetical to the spirit of free inquiry（与自由探究精神水火不容），与 inquiry（探究、探索）构成高频「形+名」词伙。"},{"id":"goal","rel":"形+名","phrase":"mutually antithetical ideological goals","note":"常用搭配：mutually antithetical ideological goals（相互对立的意识形态目标），与 goal（目标）构成高频「形+名」词伙。"}]},{"id":"dichotomous","word":"dichotomous","ipa":{"uk":"/daɪˈkɒtəməs/","us":"/daɪˈkɑːtəməs/"},"pos":"adj.","definition":{"en":"Exhibiting or characterized by a division or contrast between two things that are or are represented as being opposed or entirely different.","zh":"二分法的、两极对立的、一分为二的。"},"libraries":["writing"],"topics":["逻辑与论证"],"functions":["比较与对照","论证与证据"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（思维模式批判与分类学）· 雅思双边讨论（Discuss both views）破题大杀器，用于批评将两个可兼容的目标割裂为“非黑即白、非此即彼”的二元对立。","synonyms":[{"id":"antithetical","note":"antithetical 强调直接对抗相悖；dichotomous 强调把复杂连续体截然划分为两个互斥阵营（二元对立）。"},{"id":"incongruous","note":"incongruous 强调放在一起不协调；dichotomous 强调一分为二、彼此割裂对立。"},{"id":"contradictory","note":"近义辨析：二者均涉及对立；dichotomous 侧重将复杂事物一分为二、非黑即白，contradictory 侧重两项陈述相互矛盾。"}],"antonyms":[{"id":"homogeneous","note":"反义对照：dichotomous 表一分为二、两极分立的，而 homogeneous 表内部同质均一的。"},{"id":"holistic","note":"反义对照：dichotomous 表“二分法的、两极对立的、一分为二的”，而 holistic 表“整体的”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"reject a simplistic dichotomous view","zh":"摒弃简单化的二元对立观点"},{"en":"frame as strictly dichotomous choices","zh":"塑造成严格非此即彼的选择"},{"en":"transcend dichotomous thinking","zh":"超越非黑即白的二元思维"},{"en":"a rigid dichotomous classification","zh":"僵化的二分法分类"}],"examples":[{"type":"IELTS","en":"Framing economic prosperity and ecological conservation as strictly dichotomous choices obscures the immense potential of green industrial innovation.","zh":"将经济繁荣与生态保护塑造成严格非此即彼的选择，掩盖了绿色工业创新的巨大潜力。","highlights":["strictly dichotomous choices"]},{"type":"IELTS","en":"Educational theorists increasingly urge policymakers to transcend dichotomous thinking that pits traditional teacher-led instruction against student-centred inquiry.","zh":"教育理论家日益敦促决策者超越那种将传统教师主导教学与学生中心探究对立起来的二元思维。","highlights":["transcend dichotomous thinking"]},{"type":"GRE","en":"Contemporary social historians reject the dichotomous framework that once partitioned medieval rural society neatly into autonomous manorial lords and wholly servile peasants.","zh":"当代社会史学家摒弃了曾将中世纪乡村社会整齐切割为自主庄园领主与完全依附农奴的二元框架。","highlights":["dichotomous framework"]}],"note":"【句型框架】雅思双边讨论满分破题句式：Framing A and B as strictly dichotomous choices (或 Creating a false dichotomy between A and B) obscures how the two can be mutually reinforcing（将A与B塑造成非此即彼的选择，掩盖了二者如何能够相辅相成）。【高阶替换】升级 either-or / black-and-white / binary / polarized；词根 dicho-（一分为二）+ tom-（切割 cut，同 atom 不可再切之物）。【避坑指南】注意发音：ch 在源于希腊语的学术词中发 /k/ 音（/daɪˈkɒtəməs/），切勿读成 /tʃ/！在写作中，形容词 dichotomous 与其名词形式 a false dichotomy（伪二元对立/非黑即白谬误）交替使用，能让文章的思辨性瞬间跃升至 Band 8.5+。","forms":["dichotomy","dichotomies","dichotomously"],"partners":[{"id":"classification","rel":"形+名","phrase":"a rigid dichotomous classification","note":"常用搭配：a rigid dichotomous classification（僵化的二分法分类），与 classification（分类）构成高频「形+名」词伙。"},{"id":"transcend","rel":"动+形","phrase":"transcend dichotomous thinking","note":"常用搭配：transcend dichotomous thinking（超越非黑即白的二元思维），与 transcend（超越）构成高频「动+形」词伙。"}]},{"id":"incongruous","word":"incongruous","ipa":{"uk":"/ɪnˈkɒŋɡruəs/","us":"/ɪnˈkɑːŋɡruəs/"},"pos":"adj.","definition":{"en":"Not in harmony or keeping with the surroundings or other aspects of something.","zh":"不协调的、格格不入的、不相称的、突兀的。"},"libraries":["writing"],"topics":["文化与历史","逻辑与论证"],"functions":["比较与对照","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式（建筑美学、文化冲突与制度评估）· 适用于大作文城市规划类（古建与现代摩天楼突兀并置）或社会政策类（某项措施与时代价值观格格不入）。","synonyms":[{"id":"antithetical","note":"antithetical 强调原则上的正反对抗；incongruous 强调与周围环境、语境或其它部分搭配在一起显得怪异突兀。"},{"id":"inconsistent","note":"inconsistent 指前后矛盾或不一致；incongruous 更具美学或情境上的“违和感、格格不入”。"},{"id":"incompatible","note":"incongruous 侧重与周围环境或整体基调放在一起显得突兀违和；incompatible 侧重性质冲突而无法共存兼容。"},{"id":"inappropriate","note":"incongruous 强调情境或美学上的格格不入；inappropriate 强调不合时宜或不恰当。"}],"antonyms":[{"id":"coherent","note":"反义对照：incongruous 表“不协调的”，而 coherent 表“条理清楚的”，二者构成鲜明的语义对立。"},{"id":"compatible","note":"反义对照：incongruous 表放在一起突兀违和的，而 compatible 表可和谐共存、相互兼容的。"},{"id":"consistent","note":"反义对照：incongruous 表格格不入的，而 consistent 表协调一致的。"}],"collocations":[{"en":"appear visually incongruous with","zh":"在视觉上显得与……格格不入"},{"en":"an incongruous juxtaposition of","zh":"……的突兀并置"},{"en":"blend seemingly incongruous elements","zh":"融合看似不协调的元素"},{"en":"strike observers as incongruous","zh":"让观察者觉得突兀/不相称"}],"examples":[{"type":"IELTS","en":"Unregulated glass-and-steel skyscrapers often appear visually incongruous when erected directly adjacent to centuries-old historic civic squares.","zh":"缺乏规划监管的玻璃钢结构摩天大楼，当紧挨着拥有数百年历史的老市政广场建造时，在视觉上往往显得格格不入。","highlights":["appear visually incongruous"]},{"type":"IELTS","en":"Retaining archaic censorship laws that criminalise peaceful policy debate seems increasingly incongruous with the demands of an open knowledge society.","zh":"保留将和平政策辩论定罪的陈旧审查法律，与开放型知识社会的要求显得日益格格不入。","highlights":["incongruous with the demands"]},{"type":"GRE","en":"Contemporary musicologists no longer find the symphony's insertion of a raucous tavern dance into a solemn funeral march jarring or aesthetically incongruous.","zh":"当代音乐学家不再认为该交响曲在庄严的葬礼进行曲中插入喧闹的酒馆舞曲是刺耳的或在美学上格格不入的。","highlights":["aesthetically incongruous"]}],"note":"【句型框架】常作表语或与副词连用：appear (visually / aesthetically) incongruous with + 名词；或修饰并置关系：an incongruous mixture/juxtaposition of A and B。【高阶替换】升级 out of place / inappropriate / mismatched / discordant；与 antithetical（强调理念或目标的水火不容、针锋相对）不同，incongruous（in- 不 + congruous 协调一致的）侧重“特定事物放在某个特定环境、背景或整体中显得突兀、不搭调、画风违和”。【避坑指南】搭配介词通常用 with（incongruous with the surrounding architecture）；拼写注意词尾是 -uous（in-con-gru-ous），不要漏掉倒数第三个字母 u。","forms":["incongruously","incongruity"],"partners":[{"id":"element","rel":"形+名","phrase":"blend seemingly incongruous elements","note":"常用搭配：blend seemingly incongruous elements（融合看似不协调的元素），与 element（元素、要素）构成高频「形+名」词伙。"},{"id":"blend","rel":"动+形","phrase":"blend seemingly incongruous elements","note":"常用搭配：blend seemingly incongruous elements（融合看似不协调的元素），与 blend（融合、混合）构成高频「动+形」词伙。"}]},{"id":"juxtapose","word":"juxtapose","ipa":{"uk":"/ˌdʒʌkstəˈpəʊz/","us":"/ˌdʒʌkstəˈpoʊz/"},"pos":"v.","definition":{"en":"To place or deal with close together for contrasting effect.","zh":"把……并列、并置（以形成鲜明对比或激发思考）。"},"libraries":["writing"],"topics":["文化与历史","逻辑与论证"],"functions":["比较与对照"],"frequency":{"ielts":5,"gre":5},"register":"高度正式学术与评论动词 · 适用于雅思城市化贫富差距描写、传统与现代建筑并存讨论，以及 GRE 历史文献、文学艺术对比分析。","synonyms":[{"id":"contrast","note":"juxtapose 强调把两个截然不同的事物并排放在一起以呈现张力；contrast 强调直接对比二者的差异。"},{"id":"compare","note":"juxtapose 侧重物理或修辞上的并置呈现；compare 侧重比较异同。"}],"antonyms":[],"collocations":[{"en":"juxtapose extreme affluence with abject poverty","zh":"将极致富裕与赤贫状态并置对比"},{"en":"be starkly juxtaposed against","zh":"与……形成鲜明的并置反差"},{"en":"juxtapose competing historical narratives","zh":"将相互竞争的历史叙事并列对照"},{"en":"juxtapose traditional heritage with ultra-modern skyscrapers","zh":"将传统遗产与超现代摩天大楼并置"}],"examples":[{"type":"IELTS","en":"In many rapidly expanding metropolises, opulent commercial districts are starkly juxtaposed with informal shantytowns lacking basic sanitation.","zh":"在许多快速扩张的大都市中，奢华的商业区与缺乏基本卫生设施的非正式棚户区并置在一起，形成鲜明反差。","highlights":["starkly juxtaposed with"]},{"type":"IELTS","en":"When preservationists juxtapose historic stone facades with contemporary glass architecture, the resulting streetscape can enrich a city's aesthetic identity.","zh":"当遗产保护主义者将历史石质外立面与当代玻璃建筑并置结合时，所形成的街道景观能够丰富城市的审美特质。","highlights":["juxtapose historic stone facades with"]},{"type":"GRE","en":"By juxtaposing official court panegyrics with private merchant ledgers, the historian exposed the bleak fiscal reality behind imperial grandeur.","zh":"通过将官方宫廷颂词与私人商人账簿并置对照，这位历史学家揭露了帝国辉煌背后惨淡的财政现实。","highlights":["juxtaposing official court panegyrics with"]},{"type":"GRE","en":"The documentary filmmaker deliberately juxtaposed archival footage of industrial optimism against contemporary scenes of ecological blight to underscore the cost of unchecked extraction.","zh":"这位纪录片导演刻意将工业乐观主义时期的档案影像与当代生态凋敝的场景并置对照，以凸显无节制开采的代价。","highlights":["juxtaposed archival footage"]}],"note":"【句型框架】及物动词，标准搭配为 `juxtapose A with / and / against B`（将A与B并置对照），或被动语态 `A is starkly juxtaposed with B`。【高阶替换】降维打击 `put side by side` 或平淡的 `compare`。`compare` 只是宽泛的比较，而 `juxtapose`（词根 `juxta` 紧挨着 + `pose` 放置）专指“把两个性质迥异甚至矛盾的事物紧挨着放在一起，利用强烈视觉或逻辑反差引发深思”。【避坑指南】不要在没有“鲜明反差或对照意图”的普通并列中使用该词；其派生名词 `juxtaposition`（如 `the stark juxtaposition of wealth and squalor`）在社会类作文中同样极为惊艳。","forms":["juxtaposes","juxtaposed","juxtaposing","juxtaposition"],"partners":[{"id":"affluence","rel":"动+名","phrase":"juxtapose extreme affluence with abject poverty","note":"常用搭配：juxtapose extreme affluence with abject poverty（将极致富裕与赤贫状态并置对比），与 affluence（富裕）构成高频「动+名」词伙。"},{"id":"narrative","rel":"动+名","phrase":"juxtapose competing historical narratives","note":"常用搭配：juxtapose competing historical narratives（将相互竞争的历史叙事并列对照），与 narrative（叙事、叙述）构成高频「动+名」词伙。"}]},{"id":"reconcile","word":"reconcile","ipa":{"uk":"/ˈrekənsaɪl/","us":"/ˈrekənsaɪl/"},"pos":"v.","definition":{"en":"To make two apparently conflicting things compatible or consistent with each other; or to restore friendly relations.","zh":"调和、使协调、使一致（两个看似矛盾的目标、事实或需求）；使和解。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["让步转折","利弊权衡"],"frequency":{"ielts":5,"gre":5},"register":"正式核心学术动词 · 雅思双边讨论（Discuss both views）结尾段或让步段阐述“兼顾、调和表面矛盾的双方”时最受考官青睐的满分动词。","synonyms":[{"id":"integrate","note":"integrate 指整合并入；reconcile 特指化解两个对立面之间的冲突，使之能够共存兼容。"},{"id":"unify","note":"reconcile 侧重调和两个看似冲突的目标使其兼容共存；unify 侧重将分散的部分整合成统一整体。"}],"antonyms":[{"id":"alienate","note":"反义对照：reconcile 表“使和解”，而 alienate 表“使疏远”，二者构成鲜明的语义对立。"},{"id":"polarise","note":"reconcile 调和分歧使之兼容，polarise 激化分歧使之两极对立。"}],"collocations":[{"en":"reconcile economic growth with environmental stewardship","zh":"调和经济增长与环境治理"},{"en":"reconcile competing demands or priorities","zh":"协调相互冲突的需求或优先事项"},{"en":"difficult to reconcile with empirical data","zh":"难以与实证数据相吻合/协调"},{"en":"reconcile individual liberty with collective security","zh":"兼顾个人自由与集体安全"}],"examples":[{"type":"IELTS","en":"The central challenge of modern urban planning is how to reconcile rapid commercial development with the preservation of cultural heritage.","zh":"现代城市规划的核心挑战在于如何调和快速商业开发与文化遗产保护之间的矛盾。","highlights":["reconcile rapid commercial development with"]},{"type":"IELTS","en":"Flexible telecommuting policies enable working parents to reconcile demanding career trajectories with childcare responsibilities.","zh":"灵活的远程办公政策使职场父母能够兼顾严苛的职业发展轨迹与育儿责任。","highlights":["reconcile demanding career trajectories with"]},{"type":"GRE","en":"Cosmologists struggled for decades to reconcile the deterministic geometry of general relativity with the probabilistic framework of quantum mechanics.","zh":"宇宙学家数十年来一直在努力调和广义相对论的确定性几何结构与量子力学的概率框架。","highlights":["reconcile the deterministic geometry"]},{"type":"GRE","en":"The chronicler's assertion of unbroken agrarian prosperity is impossible to reconcile with parish registries documenting recurrent subsistence crises.","zh":"编年史作者关于农业持续繁荣的断言，根本无法与记载了周期性生存危机的教区登记册相吻合。","highlights":["impossible to reconcile with"]}],"note":"【句型框架】核心及物结构：`reconcile A with B`（调和/兼顾A与B）或 `reconcile competing / conflicting demands`（调和相互冲突的需求）。【高阶替换】在讨论“工作与生活、发展与环保、隐私与安全”等二元张力时，用 `reconcile A with B` 替换用滥了的 `balance A and B`，瞬间展现C2级学术思辨力（暗示A与B看似水火不容，但通过智慧制度得以兼容）。【避坑指南】切勿写成 `reconcile between A and B`（`reconcile` 直接接宾语A，再用 `with` 引出B）；注意区分被动用法 `be reconciled to sth`（无奈接受/顺从某苦况），在议论文中主要用 `reconcile A with B`。","forms":["reconciles","reconciled","reconciling","reconciliation","irreconcilable"],"partners":[{"id":"priority","rel":"动+名","phrase":"reconcile competing demands or priorities","note":"常用搭配：reconcile competing demands or priorities（协调相互冲突的需求或优先事项），与 priority（优先事项）构成高频「动+名」词伙。"},{"id":"liberty","rel":"动+名","phrase":"reconcile individual liberty with collective security","note":"常用搭配：reconcile individual liberty with collective security（兼顾个人自由与集体安全），与 liberty（自由、自由权）构成高频「动+名」词伙。"}]},{"id":"ostensibly","word":"ostensibly","ipa":{"uk":"/ɒˈstensəbli/","us":"/ɑːˈstensəbli/"},"pos":"adv.","definition":{"en":"Apparently or purportedly, but perhaps not actually; on the surface.","zh":"表面上、名义上、声称如此（暗示背后另有隐情或实际情况并非如此）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["让步转折","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式批判性思维副词 · 专门用于剖析政策、商业宣传或历史行为“表面宣称的崇高目的”与“背后真实动机或实际负面效果”之间的反差。","synonyms":[{"id":"purportedly","note":"purportedly 强调“据某人宣称（真伪存疑）”；ostensibly 强调“表面上打着某种旗号，实则另有目的或适得其反”。"},{"id":"apparently","note":"近义辨析：二者在“表面上”义项上相通；ostensibly 侧重“表面上”，apparently 侧重“显然”。"},{"id":"seemingly","note":"ostensibly 强调表面上打着某种堂皇旗号（暗示内里另有隐情）；seemingly 侧重外观或表面印象看似如此。"}],"antonyms":[],"collocations":[{"en":"ostensibly designed to protect consumers","zh":"表面上/名义上旨在保护消费者"},{"en":"ostensibly neutral recruitment algorithms","zh":"表面中立的招聘算法"},{"en":"an ostensibly philanthropic corporate initiative","zh":"一项表面上做慈善的企业举措"},{"en":"introduced ostensibly on national security grounds","zh":"名义上以国家安全为由而出台"}],"examples":[{"type":"IELTS","en":"Import tariffs ostensibly introduced to safeguard domestic manufacturing jobs often end up inflating living costs for low-income consumers.","zh":"名义上为保障国内制造业就业而出台的进口关税，往往最终推高了低收入消费者的生活成本。","highlights":["ostensibly introduced to safeguard"]},{"type":"IELTS","en":"Corporate greenwashing occurs when firms launch marketing campaigns that are ostensibly committed to environmental sustainability while continuing polluting practices.","zh":"当企业发起表面上致力于环境可持续发展的营销活动，实则继续污染行为时，就会发生企业“洗绿”现象。","highlights":["ostensibly committed to environmental sustainability"]},{"type":"GRE","en":"Though ostensibly a technical treatise on classical agronomy, the seventeenth-century manuscript functioned as a veiled critique of aristocratic land enclosures.","zh":"这部十七世纪的手稿虽然表面上是一部关于古典农艺学的技术专著，实则充当了对贵族圈地运动的隐晦批判。","highlights":["Though ostensibly a technical treatise"]},{"type":"GRE","en":"The commission's ostensibly impartial inquiry was fatally compromised by its reliance on testimony vetted exclusively by the incumbent administration.","zh":"该委员会表面公正的调查因其完全依赖经现任政府审查的证词而受到了致命损害。","highlights":["ostensibly impartial inquiry"]}],"note":"【句型框架】黄金批判性结构：① 修饰过去分词作后置定语：`Policies ostensibly intended / designed to do A often result in B`（名义上旨在做A的政策往往导致B）；② 修饰形容词：`ostensibly neutral / objective / benevolent`（表面中立/客观/仁慈的）。【高阶替换】精准升级 `on the surface`、`seemingly` 或 `claimed to be`。相比只描述感官表象的 `seemingly`，`ostensibly` 带有强烈的智力洞察感，暗示“主事者对外宣称或摆出某种冠冕堂皇的理由，但明眼人看得出内里并非如此”。【避坑指南】使用了 `ostensibly` 之后，后半句或下文必须跟上揭露“真实情况或相反后果”的转折内容，以形成完整的批判逻辑闭环。","forms":["ostensible"],"partners":[{"id":"protect","rel":"副+动","phrase":"ostensibly designed to protect consumers","note":"常用搭配：ostensibly designed to protect consumers（表面上/名义上旨在保护消费者），与 protect（保护）构成高频「副+动」词伙。"},{"id":"neutral","rel":"副+形","phrase":"ostensibly neutral recruitment algorithms","note":"常用搭配：ostensibly neutral recruitment algorithms（表面中立的招聘算法），与 neutral（中立的）构成高频「副+形」词伙。"}]},{"id":"paradoxically","word":"paradoxically","ipa":{"uk":"/ˌpærəˈdɒksɪkli/","us":"/ˌpærəˈdɑːksɪkli/"},"pos":"adv.","definition":{"en":"In a way that is seemingly absurd or self-contradictory, though often true in fact.","zh":"矛盾的是、吊诡的是、似非而是的是（表面看似矛盾但实际上成立）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["让步转折","因果与影响"],"frequency":{"ielts":5,"gre":5},"register":"正式学术评注副词 · 适用于雅思与GRE写作中揭示“事与愿违、适得其反或反直觉”的深刻社会与科学现象，瞬间拉满思辨深度。","synonyms":[{"id":"seemingly","note":"paradoxically 强调事态呈现出耐人寻味的反直觉悖论；seemingly 仅表表面看似。"}],"antonyms":[],"collocations":[{"en":"Paradoxically, however,","zh":"然而，吊诡的是，"},{"en":"paradoxically lead to greater insecurity","zh":"反而吊诡地导致更大的不安全感"},{"en":"paradoxically exacerbate the very problem it was meant to solve","zh":"反而吊诡地加剧了它本想解决的问题"},{"en":"Paradoxically, an abundance of choice can","zh":"似非而是的是，过多的选择反而会……"}],"examples":[{"type":"IELTS","en":"Paradoxically, social media platforms designed to connect individuals across the globe have contributed to rising levels of urban isolation and loneliness.","zh":"吊诡的是，旨在连接全球个体的社交媒体平台反而加剧了城市孤立感与孤独感的上升。","highlights":["Paradoxically, social media platforms"]},{"type":"IELTS","en":"Expanding motorway capacity to relieve traffic congestion often paradoxically induces additional private vehicle travel, leaving commuters no better off.","zh":"为缓解交通拥堵而扩建高速公路容量，往往反而吊诡地诱发了更多私家车出行，使通勤者的处境并未改善。","highlights":["paradoxically induces additional private vehicle travel"]},{"type":"GRE","en":"State attempts to suppress the heterodox pamphlet paradoxically amplified its clandestine circulation by arousing intense public curiosity.","zh":"当局查禁这本异端小册子的企图通过激起公众强烈的好奇心，反而吊诡地扩大了它的地下流传范围。","highlights":["paradoxically amplified its clandestine circulation"]},{"type":"GRE","en":"In certain autoimmune disorders, a hyperactive inflammatory response paradoxically renders the host more susceptible to opportunistic secondary infections.","zh":"在某些自身免疫性疾病中，过度活跃的炎症反应反而吊诡地使宿主更容易受到机会性继发感染的侵袭。","highlights":["paradoxically renders the host more susceptible"]}],"note":"【句型框架】可置于句首作评注性状语：`Paradoxically, [反直觉的现象].`，或置于主句谓语动词前：`Measures intended to do A often paradoxically result in B.`。【高阶替换】远超普通的 `surprisingly`、`strangely` 或 `ironically`。辨析：`ironically` 侧重戏剧性的讽刺巧合，而 `paradoxically`（源自 `paradox` 悖论）强调“表面看似自相矛盾、违背常理（如修路反而更堵、省时科技反而让人更忙），但背后存在深刻客观规律而实际上成立”。【避坑指南】如果两件事只是普通的转折而没有任何“适得其反或看似违背直觉”的张力，请用 `however` 而不要强套 `paradoxically`。","forms":["paradox","paradoxical"],"partners":[{"id":"exacerbate","rel":"副+动","phrase":"paradoxically exacerbate the very problem it was meant to solve","note":"常用搭配：paradoxically exacerbate the very problem it was meant to solve（反而吊诡地加剧了它本想解决的问题），与 exacerbate（加剧、使恶化）构成高频「副+动」词伙。"},{"id":"abundance","rel":"副+动","phrase":"Paradoxically, an abundance of choice can","note":"常用搭配：Paradoxically, an abundance of choice can（似非而是的是，过多的选择反而会……），与 abundance（大量、充裕）构成高频「副+动」词伙。"}]},{"id":"notwithstanding","word":"notwithstanding","ipa":{"uk":"/ˌnɒtwɪθˈstændɪŋ/","us":"/ˌnɑːtwɪθˈstændɪŋ/"},"pos":"adv.","definition":{"en":"Nevertheless; in spite of this; also used as a formal preposition meaning in spite of.","zh":"尽管如此、虽然这样（兼作介词“尽管……”，可前置或后置）。"},"libraries":["writing"],"topics":["逻辑与论证"],"functions":["让步转折","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"高度正式法律与学术连接词（兼作介词与副词） · 雅思大作文让步句式中替换 `despite` 或 `nevertheless` 的C2级皇冠词。","synonyms":[{"id":"nevertheless","note":"作副词时与 nevertheless 同义；但 notwithstanding 更常作介词（Notwithstanding these limitations, ...）。"},{"id":"nonetheless","note":"nonetheless 仅作副词；notwithstanding 既可前置接名词，也可放在名词短语之后（These obstacles notwithstanding）。"},{"id":"albeit","note":"albeit 为让步连词（后接形容词/短语）；notwithstanding 作介词时直接接名词短语。"}],"antonyms":[],"collocations":[{"en":"Notwithstanding these methodological limitations,","zh":"尽管存在这些方法论上的局限，"},{"en":"Notwithstanding the high initial capital outlay,","zh":"尽管初期资本投入高昂，"},{"en":"such objections notwithstanding,","zh":"尽管存在此类反对意见，"},{"en":"notwithstanding the absence of statutory mandates","zh":"尽管缺乏法定强制规定"}],"examples":[{"type":"IELTS","en":"Notwithstanding the substantial initial capital outlay, utility-scale solar infrastructure significantly reduces municipal energy expenditure over the long term.","zh":"尽管初期资本投入巨大，公用事业规模的太阳能基础设施在长期内仍能显著降低市政能源支出。","highlights":["Notwithstanding the substantial initial capital outlay"]},{"type":"IELTS","en":"Concerns over screen addiction notwithstanding, interactive digital platforms have democratised access to world-class educational resources.","zh":"尽管存在对屏幕成瘾的担忧，互动数字平台仍使世界一流教育资源的获取实现了大众化。","highlights":["Concerns over screen addiction notwithstanding"]},{"type":"GRE","en":"Occasional chronological lapses notwithstanding, the monastic chronicle remains our most reliable primary source for twelfth-century agrarian taxation.","zh":"尽管偶有年代记述上的疏漏，这部修道院编年史仍然是我们研究十二世纪农业税收最可靠的一手史料。","highlights":["Occasional chronological lapses notwithstanding"]},{"type":"GRE","en":"Notwithstanding the specimen's fragmentary preservation, paleobotanists reconstructed its vascular anatomy using high-resolution synchrotron tomography.","zh":"尽管该标本保存得支离破碎，古植物学家仍利用高分辨率同步加速器断层扫描技术重建了其维管解剖结构。","highlights":["Notwithstanding the specimen's fragmentary preservation"]}],"note":"【句型框架】三大满分用法：① 前置介词：`Notwithstanding + 名词短语, 主句.`（尽管有……）；② 后置介词（极具大师风范）：`名词短语 + notwithstanding, 主句.`；③ 独立副词：`Notwithstanding, 主句.`（尽管如此，……）。【高阶替换】直接升级 `despite`、`in spite of` 或 `nevertheless`。在雅思大作文全篇中只需在让步段首句用出一次 `Notwithstanding the high financial cost, ...`，考官立刻能识别出考生的顶尖书面语功底。【避坑指南】语法死穴：受 `in spite of` 干扰，许多考生会误写出 `notwithstanding of sth`——切记 `notwithstanding` 作介词时直接接宾语，绝对不能加 `of`！","forms":[],"partners":[{"id":"limitation","rel":"副+动","phrase":"Notwithstanding these methodological limitations,","note":"常用搭配：Notwithstanding these methodological limitations,（尽管存在这些方法论上的局限，），与 limitation（局限、限制）构成高频「副+动」词伙。"},{"id":"objection","rel":"副+动","phrase":"such objections notwithstanding,","note":"常用搭配：such objections notwithstanding,（尽管存在此类反对意见，），与 objection（反对意见、异议）构成高频「副+动」词伙。"}]},{"id":"albeit","word":"albeit","ipa":{"uk":"/ˌɔːlˈbiːɪt/","us":"/ˌɔːlˈbiːɪt/"},"pos":"adv.","definition":{"en":"Though; although (used to introduce a concessive adjective, adverb, or prepositional phrase).","zh":"尽管、虽然（用于引导形容词、副词或介词短语作补充让步说明）。"},"libraries":["writing"],"topics":["逻辑与论证"],"functions":["让步转折","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式学术让步连词/副词 · 专用于在句子内部极其紧凑地插入“让步限定成分（形容词、副词或介词短语）”，彰显高密度句法控制力。","synonyms":[{"id":"notwithstanding","note":"notwithstanding 接名词短语；albeit 专接形容词、副词、分词或介词短语（albeit slowly / albeit with caveats）。"},{"id":"nevertheless","note":"nevertheless 引导独立主句；albeit 紧跟在核心词后作凝练的让步修饰。"},{"id":"nonetheless","note":"nonetheless 为让步副词（依然）；albeit 为精炼的让步连词（尽管，后接形容词或短语）。"}],"antonyms":[],"collocations":[{"en":"albeit at a markedly slower pace","zh":"尽管速度明显较慢"},{"en":"an effective, albeit costly, intervention","zh":"一项虽成本高昂但颇具成效的干预措施"},{"en":"albeit only temporarily","zh":"尽管只是暂时的"},{"en":"accepted the reform, albeit with considerable reluctance","zh":"接受了改革，尽管颇为不情愿"}],"examples":[{"type":"IELTS","en":"Global carbon emissions from the road transport sector have begun to decline in several industrialised nations, albeit at an uneven pace.","zh":"道路交通领域的全球碳排放在几个工业化国家已开始下降，尽管步伐尚不均衡。","highlights":["albeit at an uneven pace"]},{"type":"IELTS","en":"Vocational apprenticeships offer young school-leavers a practical, albeit sometimes undervalued, pathway to stable employment.","zh":"职业学徒制为年轻的中学毕业生提供了一条实用（尽管有时被低估）的稳定就业途径。","highlights":["practical, albeit sometimes undervalued, pathway"]},{"type":"GRE","en":"The diplomatic accord established a durable, albeit fragile, equilibrium among the rival maritime republics of the eastern Mediterranean.","zh":"这项外交协定在东地中海相互竞争的海洋共和国之间建立了一种持久（尽管脆弱）的均势。","highlights":["durable, albeit fragile, equilibrium"]},{"type":"GRE","en":"Recent paleogenetic findings lend tentative support to the migration hypothesis, albeit with important caveats regarding sample contamination.","zh":"最近的古遗传学发现为迁徙假说提供了初步支持，尽管在样本污染方面带有重要的保留意见。","highlights":["albeit with important caveats"]}],"note":"【句型框架】黄金插入结构：① 嵌入两个形容词之间：`a necessary, albeit painful, reform`（一项痛苦却必要的改革）；② 置于句尾修饰主句：`..., albeit + 副词 / 介词短语`（如 `albeit slowly` / `albeit at a high cost` / `albeit to a lesser extent`）。【高阶替换】将冗长的让步状语从句 `although it is...` 浓缩为精炼的短语级构件，大幅提升学术句式的紧凑度与可读性。【避坑指南】头号语法铁律：`albeit`（古英语由 `all be it` = `although it be` 缩合而成）内部已经隐含了系动词 `be`，因此后面绝对不能接带主谓动词的完整从句（严禁写 `albeit it is expensive`，必须写 `albeit expensive`）！","forms":[],"partners":[{"id":"costly","rel":"副+形","phrase":"an effective, albeit costly, intervention","note":"常用搭配：an effective, albeit costly, intervention（一项虽成本高昂但颇具成效的干预措施），与 costly（成本高昂的）构成高频「副+形」词伙。"},{"id":"pace","rel":"副+动","phrase":"albeit at a markedly slower pace","note":"常用搭配：albeit at a markedly slower pace（尽管速度明显较慢），与 pace（速度、步调）构成高频「副+动」词伙。"}]},{"id":"hitherto","word":"hitherto","ipa":{"uk":"/ˌhɪðəˈtuː/","us":"/ˌhɪðərˈtuː/"},"pos":"adv.","definition":{"en":"Until now or until the point in time under discussion.","zh":"迄今为止、直到此时、此前一直。"},"libraries":["writing"],"topics":["文化与历史","科技与教育"],"functions":["比较与对照","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"高度正式学术与历史叙事时间副词 · 适用于雅思科技突破、医疗进步、远程教育及 GRE 考古科学文献中对比“此前一直”与“如今新局面”。","synonyms":[{"id":"formerly","note":"hitherto 侧重从过去一直延续到当前讨论节点（迄今为止）；formerly 侧重过去某个时期曾经如此（以前、从前）。"}],"antonyms":[{"id":"henceforth","note":"hitherto（迄今为止/直到此前）与 henceforth（从今往后/自此以后）是时间轴上完全对称的反义副词对！"}],"collocations":[{"en":"hitherto underserved rural communities","zh":"此前一直缺乏服务保障的农村社区"},{"en":"hitherto unknown microbial species","zh":"迄今未知的微生物物种"},{"en":"hitherto inaccessible archival records","zh":"此前无法接触到的档案记录"},{"en":"a hitherto neglected socioeconomic factor","zh":"一个此前一直被忽视的社会经济因素"}],"examples":[{"type":"IELTS","en":"Advances in satellite broadband and telemedicine have brought specialist healthcare to remote rural communities that were hitherto underserved.","zh":"卫星宽带和远程医疗的进步将专科医疗服务带到了此前一直缺乏服务保障的偏远农村社区。","highlights":["hitherto underserved"]},{"type":"IELTS","en":"Digital open-courseware allows self-taught learners to master complex subjects that were hitherto confined to elite university lecture halls.","zh":"数字化公开课件使自学者能够掌握此前仅局限于精英大学讲堂的复杂学科。","highlights":["hitherto confined to"]},{"type":"GRE","en":"By deciphering the carbonised papyrus scroll with multispectral imaging, the philologist brought to light an Epicurean commentary hitherto believed lost since antiquity.","zh":"通过利用多光谱成像技术破译这份炭化的纸莎草卷轴，这位语文学家使一部此前被认为自古失传的伊壁鸠鲁学派评注得以重见天日。","highlights":["hitherto believed lost"]},{"type":"GRE","en":"Deep-sea hydrothermal vent expeditions revealed chemosynthetic ecosystems thriving in abyssal zones hitherto assumed to be biologically barren.","zh":"深海热液喷口考察揭示了在原本被认为生物贫瘠的深海区域中蓬勃发展的化能合成生态系统。","highlights":["hitherto assumed to be"]}],"note":"【句型框架】最地道、最高频的C2级用法是置于形容词或过去分词前作前置/后置修饰语：`hitherto + [unknown / overlooked / inaccessible / unimaginable / underserved]`（此前未知的/被忽视的/无法企及的）。【高阶替换】高雅升级口语化的 `until now`、`up to this time` 或 `previously`。它专门用于烘托“某项新科技、新政策或新发现打破了过去长期存在的局限”，瞬间赋予文章学术期刊般的厚重感。【避坑指南】`hitherto` 已经包含“直到此时（until now/then）”的完整时间跨度概念，因此切勿写成 `until hitherto`；在句子中常与一般过去时或完成时搭配。","forms":[],"partners":[{"id":"inaccessible","rel":"副+形","phrase":"hitherto inaccessible archival records","note":"常用搭配：hitherto inaccessible archival records（此前无法接触到的档案记录），与 inaccessible（难以企及的、无法接触的）构成高频「副+形」词伙。"},{"id":"species","rel":"副+形","phrase":"hitherto unknown microbial species","note":"常用搭配：hitherto unknown microbial species（迄今未知的微生物物种），与 species（物种）构成高频「副+形」词伙。"}]},{"id":"henceforth","word":"henceforth","ipa":{"uk":"/ˌhensˈfɔːθ/","us":"/ˌhensˈfɔːrθ/"},"pos":"adv.","definition":{"en":"From this time on, or from that time on.","zh":"从今以后、自此以后、今后。"},"libraries":["writing"],"topics":["社会与经济","文化与历史"],"functions":["因果与影响","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"高度正式法律、制度与历史庄重副词 · 适用于雅思法规出台、政策转折描述及 GRE 历史条约、宪政改革语境。","synonyms":[{"id":"forwards","note":"henceforth 为正式公文用语，表自此以后；forwards 为普通副词，表向前或今后。"},{"id":"hence","note":"henceforth 专指从今往后、自此以后（常用于法规或声明）；hence 除表逻辑“因此”外，亦可接时间名词表“从今以后”（如 five years hence）。"}],"antonyms":[{"id":"hitherto","note":"反义对照：henceforth 表从今往后、自此以后，而 hitherto 表迄今为止、直到此前。"}],"collocations":[{"en":"shall henceforth be required to disclose","zh":"今后必须披露……"},{"en":"henceforth be held legally accountable","zh":"自此以后承担法律责任"},{"en":"henceforth known or designated as","zh":"自此被称为或指定为……"},{"en":"stipulated that henceforth all disputes would be","zh":"规定自此以后所有争端都将……"}],"examples":[{"type":"IELTS","en":"Under the newly enacted environmental statute, all large industrial manufacturers will henceforth be required to publish audited annual carbon footprints.","zh":"根据新颁布的环境法规，所有大型工业制造商今后都必须公布经审计的年度碳足迹。","highlights":["will henceforth be required to"]},{"type":"IELTS","en":"To curb juvenile cyberbullying, social media operators should henceforth be held legally accountable for failing to remove reported harassment promptly.","zh":"为了遏制青少年网络霸凌，社交媒体运营商今后若未能及时删除被举报的骚扰内容，应当承担法律责任。","highlights":["should henceforth be held legally accountable"]},{"type":"GRE","en":"The Westphalian peace treaty stipulated that territorial disputes between the signatory principalities would henceforth be adjudicated by an impartial imperial tribunal.","zh":"《威斯特伐利亚和约》规定，各缔约公国之间的领土争端自此以后将由一个公正的帝国仲裁庭裁决。","highlights":["would henceforth be adjudicated"]},{"type":"GRE","en":"Following the metrication decree of 1795, provincial guilds were informed that customary regional weights would henceforth be void in commercial contracts.","zh":"在1795年公制化法令颁布之后，各省行会被告知，习惯性的地方度量衡自此以后在商业合同中将一律无效。","highlights":["would henceforth be void"]}],"note":"【句型框架】常置于情态动词或助动词（`will / shall / should / would`）与实义动词（尤指被动语态 `be required / be prohibited / be held`）之间：`Under the new regulation, X will henceforth be required to do Y.`。【高阶替换】在涉及法律颁布、规章生效或历史分水岭的语境中，高雅替换口语化的 `from now on` 或 `starting from this time`。与前一个词形成完美的时间对称：`hitherto` 指“迄今为止/此前一直（向过去看）”，而 `henceforth` 指“自此以后/从今往后（向未来看）”。【避坑指南】该词庄重感极强，仅用于描述重大法规、制度改革或历史转折，切勿在个人日常生活小事（如“我以后每天多喝水”）中滥用。","forms":[],"partners":[{"id":"disclose","rel":"副+动","phrase":"shall henceforth be required to disclose","note":"常用搭配：shall henceforth be required to disclose（今后必须披露……），与 disclose（披露、公开）构成高频「副+动」词伙。"},{"id":"accountable","rel":"副+形","phrase":"henceforth be held legally accountable","note":"常用搭配：henceforth be held legally accountable（自此以后承担法律责任），与 accountable（负有责任的、可追责的）构成高频「副+形」词伙。"}]},{"id":"thereby","word":"thereby","ipa":{"uk":"/ˌðeəˈbaɪ/","us":"/ˌðerˈbaɪ/"},"pos":"adv.","definition":{"en":"By that means; as a result of that action.","zh":"从而、借此、由此（引出前文行动直接带来的结果，常后接现在分词）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["因果与影响","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式学术衔接副词 · 雅思大作文措施段与因果论证段中连接“具体政策手段”与“由此产生的直接积极/消极后果”的满分语法利器。","synonyms":[{"id":"consequently","note":"consequently 后接完整从句（Consequently, prices fell）；thereby 最常接现在分词作结果状语（..., thereby reducing costs）。"},{"id":"therefore","note":"therefore 为逻辑推理“因此”；thereby 意为“通过上述那个手段/途径，从而……”。"}],"antonyms":[],"collocations":[{"en":", thereby reducing carbon emissions","zh":"，从而减少碳排放"},{"en":", thereby alleviating pressure on public hospitals","zh":"，从而减轻公立医院的压力"},{"en":", thereby fostering social cohesion","zh":"，从而促进社会凝聚力"},{"en":", thereby perpetuating a cycle of poverty","zh":"，从而使贫困循环延续下去"}],"examples":[{"type":"IELTS","en":"Congestion charges discourage non-essential private car journeys into city centres, thereby reducing urban air pollution and traffic gridlock.","zh":"拥堵费能够抑制进入市中心的非必要私家车出行，从而减少城市空气污染和交通瘫痪。","highlights":["thereby reducing urban air pollution"]},{"type":"IELTS","en":"State-funded preschool programmes equip disadvantaged children with foundational literacy skills, thereby narrowing the achievement gap before primary education begins.","zh":"政府资助的学前教育项目使弱势儿童具备基础读写技能，从而在小学教育开始前缩小成绩差距。","highlights":["thereby narrowing the achievement gap"]},{"type":"GRE","en":"By standardising weights, measures, and coinage across the realm, the monarch lowered transaction costs, thereby stimulating interprovincial commerce.","zh":"通过在全国范围内统一度量衡与铸币，君主降低了交易成本，从而刺激了跨省商业贸易。","highlights":["thereby stimulating interprovincial commerce"]},{"type":"GRE","en":"The invasive shrub secretes allelopathic compounds into the rhizosphere, inhibiting mycorrhizal fungi and thereby starving native tree seedlings of essential nutrients.","zh":"这种入侵灌木向根际分泌化感化合物，抑制菌根真菌，从而使本土树苗因缺乏必需养分而枯死。","highlights":["thereby starving native tree seedlings"]}],"note":"【句型框架】雅思9分必备分词结果状语结构：`主句（主语采取某行动）, thereby + 现在分词 (doing sth)...`（例如：`Governments should subsidise public transit, thereby curbing vehicular emissions.`）。【高阶替换】彻底淘汰拖沓的 `, and as a result it can help to reduce...` 或中式英语高频错句 `, which can reduce...`。`thereby` 意为 `by that means`（借由那一手段/从而），逻辑咬合极其严密。【避坑指南】两大常见错误：① 后面误接动词原形（写成 `, thereby reduce...` 错误，无连词时必须用现在分词 `thereby reducing...`）；② 当主句是纯静态状态而非某种“行为/机制”时不宜乱用 `thereby`。","forms":[],"partners":[{"id":"alleviate","rel":"副+动","phrase":", thereby alleviating pressure on public hospitals","note":"常用搭配：, thereby alleviating pressure on public hospitals（，从而减轻公立医院的压力），与 alleviate（缓解、减轻）构成高频「副+动」词伙。"},{"id":"foster","rel":"副+动","phrase":", thereby fostering social cohesion","note":"常用搭配：, thereby fostering social cohesion（，从而促进社会凝聚力），与 foster（促进、培育）构成高频「副+动」词伙。"}]},{"id":"qualify","word":"qualify","ipa":{"uk":"/ˈkwɒlɪfaɪ/","us":"/ˈkwɑːlɪfaɪ/"},"pos":"v.","definition":{"en":"To make a statement or assertion less absolute by adding reservations; to meet the required standard.","zh":"限定，修饰（使言论不那么绝对）；取得资格。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["让步转折","论证与证据"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（学术让步与严谨界定）· GRE阅读核心熟词僻义及雅思Band 8.5+标志性动词，尤适用于在主体段或结论段对绝对化论断施加条件限制。","synonyms":[{"id":"concede","note":"在学术让步语境中相近；qualify 指通过附加条件使原观点更严谨，concede 指承认对方部分正确。"},{"id":"modify","note":"qualify 在学术论证中指通过附加条件限定笼统主张使其更严密；modify 泛指对计划、政策或表述作出修改调整。"}],"antonyms":[{"id":"substantiate","note":"反义对照：qualify 表通过附加条件限定主张、收敛绝对性，而 substantiate 表用确凿证据全面证实主张。"},{"id":"corroborate","note":"corroborate 直接强化原结论，而 qualify 则削弱其绝对性。"}],"collocations":[{"en":"qualify a sweeping assertion","zh":"限定一项笼统的断言"},{"en":"carefully qualify the conclusion","zh":"审慎地对结论加以限定"},{"en":"offer heavily qualified support for","zh":"对……提供附带诸多保留条件的支持"},{"en":"qualify one's initial optimism","zh":"修正/收敛最初的乐观态度"}],"examples":[{"type":"IELTS","en":"While vocational training demonstrably improves short-term youth employment, labour economists qualify this conclusion by noting that long-term career adaptability still requires broad foundational literacy.","zh":"尽管职业培训显著改善了短期青年就业状况，但劳动经济学家通过指出长期职业适应力仍需广泛的读写基础素养，对这一结论作了限定。","highlights":["qualify this conclusion"]},{"type":"IELTS","en":"Advocates of remote work must qualify their enthusiasm by acknowledging that digital flexibility benefits white-collar professionals far more than frontline service workers.","zh":"远程办公的倡导者必须收敛其盲目乐观，承认数字化灵活性对白领专业人士的益处远大于一线服务人员。","highlights":["qualify their enthusiasm"]},{"type":"GRE","en":"In the closing chapter, the historian carefully qualifies her initial thesis regarding mercantile decline, conceding that maritime trade networks actually expanded in several peripheral provinces.","zh":"在最后一章中，这位历史学家审慎地限定了她最初关于商业衰落的论点，承认海上贸易网络在若干边缘省份实际上有所扩张。","highlights":["carefully qualifies her initial thesis"]},{"type":"GRE","en":"The reviewer offered only heavily qualified support for the treatise, praising its archival thoroughness while dismantling its teleological assumptions.","zh":"评论者对该专著仅表达了附带诸多保留条件的肯定，在赞赏其档案考据详实的同时，驳斥了其目的论假设。","highlights":["heavily qualified support for"]}],"note":"【句型框架】高分让步限定结构：While X holds true in general, scholars qualify this claim by noting that...；或作过去分词定语：give qualified approval / heavily qualified endorsement（有保留的赞同）。【高阶替换】用于替换 limit / modify / add conditions to；相比 restrict（限制范围或自由），qualify 专指在逻辑修辞上“补充前提条件，使原本绝对的判断变得严密、温和”。【避坑指南】头号熟词僻义陷阱！在学术语境中，qualify a statement / qualified praise 绝非“使言论合格”或“有资格的称赞”，而是“限定言论、打折扣/有所保留的称赞”；切记此时它是及物动词，直接接 assertion / claim / optimism，不要加 for。","forms":["qualifies","qualified","qualifying","qualification"],"partners":[{"id":"conclusion","rel":"动+名","phrase":"carefully qualify the conclusion","note":"常用搭配：carefully qualify the conclusion（审慎地对结论加以限定），与 conclusion（结论）构成高频「动+名」词伙。"},{"id":"optimism","rel":"动+名","phrase":"qualify one's initial optimism","note":"常用搭配：qualify one's initial optimism（修正/收敛最初的乐观态度），与 optimism（乐观态度）构成高频「动+名」词伙。"}]},{"id":"quantify","word":"quantify","ipa":{"uk":"/ˈkwɒntɪfaɪ/","us":"/ˈkwɑːntɪfaɪ/"},"pos":"v.","definition":{"en":"To express or measure the quantity of something in numerical terms.","zh":"量化，用数量表示，测定……的数量。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["数量与趋势","论证与证据"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与政策评估语域；常用于教育、艺术、环保类大作文中探讨“无形社会价值能否用冰冷数据衡量”","synonyms":[{"id":"calculate","note":"quantify 侧重将原本抽象或定性的现象转化为可度量的具体数值；calculate 侧重通过数学运算推算结果。"},{"id":"assess","note":"quantify 强调精确测定数量大小；assess 强调对价值、风险或影响进行综合评估。"},{"id":"evaluate","note":"quantify 专注于数值化测量；evaluate 侧重权衡证据以评判质量或成效。"}],"antonyms":[{"id":"obscure","note":"obscure 使模糊不清，与把影响精确量化的 quantify 相反。"}],"collocations":[{"en":"difficult to quantify","zh":"难以量化"},{"en":"quantify the economic impact","zh":"量化经济影响"},{"en":"precisely quantify","zh":"精确量化"},{"en":"readily quantifiable metrics","zh":"易于量化的指标"}],"examples":[{"type":"IELTS","en":"Although the aesthetic value of urban green spaces is difficult to quantify, their contribution to public health is well documented.","zh":"尽管城市绿地的审美价值难以量化，但它们对公共健康的贡献已有充分记载。","highlights":["difficult to quantify"]},{"type":"IELTS","en":"When educational authorities evaluate schools solely through readily quantifiable metrics such as standardised test scores, teachers are pressured to neglect moral and artistic cultivation.","zh":"当教育主管部门仅凭标准化考试分数等易于量化的指标来评估学校时，教师便会迫于压力而忽视道德与艺术修养的培育。","highlights":["readily quantifiable metrics"]},{"type":"GRE","en":"Because paleoclimatologists cannot directly quantify prehistoric cloud cover, they rely on isotopic proxies preserved in marine sediments.","zh":"由于古气候学家无法直接量化史前云量，他们依赖保存在海洋沉积物中的同位素代用指标。","highlights":["directly quantify"]}],"note":"【句型框架】① Although the intangible benefits of X are difficult to quantify, ...（让步从句：虽然 X 的无形益处难以用数字量化，但其长远价值不容置疑——人文/艺术/基础科学类话题王牌句式）；② rely excessively on quantifiable metrics（过度依赖可量化指标）。【高阶替换】精准替代 measure in numbers、count、calculate；相比 measure（泛指测量大小、程度）和 gauge（侧重估计、判断民意或趋势），quantify 明确聚焦于“将事物转化为具体数字或统计指标”。【避坑指南】易混词辨析：切勿将 quantify（量化，关注数量 quantity）与 qualify（使具备资格 / 修饰限定观点，关注性质 quality）拼写或词义混淆；其派生词 quantifiable / unquantifiable 在议论文中极其实用。","forms":["quantifies","quantified","quantifying","quantifiable","quantification"],"partners":[{"id":"impact","rel":"动+名","phrase":"quantify the economic impact","note":"常用搭配：quantify the economic impact（量化经济影响），与 impact（影响、冲击）构成高频「动+名」词伙。"},{"id":"economic","rel":"动+形","phrase":"quantify the economic impact","note":"常用搭配：quantify the economic impact（量化经济影响），与 economic（经济的）构成高频「动+形」词伙。"}]},{"id":"unprecedented","word":"unprecedented","ipa":{"uk":"/ʌnˈpresɪdentɪd/","us":"/ʌnˈpresɪdentɪd/"},"pos":"adj.","definition":{"en":"Never done or known before; without previous example.","zh":"史无前例的，空前的，前所未有的。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["数量与趋势","比较与对照"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与议论文核心语域；常用于大作文引言段时代背景铺垫（如科技变革、全球化、气候危机）或主体段程度强调","synonyms":[{"id":"novel","note":"GRE 六选二高频配对：两者均表示“前所未见、新奇的”；unprecedented 语气更强，强调打破历史纪录。"},{"id":"unparalleled","note":"unprecedented 强调历史上从未有过先例；unparalleled 强调程度或成就空前绝后、无与伦比。"},{"id":"extraordinary","note":"unprecedented 侧重史无前例；extraordinary 侧重非同寻常、极其卓越或严峻。"}],"antonyms":[{"id":"conventional","note":"反义对照：unprecedented 表“前所未有的”，而 conventional 表“普通的”，二者构成鲜明的语义对立。"},{"id":"quotidian","note":"反义对照：unprecedented 表“前所未有的”，而 quotidian 表“每日的”，二者构成鲜明的语义对立。"},{"id":"hackneyed","note":"反义对照：unprecedented 表“前所未有的”，而 hackneyed 表“陈腐的”，二者构成鲜明的语义对立。"}],"collocations":[{"en":"on an unprecedented scale","zh":"以前所未有的规模"},{"en":"at an unprecedented pace","zh":"以史无前例的速度"},{"en":"face unprecedented challenges","zh":"面临前所未有的挑战"},{"en":"enjoy unprecedented access to","zh":"享有前所未有的……获取渠道"}],"examples":[{"type":"IELTS","en":"Globalisation and digital connectivity have enabled scientific collaboration on an unprecedented scale across national borders.","zh":"全球化和数字互联互通使得跨国界的科学合作达到了前所未有的规模。","highlights":["on an unprecedented scale"]},{"type":"IELTS","en":"Never before have ordinary citizens enjoyed such unprecedented access to educational resources, yet severe disparities in digital literacy persist.","zh":"普通公民从未像今天这样享有如此前所未有的教育资源获取渠道，然而数字素养方面的严重差距依然存在。","highlights":["unprecedented access to"]},{"type":"GRE","en":"Although the flood was described by local officials as unprecedented, geological core samples revealed three comparable deluges in the preceding millennium.","zh":"尽管当地官员将这次洪水描述为史无前例，但地质岩芯样本显示，在前一千年里曾发生过三次规模相当的大洪水。","highlights":["as unprecedented"]}],"note":"【句型框架】① do sth on an unprecedented scale / at an unprecedented pace（以前所未有的规模/速度做某事）；② Never before has society witnessed such unprecedented + 抽象名词（倒装句式，置于引言段首句极具震撼力）。【高阶替换】全方位升级 new、very big、never seen before 等基础表达；相比 novel（侧重性质新奇独特）和 extraordinary（侧重程度非凡），unprecedented 严格强调“历史上尚无先例可循”。【避坑指南】词根为 precedent（先例），中间是 -ced-（走），拼写切忌受 present 影响误写为 unpresented；此外该词本身已处于程度极值，前面不宜再叠加 very 或 extremely，可用 truly 或 hitherto（迄今为止）修饰。","forms":["unprecedentedly"],"partners":[{"id":"scale","rel":"形+名","phrase":"on an unprecedented scale","note":"常用搭配：on an unprecedented scale（以前所未有的规模），与 scale（规模）构成高频「形+名」词伙。"},{"id":"challenge","rel":"形+名","phrase":"face unprecedented challenges","note":"常用搭配：face unprecedented challenges（面临前所未有的挑战），与 challenge（挑战）构成高频「形+名」词伙。"}]},{"id":"safeguard","word":"safeguard","ipa":{"uk":"/ˈseɪfɡɑːd/","us":"/ˈseɪfɡɑːrd/"},"pos":"v.","definition":{"en":"To protect rights, interests, or resources from harm, loss, or infringement through active measures.","zh":"保障、捍卫、保护（权利、利益或公共资源）免受损害。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["改善与恶化","替换基础词"],"frequency":{"ielts":5,"gre":3},"register":"正式公共政策与法律语域；适用于大作文呼吁政府立法保护公民权利、文化遗产或生态安全","synonyms":[{"id":"preserve","note":"preserve 强调维持原状不被破坏；safeguard 强调通过制度或预防措施抵御潜在侵害。"},{"id":"conserve","note":"conserve 多用于节约性保护自然资源或能源；safeguard 多接权利、隐私、安全与遗产。"},{"id":"enshrine","note":"safeguard 指一般性防卫保障；enshrine 特指将原则庄严写入法典或章程予以神圣化保护。"},{"id":"secure","note":"safeguard 强调主动防卫潜在侵害；secure 强调确保某事物稳固安全、不致丧失。"}],"antonyms":[{"id":"corrode","note":"反义对照：safeguard 表周密保护、捍卫，而 corrode 表从内部恶性侵蚀、败坏。"},{"id":"undermine","note":"safeguard 巩固保护某事物，undermine 暗中侵蚀破坏。"},{"id":"deplete","note":"在资源语境中，safeguard 守护存量，deplete 耗尽存量。"}],"collocations":[{"en":"safeguard individual privacy in the digital age","zh":"在数字时代保障个人隐私"},{"en":"safeguard the interests of vulnerable groups","zh":"维护弱势群体的利益"},{"en":"safeguard ecological integrity","zh":"捍卫生态完整性"},{"en":"stringent legal and institutional safeguards","zh":"严格的法律与制度保障"}],"examples":[{"type":"IELTS","en":"Stringent data-protection legislation is essential to safeguard individual privacy as algorithmic surveillance technologies become increasingly pervasive.","zh":"随着算法监控技术日益普及，严格的数据保护立法对于保障个人隐私至关重要。","highlights":["safeguard individual privacy"]},{"type":"IELTS","en":"By establishing protected marine reserves, coastal nations can safeguard fragile coral ecosystems against overfishing and industrial runoff.","zh":"通过建立海洋保护区，沿海国家可以保护脆弱的珊瑚生态系统免受过度捕捞和工业径流的侵害。","highlights":["safeguard fragile coral ecosystems against"]},{"type":"GRE","en":"Constitutional provisions designed to safeguard judicial independence can prove hollow when judicial appointments are dominated by partisan loyalty.","zh":"当法官任命被党派忠诚所主导时，旨在保障司法独立的宪法条款可能会流于空洞。","highlights":["safeguard judicial independence"]}],"note":"【句型框架】作动词时常用 `safeguard X against/from Y`（保护 X 免受 Y 侵害）；作可数名词时常用 `introduce institutional safeguards against...`（引入防止……的制度保障）。【高阶替换】是替换高频低分词 `protect / keep safe` 的首选 Band 8+ 词汇；相比 `defend`（侧重遭遇攻击时的抗击防御）和 `preserve`（侧重维持原状不腐坏），`safeguard` 强调通过前瞻性的制度、法律或积极措施来捍卫高价值事物。【避坑指南】作名词表“保障措施”时是可数名词，常加复数 `-s`（如 `constitutional safeguards`），且后接介词 `against` 而非 `to`。","forms":["safeguards","safeguarded","safeguarding"],"partners":[{"id":"privacy","rel":"动+名","phrase":"safeguard individual privacy in the digital age","note":"常用搭配：safeguard individual privacy in the digital age（在数字时代保障个人隐私），与 privacy（隐私）构成高频「动+名」词伙。"},{"id":"integrity","rel":"动+名","phrase":"safeguard ecological integrity","note":"常用搭配：safeguard ecological integrity（捍卫生态完整性），与 integrity（完整性）构成高频「动+名」词伙。"}]},{"id":"galvanise","word":"galvanise","ipa":{"uk":"/ˈɡælvənaɪz/","us":"/ˈɡælvənaɪz/"},"pos":"v.","definition":{"en":"To shock or excite someone into taking immediate, decisive action.","zh":"激励、刺激（某人或群体）立即采取行动；使振奋。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["因果与影响","改善与恶化"],"frequency":{"ielts":5,"gre":5},"register":"正式且极具感染力的议论语域；适用于大作文呼吁段或危机应对分析（指突发事件或领导力振奋公众采取果断行动）","synonyms":[{"id":"invigorate","note":"invigorate 指注入活力与精力；galvanise 强调像通电一样突发震动并促成立即行动。"},{"id":"catalyse","note":"catalyse 强调加速变革过程，galvanise 强调唤醒原本冷漠或迟疑的人采取行动。"},{"id":"kindle","note":"都表示激发；galvanise 强调促使他人立即采取行动，kindle 侧重唤醒内心的情感。"}],"antonyms":[{"id":"enervate","note":"反义对照：galvanise 表“激励、刺激立即采取行动”，而 enervate 表“使虚弱”，二者构成鲜明的语义对立。"},{"id":"inhibit","note":"激发行动与抑制行动形成对照。"}],"collocations":[{"en":"galvanise communities into collective action","zh":"激励社区采取集体行动"},{"en":"galvanise public and legislative support for","zh":"激发公众与立法机构对……的支持"},{"en":"galvanise international efforts to combat","zh":"推动国际社会立即采取行动打击……"},{"en":"galvanise political will among policymakers","zh":"激发政策制定者的政治意愿"}],"examples":[{"type":"IELTS","en":"Visible local impacts of extreme weather events often do far more to galvanise communities into collective action than abstract global climate models.","zh":"极端天气事件在当地造成的可见影响，往往比抽象的全球气候模型更能激励社区采取集体行动。","highlights":["galvanise communities into collective action"]},{"type":"IELTS","en":"High-profile investigative journalism can galvanise political will among policymakers, compelling them to close long-standing regulatory loopholes.","zh":"引人注目的深度调查报道能够激发政策制定者的政治意愿，迫使他们堵住长期存在的监管漏洞。","highlights":["galvanise political will among policymakers"]},{"type":"GRE","en":"The publication of the epidemiological report helped galvanise legislative support for industrial safety reforms that had stalled in committee for a decade.","zh":"这份流行病学报告的发表帮助激发了对停滞十年之久的工业安全改革的立法支持。","highlights":["galvanise legislative support for"]}],"note":"【句型框架】黄金搭配为 `galvanise somebody into action / into doing something`（激起某人立即采取行动）或 `galvanise public support/political will for...`（激发对……的公众支持/政治意愿）。【高阶替换】源自电学“通电刺激肌肉收缩”，是升级 `motivate / encourage / wake up / spur` 的极具表现力的 Band 8.5+ 动词；相比温和的 `encourage`，`galvanise` 强调像通电一样让原本麻木、迟疑或冷漠的群体猛然惊醒并立刻投身行动。【避坑指南】英式拼写为 `galvanise`，美式为 `galvanize`；接人作宾语时，后面接介词短语 `into action / into doing sth` 比接不定式 `to do sth` 更地道、更符合母语者语感。","forms":["galvanize","galvanised","galvanized","galvanising"],"partners":[{"id":"community","rel":"动+名","phrase":"galvanise communities into collective action","note":"常用搭配：galvanise communities into collective action（激励社区采取集体行动），与 community（社区、群体）构成高频「动+名」词伙。"},{"id":"effort","rel":"动+名","phrase":"galvanise international efforts to combat","note":"常用搭配：galvanise international efforts to combat（推动国际社会立即采取行动打击……），与 effort（努力）构成高频「动+名」词伙。"}]},{"id":"normative","word":"normative","ipa":{"uk":"/ˈnɔːmətɪv/","us":"/ˈnɔːrmətɪv/"},"pos":"adj.","definition":{"en":"Establishing, relating to, or deriving from a standard or norm, especially regarding how things ought to be.","zh":"规范性的；建立价值标准、讨论“应当如何”的。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["论证与证据","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"高度正式（哲学、伦理、法学与公共政策）· 适用于大作文探讨科技伦理、财富分配或城市规划背后的“价值标准与应然判断”。","synonyms":[{"id":"prescriptive","note":"二者均探讨“应当如何”；normative 侧重建立道德或社会价值评判标准，prescriptive 侧重下达明确的规则指令。"},{"id":"canonical","note":"normative 强调确立行为或价值的规范准则；canonical 强调符合经典正统或权威标准。"}],"antonyms":[{"id":"empirical","note":"反义对照：normative 表“标准化的”，而 empirical 表“经验主义的”，二者构成鲜明的语义对立。"},{"id":"descriptive","note":"学术界最经典的二分法：normative（规范性：应当怎样）与 descriptive（描述性：事实上怎样）。"}],"collocations":[{"en":"establish a normative framework","zh":"建立规范性价值框架"},{"en":"involve normative judgements about","zh":"涉及关于……的规范性（价值）判断"},{"en":"challenge normative assumptions","zh":"挑战传统的规范性假设"},{"en":"exert normative pressure on","zh":"对……施加社会规范压力"}],"examples":[{"type":"IELTS","en":"Debates over autonomous vehicle algorithms involve not only technical calculations of collision probability but also normative judgements about how society ought to value human life.","zh":"关于自动驾驶汽车算法的争论不仅涉及碰撞概率的技术计算，还涉及社会应当如何珍视人的生命的规范性价值判断。","highlights":["normative judgements about"]},{"type":"IELTS","en":"Advertising campaigns that idealise affluent consumerism exert powerful normative pressure on adolescents, distorting their perception of ordinary living standards.","zh":"美化富裕消费主义的广告宣传对青少年施加了强大的社会规范压力，扭曲了他们对普通生活标准的认知。","highlights":["exert powerful normative pressure on"]},{"type":"GRE","en":"The treatise scrupulously separates empirical accounts of how credit markets actually clear from normative claims regarding how sovereign debt ought to be restructured.","zh":"该专著审慎地区分了对信贷市场实际出清方式的实证描述与关于主权债务应当如何重组的规范性主张。","highlights":["normative claims"]}],"note":"【句型框架】深度说理句型：Debates over X involve not only technical/economic calculations, but also normative judgements about how society ought to...（关于X的争论不仅涉及技术/经济计算，还涉及社会应当如何……的规范性价值判断）。【高阶替换】升级 value-based / prescriptive / moral；学术界黄金二分法：descriptive / empirical（实然的：客观描述事物“实际上是什么样 what is”）vs. normative（应然的：基于伦理或标准探讨事物“应当是什么样 what ought to be”）。【避坑指南】切勿将 normative 简单等同于 normal（普通的、正常的）！normal 指符合统计常态，而 normative 指“设立标准、涉及价值导向或道德规范的”。","forms":["normatively","normativity"],"partners":[{"id":"framework","rel":"形+名","phrase":"establish a normative framework","note":"常用搭配：establish a normative framework（建立规范性价值框架），与 framework（框架、体系）构成高频「形+名」词伙。"},{"id":"assumption","rel":"形+名","phrase":"challenge normative assumptions","note":"常用搭配：challenge normative assumptions（挑战传统的规范性假设），与 assumption（假设、假定）构成高频「形+名」词伙。"}]},{"id":"stringent","word":"stringent","ipa":{"uk":"/ˈstrɪndʒənt/","us":"/ˈstrɪndʒənt/"},"pos":"adj.","definition":{"en":"Strict, precise, and exacting regarding rules, standards, or conditions.","zh":"（法规、标准或条件）严格的、严密的、硬性的。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["替换基础词","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式政务与法规语域；常用于环保、食品安全、科技伦理及犯罪类大作文的措施段（呼吁加强监管）","synonyms":[{"id":"rigorous","note":"rigorous 侧重科研方法、推理或训练过程的严谨周密；stringent 侧重安全标准、法规或准入条件的不容通融。"},{"id":"draconian","note":"stringent 是合理必要的严格把关，draconian 则是过分严酷的苛政。"},{"id":"strict","note":"stringent 专修饰法规、标准、排放控制或准入条件严密硬性；strict 为通用词，可修饰人、纪律或规则。"},{"id":"exacting","note":"stringent 强调制度条文不留通融余地；exacting 强调工作或标准要求极高、需付出极大心力。"}],"antonyms":[{"id":"lenient","note":"反义对照：stringent 表“严格的”，而 lenient 表“宽大的”，二者构成鲜明的语义对立。"},{"id":"lax","note":"直接反义词：stringent regulations（严密监管）vs. lax oversight（松懈监管）。"},{"id":"indulgent","note":"在管束尺度上，迁就纵容与严格要求相对。"}],"collocations":[{"en":"impose stringent regulations on","zh":"对……实施严格的监管法规"},{"en":"stringent safety standards","zh":"严格的安全标准"},{"en":"stringent emissions controls","zh":"严密的排放控制措施"},{"en":"meet stringent criteria","zh":"符合严格的准入标准"}],"examples":[{"type":"IELTS","en":"Pharmaceutical products must undergo clinical trials that meet stringent safety standards before being approved for public use.","zh":"医药产品在获准供公众使用之前，必须经过符合严格安全标准的临床试验。","highlights":["stringent safety standards"]},{"type":"IELTS","en":"Only by imposing stringent regulations on industrial carbon emissions can governments compel heavy polluters to transition toward clean energy.","zh":"只有通过对工业碳排放实施严格的监管法规，政府才能迫使重污染企业向清洁能源转型。","highlights":["imposing stringent regulations on"]},{"type":"GRE","en":"Only manuscripts that satisfied the archive’s most stringent criteria for provenance were included in the definitive catalogue.","zh":"只有符合档案馆最严密来源考证标准的手稿，才被收录进这部权威目录。","highlights":["stringent criteria"]}],"note":"【句型框架】① Only by imposing stringent regulations on X can governments...（倒装句，用于大作文结尾或对策段提出政府立法措施）；② subject X to stringent scrutiny / safety standards（使 X 接受严格审查/符合严格安全标准）。【高阶替换】雅思写作替换 strict 的头号学术高分词；相比 rigorous（侧重科学方法、逻辑推导或训练过程的严谨周密）和 severe/harsh（侧重惩罚或自然环境的严酷无情），stringent 专指法律、规章、标准、检验条件“硬性、严密、不容通融”。【避坑指南】stringent 只能修饰规则、法律、标准、条件等无形制度（regulations, standards, criteria, controls），不能用来修饰人（不能写 a stringent teacher/parent，修饰人应用 strict 或 stern）。","forms":["stringently","stringency"],"partners":[{"id":"regulation","rel":"形+名","phrase":"impose stringent regulations on","note":"常用搭配：impose stringent regulations on（对……实施严格的监管法规），与 regulation（监管法规、规章）构成高频「形+名」词伙。"},{"id":"criteria","rel":"形+名","phrase":"meet stringent criteria","note":"常用搭配：meet stringent criteria（符合严格的准入标准），与 criteria（标准、准则）构成高频「形+名」词伙。"}]},{"id":"prerogative","word":"prerogative","ipa":{"uk":"/prɪˈrɒɡətɪv/","us":"/prɪˈrɑːɡətɪv/"},"pos":"n.","definition":{"en":"An exclusive right or privilege exercised by virtue of rank, office, or status.","zh":"特权；专属权利；某职位或群体的特有权限。"},"libraries":["writing"],"topics":["社会与经济","文化与历史"],"functions":["社会结构","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式宪政与社会等级名词 · 雅思教育普及、终身学习、太空探索与医疗保障话题中构造“X不再是富人/精英的专属特权”句式的点睛之笔。","synonyms":[{"id":"jurisdiction","note":"jurisdiction 指机构依法行使的司法或行政管辖权；prerogative 指某一阶层、职位或个人专享的优先特权。"},{"id":"autonomy","note":"autonomy 指自主决定权，prerogative 强调他人无权染指的专属特权（the royal / managerial prerogative）。"},{"id":"privilege","note":"prerogative 侧重特定职位、阶层或主权机构专属的排他性决定权；privilege 泛指受优待的特权或荣幸。"}],"antonyms":[{"id":"accountability","note":"不受质询的专属特权与必须接受监督问责的义务形成制度对照。"},{"id":"equity","note":"少数群体独享的特权与人人平等的公平原则相对。"}],"collocations":[{"en":"no longer the exclusive prerogative of wealthy elites","zh":"不再是富裕精英阶层的专属特权"},{"en":"exercise one's constitutional or executive prerogative","zh":"行使某人的宪政或行政特权"},{"en":"remain the sole prerogative of sovereign states","zh":"仍然是主权国家的唯一专属权限"},{"en":"jealously guard their institutional prerogatives","zh":"极力捍卫其机构特权"}],"examples":[{"type":"IELTS","en":"In a modern knowledge-based economy, university education should no longer be regarded as the exclusive prerogative of wealthy elites.","zh":"在现代知识型经济中，大学教育不应再被视为富裕精英阶层的专属特权。","highlights":["the exclusive prerogative of"]},{"type":"IELTS","en":"Thanks to budget airlines and digital booking platforms, international travel has ceased to be the sole prerogative of the affluent upper class.","zh":"得益于廉价航空公司和数字预订平台，国际旅行已不再是富裕上流阶层的唯一专利。","highlights":["the sole prerogative of"]},{"type":"GRE","en":"Seventeenth-century parliamentary reformers sought to curtail the monarch's royal prerogative to levy customs duties without legislative consent.","zh":"十七世纪的议会改革派力图削减君主在未经立法机关同意的情况下征收关税的王室特权。","highlights":["royal prerogative"]},{"type":"GRE","en":"Guild masters fiercely resisted the introduction of mechanized looms, viewing technical training as the hereditary prerogative of sworn craftsmen.","zh":"行会师傅们激烈抵制机械化织布机的引入，将技术培训视为宣誓工匠的世袭特权。","highlights":["the hereditary prerogative of"]}],"note":"【句型框架】雅思满分王牌句式：`[高等教育/国际旅行/文化艺术] is no longer the exclusive / sole prerogative of [wealthy elites / a privileged few].`（……不再是富裕精英/少数特权阶层的专属专利）。【高阶替换】高雅替换 `special right`、`monopoly` 或 `privilege`。相比普通的 `privilege`（有时仅指某种荣幸或受惠待遇），`prerogative` 强调“基于特定身份、地位或职权而独享、外人不得染指的专属特权或权限”。【避坑指南】注意拼写与发音：首音节是 `pre-`（`/prɪˈrɒɡətɪv/`），切勿受口语误导错拼成 `perogative`！","forms":["prerogatives"],"partners":[{"id":"exercise","rel":"动+名","phrase":"exercise one's constitutional or executive prerogative","note":"常用搭配：exercise one's constitutional or executive prerogative（行使某人的宪政或行政特权），与 exercise（行使、运用）构成高频「动+名」词伙。"},{"id":"exclusive","rel":"形+名","phrase":"no longer the exclusive prerogative of wealthy elites","note":"常用搭配：no longer the exclusive prerogative of wealthy elites（不再是富裕精英阶层的专属特权），与 exclusive（专属的、独享的）构成高频「形+名」词伙。"}]},{"id":"accountability","word":"accountability","ipa":{"uk":"/əˌkaʊntəˈbɪləti/","us":"/əˌkaʊntəˈbɪləti/"},"pos":"n.","definition":{"en":"The obligation of individuals or institutions to account for their actions and accept responsibility for outcomes.","zh":"问责制；责任承担；可追责性。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["社会结构","利弊权衡"],"frequency":{"ielts":5,"gre":4},"register":"正式公共管理与法律伦理核心名词 · 雅思政府监管、警察执法、医疗事故、自动驾驶与算法追责以及教育评估话题中的高频核心词。","synonyms":[{"id":"transparency","note":"transparency 指过程公开透明，accountability 指对结果承担责任并接受问责；二者常并列为 transparency and accountability。"},{"id":"responsibility","note":"accountability 侧重制度化的公开监督与出事后的可追责性；responsibility 泛指个人或机构应尽的职责与义务。"},{"id":"liability","note":"accountability 多用于公共治理与企业伦理问责；liability 多指法律或财务上的赔偿责任。"}],"antonyms":[{"id":"secrecy","note":"反义对照：accountability 表公开接受监督与问责，而 secrecy 表隐瞒保密。"},{"id":"prerogative","note":"反义对照：accountability 表必须承担责任并接受质询，而 prerogative 表不受常规干预的专属特权。"},{"id":"impunity","note":"反义对照：accountability 表有责必究的问责制，而 impunity 表违法失职却免受惩罚的逍遥法外。"}],"collocations":[{"en":"establish clear lines of accountability","zh":"建立清晰的问责界限"},{"en":"ensure corporate and environmental accountability","zh":"确保企业与环境问责"},{"en":"demand greater public accountability from officials","zh":"要求官员承担更严格的公共问责"},{"en":"mechanisms of democratic accountability","zh":"民主问责机制"}],"examples":[{"type":"IELTS","en":"Deploying autonomous vehicles on public roads requires clear lines of accountability whenever an algorithmic failure causes a traffic collision.","zh":"在公共道路上部署自动驾驶汽车，要求在算法故障引发交通碰撞时具备清晰的问责界限。","highlights":["clear lines of accountability"]},{"type":"IELTS","en":"Independent environmental watchdogs play a vital role in enforcing corporate accountability and deterring multinational firms from illegal waste dumping.","zh":"独立的环保监督机构在落实企业问责和威慑跨国公司非法倾倒废物方面发挥着至关重要的作用。","highlights":["enforcing corporate accountability"]},{"type":"GRE","en":"Decentralising budgetary authority without establishing corresponding mechanisms of accountability merely shifted fiscal patronage from national ministries to municipal boards.","zh":"下放预算权限却未建立相应的问责机制，只是把财政偏私现象从国家部委转移到了地方市政委员会。","highlights":["mechanisms of accountability"]},{"type":"GRE","en":"When regulatory agencies are staffed by former industry lobbyists, institutional accountability is frequently compromised by regulatory capture.","zh":"当监管机构由前行业游说人员担任要职时，制度性问责往往会因“监管俘获”而大打折扣。","highlights":["institutional accountability"]}],"note":"【句型框架】不可数名词，黄金搭配为 `establish / enforce / erode accountability`（建立/执行/削弱问责制）；其形容词 `accountable` 构成雅思必背句式：`hold sb accountable for sth`（追究某人对某事的责任）。【高阶替换】深度升级 `responsibility`。辨析：`responsibility` 侧重事前或事中“主观承担的职责义务”，而 `accountability`（词根 `account` 账目/交代）强调制度层面的“事后可追责性——必须向公众或监管方作出解释，若出问题须承受惩罚后果”。【避坑指南】英文中几乎没有动词 `accountabilise`，要表达“向……问责”请直接用动词短语 `hold [corporations / officials] accountable for...`。","forms":["accountable"],"partners":[{"id":"mechanism","rel":"名+名","phrase":"mechanisms of democratic accountability","note":"常用搭配：mechanisms of democratic accountability（民主问责机制），与 mechanism（机制）构成高频「名+名」词伙。"},{"id":"ensure","rel":"动+名","phrase":"ensure corporate and environmental accountability","note":"常用搭配：ensure corporate and environmental accountability（确保企业与环境问责），与 ensure（确保、保证）构成高频「动+名」词伙。"}]},{"id":"supersede","word":"supersede","ipa":{"uk":"/ˌsuːpə'siːd/","us":"/,supɚ'sid/"},"pos":"v.","definition":{"en":"To take the place of something or someone that has become old-fashioned, less effective, or obsolete.","zh":"取代；接替；因更先进有效而淘汰（旧技术、旧制度或旧观念）。"},"libraries":["writing"],"topics":["科技与教育","文化与历史"],"functions":["比较与对照","因果与影响"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与科技史动词 · 雅思讨论“数字媒体是否会取代纸质书、AI是否会取代人工、清洁能源取代化石燃料”时的首选高阶动词。","synonyms":[{"id":"displace","note":"supersede 侧重因更先进、更有效而淘汰取代旧技术或旧法规；displace 侧重挤占原有位置或迫使人群迁离。"},{"id":"supplant","note":"supersede 强调自然演进中的升级换代；supplant 强调通过竞争或排挤取而代之。"},{"id":"replace","note":"supersede 为正式书面词，隐含新事物优于旧事物；replace 为中性通用词。"}],"antonyms":[{"id":"preserve","note":"反义对照：supersede 表淘汰并取代旧事物，而 preserve 表保存并延续既有事物。"}],"collocations":[{"en":"be largely superseded by digital alternatives","zh":"在很大程度上被数字化替代方案所取代"},{"en":"supersede outdated regulatory frameworks","zh":"取代过时的监管框架"},{"en":"gradually supersede internal combustion engines","zh":"逐步取代内燃机"},{"en":"supersede prior bilateral treaties","zh":"取代先前的双边条约"}],"examples":[{"type":"IELTS","en":"Although streaming platforms and e-books have largely superseded physical media, public libraries retain an irreplaceable role as inclusive community hubs.","zh":"尽管流媒体平台和电子书已在很大程度上取代了实体媒介，但公共图书馆作为包容性社区中心仍保留着不可替代的作用。","highlights":["largely superseded physical media"]},{"type":"IELTS","en":"While artificial intelligence can automate routine diagnostic tasks, it is unlikely to completely supersede human physicians whose empathy is vital to patient care.","zh":"虽然人工智能可以自动化常规诊断任务，但它不太可能完全取代人类医生，因为医生的共情能力对患者护理至关重要。","highlights":["completely supersede human physicians"]},{"type":"GRE","en":"In the history of scientific inquiry, even long-standing explanatory paradigms are eventually superseded when more comprehensive theoretical models account for persistent anomalies.","zh":"在科学探索史上，当更具包容力的理论模型能够解释长期存在的反常现象时，即便是由来已久的解释范式最终也会被取代。","highlights":["eventually superseded"]},{"type":"GRE","en":"The newly ratified constitutional charter explicitly superseded the patchwork of feudal privileges that had governed provincial taxation for three centuries.","zh":"新批准的宪政宪章明确取代了三个世纪以来管辖行省税收的零碎封建特权。","highlights":["explicitly superseded"]}],"note":"【句型框架】及物动词，主动形式 `New technology A supersedes old method B`，被动形式更为常见：`Old method B has been largely superseded by A`（旧方式B已在很大程度上被A取代）。【高阶替换】全方位升级用滥了的 `replace`。相比普通中性的 `replace`（任何替换均可），`supersede` 蕴含着“因为新事物更先进、更高效或更具合法性，从而将已经过时落伍（`obsolete`）的旧事物淘汰接替”的进化感。【避坑指南】拼写极易出错！词根来自拉丁语 `sedere`（坐：`super` 在上面 + `sede` 坐 -> 坐到旧事物的位置上），中部是 `-sede` 而非 `-cede`，切勿错拼为 `supercede`！","forms":["superseded","supersedes","superseding","supersession","supersedure"],"partners":[{"id":"framework","rel":"动+名","phrase":"supersede outdated regulatory frameworks","note":"常用搭配：supersede outdated regulatory frameworks（取代过时的监管框架），与 framework（框架、体系）构成高频「动+名」词伙。"},{"id":"treaty","rel":"动+名","phrase":"supersede prior bilateral treaties","note":"常用搭配：supersede prior bilateral treaties（取代先前的双边条约），与 treaty（条约、协定）构成高频「动+名」词伙。"}]},{"id":"transcend","word":"transcend","ipa":{"uk":"/træn'send/","us":"/træn'sɛnd/"},"pos":"v.","definition":{"en":"To go beyond the usual limits of national, cultural, or ideological boundaries.","zh":"超越（国界、文化隔阂、个人局限或时代限制）。"},"libraries":["writing"],"topics":["文化与历史","社会与经济"],"functions":["比较与对照","观点评价"],"frequency":{"ielts":5,"gre":4},"register":"正式人文与全球治理高阶动词 · 适用于雅思文化艺术价值（跨越语言与国界）、跨国环境合作（超越短期地缘私利）及 GRE 哲学美学论述。","synonyms":[{"id":"surpass","note":"transcend 侧重超越国界、文化隔阂或狭隘私利等限制；surpass 侧重在表现、数量或程度上胜过他人。"},{"id":"exceed","note":"transcend 强调突破某种概念或制度边界；exceed 强调数值或规模超出限额。"},{"id":"outdo","note":"transcend 侧重超越抽象界限或局限；outdo 侧重在具体表现或竞争中胜过对手。"}],"antonyms":[],"collocations":[{"en":"transcend national and linguistic boundaries","zh":"超越国界与语言障碍"},{"en":"transcend cultural and ideological divides","zh":"跨越文化与意识形态鸿沟"},{"en":"transcend narrow short-term self-interest","zh":"超越狭隘的短期个人/国家私利"},{"en":"possess an enduring appeal that transcends time","zh":"拥有超越时代的恒久魅力"}],"examples":[{"type":"IELTS","en":"Music and visual art possess a unique capacity to transcend linguistic boundaries and cultivate empathy among people from vastly different cultural backgrounds.","zh":"音乐与视觉艺术拥有一种超越语言界限、在文化背景迥异的人们之间培育共情的独特力量。","highlights":["transcend linguistic boundaries"]},{"type":"IELTS","en":"Confronting ecological crises requires international treaties that transcend narrow national self-interest in favour of planetary survival.","zh":"应对生态危机需要超越狭隘国家私利、以地球生存为重的国际条约。","highlights":["transcend narrow national self-interest"]},{"type":"GRE","en":"Addressing global pandemic risks demands diplomatic architectures capable of transcending partisan rivalries and immediate geopolitical calculations.","zh":"应对全球大流行病风险需要能够超越党派竞争与眼前地缘政治算计的外交架构。","highlights":["transcending partisan rivalries"]},{"type":"GRE","en":"Far from being a mere regional chronicler, the novelist crafted allegorical narratives that transcended their provincial setting to interrogate universal moral dilemmas.","zh":"这位小说家远非仅仅是一名地方编年史作者，他创作的寓言叙事超越了其地方背景，对普世的道德困境进行了叩问。","highlights":["transcended their provincial setting"]}],"note":"【句型框架】及物动词，黄金结构为 `transcend [boundaries / barriers / divides / limitations / self-interest]`（超越国界/障碍/分歧/局限/私利）。【高阶替换】高雅替换 `go beyond`、`cross` 或 `overcome`。相比侧重空间跨越的 `cross` 或侧重客服困难的 `overcome`，`transcend`（`trans` 跨越 + `scend` 攀登）带有一种“升华至更高精神或全局维度，不再受原有狭隘框架束缚”的庄重美感。【避坑指南】`transcend` 本身就是及物动词（已含 `beyond` 之义），后面直接跟名词作宾语，切勿画蛇添足写成 `transcend beyond boundaries`！","forms":["transcends","transcended","transcending","transcendental","transcendent"],"partners":[{"id":"boundary","rel":"动+名","phrase":"transcend national and linguistic boundaries","note":"常用搭配：transcend national and linguistic boundaries（超越国界与语言障碍），与 boundary（界限、国界）构成高频「动+名」词伙。"},{"id":"partisanship","rel":"动+名","phrase":"transcend narrow partisanship","note":"常用搭配：transcend narrow partisanship（超越狭隘的派系成见），与 partisanship（党派偏见）构成高频「动+名」词伙。"}]},{"id":"discrepancy","word":"discrepancy","ipa":{"uk":"/dɪs'krepənsi/","us":"/dɪs'krɛpənsi/"},"pos":"n.","definition":{"en":"A significant difference or inconsistency between two things that should be the same, such as rhetoric and reality.","zh":"差异；不一致；不符（尤指承诺与现实、两组数据或理论与实践之间的落差）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["比较与对照","论证与证据"],"frequency":{"ielts":5,"gre":5},"register":"正式学术名词 · 常用于揭示“政策承诺与实际执行、官方统计与真实民生、主观自述与客观证据”之间的反差与出入。","synonyms":[{"id":"incongruity","note":"discrepancy 侧重两组数据、账目或言行之间本应一致却出现的明显出入；incongruity 侧重事物搭配在一起时的不协调感。"},{"id":"difference","note":"discrepancy 强调不合常理或有待解释的落差；difference 为表差异的通用词。"},{"id":"contradiction","note":"discrepancy 指存在偏差不符；contradiction 指逻辑或立场上直接相互矛盾。"}],"antonyms":[{"id":"accord","note":"反义对照：discrepancy 表数据或言行之间的落差与不符，而 accord 表完全吻合一致。"}],"collocations":[{"en":"a stark discrepancy between rhetoric and reality","zh":"口号修辞与现实状况之间的鲜明落差"},{"en":"account for the discrepancy between","zh":"解释……之间存在差异/出入的原因"},{"en":"a wide discrepancy between self-reported and actual behaviour","zh":"自我报告行为与实际行为之间的巨大出入"},{"en":"reveal a troubling discrepancy in","zh":"揭示出在……方面令人不安的不一致"}],"examples":[{"type":"IELTS","en":"Public cynicism deepens when citizens observe a stark discrepancy between corporate sustainability pledges and actual industrial emissions.","zh":"当公民观察到企业可持续发展承诺与实际工业排放之间存在巨大落差时，公众的愤世嫉俗情绪便会加深。","highlights":["a stark discrepancy between"]},{"type":"IELTS","en":"Curriculum reformers must address the growing discrepancy between the theoretical knowledge taught in universities and the practical competencies demanded by employers.","zh":"课程改革者必须解决大学教授的理论知识与雇主所需的实践能力之间日益拉大的脱节。","highlights":["the growing discrepancy between"]},{"type":"GRE","en":"The pronounced discrepancy between self-reported dietary intake and objective metabolic biomarkers underscores the methodological pitfalls of survey-based nutrition research.","zh":"自我报告的膳食摄入量与客观代谢生物标志物之间的显著不符，凸显了基于问卷调查的营养学研究在方法论上的缺陷。","highlights":["pronounced discrepancy between"]},{"type":"GRE","en":"Auditors investigating the colonial customs house uncovered systematic discrepancies between the tonnage recorded at embarkation and the duties remitted to the treasury.","zh":"调查殖民地海关的审计人员发现了装船时记录的吨位与上缴国库的关税之间存在系统性的出入。","highlights":["systematic discrepancies between"]}],"note":"【句型框架】常用 `there is a stark / wide / glaring discrepancy between A and B`（在A与B之间存在显著出入/落差），或 `account for the discrepancy in...`（解释……中的偏差）。【高阶替换】精准替换 `difference` 或 `gap`。辨析：与同组高频词 `disparity`（侧重贫富、城乡、阶层之间不公平的“悬殊差距”）不同，`discrepancy` 的核心语义是“本应一致、相符或匹配的双方（如账目与实数、言论与行动、理论与现实）出现了不吻合或矛盾”。【避坑指南】描述贫富差距时优先用 `income disparity`，而描述言行不一、学用脱节或数据矛盾时用 `discrepancy`，切勿混用。","forms":["discrepancies","discrepant"],"partners":[{"id":"stark","rel":"形+名","phrase":"a stark discrepancy between rhetoric and reality","note":"常用搭配：a stark discrepancy between rhetoric and reality（口号修辞与现实状况之间的鲜明落差），与 stark（鲜明的、明显的）构成高频「形+名」词伙。"},{"id":"reveal","rel":"动+名","phrase":"reveal a troubling discrepancy in","note":"常用搭配：reveal a troubling discrepancy in（揭示出在……方面令人不安的不一致），与 reveal（揭示、揭露）构成高频「动+名」词伙。"}]},{"id":"disseminate","word":"disseminate","ipa":{"uk":"/dɪ'semɪneɪt/","us":"/dɪ'sɛmɪnet/"},"pos":"v.","definition":{"en":"To spread information, knowledge, or research findings widely to the public.","zh":"传播、普及、散布（科学知识、学术成果或公共信息）。"},"libraries":["writing"],"topics":["科技与教育","社会与经济"],"functions":["因果与影响","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与传媒核心动词 · 适用于雅思新闻媒体、互联网科技、大学科研职能与公共卫生宣传类大作文中替代 `spread information`。","synonyms":[{"id":"distribute","note":"近义辨析：二者在“散布”义项上相通；disseminate 侧重“散布”，distribute 侧重“分发”。"},{"id":"transmit","note":"近义辨析：二者在“传播”义项上相通；disseminate 侧重“散布”，transmit 侧重“传送”。"},{"id":"propagate","note":"disseminate 侧重广泛传播科学知识、研究成果或公共信息；propagate 侧重宣传普及某种宗教、意识形态或理论。"},{"id":"circulate","note":"disseminate 强调由中心向公众全方位播撒知识；circulate 强调信息或刊物在人群中流传。"}],"antonyms":[{"id":"conceal","note":"反义对照：disseminate 表向公众广泛传播信息，而 conceal 表隐瞒、封锁信息。"},{"id":"suppress","note":"反义对照：disseminate 表普及散播知识，而 suppress 表查禁、压制信息使其不得流传。"}],"collocations":[{"en":"disseminate scientific knowledge to the public","zh":"向公众普及科学知识"},{"en":"rapidly disseminate research findings","zh":"迅速传播研究成果"},{"en":"widely disseminated through digital platforms","zh":"通过数字平台广泛传播"},{"en":"disseminate accurate public health guidance","zh":"传播准确的公共卫生指南"}],"examples":[{"type":"IELTS","en":"Open-access academic journals enable universities to disseminate research findings globally, accelerating technological innovation in developing nations.","zh":"开放获取学术期刊使高校能够在全球范围内传播研究成果，从而加速发展中国家的技术创新。","highlights":["disseminate research findings"]},{"type":"IELTS","en":"Broadcasting corporations have a civic responsibility to disseminate verified news rather than sensationalist rumours designed to maximise advertising revenue.","zh":"广播传媒公司负有传播核实新闻的公民责任，而不应散布旨在最大化广告收入的耸人听闻的谣言。","highlights":["disseminate verified news"]},{"type":"GRE","en":"While decentralised social networks can rapidly disseminate vital public health guidance, their algorithmic architecture equally amplifies unverified conspiracies.","zh":"尽管去中心化的社交网络能够迅速传播至关重要的公共卫生指南，但它们的算法架构同样会放大未经证实的阴谋论。","highlights":["rapidly disseminate vital public health guidance"]},{"type":"GRE","en":"The invention of movable-type printing enabled sixteenth-century humanists to disseminate vernacular translations of classical texts far beyond monastic scriptoria.","zh":"活字印刷术的发明使十六世纪的人文主义者能够将古典文献的方言译本广泛传播到修道院抄写室之外的广阔天地。","highlights":["disseminate vernacular translations"]}],"note":"【句型框架】及物动词，标准结构为 `disseminate [information / knowledge / findings / ideas] (to the public / across the globe)`，名词形式为 `the widespread dissemination of...`。【高阶替换】完美升级口语化的 `spread`、`share`、`pass on` 或 `give out`。词根 `semin-` 源自拉丁语 `semen`（种子），`dis-`（四散）+ `seminate`（播种）形象地描绘出“像播撒种子一样将思想、知识或信息广泛传播开来”。【避坑指南】宾语必须是“信息、知识、理论、观念、谣言”等无形抽象名词；切勿用来指传播疾病或病毒（疾病传播应使用 `transmit` 或 `spread`）！","forms":["disseminated","disseminating","disseminates","disseminative","dissemination"],"partners":[{"id":"knowledge","rel":"动+名","phrase":"disseminate scientific knowledge to the public","note":"常用搭配：disseminate scientific knowledge to the public（向公众普及科学知识），与 knowledge（知识）构成高频「动+名」词伙。"},{"id":"finding","rel":"动+名","phrase":"rapidly disseminate research findings","note":"常用搭配：rapidly disseminate research findings（迅速传播研究成果），与 finding（研究发现、成果）构成高频「动+名」词伙。"}]},{"id":"exorbitant","word":"exorbitant","ipa":{"uk":"/ɪg'zɔːbɪtənt/","us":"/ɪɡ'zɔrbɪtənt/"},"pos":"adj.","definition":{"en":"Much too high or unreasonable in price, cost, or demand.","zh":"（价格、成本、学费或代价）高得离谱的、过高的。"},"libraries":["writing"],"topics":["社会与经济","健康与生活"],"functions":["替换基础词","利弊权衡"],"frequency":{"ielts":5,"gre":4},"register":"正式评价与批判语域；常用于住房、医疗、教育及公共政策议论文中批判成本或价格过高","synonyms":[{"id":"excessive","note":"exorbitant 专指价格、租金、学费或索求高得离谱；excessive 泛指任何数量或程度超出合理界限。"},{"id":"unreasonable","note":"近义辨析：二者在“不合理、过分”义项上相通；exorbitant 侧重“过分的”，unreasonable 侧重“不讲道理的”。"},{"id":"prohibitive","note":"exorbitant 强调价格极其高昂、漫天要价；prohibitive 强调价格高到令普通人望而却步（prohibitive costs）。"},{"id":"steep","note":"exorbitant 为正式书面语，表高得离谱；steep 常用于口语或新闻中表价格过高或涨幅急剧。"}],"antonyms":[{"id":"affordable","note":"反义对照：exorbitant 表价格高得离谱的，而 affordable 表价格合理、民众负担得起的。"},{"id":"reasonable","note":"反义对照：exorbitant 表漫天要价、过高的，而 reasonable 表公道合理的。"},{"id":"moderate","note":"反义对照：exorbitant 表极端高昂的，而 moderate 表适度的、温和的。"}],"collocations":[{"en":"exorbitant housing prices","zh":"高得离谱的房价"},{"en":"exorbitant tuition fees","zh":"极其高昂的学费"},{"en":"at an exorbitant cost","zh":"以极其高昂的代价"},{"en":"charge exorbitant interest rates","zh":"收取高得离谱的利率"}],"examples":[{"type":"IELTS","en":"Exorbitant housing costs in metropolitan centres force many essential workers to endure exhausting daily commutes from distant suburbs.","zh":"大都市中心高得离谱的住房成本，迫使许多基础岗位劳动者每天忍受从远郊往返的疲惫通勤。","highlights":["Exorbitant housing costs"]},{"type":"IELTS","en":"Were universities to continue charging exorbitant tuition fees without expanding need-based scholarships, higher education would revert to a privilege of the wealthy elite.","zh":"倘若大学继续收取高昂的学费而不扩大助学金规模，高等教育将倒退回富裕精英阶层的特权。","highlights":["charging exorbitant tuition fees"]},{"type":"GRE","en":"Critics argue that charging exorbitant prices for life-saving pharmaceuticals undermines the moral legitimacy of patent protections.","zh":"批评者认为，对救命药品收取高得离谱的价格，削弱了专利保护的道德正当性。","highlights":["exorbitant prices"]}],"note":"【句型框架】① charge / impose exorbitant fees on sb（向某人收取高得离谱的费用）；② achieve sth at an exorbitant environmental/social cost（以极其高昂的环境/社会代价换取某事）。【高阶替换】强势替代 too expensive、very high（price/cost）等低幼表达；相比 costly（代价高的，偏中性客观）和 lucrative（有利可图的，不可误当“昂贵的”），exorbitant 词源意为“脱离正轨（ex- + orbit）”，自带“漫天要价、超出合理限度”的鲜明批判立场。【避坑指南】修饰对象严格限定于 price、cost、fee、rent、rate、tax、demand 等与金钱或索取相关的抽象名词，绝对不能用来修饰具体物品本身（不说 an exorbitant car，应说 a car sold at an exorbitant price）。","forms":["exorbitantly","exorbitance"],"partners":[{"id":"price","rel":"形+名","phrase":"exorbitant housing prices","note":"常用搭配：exorbitant housing prices（高得离谱的房价），与 price（价格）构成高频「形+名」词伙。"},{"id":"fee","rel":"形+名","phrase":"exorbitant tuition fees","note":"常用搭配：exorbitant tuition fees（极其高昂的学费），与 fee（费用、学费）构成高频「形+名」词伙。"}]},{"id":"harness","word":"harness","ipa":{"uk":"/'hɑːnɪs/","us":"/'hɑrnɪs/"},"pos":"v.","definition":{"en":"To control and make effective use of natural resources, technology, or human potential.","zh":"有效利用、驾驭（科技力量、自然能源或人类潜能）。"},"libraries":["writing"],"topics":["科技与教育","自然与环境"],"functions":["替换基础词","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"正式议论与对策语域；常用于科技、能源、教育及社会治理话题中提出“化潜能为现实生产力”的建设性方案","synonyms":[{"id":"utilize","note":"harness 侧重驾驭并有效转化自然能源、新兴科技或集体潜能；utilize 为善用资源或工具的通用正式词。"},{"id":"exploit","note":"harness 含正面色彩，指引导动能为人类造福；exploit 指充分开发利用资源，有时含过度压榨之贬义。"}],"antonyms":[{"id":"squander","note":"反义对照：harness 表有效驾驭并善用宝贵资源或潜能，而 squander 表白白挥霍浪费。"}],"collocations":[{"en":"harness the potential of artificial intelligence","zh":"驾驭/有效发挥人工智能的潜力"},{"en":"harness renewable energy sources","zh":"开发利用可再生能源"},{"en":"harness collective creativity","zh":"激发并善用集体创造力"},{"en":"harness market incentives","zh":"利用市场激励机制"}],"examples":[{"type":"IELTS","en":"When properly regulated, educational institutions can harness digital technologies to personalise instruction without sacrificing human mentorship.","zh":"在规范得当的前提下，教育机构可以有效利用数字技术实现个性化教学，而不牺牲教师的人文指导。","highlights":["harness digital technologies"]},{"type":"IELTS","en":"Coastal nations enjoy a distinct geographical advantage in harnessing offshore wind and tidal energy to decarbonise their power grids.","zh":"沿海国家在开发利用海上风能和潮汐能以实现电网脱碳方面，享有得天独厚的地理优势。","highlights":["harnessing offshore wind and tidal energy"]},{"type":"GRE","en":"The challenge for modern policymakers is to harness market incentives in service of ecological restoration rather than resource depletion.","zh":"现代政策制定者面临的挑战是驾驭市场激励机制，使其服务于生态修复而非资源消耗。","highlights":["harness market incentives"]}],"note":"【句型框架】① harness the full potential of X to do sth（充分释放/驾驭 X 的潜能以达成某目标）；② harness X in service of Y（驾驭力量 X 使其服务于崇高目标 Y）。【高阶替换】极具表现力地升级 use、utilize、make use of；相比 exploit（常含“剥削、掠夺性开采”的贬义风险）和 utilize（仅指实用性使用），harness 本义是“给骏马上挽具、修筑水坝引水发电”，精准传达出“将原本狂野、分散或潜在的巨大力量（如风能、AI、青春热情）加以引导控制并转化为有益动能”。【避坑指南】宾语应当是蕴含能量、潜能或动力的宏大事物（energy, technology, potential, talent, data），切勿用于日常琐碎物品（不能写 harness a pen to write 或 harness a bus to go to work）。","forms":["harnessed","harnessing","harnesses"],"partners":[{"id":"energy","rel":"动+名","phrase":"harness renewable energy sources","note":"常用搭配：harness renewable energy sources（开发利用可再生能源），与 energy（能源）构成高频「动+名」词伙。"},{"id":"incentive","rel":"动+名","phrase":"harness market incentives","note":"常用搭配：harness market incentives（利用市场激励机制），与 incentive（激励机制、诱因）构成高频「动+名」词伙。"}]},{"id":"prerequisite","word":"prerequisite","ipa":{"uk":"/ˌpriː'rekwəzɪt/","us":"/,pri'rɛkwəzɪt/"},"pos":"n.","definition":{"en":"Something that must exist or happen before something else is possible.","zh":"先决条件；必要前提。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["因果与影响","论证与证据"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与逻辑论证语域；适用于大作文构建严密的“必要条件”论证（指出唯有先满足 A，方能实现 B）","synonyms":[{"id":"requirement","note":"prerequisite 强调在某事发生之前必须先具备的先决条件；requirement 泛指规定或任务所需的各项要求。"},{"id":"necessity","note":"prerequisite 侧重逻辑或流程上的先后前提；necessity 侧重必不可少的必需性。"}],"antonyms":[],"collocations":[{"en":"an essential prerequisite for sustainable development","zh":"可持续发展的必要先决条件"},{"en":"serve as a fundamental prerequisite for","zh":"作为……的基本前提"},{"en":"fulfil the institutional prerequisites for","zh":"满足……的制度先决条件"},{"en":"political stability as a prerequisite to investment","zh":"作为投资前提的政治稳定"}],"examples":[{"type":"IELTS","en":"Universal basic literacy and reliable broadband infrastructure are essential prerequisites for meaningful participation in the modern digital economy.","zh":"普及基础读写能力与可靠的宽带基础设施，是有效参与现代数字经济的必要先决条件。","highlights":["essential prerequisites for"]},{"type":"IELTS","en":"Affordable and accessible public transit is a prerequisite for the successful implementation of inner-city congestion charges.","zh":"价格合理且便捷的公共交通，是成功实施内城拥堵收费制度的先决条件。","highlights":["a prerequisite for"]},{"type":"GRE","en":"Methodological transparency is an indispensable prerequisite for scientific progress, as independent laboratories must be able to replicate reported findings.","zh":"方法论的透明度是科学进步不可或缺的先决条件，因为独立实验室必须能够复现已报告的研究结果。","highlights":["an indispensable prerequisite for"]}],"note":"【句型框架】核心逻辑句型为 `A is an essential/indispensable prerequisite for B`（A 是实现 B 的必要先决条件）。【高阶替换】替换 `necessary condition / requirement / must-have`；前缀 `pre-`（预先）+ `requisite`（必需品），精准表达“必须先具备 A，B 才有可能发生”的先后条件逻辑，极其契合雅思大作文的因果与条件链推导。【避坑指南】后接介词通常用 `for`（也可接 `to`），注意拼写中 `-qui-` 不要漏写字母 `u`；虽然本义已含“预先必需”，但在学术英语中搭配 `essential / fundamental / vital` 属高频规范用法。","forms":["prerequisites"],"partners":[{"id":"essential","rel":"形+名","phrase":"an essential prerequisite for sustainable development","note":"常用搭配：an essential prerequisite for sustainable development（可持续发展的必要先决条件），与 essential（必不可少的、核心的）构成高频「形+名」词伙。"},{"id":"fulfil","rel":"动+名","phrase":"fulfil the institutional prerequisites for","note":"常用搭配：fulfil the institutional prerequisites for（满足……的制度先决条件），与 fulfil（满足、履行）构成高频「动+名」词伙。"}]},{"id":"proponent","word":"proponent","ipa":{"uk":"/prə'pəʊnənt/","us":"/prə'ponənt/"},"pos":"n.","definition":{"en":"A person who actively speaks or argues in support of a policy, theory, or course of action.","zh":"倡导者；支持者（尤指某项政策、理论或改革方案的拥护者）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["观点评价","比较与对照"],"frequency":{"ielts":5,"gre":4},"register":"正式（双边讨论与观点引述）· 雅思 Task 2 Discuss both views 题型必备核心词，用来优雅引述支持某项政策、技术或理论的学者与倡导者。","synonyms":[{"id":"champion","note":"proponent 为客观学术词，指持支持立场者；champion 强调为某项事业或弱势群体奋力疾呼的捍卫者。"},{"id":"protagonist","note":"近义辨析：二者在“倡导者”义项上相通；proponent 侧重“建议者”，protagonist 侧重“倡导者”。"},{"id":"exponent","note":"proponent 侧重某项政策、改革或议案的倡导者与支持者；exponent 侧重某种理论流派或技艺的代表人物与阐述者。"}],"antonyms":[{"id":"critic","note":"反义对照：proponent 表某项政策或理论的倡导者与支持者，而 critic 表批评者与反对者。"}],"collocations":[{"en":"staunch proponents of","zh":"……的坚定支持者/倡导者"},{"en":"vocal proponents of deregulation","zh":"放松监管的高调倡导者"},{"en":"proponents of globalisation contend that","zh":"全球化的倡导者主张……"},{"en":"both proponents and detractors","zh":"支持者与批评者双方"}],"examples":[{"type":"IELTS","en":"Staunch proponents of urban congestion pricing contend that financial disincentives are the most pragmatic instrument for curbing private vehicle emissions during peak commuting hours.","zh":"城市拥堵收费政策的坚定支持者主张，经济抑制手段是遏制通勤高峰期私家车排放最务实的工具。","highlights":["Staunch proponents of"]},{"type":"IELTS","en":"While proponents of standardised testing emphasise its objectivity, critics counter that high-stakes exams narrow the curriculum and penalise creative thinkers.","zh":"尽管标准化考试的支持者强调其客观性，但批评者反驳称，高风险考试会窄化课程设置并惩罚具有创造性思维的学生。","highlights":["proponents of standardised testing"]},{"type":"GRE","en":"Even the most ardent proponents of the endogenous growth hypothesis concede that longitudinal microeconomic data are still required to validate its causal mechanisms.","zh":"即便是内生增长假说最热忱的拥护者也承认，仍需纵向微观经济数据来验证其因果机制。","highlights":["ardent proponents of"]}],"note":"【句型框架】双边讨论段首破题神句：Staunch/Ardent proponents of [名词/动名词] contend/maintain that...，后段对应 Critics/Detractors/Opponents, conversely, counter that...。【高阶替换】彻底告别低分口语词 some people who agree with / supporters / fans；与 advocate 相比，proponent（词根 pro- 向前 + pon- 放置，即“提出主张之人”）学术味更浓，专门指某一理论流派、立法提案或改革路线的拥护者。【避坑指南】后接介词必须用 of（proponents of X），切勿受 support 或 agree with 影响而误写 *proponents for X 或 *proponents with X；且它是可数名词，泛指一类支持者时务必使用复数形式 proponents。","forms":["proponents","proposal","propose"],"partners":[{"id":"staunch","rel":"形+名","phrase":"staunch proponents of","note":"常用搭配：staunch proponents of（……的坚定支持者/倡导者），与 staunch（坚定的）构成高频「形+名」词伙。"},{"id":"vocal","rel":"形+名","phrase":"vocal proponents of deregulation","note":"常用搭配：vocal proponents of deregulation（放松监管的高调倡导者），与 vocal（直言不讳的、高调发声的）构成高频「形+名」词伙。"}]},{"id":"allocate","word":"allocate","ipa":{"uk":"/'æləkeɪt/","us":"/'æləket/"},"pos":"v.","definition":{"en":"To officially give a share of money, time, space, or resources for a particular purpose.","zh":"分配、拨出（财政资金、公共资源或时间）。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["利弊权衡","社会结构"],"frequency":{"ielts":5,"gre":3},"register":"正式政务与公共政策语域；政府财政预算、医疗教育资源倾斜及时间管理类大作文的最高频核心动词","synonyms":[{"id":"assign","note":"allocate 侧重划拨财政预算、资金或公共资源；assign 侧重指派工作任务、职责或席位。"},{"id":"distribute","note":"allocate 侧重决策层面的资源配置；distribute 侧重将物资或收益具体分发到各处。"},{"id":"apportion","note":"allocate 强调为特定用途拨出专门份额；apportion 强调按比例或规则在多方之间分摊或分配。"}],"antonyms":[{"id":"withhold","note":"反义对照：allocate 表正式划拨分配资金或资源，而 withhold 表扣留、拒绝拨付。"}],"collocations":[{"en":"allocate public funds to","zh":"将公共资金划拨给……"},{"en":"allocate resources equitably","zh":"公平配置资源"},{"en":"allocate a larger proportion of the budget","zh":"分配更大比例的预算"},{"en":"misallocation of scarce resources","zh":"稀缺资源的错配"}],"examples":[{"type":"IELTS","en":"Governments should allocate a greater share of healthcare budgets to preventive education rather than focusing exclusively on clinical treatment.","zh":"政府应将更大比例的医疗预算分配给预防性教育，而非仅仅专注于临床治疗。","highlights":["allocate a greater share"]},{"type":"IELTS","en":"Were municipal authorities to allocate public funds more equitably between affluent districts and deprived neighbourhoods, educational outcomes would become far less stratified.","zh":"倘若市政当局能在富裕街区与贫困社区之间更公平地配置公共资金，教育成果的阶层分化程度将会大幅降低。","highlights":["allocate public funds more equitably"]},{"type":"GRE","en":"How an institution chooses to allocate scarce research grants inevitably shapes the direction of scientific inquiry for decades.","zh":"一个机构如何选择分配稀缺的科研经费，不可避免地会塑造未来数十年的科学探索方向。","highlights":["allocate scarce research grants"]}],"note":"【句型框架】① Governments should allocate a greater share of [预算/资源] to [民生/预防领域] rather than [次要领域]（政府投资类大作文万能主旨句）；② the equitable allocation of scarce resources（稀缺资源的公平配置）。【高阶替换】精准升级 give money to、spend on、divide；相比 distribute（侧重将物品分发、散播到各个受众手中）和 assign（侧重指派工作任务或职责），allocate 强调权力机构或决策者“经过专项规划，从总额中划拨出特定份额的资金、资源或时间用于专门用途”。【避坑指南】核心介词搭配是 allocate sth to sb/sth 或 allocate sth for sth；切勿受汉语“把资金投入到……”影响而误写为 allocate money into sth，也不要采用双宾语结构（不说 allocate hospitals more money，应说 allocate more money to hospitals）。","forms":["allocated","allocating","allocates","allocable","allocation"],"partners":[{"id":"fund","rel":"动+名","phrase":"allocate public funds to","note":"常用搭配：allocate public funds to（将公共资金划拨给……），与 fund（资金、基金）构成高频「动+名」词伙。"},{"id":"resource","rel":"动+名","phrase":"allocate resources equitably","note":"常用搭配：allocate resources equitably（公平配置资源），与 resource（资源）构成高频「动+名」词伙。"}]},{"id":"exemplify","word":"exemplify","ipa":{"uk":"/ɪg'zemplɪfaɪ/","us":"/ɪɡ'zɛmplɪfaɪ/"},"pos":"v.","definition":{"en":"To be a very typical example of something, or to give an example in order to clarify an argument.","zh":"作为……的典型例证；深刻体现。"},"libraries":["writing"],"topics":["逻辑与论证","文化与历史"],"functions":["论证与证据","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与举例论证语域；常用于大作文主体段无缝引入具体案例，替代生硬的 For example","synonyms":[{"id":"epitomise","note":"exemplify 侧重作为典型例子清晰说明某普遍规律；epitomise 侧重成为某种精神或时代特征的集中缩影。"},{"id":"embody","note":"exemplify 强调以实例印证论点；embody 强调将抽象理念具体化地体现在行动或制度之中。"},{"id":"illustrate","note":"exemplify 指事物本身就是绝佳范例；illustrate 指作者通过举例或图表来阐明观点。"}],"antonyms":[{"id":"belie","note":"反义对照：exemplify 表典型地体现并印证某特征，而 belie 表掩盖真相或证明表面说法不实。"}],"collocations":[{"en":"be vividly exemplified by","zh":"由……得到生动的例证"},{"en":"exemplify the tension between","zh":"典型地体现……之间的张力"},{"en":"exemplify best practice in","zh":"成为……领域最佳实践的典范"},{"en":"as exemplified by the case of","zh":"正如……案例所例证的那样"}],"examples":[{"type":"IELTS","en":"The potential of urban greening is exemplified by cities that have transformed disused railway corridors into thriving public parks.","zh":"将废弃铁路走廊改造为生机勃勃的公共公园的城市，生动例证了城市绿化的潜力。","highlights":["is exemplified by"]},{"type":"IELTS","en":"Public-private partnerships, as exemplified by Singapore's affordable housing programme, can reconcile market efficiency with social equity.","zh":"正如新加坡平价组屋计划所例证的那样，公私合作伙伴关系能够兼顾市场效率与社会公平。","highlights":["as exemplified by"]},{"type":"GRE","en":"The treatise exemplifies the mid-century shift from speculative philosophy toward quantitative social science.","zh":"这部专著典型地体现了世纪中期从思辨哲学向定量社会科学的转向。","highlights":["exemplifies the mid-century shift"]}],"note":"【句型框架】① This phenomenon is vividly exemplified by X, which...（这一现象由 X 得到了生动例证——替代 For example 的满分衔接句式）；② X, as exemplified by Y, demonstrates that...（插入语结构，在不打断主句逻辑流的前提下嵌入精炼案例）。【高阶替换】全方位升级 give an example、be a good example of、illustrate；相比 illustrate（侧重用图表、故事或细节把抽象道理“解释清楚”），exemplify 强调“某事物本身就是该类别或趋势最具代表性的典范缩影”。【避坑指南】极其注意主动与被动语态的主宾位置关系：主动语态是“具体案例 exemplify 抽象规律”（Singapore exemplifies successful urban planning），被动语态是“抽象规律 be exemplified by 具体案例”（Successful urban planning is exemplified by Singapore），切忌把主宾颠倒！","forms":["exemplified","exemplifies","exemplifying"],"partners":[{"id":"tension","rel":"动+名","phrase":"exemplify the tension between","note":"常用搭配：exemplify the tension between（典型地体现……之间的张力），与 tension（紧张关系、张力）构成高频「动+名」词伙。"},{"id":"practice","rel":"动+名","phrase":"exemplify best practice in","note":"常用搭配：exemplify best practice in（成为……领域最佳实践的典范），与 practice（实践、做法）构成高频「动+名」词伙。"}]},{"id":"perpetuate","word":"perpetuate","ipa":{"uk":"/pə'petʃʊeɪt/","us":"/pɚ'pɛtʃuet/"},"pos":"v.","definition":{"en":"To cause an undesirable situation, belief, or inequality to continue indefinitely.","zh":"使永久化；使（不良状况、偏见或恶性循环）持续存在。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["因果与影响","改善与恶化"],"frequency":{"ielts":5,"gre":4},"register":"极正式批判性学术语域；适用于大作文剖析教育不公、阶层固化、贫困代际传递或刻板印象延续","synonyms":[{"id":"prolong","note":"perpetuate 侧重使贫困循环、偏见或阶层分化长期固化延续；prolong 侧重单纯拉长某过程或状态的持续时间。"},{"id":"sustain","note":"perpetuate 多接负面现象，指使其挥之不去；sustain 多接正面或中性事物，指维持生命力或稳定增长。"},{"id":"maintain","note":"perpetuate 强调使某种既有格局代代相传不绝；maintain 泛指保持现有状态或水准。"}],"antonyms":[{"id":"eradicate","note":"反义对照：perpetuate 表使贫困或弊病长期延续固化，而 eradicate 表将其彻底根除消灭。"},{"id":"abolish","note":"反义对照：perpetuate 表延续旧有不良制度，而 abolish 表正式废除。"},{"id":"terminate","note":"反义对照：perpetuate 表使无限期持续，而 terminate 表使终止结束。"}],"collocations":[{"en":"perpetuate the cycle of intergenerational poverty","zh":"使代际贫困的恶性循环持续下去"},{"en":"perpetuate entrenched gender stereotypes","zh":"固化根深蒂固的性别刻板印象"},{"en":"perpetuate socioeconomic stratification","zh":"延续社会经济阶层分化"},{"en":"inadvertently perpetuate a popular myth","zh":"无意中延续某种普遍谬见"}],"examples":[{"type":"IELTS","en":"Unequal access to high-quality early childhood education tends to perpetuate socioeconomic stratification across generations.","zh":"优质早期教育机会的不均等，往往会使社会经济阶层分化在代际间持续固化。","highlights":["perpetuate socioeconomic stratification"]},{"type":"IELTS","en":"Sensationalist media coverage of youth crime often serves only to perpetuate public misconceptions rather than inform rational policy debate.","zh":"媒体对青少年犯罪的煽情报道往往只会延续公众的错误观念，而无助于促进理性的政策辩论。","highlights":["perpetuate public misconceptions"]},{"type":"GRE","en":"Algorithmic recommendation systems may inadvertently perpetuate ideological echo chambers by systematically filtering out dissenting perspectives.","zh":"算法推荐系统通过系统性地过滤不同意见，可能会在无意中使意识形态信息茧房持续固化。","highlights":["inadvertently perpetuate"]}],"note":"【句型框架】高频高分句式为 `tends to perpetuate the vicious cycle of...`（往往会延续……的恶性循环）或 `serve only to perpetuate + 负面观念/不公`（只会固化……）。【高阶替换】用于替换 `keep going / make continue / maintain`；但与中性词 `maintain` 或褒义词 `preserve / sustain`（维持生计、保存文化或可持续发展）截然不同，`perpetuate` 在现代学术议论文中几乎专指“使不良状态、偏见、谬误或不平等长期固化”。【避坑指南】切勿用它搭配正面事物（如不可写 `perpetuate economic prosperity`，此时应用 `sustain`）；另外注意不要与形容词 `perpetual`（永恒的、无休止的）混用词性。","forms":["perpetuated","perpetuating","perpetuates","perpetuation"],"partners":[{"id":"poverty","rel":"动+名","phrase":"perpetuate the cycle of intergenerational poverty","note":"常用搭配：perpetuate the cycle of intergenerational poverty（使代际贫困的恶性循环持续下去），与 poverty（贫困）构成高频「动+名」词伙。"},{"id":"stereotype","rel":"动+名","phrase":"perpetuate entrenched gender stereotypes","note":"常用搭配：perpetuate entrenched gender stereotypes（固化根深蒂固的性别刻板印象），与 stereotype（刻板印象、成见）构成高频「动+名」词伙。"}]},{"id":"predominant","word":"predominant","ipa":{"uk":"/prɪ'dɒmɪnənt/","us":"/prɪ'dɑmənənt/"},"pos":"adj.","definition":{"en":"Most noticeable, powerful, or common among a group of things or factors.","zh":"占主导地位的；最显著的；占绝大多数的。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["替换基础词","数量与趋势"],"frequency":{"ielts":5,"gre":4},"register":"正式学术描述与归因语域；通用于雅思小作文概括主导数据特征及大作文分析占压倒性优势的因素或主流观点","synonyms":[{"id":"dominant","note":"predominant 侧重在数量、比例或显著程度上占绝大多数的；dominant 侧重在权力、控制力或竞争中占统治地位的。"},{"id":"prevalent","note":"predominant 强调在诸多因素中居于主导首位；prevalent 强调某种现象在特定群体或时期广泛存在。"},{"id":"primary","note":"predominant 强调客观声势或比重压倒其他；primary 强调首要的、最基本的。"}],"antonyms":[{"id":"peripheral","note":"反义对照：predominant 表占主导核心地位的，而 peripheral 表处于外围次要地位的。"},{"id":"secondary","note":"反义对照：predominant 表首要显著的，而 secondary 表次要的、从属的。"},{"id":"negligible","note":"反义对照：predominant 表占绝大多数的，而 negligible 表微不足道、可忽略不计的。"}],"collocations":[{"en":"remain the predominant driver of","zh":"仍然是……的主导驱动因素"},{"en":"play a predominant role in shaping","zh":"在塑造……方面起主导作用"},{"en":"the predominant consensus among economists","zh":"经济学家中的主流共识"},{"en":"a predominantly agrarian economy","zh":"以农业为主导的经济体"}],"examples":[{"type":"IELTS","en":"While genetic predisposition plays a minor role, sedentary lifestyles and ultra-processed diets remain the predominant drivers of modern metabolic diseases.","zh":"尽管遗传易感性有一定影响，但久坐不动的生活方式与超加工饮食仍是现代代谢疾病的主导驱动因素。","highlights":["the predominant drivers of"]},{"type":"IELTS","en":"Although renewable capacity has expanded rapidly over the past decade, fossil fuels remain the predominant source of baseload electricity in many developing economies.","zh":"尽管过去十年可再生能源装机容量迅速增长，但在许多发展中经济体中，化石燃料仍然是基荷电力的主导来源。","highlights":["the predominant source of"]},{"type":"GRE","en":"Mercantile self-interest, though rarely the sole motive, was the predominant consideration shaping the city-state's maritime alliances.","zh":"商业私利虽很少是唯一动机，却是塑造该城邦海事同盟关系的主导考量因素。","highlights":["the predominant consideration"]}],"note":"【句型框架】常用于 `remain the predominant driver/cause/source of X`（依然是 X 的主导驱动力/原因/来源），或其副词形式 `is predominantly composed of / driven by...`（主要由……组成/驱动）。【高阶替换】替换基础词 `main / chief / most common / biggest`；相比 `important`，`predominant` 特指在数量占比、发生频率或支配力量上“显著压倒其他同类因素、居于主体地位”。【避坑指南】注意区分 `predominant`（客观占比或力量占主导地位的）与 `prominent`（著名的、显眼的、突出的）：煤是某国最主要的能源用 `predominant energy source`，而著名科学家则用 `prominent scientist`。","forms":["predominantly","predominance","predomination","predominate"],"partners":[{"id":"role","rel":"形+名","phrase":"play a predominant role in shaping","note":"常用搭配：play a predominant role in shaping（在塑造……方面起主导作用），与 role（作用、角色）构成高频「形+名」词伙。"},{"id":"consensus","rel":"形+名","phrase":"the predominant consensus among economists","note":"常用搭配：the predominant consensus among economists（经济学家中的主流共识），与 consensus（共识）构成高频「形+名」词伙。"}]},{"id":"ubiquitous","word":"ubiquitous","ipa":{"uk":"/juː'bɪkwɪtəs/","us":"/ju'bɪkwɪtəs/"},"pos":"adj.","definition":{"en":"Seeming to be everywhere or in several places at the same time; extremely common.","zh":"无处不在的；随处可见的；普遍存在的。"},"libraries":["writing"],"topics":["科技与教育","社会与经济"],"functions":["替换基础词","数量与趋势"],"frequency":{"ielts":5,"gre":5},"register":"正式学术语域；常用于科技、媒体、消费主义与城市化话题的引言段背景引入或现象描述","synonyms":[{"id":"omnipresent","note":"二者均表无处不在；ubiquitous 常修饰数码设备、塑料或广告等随处可见的事物，omnipresent 语体更庄重，常修饰抽象权力或监控氛围。"},{"id":"pervasive","note":"ubiquitous 强调空间分布上到处都有；pervasive 强调影响、气味或偏见像液体一样渗透弥漫到各个角落。"},{"id":"widespread","note":"ubiquitous 语气更强，指几乎无所不在；widespread 指分布范围广。"}],"antonyms":[{"id":"rare","note":"反义对照：ubiquitous 表无处不在、随处可见的，而 rare 表罕见的、稀少的。"},{"id":"scarce","note":"反义对照：ubiquitous 表普遍存在的，而 scarce 表稀缺难觅的。"},{"id":"sporadic","note":"反义对照：ubiquitous 表全面普及的，而 sporadic 表零星散乱、偶发出现的。"}],"collocations":[{"en":"become increasingly ubiquitous","zh":"变得日益普及/无处不在"},{"en":"ubiquitous mobile devices","zh":"无处不在的移动设备"},{"en":"the ubiquitous presence of","zh":"……无处不在的身影"},{"en":"ubiquitous surveillance cameras","zh":"随处可见的监控摄像头"}],"examples":[{"type":"IELTS","en":"As smartphones and social media have become ubiquitous, the boundary between professional obligations and personal leisure has grown increasingly blurred.","zh":"随着智能手机和社交媒体变得无处不在，职业义务与个人闲暇之间的界限已日趋模糊。","highlights":["become ubiquitous"]},{"type":"IELTS","en":"So ubiquitous is commercial advertising in public spaces that consumers are subconsciously conditioned to equate material possessions with personal fulfilment.","zh":"商业广告在公共空间中如此无处不在，以至于消费者在潜意识里被训练得将物质拥有等同于个人满足感。","highlights":["So ubiquitous is"]},{"type":"GRE","en":"Plastic microfibres have become so ubiquitous in marine ecosystems that researchers now struggle to find uncontaminated control samples.","zh":"塑料微纤维在海洋生态系统中已变得如此无处不在，以至于研究人员如今难以找到未受污染的对照样本。","highlights":["so ubiquitous in"]}],"note":"【句型框架】① As X has become increasingly ubiquitous in modern society, ...（随着 X 在现代社会日益无处不在……）；② the ubiquitous presence of X in daily life（X 在日常生活中无处不在的身影，常作主语或介词宾语）。【高阶替换】精准替代 can be seen everywhere、very common、popular 等口语化表达；相比 widespread（分布范围广）和 prevalent（在特定群体或时期流行、盛行），ubiquitous 更强调“渗透到每一个角落、让人无处可避”的视觉或空间存在感。【避坑指南】ubiquitous 是形容词而非副词，切勿直接修饰动词（不能写 exist ubiquitous，应写 exist everywhere 或 be ubiquitous）；其名词形式为 ubiquity（the ubiquity of smartphones）。","forms":["ubiquity"],"partners":[{"id":"device","rel":"形+名","phrase":"ubiquitous mobile devices","note":"常用搭配：ubiquitous mobile devices（无处不在的移动设备），与 device（设备、装置）构成高频「形+名」词伙。"},{"id":"surveillance","rel":"形+名","phrase":"ubiquitous surveillance cameras","note":"常用搭配：ubiquitous surveillance cameras（随处可见的监控摄像头），与 surveillance（监控、监视）构成高频「形+名」词伙。"}]},{"id":"concerted","word":"concerted","ipa":{"uk":"/kən'sɜːtɪd/","us":"/kən'sɝtɪd/"},"pos":"adj.","definition":{"en":"Planned or done together by multiple parties for a shared purpose, especially in a determined and coordinated way.","zh":"齐心协力的；协同一致的；多方联合开展的。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["比较与对照","社会结构"],"frequency":{"ielts":5,"gre":4},"register":"正式议论形容词 · 雅思大作文结尾段呼吁“政府、企业与公众齐心协力”解决复杂社会或环境问题时的皇冠级高频搭配词。","synonyms":[{"id":"collective","note":"concerted 强调各方经过周密协调、劲往一处使的（如 concerted efforts）；collective 泛指由集体共同完成的。"},{"id":"joint","note":"concerted 突出行动的步调一致与坚定决心；joint 侧重两方或多方联合署名的或共同承担的。"},{"id":"united","note":"concerted 多修饰具体行动、努力或反击；united 多修饰团结一致的立场或阵营。"}],"antonyms":[{"id":"unilateral","note":"反义对照：concerted 表多方齐心协力、协同一致的，而 unilateral 表单方面独断采取的。"},{"id":"isolated","note":"反义对照：concerted 表联合协调的，而 isolated 表孤立零散的。"}],"collocations":[{"en":"concerted efforts from governments and individuals","zh":"政府与个人的齐心协力"},{"en":"require concerted international action","zh":"需要国际社会采取协同一致的行动"},{"en":"launch a concerted campaign against","zh":"发起一场针对……的联合攻势/运动"},{"en":"mount a concerted response to","zh":"对……作出协同一致的应对"}],"examples":[{"type":"IELTS","en":"Mitigating urban air pollution requires concerted efforts from municipal authorities, industrial manufacturers, and individual commuters alike.","zh":"缓解城市空气污染需要市政当局、工业制造商以及个人通勤者的齐心协力。","highlights":["concerted efforts from"]},{"type":"IELTS","en":"Combating online misinformation demands a concerted campaign involving technology platforms, educational institutions, and regulatory bodies.","zh":"打击网络虚假信息需要科技平台、教育机构与监管部门开展一场协同一致的联合行动。","highlights":["a concerted campaign"]},{"type":"GRE","en":"Only through concerted regulatory oversight can global financial markets prevent localized liquidity crises from cascading across national borders.","zh":"唯有通过协同一致的监管监督，全球金融市场才能防止局部流动性危机跨国蔓延。","highlights":["concerted regulatory oversight"]},{"type":"GRE","en":"Despite the microbiologists' concerted attempt to eradicate the biofilm, dormant persister cells survived the antibiotic regimen and repopulated the tissue.","zh":"尽管微生物学家齐心协力试图根除这种生物膜，休眠的持留菌仍在抗生素疗程中幸存下来并重新占据了组织。","highlights":["concerted attempt"]}],"note":"【句型框架】雅思结尾段万能收束句型：`Addressing [议题] requires concerted efforts from governments, corporations, and individuals alike.`（解决某问题需要政府、企业与个人的共同努力）。【高阶替换】彻底告别小学生式的 `work together`、`try hard together` 或平庸的 `joint efforts`。相比 `joint`（仅表共同拥有或联合署名），`concerted` 不仅包含“多方联合”，更强调“目标坚定、步调协调一致且力度集中”。【避坑指南】不要将 `concerted` 误拼或误解为 `concentrated`（集中的/浓缩的）；此外 `concerted` 几乎只作前置定语修饰抽象行为名词（如 `effort`, `action`, `campaign`, `attempt`）。","forms":["concert"],"partners":[{"id":"effort","rel":"形+名","phrase":"concerted efforts from governments and individuals","note":"常用搭配：concerted efforts from governments and individuals（政府与个人的齐心协力），与 effort（努力）构成高频「形+名」词伙。"},{"id":"action","rel":"形+名","phrase":"require concerted international action","note":"常用搭配：require concerted international action（需要国际社会采取协同一致的行动），与 action（行动）构成高频「形+名」词伙。"}]},{"id":"jeopardise","word":"jeopardise","ipa":{"uk":"/'dʒepədaɪz/","us":"/'dʒepədaiz/"},"pos":"v.","definition":{"en":"To put something important or valuable into danger of being harmed, lost, or ruined.","zh":"危及、损害（长远利益、生态平衡或公共安全）。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["利弊权衡","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"正式政策预警与利弊权衡语域；适用于大作文指出短视行为或极端政策对长远利益的威胁","synonyms":[{"id":"endanger","note":"jeopardise 侧重因决策失当而危及长远利益、前途或稳定局面；endanger 侧重使生命、物种或安全面临直接危险。"},{"id":"imperil","note":"imperil 语体极具文学与修辞张力，指使……陷入险境；jeopardise 广泛用于政策与社会经济论述。"},{"id":"impair","note":"jeopardise 强调使事物面临受损或毁灭的风险；impair 强调已经实际削弱或损害了某种机能。"}],"antonyms":[{"id":"safeguard","note":"反义对照：jeopardise 表危及、损害长远利益或安全，而 safeguard 表有力保障、捍卫。"},{"id":"protect","note":"反义对照：jeopardise 表使陷入险境，而 protect 表保护免受侵害。"},{"id":"preserve","note":"反义对照：jeopardise 表破坏稳定或前景，而 preserve 表维护保存。"}],"collocations":[{"en":"jeopardise long-term ecological sustainability","zh":"危及长期生态可持续性"},{"en":"jeopardise the future prospects of youth","zh":"损害青少年的未来发展前景"},{"en":"seriously jeopardise public health security","zh":"严重危及公共卫生安全"},{"en":"jeopardise hard-won economic stability","zh":"危及来之不易的经济稳定"}],"examples":[{"type":"IELTS","en":"Prioritising short-term industrial output over stringent environmental regulation will inevitably jeopardise long-term ecological sustainability.","zh":"将短期工业产出置于严格的环境监管之上，不可避免地会危及长期生态可持续性。","highlights":["jeopardise long-term ecological sustainability"]},{"type":"IELTS","en":"Excessive reliance on temporary gig-economy contracts can jeopardise the financial security of young workers, delaying major life milestones.","zh":"过度依赖零工经济的临时合同会危及年轻劳动者的财务安全，进而推迟其人生的重要里程碑。","highlights":["jeopardise the financial security of"]},{"type":"GRE","en":"Fiscal austerity measures that indiscriminately slash basic research funding may jeopardise a nation's capacity for frontier technological innovation.","zh":"不加区分地大幅削减基础科研经费的财政紧缩措施，可能会危及一个国家开展前沿技术创新的能力。","highlights":["jeopardise a nation's capacity"]}],"note":"【句型框架】常用于条件或动名词主语句 `Prioritising A over B will inevitably jeopardise C`（重 A 轻 B 势必危及 C），或搭配名词形式 `put/place X in jeopardy`（使 X 陷入险境）。【高阶替换】完美升级口语化的 `put in danger / risk / threaten`；相比 `harm / damage`（已造成实际损害），`jeopardise` 强调“将宝贵事物置于受损、毁灭或失败的巨大风险之中”，极具前瞻警示力量。【避坑指南】英式拼写为 `jeopardise`，美式为 `jeopardize`（同一篇作文中应保持英美拼写一致）；它是及物动词，切勿画蛇添足写成 `jeopardise to public health`。","forms":["jeopardised","jeopardising","jeopardises","jeopardy","jeopardize"],"partners":[{"id":"prospect","rel":"动+名","phrase":"jeopardise the future prospects of youth","note":"常用搭配：jeopardise the future prospects of youth（损害青少年的未来发展前景），与 prospect（前景、前途）构成高频「动+名」词伙。"},{"id":"stability","rel":"动+名","phrase":"jeopardise hard-won economic stability","note":"常用搭配：jeopardise hard-won economic stability（危及来之不易的经济稳定），与 stability（稳定、安定）构成高频「动+名」词伙。"}]},{"id":"reciprocal","word":"reciprocal","ipa":{"uk":"/rɪ'sɪprək(ə)l/","us":"/rɪ'sɪprəkl/"},"pos":"adj.","definition":{"en":"Involving two people, groups, or nations who behave toward or benefit each other in a mutual way.","zh":"互惠的；双向的；相互促进或相互依存的。"},"libraries":["writing"],"topics":["社会与经济","文化与历史"],"functions":["比较与对照","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"正式学术形容词 · 适用于雅思大作文导言段或结尾段阐述两个要素（如经济发展与生态保护、权利与义务、跨文化双向交流）相辅相成的辩证关系。","synonyms":[{"id":"mutual","note":"reciprocal 强调双向往来、投桃报李的互惠或对等关系；mutual 强调双方共同怀有的（如 mutual trust）。"},{"id":"complementary","note":"reciprocal 侧重双向互动与利益互换；complementary 侧重双方优势互补、相辅相成。"}],"antonyms":[{"id":"unilateral","note":"反义对照：reciprocal 表双向互惠、彼此对等的，而 unilateral 表单向片面的。"}],"collocations":[{"en":"a reciprocal relationship between","zh":"……之间相辅相成的双向关系"},{"en":"reciprocal cultural exchange","zh":"双向互惠的文化交流"},{"en":"entail reciprocal obligations","zh":"意味着对等互惠的义务"},{"en":"foster reciprocal trust and respect","zh":"培育相互信任与尊重"}],"examples":[{"type":"IELTS","en":"Economic vitality and environmental stewardship are not mutually exclusive; rather, they exist in a reciprocal relationship wherein sustainable ecosystems underpin long-term prosperity.","zh":"经济活力与环境治理并非水火不容；相反，二者处于一种相辅相成的双向关系之中，可持续的生态系统支撑着长远的繁荣。","highlights":["a reciprocal relationship"]},{"type":"IELTS","en":"Rather than promoting one-way cultural assimilation, international tourism should facilitate reciprocal cultural exchange between host communities and foreign visitors.","zh":"国际旅游业不应推动单向的文化同化，而应促进东道主社区与外国游客之间的双向互惠文化交流。","highlights":["reciprocal cultural exchange"]},{"type":"GRE","en":"Multilateral trade agreements endure only when participating states perceive the regulatory concessions and market access benefits to be genuinely reciprocal.","zh":"只有当各参与国认为监管让步与市场准入收益真正对等互惠时，多边贸易协定才能长久维系。","highlights":["genuinely reciprocal"]},{"type":"GRE","en":"Ethological field studies demonstrate that vampire bats maintain complex networks of reciprocal altruism, preferentially sharing blood meals with roost-mates that have previously fed them.","zh":"动物行为学实地研究表明，吸血蝠维系着复杂的互惠利他网络，优先与曾给自己喂食的同巢伙伴分享血液食物。","highlights":["reciprocal altruism"]}],"note":"【句型框架】黄金辩证模板：`A and B exist in a reciprocal relationship`（A与B处于相辅相成的双向关系中）或 `Citizenship entails reciprocal rights and obligations`（公民身份意味着对等的权利与义务）。【高阶替换】精准升级 `two-way`、`give-and-take` 或简单的 `mutual`。`mutual` 侧重双方“共同拥有同一种情感或目标”（如 `mutual respect/interest`），而 `reciprocal` 强调“你来我往的双向回馈与动态互动”（A作用于B，B反过来回馈A）。【避坑指南】不要用 `reciprocal` 修饰单向行为；其派生名词为 `reciprocity`（互惠原则），在国际贸易和人际社会学语境中同样是满分词汇。","forms":["reciprocals","reciprocally"],"partners":[{"id":"relationship","rel":"形+名","phrase":"a reciprocal relationship between","note":"常用搭配：a reciprocal relationship between（……之间相辅相成的双向关系），与 relationship（关系）构成高频「形+名」词伙。"},{"id":"obligation","rel":"形+名","phrase":"entail reciprocal obligations","note":"常用搭配：entail reciprocal obligations（意味着对等互惠的义务），与 obligation（义务、责任）构成高频「形+名」词伙。"}]},{"id":"underpin","word":"underpin","ipa":{"uk":"/ˌʌndə'pɪn/","us":"/,ʌndɚ'pɪn/"},"pos":"v.","definition":{"en":"To support, justify, or form the essential foundation of an idea, system, or institution.","zh":"支撑；构成（理论、制度或社会繁荣）的核心基石。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["论证与证据","因果与影响"],"frequency":{"ielts":5,"gre":4},"register":"极正式学术语域；适用于大作文揭示社会繁荣、制度运作或理论框架背后的底层基石与核心逻辑","synonyms":[{"id":"sustain","note":"underpin 强调提供底层逻辑或物质基础支撑；sustain 强调维持长久运作而不衰落。"},{"id":"brace","note":"近义辨析：二者在“支撑”义项上相通；underpin 侧重“加固…的基础”，brace 侧重“支撑”。"},{"id":"bolster","note":"underpin 侧重从底部构成制度或理论不可或缺的基石；bolster 侧重对已有事物予以声援加固。"},{"id":"buttress","note":"underpin 指作为核心根基支撑；buttress 指像扶壁一样从外部提供强力佐证或支持。"}],"antonyms":[{"id":"undermine","note":"经典反义词对：underpin 表从根基处支撑加固，而 undermine 表从根基处暗中侵蚀削弱。"},{"id":"erode","note":"反义对照：underpin 表奠定稳固基础，而 erode 表逐步侵蚀瓦解。"}],"collocations":[{"en":"underpin long-term economic prosperity","zh":"支撑长期的经济繁荣"},{"en":"the core principles that underpin democracy","zh":"构成民主制度基石的核心原则"},{"en":"underpin social stability and cohesion","zh":"奠定社会稳定与凝聚力的基础"},{"en":"theoretical assumptions underpinning the model","zh":"支撑该模型的理论假设"}],"examples":[{"type":"IELTS","en":"Rule of law and transparent institutional governance underpin long-term economic prosperity, whereas endemic corruption rapidly deters foreign investment.","zh":"法治与透明的制度治理是长期经济繁荣的基石，而普遍的腐败则会迅速吓阻外国投资。","highlights":["underpin long-term economic prosperity"]},{"type":"IELTS","en":"A robust universal healthcare system is required to underpin social stability, particularly in societies experiencing rapid demographic ageing.","zh":"需要建立健全的全民医疗体系来奠定社会稳定的基础，尤其是在经历快速人口老龄化的社会中。","highlights":["underpin social stability"]},{"type":"GRE","en":"Rigorous epidemiological evidence must underpin any public health mandate if authorities wish to secure enduring civic compliance.","zh":"如果当局希望获得持久的公众配合，任何公共卫生强制令都必须以严谨的流行病学证据为基石。","highlights":["underpin any public health mandate"]},{"type":"GRE","en":"The revisionist historian questioned the archival assumptions underpinning the orthodox account of seventeenth-century mercantile decline.","zh":"这位修正派历史学家质疑了支撑十七世纪重商主义衰落正统叙事的档案假设。","highlights":["assumptions underpinning the orthodox account"]}],"note":"【句型框架】常以基本价值或制度为主语：`A and B underpin C`（A 与 B 构成了 C 的基石），或用现在分词作后置定语 `the values underpinning modern jurisprudence`（支撑现代法理学的价值观）。【高阶替换】源自建筑学“加固地基”，是替换 `support / form the basis of / be the foundation of` 的 Band 9 标志性动词，能瞬间提升句子在逻辑纵深上的高级感。【避坑指南】拼写上注意重读闭音节，过去式和现在分词必须双写 `n`（即 `underpinned` 和 `underpinning`）；名词形式 `underpinnings`（基础、根基）通常用复数。","forms":["underpinned","underpinning","underpins"],"partners":[{"id":"prosperity","rel":"动+名","phrase":"underpin long-term economic prosperity","note":"常用搭配：underpin long-term economic prosperity（支撑长期的经济繁荣），与 prosperity（繁荣、兴旺）构成高频「动+名」词伙。"},{"id":"stability","rel":"动+名","phrase":"underpin social stability and cohesion","note":"常用搭配：underpin social stability and cohesion（奠定社会稳定与凝聚力的基础），与 stability（稳定）构成高频「动+名」词伙。"}]},{"id":"unilateral","word":"unilateral","ipa":{"uk":"/juːnɪ'læt(ə)r(ə)l/","us":"/'jʊnɪ'lætərəl/"},"pos":"adj.","definition":{"en":"Performed or undertaken by only one person, group, or country without the agreement of others.","zh":"单方面的；片面的；单边采取的。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["比较与对照","社会结构"],"frequency":{"ielts":5,"gre":4},"register":"正式政务与学术形容词 · 常用于雅思全球化、气候变化、跨国犯罪与公共管理议题中，批判“单边主义/一意孤行”的局限性。","synonyms":[{"id":"arbitrary","note":"unilateral 侧重未经协商而由单方面采取行动；arbitrary 侧重缺乏客观依据、凭主观意志独断专行。"},{"id":"independent","note":"unilateral 强调单边行为（多用于国际关系或管理决策，常含贬义）；independent 强调自主独立。"}],"antonyms":[{"id":"multilateral","note":"国际关系与政策核心反义对：unilateral 表单边的、单方面采取的，而 multilateral 表多边协商参与的。"},{"id":"bilateral","note":"反义对照：unilateral 表单方面的，而 bilateral 表双边互动的。"},{"id":"reciprocal","note":"反义对照：unilateral 表片面单向的，而 reciprocal 表双向互惠的。"}],"collocations":[{"en":"unilateral emissions targets","zh":"单方面的减排目标"},{"en":"impose unilateral sanctions or tariffs","zh":"实施单边制裁或关税"},{"en":"unilateral decision-making by management","zh":"管理层的单方面决策"},{"en":"prove futile through unilateral action alone","zh":"仅靠单边行动证明是徒劳的"}],"examples":[{"type":"IELTS","en":"Because greenhouse gases respect no national borders, unilateral emissions targets adopted by a handful of nations cannot halt planetary warming.","zh":"由于温室气体不分国界，少数国家采取的单方面减排目标无法遏制全球变暖。","highlights":["unilateral emissions targets"]},{"type":"IELTS","en":"Unilateral decision-making by corporate executives without consulting frontline employees frequently breeds workplace resentment and high staff turnover.","zh":"企业高管未征询一线员工意见而进行的单方面决策，往往会滋生职场不满与居高不下的员工流失率。","highlights":["Unilateral decision-making"]},{"type":"GRE","en":"Unilateral curriculum reforms imposed by central ministries without consulting classroom practitioners rarely achieve their intended pedagogical outcomes.","zh":"中央部委未征询一线教师意见而单方面强推的课程改革，鲜少能取得预期的教学成效。","highlights":["Unilateral curriculum reforms"]},{"type":"GRE","en":"The sovereign's unilateral abrogation of the commercial treaty precipitated a retaliatory embargo that crippled maritime trade across the archipelago.","zh":"君主单方面废除通商条约的举动引发了报复性禁运，重创了整个群岛的海上贸易。","highlights":["unilateral abrogation"]}],"note":"【句型框架】常与 `concerted` 或 `multilateral` 构成对比句式：`Global challenges cannot be resolved through unilateral measures alone; rather, they demand concerted international action.`（全球性挑战仅靠单边措施无法解决，而需要国际社会的协同行动）。【高阶替换】完美升级 `one-sided` 或 `done by one country/person alone`。词根 `uni-`（单一）+ `lateral`（边/面），与 `bilateral`（双边的）、`multilateral`（多边的）构成严密学术词族。【避坑指南】注意首音节发 `/ˌjuːnɪˈlætərəl/`，冠词用 `a unilateral...` 而非 `an`！","forms":["unilaterally","unilateralism","unilateralist"],"partners":[{"id":"target","rel":"形+名","phrase":"unilateral emissions targets","note":"常用搭配：unilateral emissions targets（单方面的减排目标），与 target（目标）构成高频「形+名」词伙。"},{"id":"tariff","rel":"形+名","phrase":"impose unilateral sanctions or tariffs","note":"常用搭配：impose unilateral sanctions or tariffs（实施单边制裁或关税），与 tariff（关税）构成高频「形+名」词伙。"}]},{"id":"circumvent","word":"circumvent","ipa":{"uk":"/ˌsɜːrkəm'vent/","us":"/,sɝkəm'vɛnt/"},"pos":"v.","definition":{"en":"To find a way of avoiding a rule, restriction, or obstacle, often by clever or indirect means.","zh":"规避、绕开（法律法规、监管限制或制度障碍）。"},"libraries":["writing"],"topics":["社会与经济","科技与教育"],"functions":["因果与影响","利弊权衡"],"frequency":{"ielts":5,"gre":5},"register":"正式监管、法律与科技评论语域；适用于大作文讨论跨国公司避税、算法绕开监管或技术突破地理壁垒","synonyms":[{"id":"sidestep","note":"circumvent 强调设法绕过制度障碍以达目的；sidestep 强调像横跨一步那样巧妙回避敏感问题。"},{"id":"skirt","note":"circumvent 指规避规则限制；skirt 指沿着边缘绕行而不敢直接触碰核心难题。"},{"id":"evade","note":"circumvent 侧重通过钻法律漏洞或取巧手段绕开监管限制；evade 侧重逃避纳税、责任或追查。"}],"antonyms":[{"id":"comply","note":"反义对照：circumvent 表设法绕开、规避法规限制，而 comply 表严格遵从、服从规定。"},{"id":"observe","note":"反义对照：circumvent 表取巧逃避规则，而 observe 表遵守法律或准则。"}],"collocations":[{"en":"circumvent stringent environmental regulations","zh":"规避严格的环境监管法规"},{"en":"circumvent domestic tax obligations","zh":"逃避国内纳税义务"},{"en":"circumvent traditional institutional gatekeepers","zh":"绕开传统的制度把关人"},{"en":"exploit legal loopholes to circumvent oversight","zh":"利用法律漏洞规避监督"}],"examples":[{"type":"IELTS","en":"Without coordinated multilateral enforcement, multinational corporations can easily circumvent domestic tax obligations by shifting profits to offshore havens.","zh":"若缺乏协调一致的多边执法，跨国公司很容易通过将利润转移至离岸避税港来规避国内纳税义务。","highlights":["circumvent domestic tax obligations"]},{"type":"IELTS","en":"While digital streaming platforms allow independent musicians to circumvent traditional record labels, algorithmic curation has created new barriers to visibility.","zh":"尽管数字流媒体平台让独立音乐人得以绕开传统唱片公司，但算法推荐却制造了新的曝光壁垒。","highlights":["circumvent traditional record labels"]},{"type":"GRE","en":"By routing merchandise through neutral ports, nineteenth-century merchants managed to circumvent the naval blockade without technically violating treaty stipulations.","zh":"通过让货物途经中立港口，十九世纪的商人们成功绕开了海军封锁，而在技术层面上并未违反条约规定。","highlights":["circumvent the naval blockade"]}],"note":"【句型框架】常用于 `exploit loopholes to circumvent + 规则/限制（regulations / restrictions / censorship）`（利用漏洞规避……）或中性用法 `circumvent barriers/obstacles`（巧妙绕开障碍）。【高阶替换】词根 `circum`（环绕）+ `vent`（走），字面即“绕道而行”，比泛泛的 `avoid / get around / bypass` 更精准地刻画出“用聪明、迂回甚至钻空子的方式绕开制度约束或障碍”。【避坑指南】注意区分语义色彩：当宾语是法律、税收或监管（`laws, taxes, rules`）时带有明显的“钻空子、规避”贬义；当宾语是自然障碍或旧垄断壁垒（`geographical barriers, gatekeepers`）时则为中性或褒义。","forms":["circumvented","circumventing","circumvents","circumvention"],"partners":[{"id":"regulation","rel":"动+名","phrase":"circumvent stringent environmental regulations","note":"常用搭配：circumvent stringent environmental regulations（规避严格的环境监管法规），与 regulation（法规、监管规定）构成高频「动+名」词伙。"},{"id":"obligation","rel":"动+名","phrase":"circumvent domestic tax obligations","note":"常用搭配：circumvent domestic tax obligations（逃避国内纳税义务），与 obligation（义务、责任）构成高频「动+名」词伙。"}]},{"id":"complacency","word":"complacency","ipa":{"uk":"/kəm'pleɪsnsi/","us":"/kəm'plesnsi/"},"pos":"n.","definition":{"en":"A feeling of uncritical satisfaction with oneself or the current situation, accompanied by a lack of awareness of impending danger.","zh":"自满；盲目乐观；对潜在危机掉以轻心的麻痹状态。"},"libraries":["writing"],"topics":["社会与经济","自然与环境"],"functions":["观点评价","因果与影响"],"frequency":{"ielts":5,"gre":5},"register":"正式（危机预警与政策反思）· 雅思大作文结尾段（Conclusion）升华与风险警示神词，呼吁政府或公众切勿因阶段性成果而对潜在危机麻痹大意。","synonyms":[{"id":"inertia","note":"complacency 侧重对潜在风险麻痹大意的盲目自满；inertia 侧重安于现状、不思变革的制度惰性。"},{"id":"apathy","note":"complacency 强调自以为安全而放松警惕；apathy 强调对公共事务或危机漠不关心。"},{"id":"arrogance","note":"complacency 侧重盲目乐观的自满；arrogance 侧重目中无人的傲慢自大。"}],"antonyms":[{"id":"humility","note":"反义对照：complacency 表沾沾自喜的麻痹自满，而 humility 表谦逊自省。"}],"collocations":[{"en":"leave no room for complacency","zh":"绝不容许半点自满/掉以轻心"},{"en":"breed institutional complacency","zh":"滋生制度性自满懈怠"},{"en":"guard against public complacency","zh":"警惕公众麻痹大意"},{"en":"be lulled into a false sense of complacency","zh":"陷入盲目乐观的麻痹状态"}],"examples":[{"type":"IELTS","en":"Modest reductions in urban carbon intensity should leave no room for complacency, given the accelerating pace of polar ice melt and extreme weather events.","zh":"鉴于极地冰盖消融与极端天气事件的速度正在加快，城市碳强度的温和下降绝不容许我们产生半点盲目自满。","highlights":["leave no room for complacency"]},{"type":"IELTS","en":"Initial success in containing an infectious outbreak can paradoxically lull public health authorities into complacency, leading to premature cuts in epidemiological surveillance.","zh":"在遏制传染病暴发方面取得的初步成功，反而可能使公共卫生当局陷入麻痹自满，从而过早削减流行病学监测经费。","highlights":["lull public health authorities into complacency"]},{"type":"GRE","en":"Decades of unchallenged monopoly power had bred deep-seated organisational complacency, blinding the conglomerate's executives to disruptive innovations from agile startups.","zh":"数十年未受挑战的垄断地位滋生了根深蒂固的组织自满情绪，使该企业集团的高管对敏捷初创企业带来的颠覆性创新视而不见。","highlights":["organisational complacency"]}],"note":"【句型框架】结尾段满分警示句型：There is no room for complacency when it comes to [核心议题]；或 Short-term gains should leave no room for complacency about long-term structural risks。【高阶替换】升级 self-satisfaction / carelessness / overconfidence；complacency 并非单纯的“骄傲（pride）”，而是指“安于现状、对迫在眉睫的隐患浑然不觉或掉以轻心的麻痹状态”。【避坑指南】1. 语法属性：complacency 是不可数名词，绝不可加 a 或变复数；2. 同源异形词区分：千万不要把 complacent / complacency（自满麻痹的，贬义）与同根词 complaisant / complaisance（顺从的、殷勤讨好的）混淆！","forms":["complacent","complacently"],"partners":[{"id":"breed","rel":"动+名","phrase":"breed institutional complacency","note":"常用搭配：breed institutional complacency（滋生制度性自满懈怠），与 breed（滋生、孕育）构成高频「动+名」词伙。"},{"id":"public","rel":"形+名","phrase":"guard against public complacency","note":"常用搭配：guard against public complacency（警惕公众麻痹大意），与 public（公众的）构成高频「形+名」词伙。"}]},{"id":"conundrum","word":"conundrum","ipa":{"uk":"/kə'nʌndrəm/","us":"/kə'nʌndrəm/"},"pos":"n.","definition":{"en":"A confusing and difficult problem or dilemma that has no easy answer.","zh":"棘手难题；两难困局（尤指涉及多重利益冲突的政策或伦理难题）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["利弊权衡","替换基础词"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与政策分析语域；常用于引言段点明核心矛盾，或主体段剖析“鱼与熊掌不可兼得”的政策伦理困局","synonyms":[{"id":"puzzle","note":"conundrum 为高阶正式词，多指政策或伦理困局；puzzle 为日常与通用词。"},{"id":"dilemma","note":"conundrum 泛指错综复杂、难以破解的棘手难题；dilemma 特指必须在两个往往皆有弊端的选项间做出的两难抉择。"},{"id":"quandary","note":"conundrum 侧重问题本身扑朔迷离、极难解答；quandary 侧重当事人在困境中不知所措的犹疑状态。"}],"antonyms":[{"id":"solution","note":"反义对照：conundrum 表令人困惑的棘手困局，而 solution 表破解问题的解决方案。"}],"collocations":[{"en":"pose a thorny policy conundrum","zh":"提出一个棘手的政策难题"},{"en":"resolve the ethical conundrum","zh":"解决这一伦理两难困局"},{"en":"face a perennial conundrum","zh":"面临长期存在的棘手难题"},{"en":"the central conundrum of","zh":"……的核心难题"}],"examples":[{"type":"IELTS","en":"Developing nations face the central conundrum of how to lift millions out of poverty without replicating carbon-intensive industrial pathways.","zh":"发展中国家面临的核心难题是：如何在不重走高碳工业老路的前提下帮助数以百万计的人口脱贫。","highlights":["the central conundrum of"]},{"type":"IELTS","en":"Rapid population ageing poses a thorny fiscal conundrum for welfare states: how to fund rising pension obligations with a shrinking tax base.","zh":"人口快速老龄化给福利国家提出了一个棘手的财政难题：如何在税基萎缩的情况下为日益增长的养老金义务提供资金。","highlights":["poses a thorny fiscal conundrum"]},{"type":"GRE","en":"The regulator's conundrum lies in balancing consumer data protection against the open information flows required for algorithmic innovation.","zh":"监管者的棘手难题在于平衡消费者数据保护与算法创新所需的开放信息流动。","highlights":["regulator's conundrum"]}],"note":"【句型框架】① Policymakers face the central conundrum of how to balance A against B（决策者面临如何平衡 A 与 B 的核心难题——双边讨论类作文破题神器）；② grapple with a thorny ethical conundrum（苦苦思索棘手的伦理困局）。【高阶替换】高雅替换 difficult problem、hard question、dilemma；相比 dilemma（严格指“二选一且两害相权”的进退两难）和 predicament（侧重令人尴尬或窘迫的处境），conundrum 侧重问题本身错综复杂、难以捉摸、没有现成标准答案。【避坑指南】可数名词，使用时前面必须加冠词 a 或 the（a conundrum / the conundrum of...）；常后接介词短语 of how to do sth 或 of + 动名词作同位语来具体解释难题的内容。","forms":["conundrums"],"partners":[{"id":"resolve","rel":"动+名","phrase":"resolve the ethical conundrum","note":"常用搭配：resolve the ethical conundrum（解决这一伦理两难困局），与 resolve（解决、化解）构成高频「动+名」词伙。"},{"id":"thorny","rel":"形+名","phrase":"pose a thorny policy conundrum","note":"常用搭配：pose a thorny policy conundrum（提出一个棘手的政策难题），与 thorny（棘手的、多刺的）构成高频「形+名」词伙。"}]},{"id":"counterproductive","word":"counterproductive","ipa":{"uk":"/ˌkauntəprə'dʌktɪv/","us":"/,kaʊntɚprə'dʌktɪv/"},"pos":"adj.","definition":{"en":"Having the opposite of the desired effect, making a problem worse rather than better.","zh":"适得其反的；事与愿违的；产生反效果的。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["利弊权衡","让步转折"],"frequency":{"ielts":5,"gre":4},"register":"正式论证与反驳语域；大作文反驳段批驳“一刀切禁令、过度惩罚或拔苗助长政策”时的杀手锏形容词","synonyms":[{"id":"detrimental","note":"counterproductive 强调结果与初衷完全相反、弄巧成拙；detrimental 单纯强调造成危害或不利影响。"},{"id":"futile","note":"counterproductive 指不仅无效反而使问题恶化（产生负效用）；futile 指徒劳无功（零效用）。"}],"antonyms":[{"id":"beneficial","note":"反义对照：counterproductive 表适得其反、产生负效果的，而 beneficial 表产生有益效果的。"},{"id":"effective","note":"反义对照：counterproductive 表事与愿违的，而 effective 表行之有效的。"},{"id":"fruitful","note":"反义对照：counterproductive 表弄巧成拙的，而 fruitful 表富有成效的。"}],"collocations":[{"en":"prove counterproductive in the long run","zh":"长远来看被证明适得其反"},{"en":"a counterproductive policy","zh":"事与愿违的政策"},{"en":"wholly counterproductive","zh":"完全适得其反"},{"en":"render the measure counterproductive","zh":"使该措施产生反效果"}],"examples":[{"type":"IELTS","en":"Imposing overly punitive homework loads on primary school pupils is often counterproductive, as it extinguishes their intrinsic curiosity.","zh":"给小学生施加过多惩罚性的家庭作业负担往往适得其反，因为这会扼杀他们内在的好奇心。","highlights":["is often counterproductive"]},{"type":"IELTS","en":"Draconian censorship of online dissent frequently proves counterproductive in the long run, eroding institutional credibility rather than fostering genuine social cohesion.","zh":"对网络异见的严苛审查从长远来看往往适得其反，它不仅无法促进真正的社会凝聚力，反而会侵蚀制度公信力。","highlights":["proves counterproductive in the long run"]},{"type":"GRE","en":"Blanket prohibitions on controversial technologies can be counterproductive if they drive research underground and out of regulatory oversight.","zh":"对有争议技术的一刀切禁令可能会适得其反，因为这会将研究逼入地下并脱离监管视野。","highlights":["can be counterproductive"]}],"note":"【句型框架】① Imposing blanket bans on X often proves counterproductive, as it...（对 X 实施一刀切禁令往往适得其反，因为它反而会……）；② Such well-intentioned interventions can be wholly counterproductive if...（此类出于好意的干预若……则会完全事与愿违）。【高阶替换】精准表达 have the opposite effect、make things worse；注意与 futile/ineffective 的核心逻辑区分：futile（徒劳无功）指“效果为零、白费力气”，而 counterproductive（适得其反）指“效果为负——本想治病结果致病，把事态推向初衷的反面”。【避坑指南】拼写注意中间无需连字符（counterproductive 一个完整单词）；主语应当是带有某种预期目标的“政策、措施、行为或努力”（policies, efforts, bans, punishments），不能是自然灾害等无意图的事物。","forms":[],"partners":[{"id":"policy","rel":"形+名","phrase":"a counterproductive policy","note":"常用搭配：a counterproductive policy（事与愿违的政策），与 policy（政策）构成高频「形+名」词伙。"},{"id":"measure","rel":"形+名","phrase":"render the measure counterproductive","note":"常用搭配：render the measure counterproductive（使该措施产生反效果），与 measure（措施、举措）构成高频「形+名」词伙。"}]},{"id":"myopic","word":"myopic","ipa":{"uk":"/maɪ'oupɪk/","us":"/maɪ'ɑpɪk/"},"pos":"adj.","definition":{"en":"Lacking foresight or intellectual insight; focusing only on immediate gains while ignoring long-term consequences.","zh":"目光短浅的；急功近利的；缺乏远见的。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["观点评价","利弊权衡"],"frequency":{"ielts":5,"gre":5},"register":"正式学术批判语域；大作文反驳段核心词，用于痛批“急功近利、只顾眼前经济利益而牺牲长远生态或人文价值”的短视行为","synonyms":[{"id":"parochial","note":"myopic 侧重在时间维度上目光短浅、急功近利；parochial 侧重在空间或视野上狭隘封闭、只顾局部利益。"},{"id":"insular","note":"myopic 强调缺乏长远战略眼光；insular 强调孤立排外、拒绝接纳外部新观念。"}],"antonyms":[{"id":"provident","note":"反义对照：myopic 表目光短浅、急功近利的，而 provident 表深谋远虑、未雨绸缪的。"},{"id":"prudent","note":"反义对照：myopic 表只顾眼前利益的短视，而 prudent 表审慎权衡长远后果的。"},{"id":"visionary","note":"反义对照：myopic 表缺乏远见的，而 visionary 表富有远见卓识的。"}],"collocations":[{"en":"a myopic focus on short-term profit","zh":"对短期利润的短视追逐"},{"en":"myopic policymaking","zh":"缺乏远见的政策制定"},{"en":"take a myopic view of","zh":"对……持短视看法"},{"en":"politically myopic decisions","zh":"政治上目光短浅的决策"}],"examples":[{"type":"IELTS","en":"Eliminating arts and humanities from the university curriculum to cut costs is a myopic decision that impoverishes civic culture.","zh":"为削减成本而将艺术与人文学科从大学课程中剔除，是一种令公共文化贫瘠化的短视决定。","highlights":["a myopic decision"]},{"type":"IELTS","en":"Cleared of ancient rainforests to yield immediate timber revenue, tropical regions often pay a devastating ecological price for such myopic resource exploitation.","zh":"为了获取眼前的木材收益而砍伐原始雨林，热带地区往往要为这种目光短浅的资源开发付出毁灭性的生态代价。","highlights":["myopic resource exploitation"]},{"type":"GRE","en":"Corporate governance structures tied to quarterly earnings reports often encourage myopic strategies at the expense of foundational research.","zh":"与季度财报挂钩的公司治理结构往往助长急功近利的策略，而牺牲基础性研发。","highlights":["myopic strategies"]}],"note":"【句型框架】① Sacrificing X for immediate financial gain is a profoundly myopic approach that...（为眼前经济利益而牺牲 X 是一种极其短视的做法，它会……）；② transcend myopic self-interest（超越短视的私利）。【高阶替换】替换 short-sighted、ignoring the future 的C2级学术精粹词；源自医学名词 myopia（近视），在社会科学与议论文中作隐喻使用，专指决策者、企业或公众“只盯住眼皮底下的即时回报（immediate gains），却对长远的结构性恶果视而不见”。【避坑指南】反义词为 farsighted 或 prescient（有远见的、有先见之明的）；注意拼写是 my-o-pic（源自希腊语闭眼眯看），切勿误拼为 miopic。","forms":["myopics","myopia","myope"],"partners":[{"id":"decision","rel":"形+名","phrase":"politically myopic decisions","note":"常用搭配：politically myopic decisions（政治上目光短浅的决策），与 decision（决策、决定）构成高频「形+名」词伙。"},{"id":"short-term","rel":"形+名","phrase":"a myopic focus on short-term profit","note":"常用搭配：a myopic focus on short-term profit（对短期利润的短视追逐），与 short-term（短期的）构成高频「形+名」词伙。"}]},{"id":"necessitate","word":"necessitate","ipa":{"uk":"/nɪ'sesɪteɪt/","us":"/nə'sɛsɪtet/"},"pos":"v.","definition":{"en":"To make something necessary as a result or consequence of a situation.","zh":"使成为必要；客观局势迫使、需要（采取某项行动）。"},"libraries":["writing"],"topics":["社会与经济","逻辑与论证"],"functions":["因果与影响","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与政策论证语域；适用于大作文论证客观形势变化、技术颠覆或人口趋势如何迫使制度做出相应调整","synonyms":[{"id":"entail","note":"necessitate 侧重客观局势迫使必须采取某项行动；entail 侧重某项变革或决定必然伴随某种成本或后果。"},{"id":"require","note":"necessitate 语域更正式，主语常为客观形势或危机；require 为通用词，主语可为人、规则或形势。"},{"id":"compel","note":"necessitate 指使某事在客观上成为必要；compel 指强迫某人不得不做某事。"}],"antonyms":[{"id":"obviate","note":"反义对照：necessitate 表客观局势迫使某事成为必要，而 obviate 表提前消除隐患从而免除某事的必要。"},{"id":"preclude","note":"反义对照：necessitate 表使……必不可少，而 preclude 表将……完全排除。"}],"collocations":[{"en":"necessitate a fundamental overhaul of","zh":"迫使对……进行根本性改革"},{"en":"necessitate coordinated multilateral intervention","zh":"客观上需要协调一致的多边干预"},{"en":"necessitate a reassessment of traditional pedagogy","zh":"使重新评估传统教学法成为必要"},{"en":"necessitate substantial capital expenditure","zh":"需要巨额资本支出"}],"examples":[{"type":"IELTS","en":"Rapid demographic ageing across industrialised nations will necessitate a fundamental overhaul of public pension schemes and geriatric healthcare.","zh":"工业化国家人口的快速老龄化，将迫使公共养老金计划与老年医疗保健体系进行根本性改革。","highlights":["necessitate a fundamental overhaul of"]},{"type":"IELTS","en":"The proliferation of generative artificial intelligence in higher education necessitates a shift from take-home essays toward oral and invigilated assessments.","zh":"生成式人工智能在高等教育中的普及，迫使考核方式从课后论文转向口试与监考评估。","highlights":["necessitates a shift from"]},{"type":"GRE","en":"The transboundary nature of atmospheric aerosols necessitates multilateral treaties rather than isolated domestic abatement policies.","zh":"大气气溶胶的跨境性质决定了必须依靠多边条约，而非孤立的国内减排政策。","highlights":["necessitates multilateral treaties"]}],"note":"【句型框架】标准句式为 `Objective trend/crisis X necessitates + 动作名词化短语（a fundamental overhaul of Y / immediate intervention）`（客观趋势 X 使 Y 成为必要）。【高阶替换】一个词即可浓缩替换冗长的 `make it necessary to... / require / call for`，瞬间提升句子的名词化密度与学术凝练度。【避坑指南】两大铁律：第一，主语必须是客观情况、趋势或问题，不能用“人”作主语（不可写 `The government necessitated a new law`）；第二，后接名词或动名词作宾语，严禁使用 `necessitate somebody to do something`（应改为 `compel/require sb to do sth`）。","forms":["necessitated","necessitates","necessitating","necessary","necessity"],"partners":[{"id":"intervention","rel":"动+名","phrase":"necessitate coordinated multilateral intervention","note":"常用搭配：necessitate coordinated multilateral intervention（客观上需要协调一致的多边干预），与 intervention（干预、介入）构成高频「动+名」词伙。"},{"id":"expenditure","rel":"动+名","phrase":"necessitate substantial capital expenditure","note":"常用搭配：necessitate substantial capital expenditure（需要巨额资本支出），与 expenditure（支出、开支）构成高频「动+名」词伙。"}]},{"id":"panacea","word":"panacea","ipa":{"uk":"/ˌpænə'siːə/","us":"/ˌpænə'siːə/"},"pos":"n.","definition":{"en":"Something that is claimed to solve all problems or cure all ills.","zh":"万灵药；包治百病的万能良方（常用于否定句）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["让步转折","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与辩证思辨语域；雅思大作文让步转折段标志性满分名词，用于体现“不走极端、避免绝对化”的审慎学术态度","synonyms":[{"id":"elixir","note":"panacea 指包治百病或解决一切社会难题的万灵药（常用于否定句）；elixir 原指炼金术的长生不老药，现亦喻指灵丹妙药。"},{"id":"remedy","note":"panacea 指虚幻的万能良方；remedy 指针对具体病症或社会弊病的切实补救措施。"}],"antonyms":[{"id":"toxin","note":"反义对照：panacea 表包治百病的万灵药，而 toxin 表毒害机体的毒素。"},{"id":"plague","note":"反义对照：panacea 表解除百病的良方，而 plague 表带来广泛祸患的瘟疫或弊病。"}],"collocations":[{"en":"no panacea for complex social ills","zh":"绝非解决复杂社会弊病的万能药"},{"en":"by no means a universal panacea","zh":"绝非包治百病的灵丹妙药"},{"en":"touted as a panacea for","zh":"被吹捧为解决……的万灵药"},{"en":"treat technology as a panacea","zh":"将技术奉为万灵药"}],"examples":[{"type":"IELTS","en":"While electric vehicles can reduce tailpipe emissions, they are no panacea for urban congestion or the environmental costs of battery mining.","zh":"尽管电动汽车能减少尾气排放，但它们绝非解决城市拥堵或电池开采环境代价的万灵药。","highlights":["no panacea for"]},{"type":"IELTS","en":"Often touted as a panacea for educational inequality, online learning platforms nonetheless fail to benefit underprivileged children who lack quiet study spaces and parental guidance.","zh":"在线学习平台常被吹捧为解决教育不平等的万灵药，但对于缺乏安静学习空间和家长指导的弱势儿童而言，它们依然收效甚微。","highlights":["touted as a panacea for"]},{"type":"GRE","en":"Historians caution against viewing constitutional reform as a panacea when informal institutions remain resistant to change.","zh":"历史学家告诫人们，当非正式制度依然抗拒变革时，切勿将宪制改革视为包治百病的万灵药。","highlights":["as a panacea"]}],"note":"【句型框架】① While X offers tangible benefits, it is by no means a panacea for Y（虽然 X 带来切实益处，但它绝非解决 Y 的万能药——Task 2 让步转折段万能黄金句型）；② Caution must be exercised against viewing X as a panacea for...（必须警惕将 X 奉为解决……的万灵药）。【高阶替换】完美升级 cure-all、magic solution、silver bullet（silver bullet 偏新闻口语，panacea 更具古典学术庄重感）；源自古希腊医药女神 Panakeia。【避坑指南】第一，固定介词搭配是 a panacea for + 疾病/社会问题（切勿用 of 或 to）；第二，在严谨的学术写作中，95% 以上用于否定句、让步句或质疑语境（is no panacea / far from a panacea），切勿在正面提建议时说 My policy is a panacea（这会显得论证极其天真武断）。","forms":["panaceas"],"partners":[{"id":"universal","rel":"形+名","phrase":"by no means a universal panacea","note":"常用搭配：by no means a universal panacea（绝非包治百病的灵丹妙药），与 universal（普遍的、万能的）构成高频「形+名」词伙。"},{"id":"tout","rel":"动+名","phrase":"touted as a panacea for","note":"常用搭配：touted as a panacea for（被吹捧为解决……的万灵药），与 tout（吹捧、兜售）构成高频「动+名」词伙。"}]},{"id":"preclude","word":"preclude","ipa":{"uk":"/prɪ'kluːd/","us":"/prɪ'klud/"},"pos":"v.","definition":{"en":"To prevent something from happening or make a particular outcome impossible.","zh":"排除；使……不可能发生；妨碍（某种可能性）。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["因果与影响","让步转折"],"frequency":{"ielts":5,"gre":5},"register":"极正式学术与法理语域；适用于大作文双边讨论段（论证两个目标并不互斥）或客观条件限制分析","synonyms":[{"id":"prevent","note":"近义辨析：二者均表阻止发生；preclude 侧重因条件排斥而使某种可能性彻底不复存在，prevent 为预防和阻止的通用词。"},{"id":"exclude","note":"近义辨析：二者均含排除义；preclude 侧重预先妨碍使某结果不可能发生，exclude 侧重将某人或某物排斥在范围之外。"},{"id":"eliminate","note":"近义辨析：二者均表排除；preclude 侧重从源头杜绝可能性，eliminate 侧重清除已存在的隐患或选项。"},{"id":"obviate","note":"preclude 侧重因客观限制而预先排除某种可能性；obviate 侧重通过提前采取措施从而免除某项麻烦或必要（如 obviate the need for）。"}],"antonyms":[{"id":"facilitate","note":"反义对照：preclude 表阻碍并排除某种可能性，而 facilitate 表提供便利、促使其顺利实现。"},{"id":"enable","note":"反义对照：preclude 表使不可能发生，而 enable 表使能够实现。"},{"id":"permit","note":"反义对照：preclude 表预先杜绝，而 permit 表容许发生。"}],"collocations":[{"en":"does not preclude the possibility of","zh":"并不排除……的可能性"},{"en":"preclude disadvantaged groups from participating","zh":"使弱势群体无法参与"},{"en":"mutual exclusivity that precludes compromise","zh":"排除妥协可能的排他性"},{"en":"fiscal constraints that preclude large-scale subsidies","zh":"使大规模补贴成为不可能的财政限制"}],"examples":[{"type":"IELTS","en":"Emphasising rigorous academic standards in secondary schools does not preclude the cultivation of artistic creativity and emotional resilience.","zh":"在中学强调严格的学术标准，并不排斥对艺术创造力与心理韧性的培养。","highlights":["does not preclude the cultivation of"]},{"type":"IELTS","en":"Prohibitive childcare costs often preclude mothers in low-income households from re-entering full-time employment.","zh":"高昂得令人望而却步的育儿成本，往往使低收入家庭的母亲无法重返全职工作岗位。","highlights":["preclude mothers in low-income households from"]},{"type":"GRE","en":"The fragmentary nature of the epigraphic record precludes any definitive reconstruction of the city-state's early fiscal administration.","zh":"铭文记录的残缺不全，使得任何对该城邦早期财政管理制度的确切重构都成为不可能。","highlights":["precludes any definitive reconstruction"]}],"note":"【句型框架】雅思大作文双边兼顾满分句型：`Pursuing A does not preclude B`（追求 A 并不排除/不妨碍兼顾 B）；另一常用结构为 `preclude somebody from doing something`（使某人无法做某事）。【高阶替换】词根 `pre`（预先）+ `clude`（关闭），即“预先把门关死”，完美替换 `make impossible / rule out / prevent`；相比 `impede`（仅减速阻碍），`preclude` 语义极强，指从逻辑或客观条件上彻底堵死某种可能性。【避坑指南】不要把 `preclude` 与 `include / exclude` 混淆用法：虽然都有 `-clude`，但“排除某人的参与”可说 `preclude sb from doing`，而一般不说 `preclude sb from a group`（后者用 `exclude`）。","forms":["precludes","precluded","precluding","precludable","preclusive"],"partners":[{"id":"subsidy","rel":"动+名","phrase":"fiscal constraints that preclude large-scale subsidies","note":"常用搭配：fiscal constraints that preclude large-scale subsidies（使大规模补贴成为不可能的财政限制），与 subsidy（补贴、津贴）构成高频「动+名」词伙。"},{"id":"group","rel":"动+名","phrase":"preclude disadvantaged groups from participating","note":"常用搭配：preclude disadvantaged groups from participating（使弱势群体无法参与），与 group（群体）构成高频「动+名」词伙。"}]},{"id":"relegate","word":"relegate","ipa":{"uk":"/'relɪgeɪt/","us":"/'rɛlɪɡet/"},"pos":"v.","definition":{"en":"To assign someone or something to an inferior rank, position, or secondary importance.","zh":"使降格；将……置于次要或边缘地位。"},"libraries":["writing"],"topics":["科技与教育","文化与历史"],"functions":["社会结构","比较与对照"],"frequency":{"ielts":5,"gre":5},"register":"正式议论与学术动词 · 尤其适合在雅思教育与文化大作文中批评“应试教育将体育、音乐、人文或道德素养置于次要/边缘地位”。","synonyms":[{"id":"demote","note":"relegate 侧重将某议题、学科或群体降格置于次要边缘地位；demote 侧重在行政职务或军阶上将某人降职。"},{"id":"marginalise","note":"relegate 强调从原本较高的位置贬入次要地位（常接 to）；marginalise 强调使其在社会权力结构中边缘化。"}],"antonyms":[{"id":"elevate","note":"反义对照：relegate 表将某事物降格置于次要地位，而 elevate 表提升其地位与重要性。"},{"id":"promote","note":"反义对照：relegate 表贬低排挤到边缘，而 promote 表提升、倡导。"}],"collocations":[{"en":"relegate arts and physical education to a secondary role","zh":"将艺术与体育降格为次要角色"},{"en":"be relegated to the periphery of public debate","zh":"被排挤到公共讨论的边缘"},{"en":"relegate ethical considerations to an afterthought","zh":"将伦理考量降格为事后点缀"},{"en":"relegate manual workers to precarious low-wage jobs","zh":"使体力劳动者沦落到不稳定的低薪工作岗位"}],"examples":[{"type":"IELTS","en":"An obsessive focus on standardised examination rankings often leads schools to relegate creative arts and physical education to a secondary role.","zh":"对标准化考试排名的过度痴迷，往往导致学校将创意艺术和体育降格为次要角色。","highlights":["relegate creative arts and physical education to a secondary role"]},{"type":"IELTS","en":"In profit-driven tech companies, user privacy and algorithmic fairness are all too often relegated to an afterthought during product development.","zh":"在利润驱动的科技公司中，用户隐私和算法公平性在产品开发过程中往往被降格为事后才考虑的次要问题。","highlights":["relegated to an afterthought"]},{"type":"GRE","en":"Positivist historiographical traditions tended to relegate oral testimonies and folk ballads to the status of unreliable antiquarian curiosities.","zh":"实证主义史学传统往往将口述证词和民间歌谣降格为不可靠的古玩轶事。","highlights":["relegate oral testimonies and folk ballads to"]},{"type":"GRE","en":"Once the dominant explanatory paradigm in developmental psychology, strict behaviourism was gradually relegated to the margins by the cognitive revolution.","zh":"严格的行为主义曾是发展心理学中占主导地位的解释范式，但随后被认知革命逐渐排挤到了学术边缘。","highlights":["relegated to the margins"]}],"note":"【句型框架】核心及物框架：`relegate A to B`（将A降格/打入B的次要地位），被动语态尤为高频：`A is relegated to a secondary role / the periphery / an afterthought / obscurity`。【高阶替换】高分升级 `make sth less important`、`put in second place` 或 `ignore`。相比 `ignore`（完全不理会），`relegate` 更精准地刻画出“虽然表面保留，但将其重要性大幅贬低、视作无足轻重的附庸”。【避坑指南】必须搭配介词 `to` 引出降格后的低等位置或状态，切勿漏掉 `to B` 只写 `relegate sth`；注意与 `delegate`（委派代表/授权）拼写和词义的区别。","forms":["relegated","relegating","relegates","relegation"],"partners":[{"id":"periphery","rel":"动+名","phrase":"be relegated to the periphery of public debate","note":"常用搭配：be relegated to the periphery of public debate（被排挤到公共讨论的边缘），与 periphery（外围、边缘）构成高频「动+名」词伙。"},{"id":"role","rel":"动+名","phrase":"relegate arts and physical education to a secondary role","note":"常用搭配：relegate arts and physical education to a secondary role（将艺术与体育降格为次要角色），与 role（角色、地位）构成高频「动+名」词伙。"}]},{"id":"scrutinize","word":"scrutinize","ipa":{"uk":"/'skruːtənaɪz/","us":"/'skrutənaɪz/"},"pos":"v.","definition":{"en":"To examine something very carefully and critically in order to verify its validity or detect flaws.","zh":"审视；细致审查；严格剖析（证据、政策或信息真伪）。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["论证与证据","观点评价"],"frequency":{"ielts":5,"gre":5},"register":"正式学术与批判性思维语域；常用于媒介素养、科研诚信、政府财政监督及法律审查类话题","synonyms":[{"id":"examine","note":"scrutinize 强调带着批判眼光细致入微地审视核查以找出破绽；examine 为检查或考察的通用词。"},{"id":"inspect","note":"scrutinize 多用于审视证据、账目、假设或法案；inspect 多用于官方视察或质量检验。"},{"id":"analyse","note":"scrutinize 侧重严密审视真伪与细节；analyse 侧重剖析内在结构与因果机理。"}],"antonyms":[{"id":"overlook","note":"反义对照：scrutinize 表细致入微地审视核查，而 overlook 表粗心忽略、漏看。"},{"id":"ignore","note":"反义对照：scrutinize 表严格剖析审查，而 ignore 表置若罔闻、忽视。"}],"collocations":[{"en":"scrutinize the credibility of online sources","zh":"严格审视网络信源的可信度"},{"en":"closely scrutinize public expenditure","zh":"严格审查公共开支"},{"en":"scrutinize underlying assumptions","zh":"深入剖析潜在假设"},{"en":"come under intense public scrutiny","zh":"受到公众的严格监督/审视"}],"examples":[{"type":"IELTS","en":"In an era of algorithmic news feeds, schools must train students to scrutinize the credibility of digital information rather than accept claims at face value.","zh":"在算法推送新闻的时代，学校必须培养学生严格审视数字信息可信度的能力，而非轻信表面说法。","highlights":["scrutinize the credibility of"]},{"type":"IELTS","en":"Were independent auditing bodies empowered to closely scrutinize municipal infrastructure contracts, corruption and cost overruns would be substantially curtailed.","zh":"倘若授权独立审计机构严格审查市政基础设施合同，腐败与成本超支现象将会得到大幅遏制。","highlights":["closely scrutinize"]},{"type":"GRE","en":"When independent statisticians scrutinized the original dataset, they discovered selection biases that invalidated the study's central conclusion.","zh":"当独立统计学家仔细审查原始数据集时，他们发现了使该研究核心结论失效的选择偏差。","highlights":["scrutinized the original dataset"]}],"note":"【句型框架】① train citizens/students to scrutinize the validity of X rather than accept it at face value（培养公民/学生严格审视 X 真伪的能力，而非轻信表面之词）；② Few arguments can withstand rigorous empirical scrutiny（很少有论点能经受住严格的实证推敲——使用同根不可数名词 scrutiny）。【高阶替换】强力升级 look closely at、check carefully、examine；相比 inspect（侧重官方例行视察或检验产品质量）和 browse/scan（粗略浏览），scrutinize 强调“带着批判或核查的眼光，放大镜般细致入微地逐一审视以排查瑕疵或伪造”。【避坑指南】及物动词（vt.），直接接宾语，切勿画蛇添足加介词 at 或 into（不能写 scrutinize at the data，直接写 scrutinize the data）；英式拼写亦可作 scrutinise，其名词形式 scrutiny（under scrutiny / withstand scrutiny）在雅思写作中同样属于必背高分块。","forms":["scrutinized","scrutinizing","scrutinizes","scrutiny","scrutineer"],"partners":[{"id":"credibility","rel":"动+名","phrase":"scrutinize the credibility of online sources","note":"常用搭配：scrutinize the credibility of online sources（严格审视网络信源的可信度），与 credibility（可信度、公信力）构成高频「动+名」词伙。"},{"id":"expenditure","rel":"动+名","phrase":"closely scrutinize public expenditure","note":"常用搭配：closely scrutinize public expenditure（严格审查公共开支），与 expenditure（开支、支出）构成高频「动+名」词伙。"}]},{"id":"underscore","word":"underscore","ipa":{"uk":"/ˌʌndər'skɔːr/","us":"/,ʌndɚ'skɔr/"},"pos":"v.","definition":{"en":"To emphasize or show clearly that something is important or true.","zh":"强调、凸显（某事物的紧迫性、重要性或核心地位）。"},"libraries":["writing"],"topics":["逻辑与论证","科技与教育"],"functions":["论证与证据","替换基础词"],"frequency":{"ielts":5,"gre":4},"register":"正式学术与议论文核心语域；大作文例证分析后“提炼结论、升华主题、强调政策紧迫性”的头号高分动词","synonyms":[{"id":"emphasize","note":"underscore 侧重事实或研究结果本身有力凸显出某事物的紧迫性；emphasize 为主观或客观强调的通用词。"},{"id":"highlight","note":"underscore 强调奠定重要性并引发高度重视；highlight 强调将最亮眼或最突出的部分呈现出来。"},{"id":"accentuate","note":"underscore 多用于凸显重要性或危机感；accentuate 多用于使某种特征或差异更加显著。"}],"antonyms":[{"id":"downplay","note":"反义对照：underscore 表着力凸显某事物的严重性或重要性，而 downplay 表刻意淡化、轻描淡写。"},{"id":"understate","note":"反义对照：underscore 表强调突出，而 understate 表避重就轻、保守低估。"},{"id":"obscure","note":"反义对照：underscore 表使核心问题清晰凸显，而 obscure 表掩盖模糊。"}],"collocations":[{"en":"underscore the urgency of","zh":"凸显……的紧迫性"},{"en":"underscore the need for","zh":"强调对……的迫切需求"},{"en":"empirical findings underscore that","zh":"实证研究结果凸显出……"},{"en":"underscore the vital importance of","zh":"凸显……的至关重要性"}],"examples":[{"type":"IELTS","en":"Recent supply-chain disruptions underscore the need for nations to diversify their sources of essential food and medical supplies.","zh":"近期的供应链中断凸显出各国实现基本食品与医疗物资来源多元化的必要性。","highlights":["underscore the need for"]},{"type":"IELTS","en":"Rising rates of adolescent anxiety across affluent societies underscore the fact that material abundance alone cannot guarantee psychological well-being.","zh":"富裕社会中青少年焦虑率的上升凸显出一个事实：仅靠物质丰裕并不能保障心理健康。","highlights":["underscore the fact that"]},{"type":"GRE","en":"The archival letters underscore how deeply personal rivalries shaped what was once presented as a purely theoretical dispute.","zh":"这些档案信件凸显出个人恩怨在多大程度上影响了这场曾被描绘为纯理论之争的论战。","highlights":["underscore how deeply"]}],"note":"【句型框架】① These alarming trends underscore the urgent need for governments to...（这些令人警醒的趋势凸显出政府迫切需要……——主体段尾句收束与呼吁对策的绝佳模板）；② X, underscoring the necessity of Y（现在分词作伴随结果状语，置于句尾点睛）。【高阶替换】高雅替换 emphasize、stress、show clearly、highlight；本义为“在文字下方画横线（underline）”，在学术写作中常以客观事实、危机事件或研究数据作主语，表示“客观事实本身强有力地昭示、凸显出某个道理”。【避坑指南】拼写注意是一个完整单词 underscore（无空格），过去分词 underscored；切勿与 understate（轻描淡写、低估）或 undermine（暗中削弱、动摇）这两个同样以 under- 开头的学术高频词混淆！","forms":["underscored","underscores","underscoring"],"partners":[{"id":"importance","rel":"动+名","phrase":"underscore the vital importance of","note":"常用搭配：underscore the vital importance of（凸显……的至关重要性），与 importance（重要性）构成高频「动+名」词伙。"},{"id":"finding","rel":"动+名","phrase":"empirical findings underscore that","note":"常用搭配：empirical findings underscore that（实证研究结果凸显出……），与 finding（研究发现、调查结果）构成高频「动+名」词伙。"}]},{"id":"unwarranted","word":"unwarranted","ipa":{"uk":"/ʌn'wɑːrəntɪd/","us":"/ʌn'wɔrəntɪd/"},"pos":"adj.","definition":{"en":"Not justified or authorized by evidence, reason, or circumstances.","zh":"毫无根据的；不正当的；不必要且过度的。"},"libraries":["writing"],"topics":["逻辑与论证","社会与经济"],"functions":["观点评价","论证与证据"],"frequency":{"ielts":5,"gre":5},"register":"正式（立场评估与反驳过度反应）· 常用于大作文评估科技风险、社会变革或政府干预，指出某种恐慌、乐观或侵犯行为缺乏事实依据。","synonyms":[{"id":"groundless","note":"unwarranted 侧重缺乏正当理由或证据支撑、不必要且过分的；groundless 侧重完全凭空捏造、毫无事实根据的。"},{"id":"unfounded","note":"unwarranted 可修饰悲观情绪、恐慌或侵犯行为；unfounded 多修饰传言、指控或恐惧缺乏事实依据。"},{"id":"gratuitous","note":"unwarranted 强调缺乏合理依据；gratuitous 强调无缘无故、纯粹多余的（如 gratuitous violence/insult）。"}],"antonyms":[{"id":"legitimate","note":"反义对照：unwarranted 表毫无根据、不正当的，而 legitimate 表合情合理、合法正当的。"},{"id":"reasonable","note":"反义对照：unwarranted 表不必要且过分的，而 reasonable 表有充分理由支撑的。"}],"collocations":[{"en":"unwarranted pessimism about","zh":"对……毫无根据的悲观情绪"},{"en":"an unwarranted intrusion into privacy","zh":"对隐私的不正当侵犯"},{"en":"dismiss the panic as unwarranted","zh":"认为该恐慌毫无根据而不予理会"},{"en":"draw an unwarranted conclusion","zh":"得出站不住脚的草率结论"}],"examples":[{"type":"IELTS","en":"While generative artificial intelligence will undoubtedly automate routine clerical tasks, apocalyptic predictions of permanent mass unemployment remain largely unwarranted.","zh":"尽管生成式人工智能无疑会使日常文书工作自动化，但关于永久性大规模失业的末日预言在很大程度上仍是毫无根据的。","highlights":["unwarranted"]},{"type":"IELTS","en":"Mandatory installation of tracking software on employees' personal devices constitutes an unwarranted intrusion into privacy that erodes workplace morale.","zh":"强制在员工个人设备上安装追踪软件构成了对隐私的不正当侵犯，会侵蚀职场士气。","highlights":["an unwarranted intrusion into privacy"]},{"type":"GRE","en":"Extrapolating universal laws of human cognitive development from experimental studies conducted exclusively within Western university cohorts is methodologically unwarranted.","zh":"仅从在西方大学生群体中开展的实验研究外推人类认知发展的普遍规律，在方法论上是毫无根据的。","highlights":["methodologically unwarranted"]},{"type":"GRE","en":"The archival fragments are far too sparse to justify the biographer's unwarranted assumption that the playwright secretly collaborated with his political rivals.","zh":"现存档案碎片过于稀少，不足以支撑传记作者毫无根据的臆断——即该剧作家曾暗中与政治对手合作。","highlights":["unwarranted assumption"]}],"note":"【句型框架】常作表语或前置定语：Apocalyptic fears of X remain largely unwarranted；或 X constitutes an unwarranted intrusion into / interference with Y。【高阶替换】精准替代 groundless / unjustified / uncalled-for；词根 warrant 意为“正当理由/授权依据”，因此 unwarranted 兼具双重高阶含义：一是认知上“缺乏证据支撑的（groundless）”，二是行为或权力上“越界的、不正当的（unjustified）”。【避坑指南】拼写注意双写 r（un-warrant-ed），且不要与法律上的 arrest warrant（逮捕令）混淆；在雅思写作中批评对方观点绝对化时，用 Such sweeping generalisations are unwarranted 比简单说 They are wrong 更具学者风范。","forms":[],"partners":[{"id":"pessimism","rel":"形+名","phrase":"unwarranted pessimism about","note":"常用搭配：unwarranted pessimism about（对……毫无根据的悲观情绪），与 pessimism（悲观情绪）构成高频「形+名」词伙。"},{"id":"intrusion","rel":"形+名","phrase":"an unwarranted intrusion into privacy","note":"常用搭配：an unwarranted intrusion into privacy（对隐私的不正当侵犯），与 intrusion（侵犯、侵扰）构成高频「形+名」词伙。"}]}]);
